// Batch Météo du compte (V6, shadow) — Phase 2 (voir plan de session,
// AUDIT_SCORING_V6.md, FINAL_ACCOUNT_ENGINE_V6_REPORT.md §19).
//
// Calcule et persiste scoring.score_snapshot (entity_type='account') à partir
// de DONNÉES RÉELLES uniquement, jamais fabriquées :
//   - d_ancrage    : nombre réel de porteurs internes (owners distincts).
//   - d_equilibre  : répartition réelle du volume de messages par contact.
//   - d_dynamique  : cadence/silence réels (messages+meetings) + engagements
//                    réellement tenus/glissés sur 90j (account_facts_live).
//   - d_satisfaction, d_confiance_recip : scores de dyade V6 réels par contact
//     (buildDyadScoreSnapshot sur scoring.marker_event scope='person', écrit
//     par detect-dyad-markers), pour les dyades non cold-start (P5 : ≥30j
//     d'ancienneté et ≥5 échanges). Chaque dyade est aussi PERSISTÉE
//     (scoring.score_snapshot, entity_type='dyad') pour la Fiche Personne.
//     authority dérivée du rôle qualifié (account_contact_roles) sinon repli
//     Utilisateur (0.3, décision produit actée) — jamais un score fabriqué.
//   - d_couverture : rôle qualifié (account_contact_roles) sinon repli
//     Utilisateur (0.3) × niveau relationnel réel (volume de messages).
//   - kEvents (K01-K09, scope='account') : lus tels quels, vides aujourd'hui,
//     se peupleront automatiquement plus tard sans changement de code ici.
// reliability/verdict_allowed : PAS calculés dans ce lot — la formule de
// fiabilité par cadran est marquée "provisional / à construire" dans la
// doctrine (aucune valeur figée à reproduire) ; les combler avec 0 ferait
// passer le score en "grisé sans verdict" côté front (displayRule), pire que
// de les laisser NULL. Colonnes laissées NULL / verdict_allowed=false.
//
// Ne recalcule JAMAIS le score legacy (account_relationship_score_snapshots,
// géré par score-batch) : tables et logiques strictement séparées (doctrine
// "jamais mélangé", AUDIT_SCORING_V6.md §T).

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { calculateAccountWeatherCore } from '../_shared/scoring-v6/calculateAccountWeatherCore.ts'
import { buildDyadScoreSnapshot } from '../_shared/scoring-v6/snapshots.ts'
import { PARAMS_V6_PALIER, REGISTRY_V6 } from '../_shared/scoring-v6/registry-v6.ts'
import type { AccountDyadInput, AccountWeatherInput, CoverageTarget, DialContribution, MarkerEvent } from '../_shared/scoring-v6/types.ts'

// Aucun rôle qualifié aujourd'hui (account_contact_roles vide) : profil
// "standard" par défaut — jamais "execution", qui est l'exception documentée
// du registre V6, pas la règle générale.
const UNQUALIFIED_ROLE = { label: 'Non qualifié', volontariteProfile: 'standard' as const }

// decision_role (texte libre saisi côté UI, cf. AccountRelationView.tsx::ROLE_LABELS)
// → clé d'autorité du registre V6 (decideur/influenceur/utilisateur/filtre).
// Repli acté (décision produit) : tout contact non qualifié = Utilisateur (0.3),
// jamais un rôle plus fort inventé. Les rôles qualifiés manuellement priment.
const AUTHORITY_KEY: Record<string, string> = {
  decision_maker: 'decideur', decideur: 'decideur', economic_buyer: 'decideur', buyer: 'decideur',
  gatekeeper: 'filtre', filtre: 'filtre',
  influencer: 'influenceur', prescripteur: 'influenceur', prescriber: 'influenceur', sponsor: 'influenceur', champion: 'influenceur',
  user: 'utilisateur', utilisateur: 'utilisateur', end_user: 'utilisateur', technical: 'utilisateur',
}
function authorityKeyFromRole(decisionRole: string | null | undefined): string {
  const v = (decisionRole ?? '').trim().toLowerCase()
  return AUTHORITY_KEY[v] ?? 'utilisateur'
}

// Niveau relationnel réel (Couverture) à partir du volume de messages réellement
// échangé avec ce contact — jamais un chiffre inventé. Paliers : 0 = aucun
// échange ; 0.5 = interaction directe réelle mais isolée (<3 messages, pas de
// récurrence mensuelle) ; 0.75 = plusieurs échanges substantiels (≥3) ; 1.0 =
// en plus récent (≤60j) et récurrent (≥2 mois distincts de contact).
// Limite connue et assumée : la CC n'est pas captée (C02 blocked), donc le
// palier 0.25 (présence passive/CC) n'est jamais atteint ici.
function relationalLevelFromMessages(times: number[], now: number): number {
  if (times.length === 0) return 0
  const distinctMonths = new Set(times.map((t) => monthStartUTC(new Date(t).toISOString()))).size
  if (times.length < 3) return 0.5
  const daysSinceLast = Math.round((now - times[times.length - 1]!) / DAY_MS)
  return distinctMonths >= 2 && daysSinceLast <= 60 ? 1 : 0.75
}

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-cron-secret',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}
function jsonResponse(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
}

const DAY_MS = 86_400_000
const ENGAGEMENT_WINDOW_DAYS = 90

// Types de relation réels de l'app (public.account_settings.relationship_status,
// voir src/account-list/mapping.ts::RELATION_COLORS) → clé de dialWeights.
// Repli sur 'Client/Prospect' pour tout ce qui n'est pas explicitement mappé —
// même repli que calculateAccountWeatherCore lui-même.
function toDialRelationType(relationshipStatus: string | null, accountType: string | null): string {
  const v = (relationshipStatus ?? accountType ?? '').trim().toLowerCase()
  if (v.startsWith('prospect') || v.startsWith('client')) return 'Client/Prospect'
  if (v.startsWith('partenaire')) return 'Partenaire'
  if (v.startsWith('fournisseur')) return 'Fournisseur'
  if (v.startsWith('investisseur')) return 'Investisseur'
  if (v.startsWith('interne') || v.startsWith('collègue') || v.startsWith('collegue')) return 'Interne'
  return 'Client/Prospect'
}

function median(sorted: number[]): number {
  if (sorted.length === 0) return 0
  const mid = Math.floor(sorted.length / 2)
  return sorted.length % 2 ? sorted[mid]! : (sorted[mid - 1]! + sorted[mid]!) / 2
}

function monthStartUTC(iso: string): string {
  const d = new Date(iso)
  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), 1)).toISOString().slice(0, 10)
}
function monthsAgoStartUTC(iso: string, months: number): string {
  const d = new Date(iso)
  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() - months, 1)).toISOString().slice(0, 10)
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (req.method !== 'POST') return jsonResponse({ error: 'Method not allowed' }, 405)

  const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')

  const cronHeader = req.headers.get('x-cron-secret')
  let isCron = false
  if (cronHeader) {
    const { data: sec } = await supabase.from('app_secrets').select('value').eq('name', 'monitor_cron').maybeSingle()
    if (sec?.value && sec.value === cronHeader) isCron = true
  }
  if (!isCron) {
    const authHeader = req.headers.get('Authorization') ?? ''
    const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : ''
    const segments = token.split('.')
    if (segments.length === 3) {
      try {
        const payload = JSON.parse(atob(segments[1].replace(/-/g, '+').replace(/_/g, '/')))
        if (payload?.role === 'service_role') isCron = true
      } catch { /* token non décodable : ignoré */ }
    }
  }
  if (!isCron) return jsonResponse({ error: 'Forbidden' }, 403)

  const now = new Date()
  const nowIso = now.toISOString()
  const currentMonth = monthStartUTC(nowIso)
  const previousMonth = monthsAgoStartUTC(nowIso, 1)
  const engagementCutoff = new Date(now.getTime() - ENGAGEMENT_WINDOW_DAYS * DAY_MS).toISOString()

  const { data: companies, error: companiesErr } = await supabase
    .from('companies')
    .select('id, organization_id, account_type, account_settings(archived_at, relationship_status, primary_owner_user_id)')
  if (companiesErr) return jsonResponse({ error: companiesErr.message }, 500)

  let processed = 0
  let scored = 0
  const errors: Array<{ companyId: string; message: string }> = []

  for (const row of (companies ?? []) as any[]) {
    const companyId = String(row.id)
    const organizationId = String(row.organization_id)
    const settings = Array.isArray(row.account_settings) ? row.account_settings[0] : row.account_settings
    if (settings?.archived_at) continue // compte archivé : hors calcul (doctrine implicite, même filtre que account_brain)

    try {
      // scoring.* n'est pas un schéma exposé côté PostgREST (réglage projet, pas
      // une migration) : lu/écrit via des RPC public.* SECURITY DEFINER, même
      // schéma d'accès que public.account_brain — voir migration
      // account_weather_v6_scoring_schema_rpcs.
      const [contactsRes, kEventsRes, factsRes, rolesRes] = await Promise.all([
        supabase.from('contacts').select('id, owner_user_id').eq('company_id', companyId).is('merged_into_contact_id', null),
        supabase.rpc('get_account_k_marker_events', { p_company_id: companyId }),
        supabase.from('account_facts_live').select('status, resolved_at, is_overdue, occurred_at')
          .eq('company_id', companyId).eq('fact_type', 'commitment').gte('occurred_at', engagementCutoff),
        supabase.from('account_contact_roles').select('contact_id, decision_role').eq('company_id', companyId).eq('active', true),
      ])
      const contacts = (contactsRes.data ?? []) as Array<{ id: string; owner_user_id: string | null }>
      const contactIds = contacts.map((c) => c.id)
      // Rôle qualifié manuellement (UI existante) s'il existe, sinon repli Utilisateur (cf. authorityKeyFromRole).
      const roleByContact = new Map<string, string | null>()
      for (const r of (rolesRes.data ?? []) as Array<{ contact_id: string; decision_role: string | null }>) roleByContact.set(r.contact_id, r.decision_role)

      let messages: Array<{ contact_id: string; sent_at: string }> = []
      let meetingTimes: string[] = []
      if (contactIds.length > 0) {
        const { data } = await supabase.from('communication_messages').select('contact_id, sent_at').in('contact_id', contactIds)
        messages = (data ?? []) as typeof messages
      }
      {
        const { data } = await supabase.from('meetings').select('starts_at').eq('company_id', companyId)
        meetingTimes = ((data ?? []) as Array<{ starts_at: string }>).map((m) => m.starts_at)
      }

      // ── equilibreShares : volume réel de messages par contact ──────────
      const countByContact = new Map<string, number>()
      for (const msg of messages) countByContact.set(msg.contact_id, (countByContact.get(msg.contact_id) ?? 0) + 1)
      const equilibreShares = contactIds.map((id) => countByContact.get(id) ?? 0).filter((n) => n > 0)

      // ── Dyades V6 par contact : snapshot PERSISTÉ (scoring.score_snapshot,
      // entity_type='dyad') pour chaque contact ayant au moins un échange réel
      // — pas seulement ceux « actifs » côté compte. Réutilisé par la Fiche
      // Personne (get_dyad_weather_snapshot) ET par les cadrans Satisfaction/
      // Confiance & réciprocité du compte (activeDyads, dyades non cold-start
      // uniquement). Fiabilité : channelCoverage/identityResolution/
      // diarizationQuality fixées à 1 (non mesurables aujourd'hui, cf. audit
      // detectors.ts) — seul le volume réel de marqueurs fait varier la fiabilité.
      const activeDyads: AccountDyadInput[] = []
      const allPersonEvents: MarkerEvent[] = [] // pour les preuves affichées (Confiance/Satisfaction), jamais utilisé dans le calcul
      const messagesByContact = new Map<string, number[]>()
      for (const msg of messages) messagesByContact.set(msg.contact_id, [...(messagesByContact.get(msg.contact_id) ?? []), new Date(msg.sent_at).getTime()])
      for (const times of messagesByContact.values()) times.sort((a, b) => a - b)

      for (const contactId of contactIds) {
        const contactMessages = messagesByContact.get(contactId) ?? []
        if (contactMessages.length === 0) continue
        const ageDays = Math.max(0, Math.round((now.getTime() - contactMessages[0]!) / DAY_MS))
        const episodes = contactMessages.length
        const contactDaysSinceLast = Math.max(0, Math.round((now.getTime() - contactMessages[contactMessages.length - 1]!) / DAY_MS))
        const contactGaps = contactMessages.slice(1).map((t, i) => (t - contactMessages[i]!) / DAY_MS).sort((a, b) => a - b)
        const contactCadenceMedian = median(contactGaps)

        const { data: eventRows } = await supabase.rpc('get_person_marker_events', { p_contact_id: contactId })
        const events: MarkerEvent[] = ((eventRows ?? []) as Array<{ marker_id: string; sense: number; observed_at: string; evidence_ref: string; evidence_text?: string | null; is_verbatim?: boolean }>)
          .map((e) => ({
            markerId: e.marker_id, sense: (e.sense >= 0 ? 1 : -1) as -1 | 1, observedAt: e.observed_at, evidenceRef: e.evidence_ref,
            evidenceText: e.evidence_text ?? null, isVerbatim: e.is_verbatim ?? false,
          }))
        allPersonEvents.push(...events)

        const snapshot = buildDyadScoreSnapshot({
          markerEvents: events, role: UNQUALIFIED_ROLE, at: nowIso,
          context: { ageDays, episodes, daysSinceLast: contactDaysSinceLast, cadenceMedian: contactCadenceMedian, hasX02: false },
          reliabilityInputs: { channelCoverage: 1, identityResolution: 1, diarizationQuality: 1 },
          params: PARAMS_V6_PALIER, registry: REGISTRY_V6,
        })

        const { error: dyadErr } = await supabase.rpc('upsert_dyad_weather_snapshot', {
          p_organization_id: organizationId, p_contact_id: contactId, p_account_id: companyId,
          p_at: nowIso, p_snapshot_month: currentMonth,
          p_params_version: snapshot.paramsVersion, p_registry_version: snapshot.registryVersion,
          p_axes: snapshot.core?.axes ?? null, p_score: snapshot.score,
          p_reliability: snapshot.reliability, p_verdict_allowed: snapshot.verdictAllowed, p_status: snapshot.status,
        })
        if (dyadErr) throw new Error(`dyad ${contactId}: ${dyadErr.message}`)

        if (!snapshot.coldStart && snapshot.core) {
          const authority = PARAMS_V6_PALIER.authority[authorityKeyFromRole(roleByContact.get(contactId))] ?? PARAMS_V6_PALIER.authority.utilisateur!
          activeDyads.push({ contactId, authority, satisfaction: snapshot.core.axes.satisfaction.value, confiance: snapshot.core.axes.confiance.value, reciprocite: snapshot.core.axes.reciprocite.value })
        }
      }

      // ── carriers : porteurs internes réels distincts ───────────────────
      const carrierIds = new Set<string>()
      for (const c of contacts) if (c.owner_user_id) carrierIds.add(c.owner_user_id)
      if (settings?.primary_owner_user_id) carrierIds.add(settings.primary_owner_user_id)
      const carriers = carrierIds.size

      // ── dynamics : cadence/silence réels + engagements réels sur 90j ───
      const allTimes = [...messages.map((m) => m.sent_at), ...meetingTimes].map((t) => new Date(t).getTime()).filter((t) => Number.isFinite(t)).sort((a, b) => a - b)
      const daysSinceLast = allTimes.length ? Math.max(0, Math.round((now.getTime() - allTimes[allTimes.length - 1]!) / DAY_MS)) : 0
      const gaps = allTimes.slice(1).map((t, i) => (t - allTimes[i]!) / DAY_MS).sort((a, b) => a - b)
      const cadenceMedian = median(gaps)
      const facts = (factsRes.data ?? []) as Array<{ status: string | null; resolved_at: string | null; is_overdue: boolean | null }>
      const engagementsHeld = facts.filter((f) => f.resolved_at && !f.is_overdue).length
      const engagementsSlipped = facts.filter((f) => f.is_overdue).length

      // ── kEvents : marqueurs compte réels — agrégés par marker_id
      // (occurrences = nb de lignes non résolues ; K01 : ancienneté en mois
      // depuis la 1ère occurrence non résolue, pour le plafond "ouvert > 12
      // mois"). evidence_ref/evidence_text/observed_at proviennent de
      // scoring.marker_event — conservés pour la traçabilité « Preuves » de
      // la Météo, jamais utilisés dans le calcul lui-même.
      const kRows = (kEventsRes.data ?? []) as Array<{ marker_id: string; observed_at: string; evidence_ref?: string | null; evidence_text?: string | null; is_verbatim?: boolean }>
      const byMarker = new Map<string, Array<{ observedAt: string; evidenceRef: string | null; evidenceText: string | null; isVerbatim: boolean }>>()
      for (const k of kRows) byMarker.set(k.marker_id, [...(byMarker.get(k.marker_id) ?? []), { observedAt: k.observed_at, evidenceRef: k.evidence_ref ?? null, evidenceText: k.evidence_text ?? null, isVerbatim: k.is_verbatim ?? false }])
      const kEvents = [...byMarker.entries()].map(([markerId, occs]) => {
        const earliest = occs.reduce((a, b) => (a.observedAt < b.observedAt ? a : b))
        const openMonths = markerId === 'K01' ? Math.floor((now.getTime() - new Date(earliest.observedAt).getTime()) / (DAY_MS * 30.44)) : undefined
        return { markerId, observedAt: earliest.observedAt, resolvedAt: null, occurrences: occs.length, openMonths, evidenceRef: earliest.evidenceRef ?? '', evidenceText: earliest.evidenceText, isVerbatim: earliest.isVerbatim }
      })

      // ── coverage.targets : rôle qualifié (account_contact_roles) sinon repli
      // Utilisateur (0.3, décision produit actée) × niveau relationnel réel
      // dérivé du volume de messages (relationalLevelFromMessages). Porte sur
      // TOUS les contacts du compte, pas seulement les dyades actives — un
      // décideur jamais contacté doit faire baisser la Couverture.
      const coverageTargets: CoverageTarget[] = contacts.map((c) => {
        const authKey = authorityKeyFromRole(roleByContact.get(c.id))
        const relationalLevel = relationalLevelFromMessages(messagesByContact.get(c.id) ?? [], now.getTime())
        return { role: authKey, authority: PARAMS_V6_PALIER.authority[authKey] ?? PARAMS_V6_PALIER.authority.utilisateur!, covered: relationalLevel > 0, isDecider: authKey === 'decideur', relationalLevel }
      })

      // Aucun historique réel du tout : ne pas écrire de snapshot (rien à mesurer).
      if (allTimes.length === 0 && kEvents.length === 0 && carriers === 0 && coverageTargets.length === 0) { processed++; continue }

      const input: AccountWeatherInput = {
        relationType: toDialRelationType(settings?.relationship_status ?? null, row.account_type ?? null),
        activeDyads,
        coverage: { targets: coverageTargets },
        equilibreShares,
        carriers,
        kEvents,
        dynamics: { delta30OtherDials: 0, daysSinceLast, cadenceMedian, engagementsHeld, engagementsSlipped },
        at: nowIso,
      }
      const result = calculateAccountWeatherCore(input, PARAMS_V6_PALIER, REGISTRY_V6)

      // ── Preuves affichage Confiance/Satisfaction : les marqueurs personne
      // (C../R.. → Confiance, S.. → Satisfaction) qui ont réellement produit
      // les valeurs de dyade agrégées dans activeDyads. Purement pour le
      // panneau « Preuves » de l'UI — n'entre dans AUCUN calcul (le score du
      // cadran est déjà figé par wavg(activeDyads) ci-dessus).
      const evidenceModifiers = (axes: Array<'confiance' | 'reciprocite' | 'satisfaction'>): DialContribution[] =>
        allPersonEvents
          .filter((e) => { const entry = REGISTRY_V6.markers[e.markerId]; return entry && !entry.deprecatedAt && entry.axis && axes.includes(entry.axis as any) })
          .sort((a, b) => b.observedAt.localeCompare(a.observedAt))
          .slice(0, 15)
          .map((e) => ({
            markerId: e.markerId, pointsEffectifs: 0, occurrences: 1, repetitionMultiplier: 1,
            contribution: REGISTRY_V6.markers[e.markerId]?.sign || e.sense,
            evidenceRef: e.evidenceRef || null, observedAt: e.observedAt || null,
            evidenceText: e.evidenceText ?? null, isVerbatim: e.isVerbatim ?? false,
          }))
      result.dials.d_confiance_recip.modifiers = evidenceModifiers(['confiance', 'reciprocite'])
      result.dials.d_satisfaction.modifiers = [...result.dials.d_satisfaction.modifiers, ...evidenceModifiers(['satisfaction'])]

      const { data: prevScore } = await supabase.rpc('get_account_prev_weather_score', {
        p_company_id: companyId, p_snapshot_month: previousMonth,
        p_params_version: result.paramsVersion, p_registry_version: result.registryVersion,
      })
      const delta30d = prevScore != null && result.score != null ? result.score - Number(prevScore) : null

      const { error: upsertErr } = await supabase.rpc('upsert_account_weather_snapshot', {
        p_organization_id: organizationId,
        p_company_id: companyId,
        p_at: nowIso,
        p_snapshot_month: currentMonth,
        p_params_version: result.paramsVersion,
        p_registry_version: result.registryVersion,
        p_dials: result.dials,
        p_score: result.score,
        p_weakest_dial: result.weakestDial,
        p_delta_30d: delta30d,
      })
      if (upsertErr) throw new Error(upsertErr.message)

      scored++
      processed++
    } catch (err) {
      errors.push({ companyId, message: err instanceof Error ? err.message : String(err) })
      processed++
    }
  }

  return jsonResponse({ processed, scored, errors })
})

// Copie exacte de src/services/scoring/calculateAccountWeatherCore.ts — voir
// le commentaire de types.ts dans ce même dossier pour la raison de cette
// duplication. Fonction PURE : aucune DB, aucun LLM, aucune fiabilité.
// Reproduit exactement reference_account_v6 (Météo 33).

import type {
  AccountKEvent, AccountWeatherCoreResult, AccountWeatherInput, DialContribution,
  DialId, DialResult, MarkerRegistry, ScoringParams,
} from './types.ts'
import { relationTypeStatus } from './registry-v6.ts'

const DIALS: DialId[] = ['d_satisfaction', 'd_confiance_recip', 'd_couverture', 'd_equilibre', 'd_ancrage', 'd_dynamique']
const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))

function repMult(occurrences: number, params: ScoringParams): number {
  if (occurrences >= 4) return params.repetition.occ4plus
  if (occurrences >= 2) return params.repetition.occ2to3
  return params.repetition.occ1
}

function kPoints(markerId: string, params: ScoringParams, registry: MarkerRegistry): number {
  const entry = registry.markers[markerId]
  if (!entry) return 0
  if (params.mode === 'spec') return entry.ptsSpec ?? 0
  const t = params.tiers[entry.tier]
  return entry.sign < 0 ? t.neg : entry.sign > 0 ? t.pos : 0
}

function interp3(x: number, xa: number, va: number, xb: number, vb: number, xc: number, vc: number): number {
  if (xa < xc) {
    if (x <= xa) return va
    if (x <= xb) return va + (x - xa) / (xb - xa) * (vb - va)
    if (x <= xc) return vb + (x - xb) / (xc - xb) * (vc - vb)
    return vc
  }
  if (x >= xa) return va
  if (x >= xb) return vb + (x - xb) / (xa - xb) * (va - vb)
  if (x >= xc) return vc + (x - xc) / (xb - xc) * (vb - vc)
  return vc
}

function wavg(items: Array<{ authority: number }>, valueFn: (i: any) => number): number | null {
  const wsum = items.reduce((s, i) => s + i.authority, 0)
  if (wsum <= 0) return null
  return items.reduce((s, i) => s + i.authority * valueFn(i), 0) / wsum
}

function kModifiers(kEvents: AccountKEvent[], params: ScoringParams, registry: MarkerRegistry) {
  const byDial = new Map<DialId, DialContribution[]>()
  let capK06 = false
  let capK01 = false
  for (const ke of kEvents) {
    if (ke.resolvedAt) continue
    const entry = registry.markers[ke.markerId]
    if (!entry || entry.scope !== 'account' || !entry.dial) continue
    if (ke.markerId === 'K06') capK06 = true
    if (ke.markerId === 'K01' && (ke.openMonths ?? 0) > params.dynamics.k01CapMonths) capK01 = true
    const pts = kPoints(ke.markerId, params, registry)
    const rep = repMult(ke.occurrences ?? 1, params)
    const contribution = pts * rep
    const list = byDial.get(entry.dial) ?? []
    list.push({
      markerId: ke.markerId, pointsEffectifs: pts, occurrences: ke.occurrences ?? 1, repetitionMultiplier: rep, contribution,
      evidenceRef: ke.evidenceRef || null, observedAt: ke.observedAt || null,
      evidenceText: ke.evidenceText ?? null, isVerbatim: ke.isVerbatim ?? false,
    })
    byDial.set(entry.dial, list)
  }
  return { byDial, capK06, capK01 }
}

export function calculateAccountWeatherCore(
  input: AccountWeatherInput,
  params: ScoringParams,
  registry: MarkerRegistry,
): AccountWeatherCoreResult {
  const km = kModifiers(input.kEvents, params, registry)
  const mod = (d: DialId) => (km.byDial.get(d) ?? [])
  const modSum = (d: DialId) => mod(d).reduce((s, c) => s + c.contribution, 0)

  const dials = {} as Record<DialId, DialResult>
  const weights = params.dialWeights[input.relationType] ?? params.dialWeights['Client/Prospect']!

  {
    const base = wavg(input.activeDyads, (d) => d.satisfaction)
    let value: number | null = null
    let cappedBy: string | null = null
    if (base !== null) {
      value = clamp(Math.round(base + modSum('d_satisfaction')), 0, 100)
      if (km.capK06) { value = Math.min(value, params.dynamics.k06Cap); cappedBy = 'K06' }
    }
    dials.d_satisfaction = mkDial('d_satisfaction', base, value, weights.d_satisfaction, cappedBy, mod('d_satisfaction'))
  }
  {
    const base = wavg(input.activeDyads, (d) => (d.confiance + d.reciprocite) / 2)
    const value = base === null ? null : clamp(Math.round(base), 0, 100)
    dials.d_confiance_recip = mkDial('d_confiance_recip', base, value, weights.d_confiance_recip, null, [])
  }
  {
    const targets = input.coverage.targets
    const sumTargets = targets.reduce((s, t) => s + t.authority, 0)
    let base: number | null = null
    let value: number | null = null
    let cappedBy: string | null = null
    if (sumTargets > 0) {
      const sumCovered = targets.reduce((s, t) => s + t.authority * (t.relationalLevel ?? (t.covered ? 1 : 0)), 0)
      base = 100 * sumCovered / sumTargets
      let v = base + (input.coverage.rcsChangeUnreflected ? params.coverage.malusRcsUnreflected : 0)
      const deciderWithoutDyad = targets.some((t) => t.isDecider && !t.covered)
      if (deciderWithoutDyad) { v = Math.min(v, params.coverage.capDeciderNoDyad); cappedBy = 'décideur sans dyade' }
      value = clamp(Math.round(v), 0, 100)
    }
    dials.d_couverture = mkDial('d_couverture', base, value, weights.d_couverture, cappedBy, [])
  }
  {
    const shares = input.equilibreShares
    let value: number | null = null
    let base: number | null = null
    if (shares.length === 0) { /* null */ }
    else if (shares.length === 1) { base = 0; value = 0 }
    else {
      const total = shares.reduce((s, x) => s + x, 0)
      if (total > 0) {
        const hhi = shares.reduce((s, x) => s + (x / total) ** 2, 0)
        base = 100 * (1 - hhi)
        value = clamp(Math.round(base), 0, 100)
      }
    }
    dials.d_equilibre = mkDial('d_equilibre', base, value, weights.d_equilibre, null, [])
  }
  {
    const c = input.carriers
    const base = c <= 0 ? params.anchoring[0] : c === 1 ? params.anchoring[1] : c === 2 ? params.anchoring[2] : params.anchoring.threePlus
    const value = clamp(Math.round(base + modSum('d_ancrage')), 0, 100)
    dials.d_ancrage = mkDial('d_ancrage', base, value, weights.d_ancrage, null, mod('d_ancrage'))
  }
  {
    const dy = input.dynamics
    const a = params.dynamics
    const pente = interp3(dy.delta30OtherDials, a.penteAnchors.deltaHigh, a.penteAnchors.vHigh, a.penteAnchors.deltaMid, a.penteAnchors.vMid, a.penteAnchors.deltaLow, a.penteAnchors.vLow)
    const ratio = dy.cadenceMedian > 0 ? dy.daysSinceLast / dy.cadenceMedian : (dy.daysSinceLast > 0 ? 99 : 0)
    const silence = interp3(ratio, a.silenceAnchors.r1, a.silenceAnchors.v1, a.silenceAnchors.r2, a.silenceAnchors.v2, a.silenceAnchors.r3, a.silenceAnchors.v3)
    const solde = clamp(a.solde.base + a.solde.step * (dy.engagementsHeld - dy.engagementsSlipped), 0, 100)
    const base = a.weights.pente * pente + a.weights.silence * silence + a.weights.solde * solde
    let cappedBy: string | null = null
    let v = base + modSum('d_dynamique')
    if (km.capK01) { v = Math.min(v, params.dynamics.k01Cap); cappedBy = 'K01>12mois' }
    const value = clamp(Math.round(v), 0, 100)
    const d = mkDial('d_dynamique', Math.round(base), value, weights.d_dynamique, cappedBy, mod('d_dynamique'))
    d.note = `pente=${Math.round(pente)} · silence=${Math.round(silence)} · solde=${Math.round(solde)}`
    d.trendDelta30d = Math.round(dy.delta30OtherDials)
    dials.d_dynamique = d
  }

  const calculable = DIALS.filter((d) => dials[d].value !== null)
  let score: number | null = null
  let weakestDial: DialId | null = null
  if (calculable.length > 0) {
    const wsum = calculable.reduce((s, d) => s + dials[d].weight, 0)
    for (const d of DIALS) dials[d].effectiveWeight = dials[d].value === null ? 0 : dials[d].weight / wsum
    if (calculable.length < DIALS.length) for (const d of calculable) dials[d].note = (dials[d].note ? dials[d].note + ' · ' : '') + 'poids redistribué'
    score = Math.round(calculable.reduce((s, d) => s + (dials[d].value as number) * dials[d].effectiveWeight, 0))
    weakestDial = calculable.reduce((min, d) => (dials[d].value as number) < (dials[min].value as number) ? d : min, calculable[0]!)
  }

  return {
    score,
    dials,
    weakestDial,
    relationType: input.relationType,
    relationTypeStatus: relationTypeStatus(input.relationType),
    paramsVersion: params.version,
    registryVersion: registry.version,
    mode: params.mode,
  }
}

function mkDial(dial: DialId, base: number | null, value: number | null, weight: number, cappedBy: string | null, modifiers: DialContribution[]): DialResult {
  return { dial, base, value, weight, effectiveWeight: 0, cappedBy, modifiers }
}

// Copie PARTIELLE (dyade uniquement) de src/services/scoring/snapshots.ts —
// voir le commentaire de types.ts dans ce même dossier pour la raison de
// cette duplication. Couche SNAPSHOT dyade : fenêtre, P5 (cold start), P7
// (verdict), fiabilité, statut cadence — jamais inventés silencieusement.

import { calculateDyadScoreCore } from './calculateDyadScoreCore.ts'
import type { DyadRole, DyadScoreCoreResult, MarkerEvent, MarkerRegistry, ScoringParams } from './types.ts'

export const RELIABILITY_PARAMS_V1 = {
  version: 'reliability_params-v1',
  status: 'provisional' as const,
  volumeSaturationMarkers: 8,
  x01Cap: 0.6,
  significantDialWeight: 0.15,
  thresholds: { verdict: 0.60, amber: 0.50 },
  p5AgeMinDays: 30, p5EpisodesMin: 5, p7MarkersMin: 5,
  cadence: { actif: 1.5, ralenti: 3, rompu: 6 },
}

const clamp01 = (x: number) => Math.max(0, Math.min(1, Number.isFinite(x) ? x : 0))

export type RelationalStatus = 'actif' | 'ralenti' | 'dormant' | 'rompu' | 'cold_start'

export function statusFromCadence(daysSinceLast: number, cadenceMedian: number, hasX02: boolean): RelationalStatus {
  if (hasX02) return 'rompu'
  if (cadenceMedian <= 0) return 'actif'
  const ratio = daysSinceLast / cadenceMedian
  const c = RELIABILITY_PARAMS_V1.cadence
  if (ratio > c.rompu) return 'rompu'
  if (ratio > c.ralenti) return 'dormant'
  if (ratio >= c.actif) return 'ralenti'
  return 'actif'
}

export interface DyadReliabilityInputs {
  channelCoverage: number
  identityResolution: number
  diarizationQuality: number
  markerCount: number
  hasX01: boolean
}

export function reliabilityDyad(r: DyadReliabilityInputs): number {
  const volume = clamp01(r.markerCount / RELIABILITY_PARAMS_V1.volumeSaturationMarkers)
  let rel = clamp01(r.channelCoverage) * volume * clamp01(r.identityResolution) * clamp01(r.diarizationQuality)
  if (r.hasX01) rel = Math.min(rel, RELIABILITY_PARAMS_V1.x01Cap)
  return clamp01(rel)
}

export interface DyadSnapshotInput {
  markerEvents: MarkerEvent[]
  role: DyadRole
  at: string
  context: { ageDays: number; episodes: number; daysSinceLast: number; cadenceMedian: number; hasX02: boolean }
  reliabilityInputs: Omit<DyadReliabilityInputs, 'markerCount'>
  params: ScoringParams
  registry: MarkerRegistry
}

export interface DyadSnapshot {
  entityType: 'dyad'
  at: string
  score: number | null
  reliability: number
  verdictAllowed: boolean
  status: RelationalStatus
  coldStart: boolean
  markerCount: number
  core: DyadScoreCoreResult | null
  paramsVersion: string
  registryVersion: string
  reliabilityParamsVersion: string
}

export function buildDyadScoreSnapshot(input: DyadSnapshotInput): DyadSnapshot {
  const { at, params, registry } = input
  const atMs = new Date(at).getTime()
  const windowed = input.markerEvents.filter((e) => new Date(e.observedAt).getTime() <= atMs)
  const markerCount = windowed.length

  const reliability = reliabilityDyad({ ...input.reliabilityInputs, markerCount })
  const p5 = input.context.ageDays < RELIABILITY_PARAMS_V1.p5AgeMinDays || input.context.episodes < RELIABILITY_PARAMS_V1.p5EpisodesMin
  const status = p5 ? 'cold_start' : statusFromCadence(input.context.daysSinceLast, input.context.cadenceMedian, input.context.hasX02)

  if (p5) {
    return {
      entityType: 'dyad', at, score: null, reliability, verdictAllowed: false, status, coldStart: true,
      markerCount, core: null, paramsVersion: params.version, registryVersion: registry.version,
      reliabilityParamsVersion: RELIABILITY_PARAMS_V1.version,
    }
  }

  const core = calculateDyadScoreCore(windowed, input.role, params, registry)
  return {
    entityType: 'dyad', at, score: core.score, reliability,
    verdictAllowed: markerCount >= RELIABILITY_PARAMS_V1.p7MarkersMin,
    status, coldStart: false, markerCount, core,
    paramsVersion: params.version, registryVersion: registry.version,
    reliabilityParamsVersion: RELIABILITY_PARAMS_V1.version,
  }
}

export function displayRule(reliability: number, verdictAllowed: boolean): 'score_and_verdict' | 'score_amber' | 'score_greyed_no_verdict' {
  if (reliability < RELIABILITY_PARAMS_V1.thresholds.amber) return 'score_greyed_no_verdict'
  if (!verdictAllowed) return 'score_greyed_no_verdict'
  if (reliability < RELIABILITY_PARAMS_V1.thresholds.verdict) return 'score_amber'
  return 'score_and_verdict'
}

// Copie exacte de src/services/scoring/calculateDyadScoreCore.ts — voir le
// commentaire de types.ts dans ce même dossier pour la raison de cette
// duplication. Fonction PURE : mêmes entrées → mêmes sorties.

import type {
  AxisId, DyadRole, DyadScoreCoreResult, MarkerContribution, MarkerEvent,
  MarkerRegistry, MarkerRegistryEntry, ScoringParams,
} from './types.ts'

const AXES: AxisId[] = ['confiance', 'satisfaction', 'engagement', 'reciprocite', 'ancrage']
const clamp = (v: number, min: number, max: number) => Math.max(min, Math.min(max, v))
const signOf = (v: number): -1 | 0 | 1 => (v > 0 ? 1 : v < 0 ? -1 : 0)

function effectivePoints(entry: MarkerRegistryEntry, sense: -1 | 1, params: ScoringParams): number {
  const effSign: -1 | 1 = entry.sign !== 0 ? entry.sign : sense
  if (params.mode === 'spec') {
    const spec = entry.ptsSpec ?? 0
    return entry.sign !== 0 ? spec : Math.abs(spec) * effSign
  }
  const tier = params.tiers[entry.tier]
  return effSign > 0 ? tier.pos : tier.neg
}

function renormVolontarite(volBase: number, role: DyadRole, params: ScoringParams): number {
  const table = role.volontariteProfile === 'execution' ? params.volontarite.execution : params.volontarite
  if (volBase === 0.3) return table.prescrit
  if (volBase === 0.6) return table.semi
  if (volBase === 1.0) return table.volontaire
  return volBase
}

function repetitionMultiplier(occurrences: number, params: ScoringParams): number {
  if (occurrences >= 4) return params.repetition.occ4plus
  if (occurrences >= 2) return params.repetition.occ2to3
  return params.repetition.occ1
}

export function calculateDyadScoreCore(
  markerEvents: MarkerEvent[],
  role: DyadRole,
  params: ScoringParams,
  registry: MarkerRegistry,
): DyadScoreCoreResult {
  const axes = {} as DyadScoreCoreResult['axes']

  for (const axis of AXES) {
    const axisEvents = markerEvents.filter((event) => {
      const entry = registry.markers[event.markerId]
      return entry && !entry.deprecatedAt && entry.axis === axis
    })

    if (axisEvents.length === 0) {
      axes[axis] = { axis, base: 50, value: 50, weight: params.axisWeights[axis], cappedByS07: false, contributions: [] }
      continue
    }

    const groups = new Map<string, { entry: MarkerRegistryEntry; sense: -1 | 1; count: number }>()
    for (const event of axisEvents) {
      const entry = registry.markers[event.markerId]!
      const sense: -1 | 1 = entry.sign !== 0 ? (entry.sign as -1 | 1) : event.sense
      const key = `${event.markerId}|${sense}`
      const g = groups.get(key)
      if (g) g.count += 1
      else groups.set(key, { entry, sense, count: 1 })
    }

    const raw: Array<Omit<MarkerContribution, 'rank' | 'decayMultiplier' | 'contributionFinale'>> = []
    for (const { entry, sense, count } of groups.values()) {
      const pts = effectivePoints(entry, sense, params)
      const vol = renormVolontarite(entry.volBase, role, params)
      const rep = repetitionMultiplier(count, params)
      const magnitude = Math.abs(pts) * vol * rep
      raw.push({ markerId: entry.markerId, sense, occurrences: count, pointsEffectifs: pts, volontarite: vol, repetitionMultiplier: rep, magnitude })
    }

    raw.sort((a, b) => (b.magnitude - a.magnitude) || a.markerId.localeCompare(b.markerId))

    const contributions: MarkerContribution[] = raw.map((c, index) => {
      const decayMultiplier = params.decay[Math.min(index, params.decay.length - 1)] ?? params.decay[params.decay.length - 1] ?? 1
      const contributionFinale = signOf(c.pointsEffectifs) * c.magnitude * decayMultiplier
      return { ...c, rank: index + 1, decayMultiplier, contributionFinale }
    })

    const total = contributions.reduce((sum, c) => sum + c.contributionFinale, 0)
    let value = clamp(Math.round(50 + total), 0, 100)

    const cappedByS07 = axis === 'satisfaction' && axisEvents.some((e) => e.markerId === 'S07')
    if (cappedByS07) value = Math.min(value, 20)

    axes[axis] = { axis, base: 50, value, weight: params.axisWeights[axis], cappedByS07, contributions }
  }

  const score = Math.round(AXES.reduce((sum, axis) => sum + axes[axis].value * axes[axis].weight, 0))

  return {
    score,
    axes,
    role,
    paramsVersion: params.version,
    registryVersion: registry.version,
    mode: params.mode,
  }
}

// classify-markers — Classificateur sémantique (DÉTECTEUR, jamais un score).
// Opère sur les EXTRAITS déjà dérivés (person_key_moments.summary /
// person_memory_entries[commitment].source_excerpt) — les corps bruts ne sont pas
// stockés. Registre FERMÉ ; le LLM répond marker_id∈registre | NO_MARKER + confidence ;
// jamais un nombre d'axe. Persiste des scoring.marker_event (is_candidate selon les
// garde-fous : verbatim obligatoire S07, seuil de confiance). Idempotent (dedup_key).
// Logique validée par src/services/scoring/__tests__/semanticClassifier.test.ts.
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const cors = { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-cron-secret', 'Access-Control-Allow-Methods': 'POST, OPTIONS' }
const json = (b: unknown, s = 200) => new Response(JSON.stringify(b), { status: s, headers: { ...cors, 'Content-Type': 'application/json' } })

const REGISTRY: Record<string, { sense: -1 | 1; requiresVerbatim: boolean; def: string }> = {
  C01: { sense: 1, requiresVerbatim: false, def: 'divulgation interne/personnelle non nécessaire à la tâche' },
  C05: { sense: 1, requiresVerbatim: false, def: 'jugement personnel partagé sur un tiers absent' },
  S03: { sense: -1, requiresVerbatim: false, def: 'appréciation négative explicite' },
  S06: { sense: -1, requiresVerbatim: false, def: 'désintermédiation / contournement direct' },
  S07: { sense: -1, requiresVerbatim: true, def: 'dénonciation auprès d’un tiers (verbatim obligatoire)' },
  S08: { sense: 1, requiresVerbatim: false, def: 'éloge spontané, non sollicité, hors politesse' },
  E01: { sense: 1, requiresVerbatim: false, def: 'mise en relation avec un tiers de son réseau' },
  E02: { sense: 1, requiresVerbatim: false, def: 'ouverture d’organigramme / accès à collègues/hiérarchie' },
  E03: { sense: 1, requiresVerbatim: false, def: 'projection au-delà de l’engagement courant' },
  E04: { sense: 1, requiresVerbatim: false, def: 'artefact / livrable non demandé' },
}
const ACCEPT = 0.75, VERSION = 'semantic-classifier-v1'

function prompt(text: string): string {
  const reg = Object.entries(REGISTRY).map(([id, r]) => `- ${id} : ${r.def} (sens ${r.sense >= 0 ? '+' : '−'})`).join('\n')
  return `Tu es un DÉTECTEUR de marqueurs relationnels. Tu ne produis JAMAIS de score.
Indique si l'extrait correspond EXACTEMENT à UN marqueur du REGISTRE FERMÉ, sinon NO_MARKER.
Choisis UNIQUEMENT dans cette liste (aucune invention) :
${reg}

Extrait : « ${text} »
Réponds en JSON strict : {"marker_id":"<ID>|NO_MARKER","confidence":0..1,"rationale":"<1 phrase>"}
Si tu hésites : NO_MARKER.`
}

async function classify(text: string, apiKey: string, model: string): Promise<{ marker_id: string; confidence: number; rationale: string } | null> {
  const res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
    method: 'POST', headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json', 'X-Title': 'Tohu Semantic Classifier' },
    body: JSON.stringify({ model, temperature: 0, max_tokens: 200, response_format: { type: 'json_object' }, messages: [{ role: 'user', content: prompt(text) }] }),
  })
  if (!res.ok) return null
  const data = await res.json()
  try { return JSON.parse(String(data.choices?.[0]?.message?.content ?? '{}')) } catch { return null }
}

// Cron secret : même mécanique que score-batch-account-v6 (x-cron-secret contre
// public.app_secrets, ou service_role JWT) — accepté en plus de l'appel manuel
// authentifié existant, pour permettre l'invocation automatique généralisée.
async function isAuthorized(req: Request, supabase: ReturnType<typeof createClient>): Promise<boolean> {
  const cronHeader = req.headers.get('x-cron-secret')
  if (cronHeader) {
    const { data: sec } = await supabase.from('app_secrets').select('value').eq('name', 'monitor_cron').maybeSingle()
    if (sec?.value && sec.value === cronHeader) return true
  }
  const authHeader = req.headers.get('Authorization') ?? ''
  const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : ''
  const segments = token.split('.')
  if (segments.length === 3) {
    try {
      const payload = JSON.parse(atob(segments[1].replace(/-/g, '+').replace(/_/g, '/')))
      if (payload?.role === 'service_role') return true
    } catch { /* token non décodable : ignoré */ }
  }
  return false
}

async function classifyOrganization(
  supabase: ReturnType<typeof createClient>, organizationId: string, companyId: string | null, limit: number, apiKey: string, model: string,
) {
  // Extraits : moments (summary, pas verbatim) + engagements (source_excerpt = verbatim)
  const [{ data: moments }, { data: commitments }] = await Promise.all([
    supabase.from('person_key_moments').select('id, contact_id, occurred_at, summary, contacts!inner(company_id, organization_id)')
      .eq('contacts.organization_id', organizationId).limit(limit),
    supabase.from('person_memory_entries').select('id, contact_id, observed_at, source_occurred_at, source_excerpt, contacts!inner(company_id, organization_id)')
      .eq('contacts.organization_id', organizationId).eq('entry_type', 'commitment').limit(limit),
  ])
  const items: Array<{ id: string; contactId: string; companyId: string; text: string; observedAt: string | null; hasVerbatim: boolean }> = []
  for (const m of moments ?? []) {
    const co = (m as any).contacts?.company_id
    if (!co || (companyId && co !== companyId) || !m.summary) continue
    items.push({ id: String(m.id), contactId: String(m.contact_id), companyId: co, text: String(m.summary), observedAt: m.occurred_at as string, hasVerbatim: false })
  }
  for (const e of commitments ?? []) {
    const co = (e as any).contacts?.company_id
    if (!co || (companyId && co !== companyId) || !e.source_excerpt) continue
    items.push({ id: String(e.id), contactId: String(e.contact_id), companyId: co, text: String(e.source_excerpt), observedAt: (e.source_occurred_at ?? e.observed_at) as string, hasVerbatim: true })
  }

  // scoring.marker_event vit dans un schéma non exposé à PostgREST (comme pour
  // score-batch-account-v6) : écriture exclusivement via la RPC public.*
  // SECURITY DEFINER, jamais .schema('scoring').from(...) qui échoue en
  // PGRST106 (schéma non exposé) — silencieusement, si l'erreur n'est pas lue.
  let accepted = 0, candidates = 0, noMarker = 0
  const events: Array<Record<string, unknown>> = []
  for (const it of items) {
    const r = await classify(it.text, apiKey, model)
    const id = (r?.marker_id ?? '').trim()
    if (!id || id === 'NO_MARKER' || !REGISTRY[id] || !it.observedAt) { noMarker++; continue }
    const entry = REGISTRY[id]!
    const confidence = Math.max(0, Math.min(1, Number(r?.confidence) || 0))
    let isCandidate = confidence < ACCEPT
    if (entry.requiresVerbatim && !it.hasVerbatim) isCandidate = true
    isCandidate ? candidates++ : accepted++
    events.push({
      marker_id: id, contact_id: it.contactId, account_id: it.companyId, observed_at: it.observedAt, sense: entry.sense,
      measure: { confidence, rationale: String(r?.rationale ?? '').slice(0, 240) }, source: 'classifier:extract',
      evidence_ref: it.id, evidence_text: it.text.slice(0, 500), detector_version: VERSION, is_candidate: isCandidate,
      // is_verbatim : source_excerpt (commitment, hasVerbatim=true) = extrait garanti fidèle ;
      // person_key_moments.summary (hasVerbatim=false) = paraphrase LLM, jamais présentée comme verbatim.
      is_verbatim: it.hasVerbatim,
      dedup_key: `sem:${id}:${it.id}`,
    })
  }
  let inserted = 0
  if (events.length > 0) {
    const { data, error } = await supabase.rpc('upsert_person_marker_events', { p_organization_id: organizationId, p_events: events })
    if (error) console.error('upsert_person_marker_events', error.message)
    else inserted = Number(data) || 0
  }
  return { analyzed: items.length, accepted, candidates, no_marker: noMarker, inserted }
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: cors })
  if (req.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
  const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')
  const body = await req.json().catch(() => ({}))
  const organizationId = typeof body.organizationId === 'string' ? body.organizationId : null
  const companyId = typeof body.companyId === 'string' ? body.companyId : null
  const limit = Math.min(Number(body.limit) || 40, 100)
  const apiKey = Deno.env.get('OPENROUTER_API_KEY')
  if (!apiKey) return json({ error: 'OPENROUTER_API_KEY non configurée' }, 500)
  const model = Deno.env.get('OPENROUTER_ANALYSIS_MODEL') ?? 'google/gemini-3.1-flash-lite'

  // organizationId explicite : appel manuel ciblé (comportement historique, inchangé).
  if (organizationId) {
    const result = await classifyOrganization(supabase, organizationId, companyId, limit, apiKey, model)
    return json(result)
  }

  // Sans organizationId : invocation généralisée (cron), même mécanique d'auth
  // que score-batch-account-v6 — toutes les organisations, une à une.
  if (!(await isAuthorized(req, supabase))) return json({ error: 'Forbidden' }, 403)
  const { data: orgs, error: orgsErr } = await supabase.from('organizations').select('id')
  if (orgsErr) return json({ error: orgsErr.message }, 500)

  let orgsProcessed = 0
  const totals = { analyzed: 0, accepted: 0, candidates: 0, no_marker: 0, inserted: 0 }
  const errors: Array<{ organizationId: string; message: string }> = []
  for (const org of (orgs ?? []) as Array<{ id: string }>) {
    try {
      const r = await classifyOrganization(supabase, String(org.id), null, limit, apiKey, model)
      totals.analyzed += r.analyzed; totals.accepted += r.accepted; totals.candidates += r.candidates
      totals.no_marker += r.no_marker; totals.inserted += r.inserted
      orgsProcessed++
    } catch (err) {
      errors.push({ organizationId: String(org.id), message: err instanceof Error ? err.message : String(err) })
    }
  }
  return json({ orgsProcessed, ...totals, errors })
})

// Détecte les marqueurs personne (V6, scope='person') à partir des données
// RÉELLES de communication_messages/meetings, via les détecteurs déterministes
// PURS déjà écrits et testés (src/services/scoring/detectors.ts, copie Deno
// dans _shared/scoring-v6/detectors.ts). Alimente scoring.marker_event pour que
// score-batch-account-v6 puisse calculer de vrais scores de dyade (Satisfaction,
// Confiance & réciprocité) — jamais de marqueur fabriqué : un contact sans
// historique suffisant ne produit simplement aucun draft.
//
// Ne persiste que des drafts déterministes (S04/R01/R02/A01/A02/E05) —
// aucun appel LLM ici (voir classify-markers pour le volet sémantique,
// non câblé à ce jour). `status==='candidate'` est écrit avec is_candidate=true
// (traçabilité) mais n'entre jamais dans le calcul tant que non validé
// (cf. index scoring.marker_event_scoreable, filtré côté get_person_marker_events).

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { runDeterministicDetectors, type DyadMeeting, type DyadMessage } from '../_shared/scoring-v6/detectors.ts'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-cron-secret',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}
function jsonResponse(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (req.method !== 'POST') return jsonResponse({ error: 'Method not allowed' }, 405)

  const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')

  const cronHeader = req.headers.get('x-cron-secret')
  let isCron = false
  if (cronHeader) {
    const { data: sec } = await supabase.from('app_secrets').select('value').eq('name', 'monitor_cron').maybeSingle()
    if (sec?.value && sec.value === cronHeader) isCron = true
  }
  if (!isCron) {
    const authHeader = req.headers.get('Authorization') ?? ''
    const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : ''
    const segments = token.split('.')
    if (segments.length === 3) {
      try {
        const payload = JSON.parse(atob(segments[1].replace(/-/g, '+').replace(/_/g, '/')))
        if (payload?.role === 'service_role') isCron = true
      } catch { /* token non décodable : ignoré */ }
    }
  }
  if (!isCron) return jsonResponse({ error: 'Forbidden' }, 403)

  const now = new Date()

  const { data: companies, error: companiesErr } = await supabase
    .from('companies')
    .select('id, organization_id, account_settings(archived_at)')
  if (companiesErr) return jsonResponse({ error: companiesErr.message }, 500)

  let contactsProcessed = 0
  let eventsWritten = 0
  const errors: Array<{ companyId: string; message: string }> = []

  for (const row of (companies ?? []) as any[]) {
    const companyId = String(row.id)
    const organizationId = String(row.organization_id)
    const settings = Array.isArray(row.account_settings) ? row.account_settings[0] : row.account_settings
    if (settings?.archived_at) continue

    try {
      const { data: contacts } = await supabase.from('contacts').select('id')
        .eq('company_id', companyId).is('merged_into_contact_id', null)
      const contactIds = (contacts ?? []).map((c: any) => String(c.id))
      if (contactIds.length === 0) continue

      const [{ data: messages }, { data: participations }] = await Promise.all([
        supabase.from('communication_messages').select('id, contact_id, thread_id, direction, sent_at, subject').in('contact_id', contactIds),
        supabase.from('meeting_participants').select('contact_id, meeting_id, meetings(id, starts_at, ends_at)').in('contact_id', contactIds),
      ])

      const messagesByContact = new Map<string, DyadMessage[]>()
      for (const m of (messages ?? []) as any[]) {
        const list = messagesByContact.get(String(m.contact_id)) ?? []
        list.push({ id: String(m.id), threadId: String(m.thread_id), direction: m.direction, sentAt: m.sent_at, subject: m.subject })
        messagesByContact.set(String(m.contact_id), list)
      }
      const meetingsByContact = new Map<string, DyadMeeting[]>()
      for (const p of (participations ?? []) as any[]) {
        const meeting = Array.isArray(p.meetings) ? p.meetings[0] : p.meetings
        if (!meeting?.starts_at) continue
        const list = meetingsByContact.get(String(p.contact_id)) ?? []
        list.push({
          id: String(meeting.id), startsAt: meeting.starts_at,
          occurred: meeting.ends_at ? new Date(meeting.ends_at).getTime() < now.getTime() : new Date(meeting.starts_at).getTime() < now.getTime(),
          contactParticipated: true, // présence dans meeting_participants = seule preuve fiable (accept/decline non capté, cf. audit detectors.ts)
        })
        meetingsByContact.set(String(p.contact_id), list)
      }

      const events: Array<Record<string, unknown>> = []
      for (const contactId of contactIds) {
        const msgs = messagesByContact.get(contactId) ?? []
        const meets = meetingsByContact.get(contactId) ?? []
        if (msgs.length === 0 && meets.length === 0) continue
        const { drafts } = runDeterministicDetectors(msgs, meets, now.getTime())
        for (const d of drafts) {
          events.push({
            marker_id: d.markerId, contact_id: contactId, account_id: companyId,
            observed_at: d.observedAt, sense: d.sense, measure: d.measure, source: `detector:${d.detectorVersion}`,
            evidence_ref: d.evidenceRef, evidence_text: d.evidenceText, detector_version: d.detectorVersion,
            is_candidate: d.status === 'candidate',
            dedup_key: `det:${d.detectorVersion}:${d.markerId}:${contactId}:${d.evidenceRef}`,
          })
        }
        contactsProcessed++
      }

      if (events.length > 0) {
        const { data: inserted, error: upsertErr } = await supabase.rpc('upsert_person_marker_events', {
          p_organization_id: organizationId, p_events: events,
        })
        if (upsertErr) throw new Error(upsertErr.message)
        eventsWritten += Number(inserted ?? 0)
      }
    } catch (err) {
      errors.push({ companyId, message: err instanceof Error ? err.message : String(err) })
    }
  }

  return jsonResponse({ contactsProcessed, eventsWritten, errors })
})

// Copie exacte de src/services/scoring/detectors.ts — voir le commentaire de
// types.ts dans ce même dossier pour la raison de cette duplication.
// Détecteurs DÉTERMINISTES V6 — purs, sans DB/LLM. Produisent des marker_event
// « drafts » (preuve + date obligatoires) à partir des données RÉELLES disponibles
// (communication_messages, meetings). Un draft n'entre PAS dans le score tant qu'il
// n'est pas persisté ; un draft `candidate` n'entre jamais tel quel (validation requise).

export const DETECTOR_VERSION = 'detectors-v1'

export interface DyadMessage {
  id: string
  threadId: string
  direction: 'inbound' | 'outbound'
  sentAt: string
  subject?: string | null
}
export interface DyadMeeting {
  id: string
  startsAt: string
  occurred: boolean
  contactParticipated: boolean
}

export interface MarkerEventDraft {
  markerId: string
  scope: 'person'
  sense: -1 | 1
  observedAt: string
  evidenceRef: string
  evidenceText: string
  measure: Record<string, unknown>
  detectorVersion: string
  confidence: number
  status: 'accepted' | 'candidate'
}

const DAY = 86_400_000
const median = (xs: number[]): number | null => {
  if (!xs.length) return null
  const s = [...xs].sort((a, b) => a - b)
  const mid = Math.floor(s.length / 2)
  return s.length % 2 ? s[mid]! : (s[mid - 1]! + s[mid]!) / 2
}

export interface DyadBaseline {
  episodes: number
  sufficient: boolean
  reliabilityCap: number
  cadenceMedianDays: number | null
  contactResponseMedianHours: number | null
  ourResponseMedianHours: number | null
  avgThreadDepth: number | null
  channels: string[]
  windowDays: number
}

export function computeDyadBaseline(messages: DyadMessage[], meetings: DyadMeeting[], nowMs: number, windowDays = 182): DyadBaseline {
  const from = nowMs - windowDays * DAY
  const msg = messages.filter((m) => { const t = new Date(m.sentAt).getTime(); return t >= from && t <= nowMs }).sort((a, b) => new Date(a.sentAt).getTime() - new Date(b.sentAt).getTime())
  const meet = meetings.filter((m) => { const t = new Date(m.startsAt).getTime(); return t >= from && t <= nowMs })
  const episodes = msg.length + meet.length

  const byThread = new Map<string, DyadMessage[]>()
  for (const m of msg) byThread.set(m.threadId, [...(byThread.get(m.threadId) ?? []), m])
  const contactResp: number[] = []
  const ourResp: number[] = []
  for (const arr of byThread.values()) {
    const s = arr.sort((a, b) => new Date(a.sentAt).getTime() - new Date(b.sentAt).getTime())
    for (let i = 1; i < s.length; i++) {
      const prev = s[i - 1]!, cur = s[i]!
      if (prev.direction === cur.direction) continue
      const gapH = (new Date(cur.sentAt).getTime() - new Date(prev.sentAt).getTime()) / 3_600_000
      if (prev.direction === 'outbound' && cur.direction === 'inbound') contactResp.push(gapH)
      else if (prev.direction === 'inbound' && cur.direction === 'outbound') ourResp.push(gapH)
    }
  }

  const times = [...msg.map((m) => new Date(m.sentAt).getTime()), ...meet.map((m) => new Date(m.startsAt).getTime())].sort((a, b) => a - b)
  const gaps: number[] = []
  for (let i = 1; i < times.length; i++) gaps.push((times[i]! - times[i - 1]!) / DAY)

  const channels: string[] = []
  if (msg.length) channels.push('email')
  if (meet.length) channels.push('meeting')

  const sufficient = episodes >= 8
  return {
    episodes, sufficient, reliabilityCap: sufficient ? 1 : 0.5,
    cadenceMedianDays: median(gaps),
    contactResponseMedianHours: median(contactResp),
    ourResponseMedianHours: median(ourResp),
    avgThreadDepth: byThread.size ? msg.length / byThread.size : null,
    channels, windowDays,
  }
}

export function detectS04(messages: DyadMessage[]): MarkerEventDraft[] {
  const byThread = new Map<string, DyadMessage[]>()
  for (const m of messages) byThread.set(m.threadId, [...(byThread.get(m.threadId) ?? []), m])
  const out: MarkerEventDraft[] = []
  for (const [threadId, arr] of byThread) {
    const outbound = arr.filter((m) => m.direction === 'outbound')
    const inbound = arr.filter((m) => m.direction === 'inbound')
    if (inbound.length > 0 || outbound.length < 2) continue
    const days = new Set(outbound.map((m) => m.sentAt.slice(0, 10)))
    if (days.size < 2) continue
    const sorted = outbound.sort((a, b) => new Date(a.sentAt).getTime() - new Date(b.sentAt).getTime())
    const spanDays = (new Date(sorted[sorted.length - 1]!.sentAt).getTime() - new Date(sorted[0]!.sentAt).getTime()) / DAY
    out.push({
      markerId: 'S04', scope: 'person', sense: -1, observedAt: sorted[sorted.length - 1]!.sentAt,
      evidenceRef: sorted[0]!.id,
      evidenceText: `${outbound.length} relances sans réponse sur « ${sorted[0]!.subject ?? 'sujet inconnu'} » (${Math.round(spanDays)} j)`,
      measure: { threadId, outboundCount: outbound.length, inboundCount: 0, spanDays: Math.round(spanDays) },
      detectorVersion: DETECTOR_VERSION, confidence: 0.9, status: 'accepted',
    })
  }
  return out
}

export function detectR01(baseline: DyadBaseline, recentMessages: DyadMessage[], nowMs: number, recentDays = 45): MarkerEventDraft[] {
  if (!baseline.sufficient || baseline.contactResponseMedianHours == null) return []
  const from = nowMs - recentDays * DAY
  const byThread = new Map<string, DyadMessage[]>()
  for (const m of recentMessages) if (new Date(m.sentAt).getTime() >= from) byThread.set(m.threadId, [...(byThread.get(m.threadId) ?? []), m])
  const recent: number[] = []
  let lastId = ''
  for (const arr of byThread.values()) {
    const s = arr.sort((a, b) => new Date(a.sentAt).getTime() - new Date(b.sentAt).getTime())
    for (let i = 1; i < s.length; i++) {
      if (s[i - 1]!.direction === 'outbound' && s[i]!.direction === 'inbound') {
        recent.push((new Date(s[i]!.sentAt).getTime() - new Date(s[i - 1]!.sentAt).getTime()) / 3_600_000)
        lastId = s[i]!.id
      }
    }
  }
  const recentMed = median(recent)
  if (recentMed == null || recent.length < 2) return []
  const ratio = recentMed / baseline.contactResponseMedianHours
  let sense: -1 | 1 | 0 = 0
  if (ratio >= 1.5) sense = -1
  else if (ratio <= 0.67) sense = 1
  if (sense === 0) return []
  return [{
    markerId: 'R01', scope: 'person', sense, observedAt: new Date(nowMs).toISOString(),
    evidenceRef: lastId,
    evidenceText: `Latence de réponse du contact ${sense < 0 ? 'dégradée' : 'améliorée'} (${recentMed.toFixed(0)}h vs baseline ${baseline.contactResponseMedianHours.toFixed(0)}h)`,
    measure: { baselineHours: baseline.contactResponseMedianHours, recentHours: recentMed, ratio: Number(ratio.toFixed(2)) },
    detectorVersion: DETECTOR_VERSION, confidence: 0.75, status: 'accepted',
  }]
}

export function detectR02(messages: DyadMessage[], nowMs: number, recentDays = 90): MarkerEventDraft[] {
  const from = nowMs - recentDays * DAY
  const byThread = new Map<string, DyadMessage[]>()
  for (const m of messages) byThread.set(m.threadId, [...(byThread.get(m.threadId) ?? []), m])
  let inboundStarts = 0
  let firstInboundId = ''
  for (const arr of byThread.values()) {
    const s = arr.sort((a, b) => new Date(a.sentAt).getTime() - new Date(b.sentAt).getTime())
    const first = s[0]!
    if (first.direction === 'inbound' && new Date(first.sentAt).getTime() >= from) { inboundStarts++; if (!firstInboundId) firstInboundId = first.id }
  }
  if (inboundStarts === 0) return []
  return [{
    markerId: 'R02', scope: 'person', sense: 1, observedAt: new Date(nowMs).toISOString(),
    evidenceRef: firstInboundId,
    evidenceText: `${inboundStarts} fil(s) initié(s) par le contact — substance à confirmer (contenu non stocké)`,
    measure: { inboundThreadStarts: inboundStarts },
    detectorVersion: DETECTOR_VERSION, confidence: 0.5, status: 'candidate',
  }]
}

export function detectA01(messages: DyadMessage[], meetings: DyadMeeting[], nowMs: number, windowDays = 182): MarkerEventDraft[] {
  const from = nowMs - windowDays * DAY
  const hasEmail = messages.some((m) => new Date(m.sentAt).getTime() >= from)
  const hasMeeting = meetings.some((m) => new Date(m.startsAt).getTime() >= from)
  const channels = [hasEmail && 'email', hasMeeting && 'meeting'].filter(Boolean) as string[]
  if (channels.length === 0) return []
  const sense: -1 | 1 = channels.length >= 2 ? 1 : -1
  return [{
    markerId: 'A01', scope: 'person', sense, observedAt: new Date(nowMs).toISOString(),
    evidenceRef: 'channels',
    evidenceText: `${channels.length} canal/canaux actif(s) : ${channels.join(', ')}`,
    measure: { channelCount: channels.length, channels },
    detectorVersion: DETECTOR_VERSION, confidence: 0.8, status: 'accepted',
  }]
}

export function detectA02(messages: DyadMessage[], meetings: DyadMeeting[], nowMs: number): MarkerEventDraft[] {
  const times = [...messages.map((m) => new Date(m.sentAt).getTime()), ...meetings.map((m) => new Date(m.startsAt).getTime())]
  const activeQuarters = new Set<number>()
  for (let q = 0; q < 4; q++) {
    const start = nowMs - (q + 1) * 90 * DAY, end = nowMs - q * 90 * DAY
    if (times.some((t) => t > start && t <= end)) activeQuarters.add(q)
  }
  const n = activeQuarters.size
  if (n === 0) return []
  let sense: -1 | 1 | 0 = 0
  if (n >= 3) sense = 1
  else if (n <= 1) sense = -1
  if (sense === 0) return []
  return [{
    markerId: 'A02', scope: 'person', sense, observedAt: new Date(nowMs).toISOString(),
    evidenceRef: 'continuity',
    evidenceText: `${n}/4 trimestres actifs sur 12 mois`,
    measure: { activeQuarters: n },
    detectorVersion: DETECTOR_VERSION, confidence: 0.75, status: 'accepted',
  }]
}

export function detectE05Candidate(meetings: DyadMeeting[]): MarkerEventDraft[] {
  const held = meetings.filter((m) => m.occurred && m.contactParticipated)
  if (held.length === 0) return []
  const last = held.sort((a, b) => new Date(b.startsAt).getTime() - new Date(a.startsAt).getTime())[0]!
  return [{
    markerId: 'E05', scope: 'person', sense: 1, observedAt: last.startsAt,
    evidenceRef: last.id,
    evidenceText: `${held.length} réunion(s) tenue(s) avec le contact — acceptation présumée (statut accept/decline non capté)`,
    measure: { heldMeetings: held.length },
    detectorVersion: DETECTOR_VERSION, confidence: 0.5, status: 'candidate',
  }]
}

export function runDeterministicDetectors(messages: DyadMessage[], meetings: DyadMeeting[], nowMs: number): { baseline: DyadBaseline; drafts: MarkerEventDraft[] } {
  const baseline = computeDyadBaseline(messages, meetings, nowMs)
  const drafts = [
    ...detectS04(messages),
    ...detectR01(baseline, messages, nowMs),
    ...detectR02(messages, nowMs),
    ...detectA01(messages, meetings, nowMs),
    ...detectA02(messages, meetings, nowMs),
    ...detectE05Candidate(meetings),
  ]
  return { baseline, drafts }
}

// Scoring relationnel EN MASSE (doc 08) → cognitive_profiles + historique mensuel (contact_score_history).
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { observedRelationshipAgeInDays, scoreLongevite } from '../_shared/relationship-longevity.ts';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-cron-secret',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};
function jsonResponse(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
}

// Score composite PERSONNE — 5 axes (doc 5-axes) :
//   Confiance(25%) + Satisfaction(25%) + Engagement(20%) + Réciprocité(20%) + Ancrage(10%)
// Remplace la V57 (Intensité/Réciprocité/Récence). Moyenne pondérée pure, SANS
// règle plancher (le document de référence donne un exemple chiffré — 92/88/76/81/40
// → 80,4 — où le résultat dépasse largement l'axe le plus faible : la Confiance et la
// Satisfaction pèsent volontairement plus que l'Ancrage, un point de fragilité isolé
// (ex. bus factor) ne doit pas noyer une relation par ailleurs solide).
// Confiance et Satisfaction nécessitent une lecture du CONTENU des échanges (pas
// seulement leurs métadonnées) : elles sont extraites par IA dans sync-email-analysis
// (voir _shared/behavior-analysis.ts, champs trust/satisfaction) et lues ici depuis
// cognitive_profiles — score-batch reste un pur calcul, jamais d'appel IA lui-même.
const AXIS_WEIGHTS = { confiance: 0.25, satisfaction: 0.25, engagement: 0.20, reciprocite: 0.20, ancrage: 0.10 };
const PHASE_DELTA = 8.0, PHASE_DECLINE_MAX = 70;
// Score compte : mêmes seuils de phase que le score personne (cohérence de lecture),
// demi-vie de récence plus longue car un compte reste "vivant" plus longtemps qu'un contact isolé.
const ACCOUNT_PHASE_DELTA = 8, ACCOUNT_PHASE_DECLINE_MAX = 70, ACCOUNT_RECENCY_HALFLIFE_DAYS = 90;
const RECENT_WINDOW_MS = 14 * 86400000;
const clamp = (v: number, min = 0, max = 1) => Math.max(min, Math.min(max, v));
// "N mois calendaires avant `base`" — jamais une approximation en multiples de
// 30 jours (dérive des vrais mois, deux `ma` différents pouvaient retomber
// dans le même mois civil et produire deux snapshots contradictoires pour "le
// même mois", ex. Limayrac mars 2026). Le jour du mois est borné à la
// longueur réelle du mois cible (31 mars − 1 mois → 28/29 févr., jamais 2/3 mars).
function monthsAgoInstant(base: number, ma: number): number {
  if (ma === 0) return base;
  const d = new Date(base);
  const targetMonthIndex = d.getUTCMonth() - ma;
  const daysInTargetMonth = new Date(Date.UTC(d.getUTCFullYear(), targetMonthIndex + 1, 0)).getUTCDate();
  const day = Math.min(d.getUTCDate(), daysInTargetMonth);
  return Date.UTC(d.getUTCFullYear(), targetMonthIndex, day, d.getUTCHours(), d.getUTCMinutes(), d.getUTCSeconds(), d.getUTCMilliseconds());
}
// Premier jour (UTC) du mois civil représenté par `ma` mois avant `base` —
// période explicite (snapshot_month), distincte de la date de calcul technique
// (computed_at, toujours réelle désormais, jamais antidatée).
function monthStartUTC(base: number, ma: number): string {
  const d = new Date(base);
  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() - ma, 1)).toISOString().slice(0, 10);
}
// Types de relation où une asymétrie d'initiative est structurellement normale
// (ex. un prospect ne relance pas autant qu'un commercial) — atténue la
// pénalité de réciprocité plutôt que de la supprimer (voir scoreReciprocite).
const ASYMMETRIC_RELATIONSHIP_TYPES = new Set(['Prospect', 'Client', 'Fournisseur / Prestataire', 'Investisseur']);
// Nombre de messages minimum avec un même membre interne pour le compter comme
// « porteur » de la relation (ancrage) — évite qu'un simple CC ponctuel compte.
const ANCRAGE_MIN_MESSAGES_PER_CARRIER = 3;

interface Stats {
  emailsLast90: number; meetingsLast90: number; avgThreadDepth: number; channelCount: number;
  initiationRatio: number; responseRate: number; responseTimeRatio: number; ageInDays: number;
  daysSinceLastContact: number; monthlyExchangeCounts: number[]; quartersWithMeetings: number;
  totalInteractions: number;
}

// Engagement (20%) : intensité de la relation comparée à SA PROPRE baseline
// (moyenne d'interactions/90j sur toute la relation observée), pas à un seuil
// absolu — 20 échanges avec quelqu'un contacté 2x/mois est un signal fort, 20
// échanges avec quelqu'un contacté quotidiennement ne l'est pas. Sous la
// baseline → signal dégradé ; au-dessus → signal fort, plafonné à 2x la
// baseline. Une relation trop jeune (<45j) n'a pas encore de baseline fiable :
// traitée neutre plutôt que biaisée par sa propre activité de démarrage.
function scoreEngagement(s: Stats): number {
  const periods = Math.max(1, s.ageInDays / 90);
  const baselineRate = s.totalInteractions / periods;
  const recentRate = s.emailsLast90 + s.meetingsLast90 * 4;
  const ratio = s.ageInDays < 45 ? 1 : (baselineRate > 0 ? Math.min(4, recentRate / baselineRate) : (recentRate > 0 ? 2 : 0));
  const baselineComponent = ratio <= 1 ? ratio * 60 : Math.min(100, 60 + (ratio - 1) * 40);
  const richness = s.channelCount >= 3 ? 100 : s.channelCount === 2 ? 65 : 25;
  const depth = clamp(s.avgThreadDepth / 5) * 100;
  return clamp(baselineComponent * 0.70 + richness * 0.15 + depth * 0.15, 0, 100);
}

// Réciprocité (20%) : équilibre des initiatives, atténué selon le type de
// relation déclaré (une asymétrie commercial↔prospect est normale, une
// asymétrie partenaire↔partenaire l'est moins).
function scoreReciprocite(s: Stats, relationshipType: string | null): number {
  const asym = Math.abs(s.initiationRatio - 0.5) * 2;
  const asymWeight = relationshipType && ASYMMETRIC_RELATIONSHIP_TYPES.has(relationshipType) ? 0.35 : 0.60;
  const balance = Math.max(0.40, 1.0 - asym * asymWeight);
  return clamp(balance * 0.50 + clamp(s.responseRate) * 0.30 + clamp(s.responseTimeRatio / 2) * 0.20, 0, 1) * 100;
}

// Ancrage (10%) : nombre de membres internes distincts ayant une relation
// réelle (≥3 messages) avec ce contact — 1 porteur = risque bus factor,
// 3+ = relation intégrée à l'organisation, résiliente au départ d'un individu.
function scoreAncrage(carriers: number): number {
  if (carriers <= 0) return 0;
  if (carriers === 1) return 25;
  if (carriers === 2) return 60;
  return 100;
}

// Catégorisation COMPTE (chargement des comptes) : agrège les indices par
// contact (account_relation_hint, un par personne suivie du compte) en une
// suggestion unique — majorité PONDÉRÉE par confiance (un indice à 90% pèse
// plus que trois à 20%), jamais un simple décompte. Aucune suggestion tant que
// le signal est faible ou trop partagé entre catégories : mieux vaut laisser
// « à qualifier » qu'une catégorie hasardeuse (zéro hallucination).
const ACCOUNT_RELATION_MIN_CONFIDENCE = 55;
const ACCOUNT_RELATION_MIN_SHARE = 0.55;
function aggregateAccountRelation(hints: Array<{ category: string; confidence: number }>): { category: string; confidence: number } | null {
  const usable = hints.filter((hint) => hint.confidence >= ACCOUNT_RELATION_MIN_CONFIDENCE);
  if (!usable.length) return null;
  const weightByCategory = new Map<string, number>();
  let totalWeight = 0;
  for (const hint of usable) {
    weightByCategory.set(hint.category, (weightByCategory.get(hint.category) ?? 0) + hint.confidence);
    totalWeight += hint.confidence;
  }
  const [topCategory, topWeight] = [...weightByCategory.entries()].reduce((max, entry) => entry[1] > max[1] ? entry : max);
  if (totalWeight <= 0 || topWeight / totalWeight < ACCOUNT_RELATION_MIN_SHARE) return null;
  const contributingHints = usable.filter((hint) => hint.category === topCategory);
  const avgConfidence = contributingHints.reduce((sum, hint) => sum + hint.confidence, 0) / contributingHints.length;
  return { category: topCategory, confidence: Math.round(avgConfidence) };
}

function buildStats(allMsgs: any[], allMeets: any[], nowMs: number): Stats {
  const messages = allMsgs.filter(m => m.sent_at && new Date(m.sent_at).getTime() <= nowMs);
  const meetings = allMeets.filter(m => m.starts_at && new Date(m.starts_at).getTime() <= nowMs);
  const c90 = nowMs - 90 * 86400000;
  const outbound = messages.filter(m => m.direction === 'outbound').length;
  const inbound = messages.filter(m => m.direction === 'inbound').length;
  const total = messages.length || 1;
  const initiationRatio = outbound / total;
  const responseRate = total > 1 ? clamp((Math.min(inbound, outbound) * 2) / total) : 0.3;
  const rts = messages.filter(m => (m.metadata as any)?.response_time_hours != null).map(m => (m.metadata as any).response_time_hours);
  const avgRt = rts.length ? rts.reduce((a: number, b: number) => a + b, 0) / rts.length : 24;
  const responseTimeRatio = clamp(24 / Math.max(avgRt, 1), 0, 4) / 4;
  const threads = new Map<string, number>();
  for (const m of messages) if (m.thread_id) threads.set(m.thread_id, (threads.get(m.thread_id) || 0) + 1);
  const avgThreadDepth = threads.size ? Array.from(threads.values()).reduce((a, b) => a + b, 0) / threads.size : 1;
  const channelCount = (messages.length > 0 ? 1 : 0) + (meetings.length > 0 ? 1 : 0);
  const allDates = [...messages.map(m => new Date(m.sent_at).getTime()), ...meetings.map(m => new Date(m.starts_at).getTime())];
  // L'ancienneté de la relation commence à la première interaction observée.
  // contacts.created_at est une date d'import technique : l'utiliser remettait
  // à zéro la longevité de relations anciennes lors d'une synchronisation.
  const ageInDays = observedRelationshipAgeInDays(allDates, nowMs);
  const lastContact = allDates.length ? Math.max(...allDates) : 0;
  const daysSinceLastContact = lastContact ? Math.round((nowMs - lastContact) / 86400000) : 999;
  const monthlyExchangeCounts: number[] = [];
  for (let i = 0; i < 6; i++) {
    const start = nowMs - (i + 1) * 30 * 86400000, end = nowMs - i * 30 * 86400000;
    const messageCount = messages.filter(m => { const t = new Date(m.sent_at).getTime(); return t > start && t <= end; }).length;
    const meetingCount = meetings.filter(m => { const t = new Date(m.starts_at).getTime(); return t > start && t <= end; }).length;
    monthlyExchangeCounts.push(messageCount + meetingCount);
  }
  const quartersWithMeetings = [0, 1, 2, 3].filter(q => {
    const start = nowMs - (q + 1) * 90 * 86400000, end = nowMs - q * 90 * 86400000;
    return meetings.some(m => { const t = new Date(m.starts_at).getTime(); return t > start && t <= end; });
  }).length;
  return {
    emailsLast90: messages.filter(m => new Date(m.sent_at).getTime() > c90).length,
    meetingsLast90: meetings.filter(m => new Date(m.starts_at).getTime() > c90).length,
    avgThreadDepth, channelCount, initiationRatio, responseRate, responseTimeRatio, ageInDays, daysSinceLastContact,
    monthlyExchangeCounts, quartersWithMeetings, totalInteractions: messages.length + meetings.length * 4,
  };
}

type AxisInputs = { trustScore: number | null; satisfactionScore: number | null; relationshipType: string | null; ancrageCarriers: number };

// Interprétation déterministe (jamais un appel IA séparé) : identifie l'axe le
// plus faible et le formule en phrase actionnable, à l'image du document de
// référence — jamais un simple "score : X/100".
function interpretAxes(axes: { confiance: number; satisfaction: number; engagement: number; reciprocite: number; ancrage: number }): string {
  const labels: Record<keyof typeof axes, string> = { confiance: 'la confiance', satisfaction: 'la satisfaction', engagement: "l'engagement", reciprocite: 'la réciprocité', ancrage: "l'ancrage organisationnel" };
  const entries = Object.entries(axes) as Array<[keyof typeof axes, number]>;
  const [weakestKey, weakestValue] = entries.reduce((min, entry) => entry[1] < min[1] ? entry : min);
  const [strongestKey, strongestValue] = entries.reduce((max, entry) => entry[1] > max[1] ? entry : max);
  const overall = axes.confiance * AXIS_WEIGHTS.confiance + axes.satisfaction * AXIS_WEIGHTS.satisfaction + axes.engagement * AXIS_WEIGHTS.engagement + axes.reciprocite * AXIS_WEIGHTS.reciprocite + axes.ancrage * AXIS_WEIGHTS.ancrage;
  const level = overall >= 70 ? 'Relation solide' : overall >= 50 ? 'Relation intermédiaire' : 'Relation fragile';
  const strength = strongestValue >= 70 ? `, portée par ${labels[strongestKey]}` : '';
  const weakness = weakestValue < 60
    ? `. Le principal point de fragilité vient de ${labels[weakestKey]} (${weakestValue}/100)${weakestKey === 'ancrage' ? " : la relation reste trop dépendante d'un nombre limité de porteurs internes" : ''}.`
    : '.';
  return `${level}${strength}${weakness}`;
}

// Le projet Supabase plafonne chaque requête PostgREST à 1000 lignes côté
// serveur (db-max-rows), quel que soit le .limit() demandé côté client — un
// org avec plus de 1000 messages/snapshots ne recevait donc qu'un sous-ensemble
// arbitraire (aucun tri explicite), faussant potentiellement le calcul du
// score. On pagine explicitement via .range() jusqu'à épuisement des pages.
async function fetchAllPages<T>(build: (from: number, to: number) => PromiseLike<{ data: T[] | null; error: any }>, pageSize = 1000, maxRows = 30000): Promise<T[]> {
  const out: T[] = [];
  let from = 0;
  while (from < maxRows) {
    const { data, error } = await build(from, from + pageSize - 1);
    if (error) throw error;
    const page = data ?? [];
    out.push(...page);
    if (page.length < pageSize) break;
    from += pageSize;
  }
  return out;
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders });
  if (req.method !== 'POST') return jsonResponse({ error: 'Method not allowed' }, 405);

  const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '');
  const body = await req.json().catch(() => ({}));

  const cronHeader = req.headers.get('x-cron-secret');
  let isCron = false;
  if (cronHeader) {
    const { data: sec } = await supabase.from('app_secrets').select('value').eq('name', 'monitor_cron').maybeSingle();
    if (sec?.value && sec.value === cronHeader) isCron = true;
  }
  // Appel admin (Service Role) : la passerelle Supabase (verify_jwt) a déjà
  // validé la signature du token avant d'invoquer la fonction — il suffit de
  // lire son rôle, pas de comparer une chaîne littérale.
  if (!isCron) {
    const authHeader = req.headers.get('Authorization') ?? '';
    const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : '';
    const segments = token.split('.');
    if (segments.length === 3) {
      try {
        const payload = JSON.parse(atob(segments[1].replace(/-/g, '+').replace(/_/g, '/')));
        if (payload?.role === 'service_role') isCron = true;
      } catch { /* token non décodable : ignoré, pas d'accès admin */ }
    }
  }

  // deepBackfill : reconstruit tout l'historique réel (jusqu'à la toute
  // première interaction observée, sans plafond métier) au lieu de la fenêtre
  // glissante de 6 mois du cron normal — même formule, aucune divergence entre
  // score passé et présent. Toujours borné à une organisation (jamais un
  // backfill global non scopé) pour contenir le coût d'un seul appel.
  const deepBackfill = body.deepBackfill === true;
  if (deepBackfill && !body.organizationId) return jsonResponse({ error: 'deepBackfill nécessite organizationId' }, 400);
  // forceRecompute : ignore le « déjà couvert » et RECALCULE (upsert, jamais un
  // insert brut) les mois déjà présents — sert à corriger un backfill antérieur
  // qui aurait tourné sur des données incomplètes (ex. plafond de lignes côté
  // serveur), sans jamais supprimer de ligne existante.
  const forceRecompute = deepBackfill && body.forceRecompute === true;

  let cq = supabase.from('contacts').select('id, organization_id, created_at, owner_user_id, company_id').eq('is_tracked', true).is('merged_into_contact_id', null);
  if (!isCron) {
    const auth = req.headers.get('Authorization');
    if (!auth) return jsonResponse({ error: 'Missing authorization' }, 401);
    const { data: { user }, error: uErr } = await supabase.auth.getUser(auth.replace('Bearer ', ''));
    if (uErr || !user) return jsonResponse({ error: 'Unauthorized' }, 401);
    if (!body.organizationId) return jsonResponse({ error: 'organizationId required' }, 400);
    cq = cq.eq('organization_id', body.organizationId);
  } else if (body.organizationId) {
    cq = cq.eq('organization_id', body.organizationId);
  }
  if (body.contactId) cq = cq.eq('id', body.contactId);
  const { data: rawContacts } = await cq.limit(2000);
  if (!rawContacts?.length) return jsonResponse({ success: true, scored: 0 });

  // Un contact archivé (person_settings.archived_at) n'alimente plus aucun
  // score — ni le sien, ni celui de son compte — tant qu'il reste archivé.
  // L'archivage produit ne touche jamais contacts.is_tracked (qui reste vrai),
  // donc l'exclusion se fait ici, explicitement. On récupère au passage le
  // type de relation déclaré (utilisé pour nuancer la réciprocité).
  const { data: personSettingsRows } = await supabase.from('person_settings').select('contact_id, archived_at, relationship_type').in('contact_id', rawContacts.map((c: any) => c.id));
  const archivedContactIds = new Set((personSettingsRows ?? []).filter((r: any) => r.archived_at).map((r: any) => r.contact_id));
  const relationshipTypeByContact = new Map<string, string | null>((personSettingsRows ?? []).map((r: any) => [r.contact_id, r.relationship_type ?? null]));
  const contacts = rawContacts.filter((c: any) => !archivedContactIds.has(c.id));
  if (!contacts.length) return jsonResponse({ success: true, scored: 0 });

  const ids = contacts.map((c: any) => c.id);
  const orgIds = Array.from(new Set(contacts.map((c: any) => c.organization_id)));
  const contactOrgMap = new Map<string, string>(contacts.map((c: any) => [c.id, c.organization_id]));
  const contactCompanyMap = new Map<string, string>(contacts.filter((c: any) => c.company_id).map((c: any) => [c.id, c.company_id]));
  const companyIds = Array.from(new Set(contacts.map((c: any) => c.company_id).filter(Boolean))) as string[];

  const [msgs, parts, { data: prevProfiles }, { data: mems }] = await Promise.all([
    fetchAllPages<any>((from, to) => supabase.from('communication_messages').select('contact_id, direction, sent_at, thread_id, metadata').in('contact_id', ids).order('id', { ascending: true }).range(from, to)),
    fetchAllPages<any>((from, to) => supabase.from('meeting_participants').select('contact_id, meetings(starts_at)').in('contact_id', ids).order('id', { ascending: true }).range(from, to)),
    // trust_score/satisfaction_score/account_relation_hint : derniers signaux IA
    // connus (voir sync-email-analysis) — score-batch les LIT, ne les calcule
    // jamais lui-même (pas d'appel IA ici).
    supabase.from('cognitive_profiles').select('contact_id, engagement_score, trust_score, satisfaction_score, account_relation_hint, account_relation_hint_confidence').in('contact_id', ids),
    supabase.from('memberships').select('organization_id, user_id, role').in('organization_id', orgIds),
  ]);

  // Mois déjà couverts (granularité calendaire) : un deepBackfill rejoué n'a
  // pas à recalculer un mois déjà réellement écoulé et présent — ni pour
  // l'historique personne (contact_score_history), ni pour la santé de
  // compte (account_relationship_score_snapshots).
  const existingMonthsByContact = new Map<string, Set<string>>();
  const existingMonthsByCompany = new Map<string, Set<string>>();
  if (deepBackfill) {
    const [existingHist, existingAccountHist] = await Promise.all([
      fetchAllPages<any>((from, to) => supabase.from('contact_score_history').select('contact_id, snapshot_date').in('contact_id', ids).order('id', { ascending: true }).range(from, to)),
      companyIds.length
        ? fetchAllPages<any>((from, to) => supabase.from('account_relationship_score_snapshots').select('company_id, snapshot_month').in('company_id', companyIds).order('id', { ascending: true }).range(from, to))
        : Promise.resolve([] as any[]),
    ]);
    for (const row of (existingHist ?? []) as any[]) {
      if (!existingMonthsByContact.has(row.contact_id)) existingMonthsByContact.set(row.contact_id, new Set());
      existingMonthsByContact.get(row.contact_id)!.add(String(row.snapshot_date).slice(0, 7));
    }
    for (const row of (existingAccountHist ?? []) as any[]) {
      if (!existingMonthsByCompany.has(row.company_id)) existingMonthsByCompany.set(row.company_id, new Set());
      // snapshot_month : période explicite (voir migration 20260910220000), plus fiable
      // que computed_at qui ne représente plus jamais une date simulée.
      existingMonthsByCompany.get(row.company_id)!.add(String(row.snapshot_month).slice(0, 7));
    }
  }

  // ── Scope compte (santé + recommandations) : chargé une fois pour tout le run ──
  const trackedCompanySet = new Set<string>();
  const companyStrategic = new Map<string, boolean>();
  const companyOwner = new Map<string, string | null>();
  const decisionMakersByCompany = new Map<string, Set<string>>();
  const prevAccountScoreByCompany = new Map<string, number>();
  const accountSignalsByCompany = new Map<string, any[]>();
  const companyRelationshipStatus = new Map<string, string | null>();
  const companyRelationshipSource = new Map<string, string | null>();
  const companyContactTotal = new Map<string, number>();
  const companyOrgId = new Map<string, string>();
  for (const c of contacts as any[]) {
    if (!c.company_id) continue;
    companyContactTotal.set(c.company_id, (companyContactTotal.get(c.company_id) ?? 0) + 1);
    if (!companyOrgId.has(c.company_id)) companyOrgId.set(c.company_id, c.organization_id);
  }
  if (companyIds.length) {
    const recentCutoff = new Date(Date.now() - RECENT_WINDOW_MS).toISOString();
    const [{ data: trackedCompanies }, { data: accountSettingsRows }, { data: contactRoles }, { data: prevAccountScores }, { data: recentAccountSignals }] = await Promise.all([
      supabase.from('companies').select('id').in('id', companyIds).eq('is_tracked', true),
      supabase.from('account_settings').select('company_id, strategic, primary_owner_user_id, archived_at, relationship_status, relationship_status_source').in('company_id', companyIds),
      supabase.from('account_contact_roles').select('company_id, contact_id').in('company_id', companyIds).eq('active', true).not('decision_role', 'is', null),
      supabase.from('account_relationship_score_snapshots').select('company_id, score, computed_at').in('company_id', companyIds).order('computed_at', { ascending: false }),
      supabase.from('company_signals').select('id, company_id, family, title, observed_at').in('company_id', companyIds).in('family', ['risque', 'churn']).eq('status', 'candidate').gte('observed_at', recentCutoff),
    ]);
    // Un compte archivé (account_settings.archived_at) sort du calcul : plus
    // aucun account_relationship_score_snapshots/recommandation n'est produit
    // pour lui tant qu'il reste archivé (même logique que pour les contacts).
    const archivedCompanyIds = new Set((accountSettingsRows ?? []).filter((row: any) => row.archived_at).map((row: any) => row.company_id));
    for (const row of (trackedCompanies ?? []) as any[]) { if (!archivedCompanyIds.has(row.id)) trackedCompanySet.add(row.id); }
    for (const row of (accountSettingsRows ?? []) as any[]) {
      companyStrategic.set(row.company_id, row.strategic === true);
      companyOwner.set(row.company_id, row.primary_owner_user_id ?? null);
      companyRelationshipStatus.set(row.company_id, row.relationship_status ?? null);
      companyRelationshipSource.set(row.company_id, row.relationship_status_source ?? null);
    }
    for (const row of (contactRoles ?? []) as any[]) { if (!decisionMakersByCompany.has(row.company_id)) decisionMakersByCompany.set(row.company_id, new Set()); decisionMakersByCompany.get(row.company_id)!.add(row.contact_id); }
    for (const row of (prevAccountScores ?? []) as any[]) { if (!prevAccountScoreByCompany.has(row.company_id) && row.score != null) prevAccountScoreByCompany.set(row.company_id, row.score); }
    for (const row of (recentAccountSignals ?? []) as any[]) { if (!accountSignalsByCompany.has(row.company_id)) accountSignalsByCompany.set(row.company_id, []); accountSignalsByCompany.get(row.company_id)!.push(row); }
  }

  const recentCareerCutoff = new Date(Date.now() - RECENT_WINDOW_MS).toISOString();
  const [{ data: recentCareerChanges }, { data: openPersonRecs }] = await Promise.all([
    supabase.from('person_career_entries').select('id, contact_id, title, organization_name, created_at').in('contact_id', ids).eq('entry_type', 'detected_change').gte('created_at', recentCareerCutoff),
    supabase.from('person_recommendations').select('contact_id, category').in('contact_id', ids).eq('status', 'open'),
  ]);
  let openAccountRecs: any[] = [];
  if (companyIds.length) {
    const { data } = await supabase.from('account_recommendations').select('company_id, category, source_signal_id').in('company_id', companyIds).eq('status', 'open');
    openAccountRecs = data ?? [];
  }
  const openPersonRecKey = new Set((openPersonRecs ?? []).map((r: any) => `${r.contact_id}|${r.category}`));
  const openAccountRecKey = new Set(openAccountRecs.map((r: any) => `${r.company_id}|${r.category}`));
  const openAccountRecBySignal = new Set(openAccountRecs.filter((r: any) => r.source_signal_id).map((r: any) => r.source_signal_id));

  const msgsByC = new Map<string, any[]>();
  for (const m of (msgs ?? [])) { if (!msgsByC.has(m.contact_id)) msgsByC.set(m.contact_id, []); msgsByC.get(m.contact_id)!.push(m); }
  const meetsByC = new Map<string, any[]>();
  for (const p of (parts ?? [])) { const mt = (p as any).meetings; if (!mt) continue; if (!meetsByC.has(p.contact_id)) meetsByC.set(p.contact_id, []); meetsByC.get(p.contact_id)!.push(mt); }
  const prevByC = new Map<string, number>();
  for (const p of (prevProfiles ?? [])) if ((p as any).engagement_score != null) prevByC.set(p.contact_id, (p as any).engagement_score);
  const axisInputsByContact = new Map<string, { trustScore: number | null; satisfactionScore: number | null }>();
  for (const p of (prevProfiles ?? []) as any[]) axisInputsByContact.set(p.contact_id, { trustScore: p.trust_score ?? null, satisfactionScore: p.satisfaction_score ?? null });
  const orgOwner = new Map<string, string>();
  for (const m of (mems ?? []) as any[]) { if (!orgOwner.has(m.organization_id) || m.role === 'owner') orgOwner.set(m.organization_id, m.user_id); }

  // Catégorisation COMPTE : indice par contact (voir _shared/behavior-analysis.ts,
  // champ account_relation, même appel IA que trust/satisfaction), agrégé par
  // compte plus bas (aggregateAccountRelation) pour suggérer relationship_status.
  const relationHintsByCompany = new Map<string, Array<{ category: string; confidence: number }>>();
  for (const p of (prevProfiles ?? []) as any[]) {
    if (!p.account_relation_hint) continue;
    const companyId = contactCompanyMap.get(p.contact_id);
    if (!companyId) continue;
    if (!relationHintsByCompany.has(companyId)) relationHintsByCompany.set(companyId, []);
    relationHintsByCompany.get(companyId)!.push({ category: p.account_relation_hint, confidence: Number(p.account_relation_hint_confidence) || 0 });
  }

  // Ancrage : porteurs internes distincts par contact, calculés sur TOUT
  // l'historique de messages disponible pour ce run (pas seulement la fenêtre
  // récente) — la résilience organisationnelle d'une relation ne se mesure
  // pas sur 90 jours. metadata.user_id n'est pas toujours renseigné selon la
  // voie d'ingestion : le propriétaire déclaré du contact compte toujours
  // comme au moins 1 porteur (jamais 0 par simple absence de métadonnée).
  const ancrageCarriersByContact = new Map<string, number>();
  for (const c of contacts as any[]) {
    const contactMsgs = msgsByC.get(c.id) ?? [];
    const countsByUser = new Map<string, number>();
    for (const m of contactMsgs) {
      const uid = (m.metadata as any)?.user_id;
      if (!uid) continue;
      countsByUser.set(uid, (countsByUser.get(uid) ?? 0) + 1);
    }
    const detected = Array.from(countsByUser.values()).filter((n) => n >= ANCRAGE_MIN_MESSAGES_PER_CARRIER).length;
    ancrageCarriersByContact.set(c.id, c.owner_user_id ? Math.max(detected, 1) : detected);
  }

  function computeScore(stats: Stats, prevScore: number | null, axisInputs: AxisInputs) {
    const engagement = scoreEngagement(stats);
    const reciprocite = scoreReciprocite(stats, axisInputs.relationshipType);
    const ancrage = scoreAncrage(axisInputs.ancrageCarriers);
    // Confiance/Satisfaction : valeur IA si déjà mesurée, sinon neutre (50) en
    // attendant l'analyse — jamais fabriquée à partir du seul volume d'emails
    // (voir _shared/behavior-analysis.ts). `*Measured` distingue les deux cas
    // pour l'interprétation et la confiance affichées.
    const confianceMeasured = axisInputs.trustScore != null;
    const satisfactionMeasured = axisInputs.satisfactionScore != null;
    const confiance = axisInputs.trustScore ?? 50;
    const satisfaction = axisInputs.satisfactionScore ?? 50;
    const { score: sl } = scoreLongevite(stats);
    const weighted = confiance * AXIS_WEIGHTS.confiance + satisfaction * AXIS_WEIGHTS.satisfaction
      + engagement * AXIS_WEIGHTS.engagement + reciprocite * AXIS_WEIGHTS.reciprocite + ancrage * AXIS_WEIGHTS.ancrage;
    const finalScore = Math.round(clamp(weighted, 0, 100));
    const delta = finalScore - (prevScore ?? finalScore);
    let phase: 'growth' | 'stagnant' | 'decline' = 'stagnant';
    if (delta >= PHASE_DELTA) phase = 'growth';
    else if (delta <= -PHASE_DELTA && finalScore <= PHASE_DECLINE_MAX) phase = 'decline';
    const measuredAxisCount = 3 + (confianceMeasured ? 1 : 0) + (satisfactionMeasured ? 1 : 0);
    return {
      finalScore, delta, phase,
      engagement: Math.round(engagement), reciprocite: Math.round(reciprocite), ancrage: Math.round(ancrage),
      confiance: Math.round(confiance), satisfaction: Math.round(satisfaction), confianceMeasured, satisfactionMeasured,
      sl: Math.round(sl * 100),
      confidence: Math.min(90, 20 + stats.totalInteractions * 2 + measuredAxisCount * 8),
    };
  }

  const profileRows: any[] = [];
  const histRows: any[] = [];
  const relationshipRows: any[] = [];
  const personSnapshotRows: any[] = [];
  const personRecRows: any[] = [];
  type CompanyEngaged = { contactId: string; score: number; interactions: number; lastContactMs: number | null };
  // ma -> companyId -> contacts engagés CE mois-là — permet de reconstruire la
  // santé de compte mois par mois pendant un deepBackfill (pas seulement
  // « aujourd'hui »), sans alourdir le cron normal (ma===0 uniquement).
  const companyEngagedByMonth = new Map<number, Map<string, CompanyEngaged[]>>();
  const DEFAULT_MONTHS = [5, 4, 3, 2, 1, 0];
  // Aucun plafond métier : on remonte jusqu'à la toute première interaction
  // réelle du contact (les emails/réunions existent, l'historique ne doit
  // jamais être amputé). Seul un garde-fou technique très large empêche une
  // donnée de date corrompue de générer une boucle démesurée.
  const DEEP_BACKFILL_SAFETY_CAP_MONTHS = 600;
  const now = Date.now();

  for (const c of contacts as any[]) {
    const cm = (msgsByC.get(c.id) ?? []).sort((a, b) => new Date(b.sent_at).getTime() - new Date(a.sent_at).getTime());
    const cmeet = meetsByC.get(c.id) ?? [];
    const userId = c.owner_user_id ?? orgOwner.get(c.organization_id) ?? null;
    let lastScore: number | null = null;
    const axisInputs: AxisInputs = {
      trustScore: axisInputsByContact.get(c.id)?.trustScore ?? null,
      satisfactionScore: axisInputsByContact.get(c.id)?.satisfactionScore ?? null,
      relationshipType: relationshipTypeByContact.get(c.id) ?? null,
      ancrageCarriers: ancrageCarriersByContact.get(c.id) ?? 0,
    };

    // deepBackfill : fenêtre étendue jusqu'à la première interaction réelle de
    // CE contact (pas une fenêtre globale) — un contact récent ne recalcule
    // pas des dizaines de mois de silence pour rien.
    let contactMonths: number[] = DEFAULT_MONTHS;
    if (deepBackfill) {
      const allTimes = [...cm.map((m: any) => new Date(m.sent_at).getTime()), ...cmeet.map((m: any) => new Date(m.starts_at).getTime())].filter(Number.isFinite);
      if (allTimes.length) {
        const monthsBack = Math.min(DEEP_BACKFILL_SAFETY_CAP_MONTHS, Math.ceil((now - Math.min(...allTimes)) / (30 * 86400000)));
        contactMonths = Array.from({ length: monthsBack + 1 }, (_, i) => monthsBack - i);
      } else {
        contactMonths = [0];
      }
    }
    const coveredMonths = deepBackfill && !forceRecompute ? (existingMonthsByContact.get(c.id) ?? new Set<string>()) : null;

    for (const ma of contactMonths) {
      const nowMs = monthsAgoInstant(now, ma);
      const snapDate = new Date(nowMs).toISOString().slice(0, 10);
      // Un mois déjà réellement couvert (backfill rejoué) n'est jamais recalculé ;
      // le mois courant (ma===0), lui, doit toujours rester à jour.
      if (coveredMonths && ma !== 0 && coveredMonths.has(snapDate.slice(0, 7))) continue;
      const stats = buildStats(cm, cmeet, nowMs);
      if (stats.totalInteractions === 0) continue;
      const r = computeScore(stats, ma === 0 ? (prevByC.get(c.id) ?? null) : lastScore, axisInputs);
      lastScore = r.finalScore;
      if (userId) histRows.push({ organization_id: c.organization_id, contact_id: c.id, user_id: userId, score: r.finalScore, phase: r.phase, score_engagement: r.engagement, score_reciprocite: r.reciprocite, score_confiance: r.confiance, score_satisfaction: r.satisfaction, score_ancrage: r.ancrage, snapshot_date: snapDate });

      // relationship_snapshots (tendance Home « 1 mois / trimestre / année »)
      // + agrégation compte plus bas : reconstruits mois par mois UNIQUEMENT en
      // deepBackfill, pour ne pas alourdir le cron normal (qui garde ma===0 seul,
      // comportement inchangé).
      if (ma === 0 || deepBackfill) {
        const cutoffLastInteractionAt = stats.daysSinceLastContact < 999 ? new Date(nowMs - stats.daysSinceLastContact * 86400000).toISOString() : null;
        if (userId) relationshipRows.push({ organization_id: c.organization_id, user_id: userId, contact_id: c.id, engagement_score: r.finalScore, score_evolution: r.delta, phase: r.phase, phase_started_at: new Date(nowMs).toISOString(), last_contact_at: cutoffLastInteractionAt, last_contact_type: cm.length ? 'email' : cmeet.length ? 'meeting' : null, reciprocity_pct: r.reciprocite, snapshot_date: snapDate });
        if (c.company_id && trackedCompanySet.has(c.company_id)) {
          if (!companyEngagedByMonth.has(ma)) companyEngagedByMonth.set(ma, new Map());
          const monthMap = companyEngagedByMonth.get(ma)!;
          if (!monthMap.has(c.company_id)) monthMap.set(c.company_id, []);
          monthMap.get(c.company_id)!.push({ contactId: c.id, score: r.finalScore, interactions: stats.totalInteractions, lastContactMs: cutoffLastInteractionAt ? new Date(cutoffLastInteractionAt).getTime() : null });
        }
      }

      if (ma === 0) {
        const interactionDates = [
          ...cm.map((message: any) => message.sent_at),
          ...cmeet.map((meeting: any) => meeting.starts_at),
        ].filter(Boolean).map((value: string) => new Date(value).getTime()).filter(Number.isFinite);
        const lastInteractionAt = interactionDates.length ? new Date(Math.max(...interactionDates)).toISOString() : null;
        profileRows.push({ organization_id: c.organization_id, contact_id: c.id, profile_version: 1, engagement_score: r.finalScore, score_delta: r.delta, score_phase: r.phase, score_engagement: r.engagement, score_reciprocite: r.reciprocite, score_confiance: r.confiance, score_satisfaction: r.satisfaction, score_ancrage: r.ancrage, global_confidence: r.confidence, updated_at: new Date().toISOString() });
        const interpretation = interpretAxes({ confiance: r.confiance, satisfaction: r.satisfaction, engagement: r.engagement, reciprocite: r.reciprocite, ancrage: r.ancrage });
        personSnapshotRows.push({ organization_id: c.organization_id, contact_id: c.id, score: r.finalScore, phase: r.phase === 'growth' ? 'growing' : r.phase === 'decline' ? 'declining' : 'stable', phase_delta: r.delta, engagement_score: r.engagement, reciprocity_score: r.reciprocite, confiance_score: r.confiance, satisfaction_score: r.satisfaction, ancrage_score: r.ancrage, ancrage_carriers: axisInputs.ancrageCarriers, axis_interpretation: interpretation, relationship_age_days: stats.ageInDays, confidence: r.confidence, total_interactions: stats.totalInteractions, email_interactions: cm.length, meeting_interactions: cmeet.length, last_interaction_at: lastInteractionAt, computed_at: new Date().toISOString(), model_version: 'relationship-score-v4', source_type: 'computed', source_label: 'Moteur relationnel Tohu', observed_at: lastInteractionAt, inference_level: 'inferred' });

        // ── Recommandations personne : règles déterministes, une seule par run/contact — toujours sur l'état ACTUEL ──
        const recNowIso = new Date().toISOString();
        if (r.phase === 'decline' && r.finalScore <= 70 && !openPersonRecKey.has(`${c.id}|relationnel`)) {
          personRecRows.push({
            organization_id: c.organization_id, contact_id: c.id, kind: 'action', category: 'relationnel',
            priority: Math.min(100, 50 + Math.abs(r.delta)), title: 'Renouer le contact',
            justification: `Score relationnel en baisse de ${Math.abs(r.delta)} pts (actuellement ${r.finalScore}/100).`,
            recommended_action: 'Planifier un point avec ce contact dans les prochains jours.',
            source_type: 'engine', source_label: 'Moteur de recommandations Tohu', observed_at: recNowIso,
            confidence: r.confidence, inference_level: 'inferred',
          });
        } else if (userId && stats.daysSinceLastContact >= 45 && stats.daysSinceLastContact < 999 && !openPersonRecKey.has(`${c.id}|relationnel`)) {
          personRecRows.push({
            organization_id: c.organization_id, contact_id: c.id, kind: 'action', category: 'relationnel',
            priority: Math.min(90, 40 + Math.floor(stats.daysSinceLastContact / 5)), title: 'Reprendre contact',
            justification: `Aucun échange détecté depuis ${stats.daysSinceLastContact} jours.`,
            recommended_action: 'Envoyer un message ou proposer un point rapide.',
            source_type: 'engine', source_label: 'Moteur de recommandations Tohu', observed_at: recNowIso,
            confidence: r.confidence, inference_level: 'inferred',
          });
        } else if (axisInputs.ancrageCarriers <= 1 && stats.totalInteractions >= 8 && !openPersonRecKey.has(`${c.id}|ancrage`)) {
          personRecRows.push({
            organization_id: c.organization_id, contact_id: c.id, kind: 'action', category: 'ancrage',
            priority: 45, title: "Élargir les porteurs de la relation",
            justification: `Cette relation repose sur un seul interlocuteur interne (ancrage faible) malgré ${stats.totalInteractions} interactions.`,
            recommended_action: 'Impliquer un autre membre de l’équipe dans les prochains échanges.',
            source_type: 'engine', source_label: 'Moteur de recommandations Tohu', observed_at: recNowIso,
            confidence: r.confidence, inference_level: 'inferred',
          });
        }
      }
    }
  }

  for (const entry of (recentCareerChanges ?? []) as any[]) {
    if (openPersonRecKey.has(`${entry.contact_id}|opportunite`)) continue;
    const orgId = contactOrgMap.get(entry.contact_id);
    if (!orgId) continue;
    personRecRows.push({
      organization_id: orgId, contact_id: entry.contact_id, kind: 'action', category: 'opportunite',
      priority: 70, title: 'Confirmer le nouveau poste',
      justification: `Changement de poste détecté : ${entry.title}${entry.organization_name ? ' @ ' + entry.organization_name : ''}.`,
      recommended_action: 'Féliciter le contact et confirmer les nouvelles priorités.',
      source_type: 'engine', source_label: 'Moteur de recommandations Tohu', observed_at: entry.created_at,
      confidence: 65, inference_level: 'inferred',
    });
  }

  // ── Santé de compte + recommandations compte : agrégation à partir des scores personne calculés ci-dessus ──
  // Cron normal : un seul mois (aujourd'hui), comportement inchangé. deepBackfill :
  // rejoue la même agrégation pour chaque mois reconstruit — même formule.
  const accountScoreRows: any[] = [];
  const accountRecRows: any[] = [];
  const accountRelationSuggestionRows: any[] = [];
  const accountMonths = Array.from(new Set([0, ...companyEngagedByMonth.keys()])).sort((a, b) => b - a);
  const lastAccountScore = new Map<string, number>();
  for (const ma of accountMonths) {
    const nowMsForMonth = monthsAgoInstant(now, ma);
    const accountNowIso = new Date(nowMsForMonth).toISOString();
    const snapshotMonth = monthStartUTC(now, ma);
    const engagedThisMonth = companyEngagedByMonth.get(ma) ?? new Map<string, CompanyEngaged[]>();
    for (const companyId of trackedCompanySet) {
      const orgId = companyOrgId.get(companyId);
      const totalContacts = companyContactTotal.get(companyId) ?? 0;
      if (!orgId || totalContacts === 0) continue;
      if (deepBackfill && !forceRecompute && ma !== 0) {
        const covered = existingMonthsByCompany.get(companyId);
        if (covered?.has(snapshotMonth.slice(0, 7))) continue;
      }
      const engaged = engagedThisMonth.get(companyId) ?? [];
      if (ma !== 0 && engaged.length === 0) continue; // rien de nouveau à écrire pour ce mois-là

      const contactCoverage = Math.round((engaged.length / totalContacts) * 100);
      const totalInteractions = engaged.reduce((sum, e) => sum + e.interactions, 0);
      const lastContactMsValues = engaged.map(e => e.lastContactMs).filter((v): v is number => v != null);
      const lastInteractionAt = lastContactMsValues.length ? new Date(Math.max(...lastContactMsValues)).toISOString() : null;
      const daysSinceLastInteraction = lastContactMsValues.length ? (nowMsForMonth - Math.max(...lastContactMsValues)) / 86400000 : null;
      const interactionFrequency30d = Math.round((totalInteractions / 30) * 100) / 100;

      const decisionMakers = decisionMakersByCompany.get(companyId);
      const decisionMakerCoverage = decisionMakers && decisionMakers.size
        ? Math.round((engaged.filter(e => decisionMakers.has(e.contactId)).length / decisionMakers.size) * 100)
        : null;

      const maxSingleContactInteractions = engaged.reduce((max, e) => Math.max(max, e.interactions), 0);
      const concentrationRisk = totalInteractions > 0 ? Math.round((maxSingleContactInteractions / totalInteractions) * 100) : null;
      // Le contact qui concentre le plus d'échanges — sert d'interlocuteur concerné
      // sur la recommandation risque_concentration (voir plus bas).
      const dominantContactId = maxSingleContactInteractions > 0
        ? engaged.find((e) => e.interactions === maxSingleContactInteractions)?.contactId ?? null
        : null;

      const weightedScoreSum = engaged.reduce((sum, e) => sum + e.score * (1 + e.interactions), 0);
      const weightSum = engaged.reduce((sum, e) => sum + (1 + e.interactions), 0);
      const engagementComponent = weightSum > 0 ? weightedScoreSum / weightSum : 0;
      const recencyComponent = daysSinceLastInteraction != null ? Math.exp(-(Math.LN2 / ACCOUNT_RECENCY_HALFLIFE_DAYS) * daysSinceLastInteraction) * 100 : 0;
      // Aucun contact engagé mesuré ≠ compte en échec : neutre (50), pas 0 — le
      // phase 'unknown' ci-dessous distingue déjà ce cas d'un score réellement mauvais.
      const finalScore = engaged.length > 0
        ? Math.round(clamp((engagementComponent / 100) * 0.55 + (contactCoverage / 100) * 0.25 + (recencyComponent / 100) * 0.20) * 100)
        : 50;

      const prevScore = ma === 0 ? (prevAccountScoreByCompany.get(companyId) ?? null) : (lastAccountScore.get(companyId) ?? null);
      const phaseDelta = prevScore != null ? finalScore - prevScore : null;
      lastAccountScore.set(companyId, finalScore);
      let phase: 'growing' | 'stable' | 'declining' | 'unknown' = engaged.length === 0 ? 'unknown' : 'stable';
      if (phaseDelta != null) {
        if (phaseDelta >= ACCOUNT_PHASE_DELTA) phase = 'growing';
        else if (phaseDelta <= -ACCOUNT_PHASE_DELTA && finalScore <= ACCOUNT_PHASE_DECLINE_MAX) phase = 'declining';
      }
      const confidence = Math.min(90, 30 + totalInteractions);

      accountScoreRows.push({
        organization_id: orgId, company_id: companyId, score: finalScore, phase, phase_delta: phaseDelta,
        confidence, concentration_risk: concentrationRisk, contact_coverage: contactCoverage,
        decision_maker_coverage: decisionMakerCoverage, total_interactions: totalInteractions,
        interaction_frequency_30d: interactionFrequency30d, last_interaction_at: lastInteractionAt,
        // Composantes réelles du score (0,55 engagement + 0,25 couverture + 0,20 récence) —
        // null (pas 0) quand aucun contact engagé ce mois-là : une absence de mesure
        // n'est pas un mauvais score, jamais fabriquée (voir §2.4 doc scoring).
        engagement_component: engaged.length > 0 ? Math.round(engagementComponent) : null,
        recency_component: engaged.length > 0 ? Math.round(recencyComponent) : null,
        // snapshot_month = période représentée (calendaire, explicite) ; computed_at =
        // moment technique RÉEL de ce calcul, plus jamais antidaté — voir migration
        // 20260910220000. accountNowIso reste utilisé pour last_interaction_at/
        // observed_at ci-dessus, qui sont des faits datés dans le temps simulé, pas
        // des métadonnées de calcul.
        snapshot_month: snapshotMonth, computed_at: new Date().toISOString(),
        model_version: 'account-relationship-score-v1', source_type: 'computed',
        source_label: 'Moteur relationnel Tohu', observed_at: lastInteractionAt, inference_level: 'inferred',
      });

      if (ma !== 0) continue; // recommandations : toujours sur l'état actuel, jamais rétroactives

      // Catégorisation compte : ne retouche JAMAIS un choix humain confirmé
      // (relationship_status_source === 'manual'). Tant que non confirmée, la
      // suggestion peut être raffinée à chaque run à mesure que d'autres
      // contacts du compte sont analysés — sans jamais effacer une suggestion
      // déjà posée si ce run-ci manque simplement de signal frais.
      if (companyRelationshipSource.get(companyId) !== 'manual') {
        const suggestion = aggregateAccountRelation(relationHintsByCompany.get(companyId) ?? []);
        if (suggestion) {
          accountRelationSuggestionRows.push({
            organization_id: orgId, company_id: companyId,
            relationship_status: suggestion.category, relationship_status_source: 'suggested',
            relationship_status_confidence: suggestion.confidence, updated_by: null, updated_at: accountNowIso,
          });
        }
      }

      if (phase === 'declining' && !openAccountRecKey.has(`${companyId}|risque`)) {
        accountRecRows.push({
          organization_id: orgId, company_id: companyId, category: 'risque', priority: Math.min(100, 50 + Math.abs(phaseDelta ?? 0)),
          title: 'Compte en tension', justification: `Score relationnel du compte en baisse de ${Math.abs(phaseDelta ?? 0)} pts (actuellement ${finalScore}/100).`,
          recommended_action: 'Planifier un point stratégique avec les interlocuteurs clés.',
          source_label: 'Moteur de recommandations Tohu', observed_at: accountNowIso, confidence, inference_level: 'inferred',
        });
      }
      if (concentrationRisk != null && concentrationRisk > 70 && engaged.length > 1 && !openAccountRecKey.has(`${companyId}|risque_concentration`)) {
        accountRecRows.push({
          organization_id: orgId, company_id: companyId, category: 'risque_concentration', priority: concentrationRisk,
          contact_id: dominantContactId,
          title: 'Élargir les points de contact', justification: `${concentrationRisk}% des échanges reposent sur un seul contact.`,
          recommended_action: 'Identifier et engager d’autres interlocuteurs chez ce compte.',
          source_label: 'Moteur de recommandations Tohu', observed_at: accountNowIso, confidence, inference_level: 'inferred',
        });
      }
      if (companyStrategic.get(companyId) && !companyOwner.get(companyId) && !openAccountRecKey.has(`${companyId}|ownership`)) {
        accountRecRows.push({
          organization_id: orgId, company_id: companyId, category: 'ownership', priority: 60,
          title: 'Assigner un pilote de compte', justification: 'Ce compte est marqué stratégique mais n’a pas de propriétaire attitré.',
          recommended_action: 'Désigner un owner interne pour ce compte.',
          source_label: 'Moteur de recommandations Tohu', observed_at: accountNowIso, confidence: 80, inference_level: 'inferred',
        });
      }
      for (const signal of (accountSignalsByCompany.get(companyId) ?? [])) {
        if (openAccountRecBySignal.has(signal.id)) continue;
        accountRecRows.push({
          organization_id: orgId, company_id: companyId, source_signal_id: signal.id,
          category: signal.family === 'churn' ? 'risque_churn' : 'risque', priority: 75,
          title: signal.title, justification: `Signal de veille détecté : ${signal.title}.`,
          recommended_action: 'Qualifier ce signal et décider d’une action.',
          source_label: 'Veille Tohu', observed_at: signal.observed_at ?? accountNowIso, confidence: null, inference_level: 'inferred',
        });
      }
    }
  }

  // Persistance du SCORING (pas les recommandations/suggestions, best-effort comme
  // avant) : une erreur ici doit être visible — jamais avalée en silence. Chaque
  // échec est logué (console.error, remonte dans les logs de la fonction) ET
  // renvoyé dans la réponse JSON (persistence_errors), pour qu'un appelant ou un
  // monitoring externe puisse le détecter sans avoir à fouiller les logs.
  const persistenceErrors: Array<{ table: string; batch_from: number; batch_size: number; message: string }> = [];
  async function persistBatch(table: string, rowsToWrite: any[], write: (batch: any[]) => Promise<{ error: { message?: string } | null }>, batchSize = 200) {
    for (let i = 0; i < rowsToWrite.length; i += batchSize) {
      const batch = rowsToWrite.slice(i, i + batchSize);
      const { error } = await write(batch);
      if (error) {
        const message = error.message ?? String(error);
        console.error(`[score-batch] échec persistance ${table} (lignes ${i}-${i + batch.length}) : ${message}`);
        persistenceErrors.push({ table, batch_from: i, batch_size: batch.length, message });
      }
    }
  }

  let scored = 0;
  for (let i = 0; i < profileRows.length; i += 100) {
    const batch = profileRows.slice(i, i + 100);
    const { error } = await supabase.from('cognitive_profiles').upsert(batch, { onConflict: 'organization_id,contact_id,profile_version' });
    if (!error) scored += Math.min(100, profileRows.length - i);
    else {
      const message = error.message ?? String(error);
      console.error(`[score-batch] échec persistance cognitive_profiles (lignes ${i}-${i + batch.length}) : ${message}`);
      persistenceErrors.push({ table: 'cognitive_profiles', batch_from: i, batch_size: batch.length, message });
    }
  }
  await persistBatch('contact_score_history', histRows,
    (batch) => supabase.from('contact_score_history').upsert(batch, { onConflict: 'organization_id,contact_id,user_id,snapshot_date', ignoreDuplicates: false }));
  await persistBatch('relationship_snapshots', relationshipRows,
    (batch) => supabase.from('relationship_snapshots').upsert(batch, { onConflict: 'organization_id,user_id,contact_id,snapshot_date', ignoreDuplicates: false }));
  const today = new Date().toISOString().slice(0, 10);
  const { data: existingToday } = await supabase.from('person_relationship_score_snapshots')
    .select('contact_id').in('contact_id', ids).gte('computed_at', `${today}T00:00:00.000Z`);
  const alreadySnapshotted = new Set((existingToday ?? []).map((row: any) => row.contact_id));
  const newPersonSnapshots = personSnapshotRows.filter((row) => !alreadySnapshotted.has(row.contact_id));
  await persistBatch('person_relationship_score_snapshots', newPersonSnapshots,
    (batch) => supabase.from('person_relationship_score_snapshots').insert(batch));
  // Upsert (pas insert) : un seul snapshot de référence par compte+mois+version de
  // formule (contrainte account_relationship_score_snapshots_period_uidx, migration
  // 20260910220000) — le cron 6h met à jour le mois courant au lieu d'empiler des
  // doublons intrajournaliers, et un deepBackfill/forceRecompute remplace proprement
  // un mois déjà écrit au lieu d'entrer en collision avec lui.
  await persistBatch('account_relationship_score_snapshots', accountScoreRows,
    (batch) => supabase.from('account_relationship_score_snapshots').upsert(batch, { onConflict: 'organization_id,company_id,snapshot_month,model_version' }));
  for (let i = 0; i < accountRecRows.length; i += 200) {
    await supabase.from('account_recommendations').insert(accountRecRows.slice(i, i + 200));
  }
  for (let i = 0; i < accountRelationSuggestionRows.length; i += 200) {
    await supabase.from('account_settings').upsert(accountRelationSuggestionRows.slice(i, i + 200), { onConflict: 'organization_id,company_id' });
  }
  for (let i = 0; i < personRecRows.length; i += 200) {
    await supabase.from('person_recommendations').insert(personRecRows.slice(i, i + 200));
  }

  if (persistenceErrors.length) console.error(`[score-batch] ${persistenceErrors.length} échec(s) de persistance du scoring sur ce run.`, JSON.stringify(persistenceErrors));

  return jsonResponse({
    success: true, scored, history_points: histRows.length, relationship_snapshots: relationshipRows.length,
    person_snapshots: newPersonSnapshots.length,
    account_snapshots: accountScoreRows.length, account_recommendations: accountRecRows.length, person_recommendations: personRecRows.length,
    account_relation_suggestions: accountRelationSuggestionRows.length,
    mode: isCron ? 'cron' : 'user',
    persistence_errors: persistenceErrors,
  });
});

const DAY_MS = 86_400_000;

const clamp = (value: number, min = 0, max = 1) =>
  Math.max(min, Math.min(max, value));

export interface LongevityStats {
  ageInDays: number;
  monthlyExchangeCounts: number[];
  quartersWithMeetings: number;
  totalInteractions: number;
}

/** Ancienneté fondée uniquement sur les interactions réellement observées. */
export function observedRelationshipAgeInDays(
  interactionTimes: number[],
  nowMs: number,
): number {
  const observedTimes = interactionTimes.filter((time) =>
    Number.isFinite(time) && time <= nowMs
  );
  if (!observedTimes.length) return 0;
  return Math.max(0, Math.floor((nowMs - Math.min(...observedTimes)) / DAY_MS));
}

/**
 * Longévité = durée observée + continuité des échanges + continuité des réunions.
 *
 * Il n'y a plus de seuil qui force le résultat à zéro. Le facteur de maturité
 * limite seulement le poids de la longévité dans le score composite durant les
 * 90 premiers jours. Dès qu'il existe des échanges horodatés, ils produisent
 * une information exploitable.
 */
export function scoreLongevite(
  stats: LongevityStats,
): { score: number; factor: number } {
  if (stats.totalInteractions <= 0) return { score: 0, factor: 0 };

  const ageInDays = Math.max(0, stats.ageInDays);
  const elapsedMonths = Math.max(1, Math.min(6, Math.ceil((ageInDays + 1) / 30)));
  const monthlyCounts = stats.monthlyExchangeCounts.slice(0, elapsedMonths);
  while (monthlyCounts.length < elapsedMonths) monthlyCounts.push(0);

  const activeMonthRatio =
    monthlyCounts.filter((count) => count > 0).length / elapsedMonths;
  const mean =
    monthlyCounts.reduce((total, count) => total + count, 0) / elapsedMonths;
  const regularity = mean > 0
    ? Math.max(
      0,
      1 -
        Math.sqrt(
            monthlyCounts.reduce(
              (total, count) => total + (count - mean) ** 2,
              0,
            ) / elapsedMonths,
          ) /
          mean /
          2,
    )
    : 0;

  const ageScore = clamp(ageInDays / (24 * 30));
  const consistency = activeMonthRatio * 0.65 + regularity * 0.35;
  const meetingContinuity = clamp(stats.quartersWithMeetings / 4);
  const score =
    ageScore * 0.45 + consistency * 0.40 + meetingContinuity * 0.15;

  // Une relation récente apporte déjà un signal, mais sa dimension de
  // longévité gagne progressivement son poids complet pendant 90 jours.
  const factor = 0.35 + clamp(ageInDays / 90) * 0.65;
  return { score: clamp(score) * factor, factor };
}

// Préparation de réunion (T-48h max, aligné sur generate_user_notifications) +
// digest quotidien (SPEC-08 adapté à la cadence déjà configurée dans
// notification_preferences.daily_digest_time, plutôt qu'une cadence hebdo
// imposée qui contredirait un réglage déjà existant et configurable).
//
// mode par défaut : génère le contenu des briefs pour les réunions externes
// proches sans brief, puis rafraîchit les rappels via generate_user_notifications
// (fonction SQL existante mais jamais appelée jusqu'ici).
// mode "digest" : envoie le digest quotidien aux utilisateurs dont l'heure
// préférée correspond au tick courant, une fois par jour maximum.
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-cron-secret',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};
function jsonResponse(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
}

const MAX_MEETINGS_PER_RUN = 30;
const GENERATION_WINDOW_HOURS = 48;
const DIGEST_WINDOW_MINUTES = 7; // cron toutes les 15 min : tolérance pour matcher l'heure préférée sans trou

type SupabaseClient = ReturnType<typeof createClient>;

type Meeting = {
  id: string; organization_id: string; owner_user_id: string | null; user_id: string | null;
  company_id: string | null; title: string; starts_at: string | null; is_external: boolean | null;
};

async function runWithConcurrency<T>(items: T[], limit: number, worker: (item: T) => Promise<void>): Promise<void> {
  let index = 0;
  async function next(): Promise<void> {
    const current = index++;
    if (current >= items.length) return;
    await worker(items[current]);
    return next();
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, () => next()));
}

function band(score: number | null): string | null {
  if (score === null || score === undefined) return null;
  return score >= 70 ? 'solide' : score >= 50 ? 'intermediaire' : 'fragile';
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders });
  if (req.method !== 'POST') return jsonResponse({ error: 'Method not allowed' }, 405);

  // trace_id : identifiant de corrélation propagé dans tous les logs de cette
  // invocation (SPEC-10 §14 — traçage de bout en bout, sans contenu métier).
  const traceId = crypto.randomUUID();
  const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '');
  const body = await req.json().catch(() => ({}));

  const cronHeader = req.headers.get('x-cron-secret');
  let isCron = false;
  if (cronHeader) {
    const { data: sec } = await supabase.from('app_secrets').select('value').eq('name', 'monitor_cron').maybeSingle();
    if (sec?.value && sec.value === cronHeader) isCron = true;
  }
  if (!isCron) {
    // Génération transverse multi-organisation : réservée au cron pour l'instant,
    // pas d'usage interactif prévu (pas de bouton "générer maintenant" côté UI).
    return jsonResponse({ error: 'Cette fonction est réservée au cron.', trace_id: traceId }, 403);
  }

  console.log(JSON.stringify({ trace_id: traceId, fn: 'generate-briefs', mode: body.mode === 'digest' ? 'digest' : 'briefs', event: 'start' }));
  const result = body.mode === 'digest' ? await runDigest(supabase, traceId) : await runBriefs(supabase, traceId);
  const resultBody = await result.clone().json().catch(() => ({}));
  console.log(JSON.stringify({ trace_id: traceId, fn: 'generate-briefs', event: 'end', ...resultBody }));
  return result;
});

async function runBriefs(supabase: SupabaseClient, traceId: string) {
  const now = new Date();
  const windowEnd = new Date(now.getTime() + GENERATION_WINDOW_HOURS * 3_600_000);

  const { data: meetingsData, error } = await supabase
    .from('meetings')
    .select('id,organization_id,owner_user_id,user_id,company_id,title,starts_at,is_external')
    .or('brief_status.eq.to_generate,brief_status.is.null')
    .eq('is_external', true)
    .gte('starts_at', now.toISOString())
    .lte('starts_at', windowEnd.toISOString())
    .order('starts_at', { ascending: true })
    .limit(MAX_MEETINGS_PER_RUN);
  if (error) return jsonResponse({ success: false, trace_id: traceId, error: error.message }, 500);
  const meetings = (meetingsData ?? []) as Meeting[];
  if (!meetings.length) return jsonResponse({ success: true, trace_id: traceId, scanned: 0, generated: 0 });

  let generated = 0;
  let insufficient = 0;
  let failed = 0;
  const notifyTargets = new Map<string, { userId: string; orgId: string }>();

  await runWithConcurrency(meetings, 5, async (meeting) => {
    try {
      const [participantsRes, companyScoreRes, companyRecosRes, companySignalsRes] = await Promise.all([
        supabase.from('meeting_participants').select('contact_id,display_name,role_in_meeting').eq('meeting_id', meeting.id).not('contact_id', 'is', null),
        meeting.company_id
          ? supabase.from('account_relationship_score_snapshots').select('score,phase,computed_at').eq('company_id', meeting.company_id).order('computed_at', { ascending: false }).limit(1).maybeSingle()
          : Promise.resolve({ data: null as { score: number; phase: string | null } | null }),
        meeting.company_id
          ? supabase.from('account_recommendations').select('title,justification,priority').eq('company_id', meeting.company_id).eq('status', 'open').order('priority', { ascending: false }).limit(2)
          : Promise.resolve({ data: [] as Array<{ title: string; justification: string }> }),
        meeting.company_id
          ? supabase.from('company_signals').select('title,summary,observed_at').eq('company_id', meeting.company_id).order('observed_at', { ascending: false }).limit(2)
          : Promise.resolve({ data: [] as Array<{ title: string; summary: string | null; observed_at: string }> }),
      ]);

      const participants = (participantsRes.data ?? []) as Array<{ contact_id: string; display_name: string | null; role_in_meeting: string | null }>;
      const contactIds = participants.map((p) => p.contact_id).filter((id): id is string => Boolean(id));

      const [contactsRes, scoresRes, recosRes] = await Promise.all([
        contactIds.length ? supabase.from('contacts').select('id,full_name').in('id', contactIds) : Promise.resolve({ data: [] as Array<{ id: string; full_name: string }> }),
        contactIds.length ? supabase.from('contact_score_history').select('contact_id,score,phase,snapshot_date').in('contact_id', contactIds).order('snapshot_date', { ascending: false }) : Promise.resolve({ data: [] as Array<{ contact_id: string; score: number; phase: string | null }> }),
        contactIds.length ? supabase.from('person_recommendations').select('contact_id,title').in('contact_id', contactIds).eq('status', 'open').order('priority', { ascending: false }) : Promise.resolve({ data: [] as Array<{ contact_id: string; title: string }> }),
      ]);

      const namesByContact = new Map((contactsRes.data ?? []).map((c) => [c.id, c.full_name]));
      const latestScoreByContact = new Map<string, { score: number; phase: string | null }>();
      for (const row of (scoresRes.data ?? [])) {
        if (!latestScoreByContact.has(row.contact_id)) latestScoreByContact.set(row.contact_id, { score: row.score, phase: row.phase });
      }
      const recoByContact = new Map<string, string>();
      for (const row of (recosRes.data ?? [])) {
        if (!recoByContact.has(row.contact_id)) recoByContact.set(row.contact_id, row.title);
      }

      const participantBlocks = participants.map((p) => {
        const scoreRow = latestScoreByContact.get(p.contact_id);
        const score = scoreRow?.score ?? null;
        return {
          contactId: p.contact_id,
          name: namesByContact.get(p.contact_id) ?? p.display_name ?? 'Contact',
          role: p.role_in_meeting,
          score,
          band: band(score),
          openRecommendation: recoByContact.get(p.contact_id) ?? null,
        };
      });

      const companyScore = companyScoreRes.data as { score: number; phase: string | null } | null;
      const companyRecos = (companyRecosRes.data ?? []) as Array<{ title: string; justification: string }>;
      const companySignals = (companySignalsRes.data ?? []) as Array<{ title: string; summary: string | null; observed_at: string }>;
      const hasCompanyData = meeting.company_id !== null && (companyScore !== null || companyRecos.length > 0 || companySignals.length > 0);
      const hasParticipantData = participantBlocks.some((p) => p.score !== null || p.openRecommendation !== null);

      if (!hasCompanyData && !hasParticipantData) {
        await supabase.from('meetings').update({ brief_status: 'insufficient_data' }).eq('id', meeting.id);
        insufficient++;
        return;
      }

      const content = {
        meeting: { id: meeting.id, title: meeting.title, startsAt: meeting.starts_at },
        account: meeting.company_id ? {
          companyId: meeting.company_id,
          score: companyScore?.score ?? null,
          band: band(companyScore?.score ?? null),
          phase: companyScore?.phase ?? null,
          openRecommendations: companyRecos.map((r) => ({ title: r.title, justification: r.justification })),
          recentSignals: companySignals.map((s) => ({ title: s.title, summary: s.summary, observedAt: s.observed_at })),
        } : null,
        participants: participantBlocks,
      };
      const dataPoints = [hasCompanyData, hasParticipantData, companyRecos.length > 0, participantBlocks.some((p) => p.openRecommendation !== null)].filter(Boolean).length;
      const confidenceScore = Math.round((dataPoints / 4) * 100);

      const { error: insertError } = await supabase.from('briefs').insert({
        organization_id: meeting.organization_id,
        meeting_id: meeting.id,
        brief_type: 'meeting_preparation',
        status: 'ready',
        confidence_score: confidenceScore,
        content,
        sources: [
          ...(meeting.company_id ? [{ type: 'account', id: meeting.company_id }] : []),
          ...contactIds.map((id) => ({ type: 'contact', id })),
        ],
      });
      if (insertError) {
        failed++;
        await supabase.from('meetings').update({ brief_status: 'failed' }).eq('id', meeting.id);
        return;
      }

      await supabase.from('meetings').update({ brief_status: 'ready' }).eq('id', meeting.id);
      generated++;

      const targetUser = meeting.owner_user_id ?? meeting.user_id;
      if (targetUser) notifyTargets.set(`${meeting.organization_id}:${targetUser}`, { userId: targetUser, orgId: meeting.organization_id });
    } catch (err) {
      failed++;
      await supabase.from('meetings').update({ brief_status: 'failed' }).eq('id', meeting.id);
      console.error(JSON.stringify({ trace_id: traceId, fn: 'generate-briefs', event: 'meeting_failed', meeting_id: meeting.id, message: err instanceof Error ? err.message : String(err) }));
    }
  });

  for (const target of notifyTargets.values()) {
    await supabase.rpc('generate_user_notifications', { p_user_id: target.userId, p_org_id: target.orgId });
  }

  return jsonResponse({ success: true, trace_id: traceId, scanned: meetings.length, generated, insufficient, failed, notified: notifyTargets.size });
}

async function runDigest(supabase: SupabaseClient, traceId: string) {
  const now = new Date();
  const parisNow = new Date(now.toLocaleString('en-US', { timeZone: 'Europe/Paris' }));
  const nowMinutes = parisNow.getHours() * 60 + parisNow.getMinutes();

  const { data: prefsData, error } = await supabase
    .from('notification_preferences')
    .select('user_id,organization_id,daily_digest_time')
    .eq('daily_digest_enabled', true);
  if (error) return jsonResponse({ success: false, trace_id: traceId, error: error.message }, 500);
  const prefs = (prefsData ?? []) as Array<{ user_id: string; organization_id: string; daily_digest_time: string }>;
  if (!prefs.length) return jsonResponse({ success: true, trace_id: traceId, sent: 0, checked: 0 });

  const todayStart = new Date(now);
  todayStart.setUTCHours(0, 0, 0, 0);

  let sent = 0;
  for (const pref of prefs) {
    const [hourRaw, minuteRaw] = pref.daily_digest_time.split(':');
    const targetMinutes = (Number(hourRaw) || 8) * 60 + (Number(minuteRaw) || 0);
    if (Math.abs(nowMinutes - targetMinutes) > DIGEST_WINDOW_MINUTES) continue;

    const { data: already } = await supabase.from('notifications').select('id').eq('user_id', pref.user_id).eq('type', 'daily_digest').gte('created_at', todayStart.toISOString()).limit(1);
    if (already?.length) continue;

    const dayAgo = new Date(now.getTime() - 24 * 3_600_000).toISOString();
    const [scoresRes, companySignalsRes, behavioralSignalsRes] = await Promise.all([
      supabase.from('account_relationship_score_snapshots').select('company_id,score,computed_at').eq('organization_id', pref.organization_id).order('computed_at', { ascending: false }).limit(2000),
      supabase.from('company_signals').select('id').eq('organization_id', pref.organization_id).gte('observed_at', dayAgo),
      supabase.from('behavioral_signals').select('id').eq('organization_id', pref.organization_id).gte('observed_at', dayAgo),
    ]);

    const latestByCompany = new Map<string, number>();
    for (const row of (scoresRes.data ?? []) as Array<{ company_id: string; score: number }>) {
      if (!latestByCompany.has(row.company_id)) latestByCompany.set(row.company_id, row.score);
    }
    let fragile = 0, intermediate = 0, strong = 0;
    for (const score of latestByCompany.values()) {
      if (score < 50) fragile++;
      else if (score < 70) intermediate++;
      else strong++;
    }
    const newSignals = (companySignalsRes.data?.length ?? 0) + (behavioralSignalsRes.data?.length ?? 0);

    if (!latestByCompany.size && !newSignals) continue; // rien à dire : pas de digest vide trompeur

    const body = `Portefeuille : ${strong} solide${strong > 1 ? 's' : ''}, ${intermediate} intermédiaire${intermediate > 1 ? 's' : ''}, ${fragile} fragile${fragile > 1 ? 's' : ''} · ${newSignals} nouveau${newSignals > 1 ? 'x' : ''} signal${newSignals > 1 ? 'aux' : ''} sur 24 h.`;

    const { error: insertError } = await supabase.from('notifications').insert({
      organization_id: pref.organization_id,
      user_id: pref.user_id,
      type: 'daily_digest',
      priority: 'info',
      title: 'Digest quotidien',
      body,
      entity_type: null,
      entity_id: null,
      link: '/app/home',
    });
    if (!insertError) sent++;
  }
  return jsonResponse({ success: true, trace_id: traceId, sent, checked: prefs.length });
}

// Digest hebdomadaire (ACT-88, 1×/sem). Trois usages :
//  - CRON (en-tête x-cron-secret) : itère les membres (modèle opt-out), assemble les
//    vraies données de la semaine et envoie ; dédup `digest:{user}:{semaine ISO}`.
//  - { organizationId } (JWT utilisateur) : assemble le digest RÉEL de son org et
//    l'envoie à l'appelant — sert de test « données réelles ».
//  - { test: true } : envoie le digest d'exemple à l'appelant (valide Resend + rendu).
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { sendEmail, isoWeekKey } from '../_shared/email.ts'
import { renderDigest, renderDigestEmpty, SAMPLE_DIGEST } from '../_shared/email-templates/digest.ts'
import { assembleDigest } from './assemble.ts'

const DASHBOARD_URL = 'https://tohu.co/app/home'
const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-cron-secret',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}
function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
}
async function appSecret(supabase: any, name: string): Promise<string | null> {
  const { data } = await supabase.from('app_secrets').select('value').eq('name', name).maybeSingle()
  return (data as { value?: string } | null)?.value ?? null
}

async function sendForUser(supabase: any, userId: string, organizationId: string, email: string): Promise<{ sent: boolean; reason?: string }> {
  const { data, significant } = await assembleDigest(supabase, organizationId, DASHBOARD_URL)
  const rendered = significant ? renderDigest(data) : renderDigestEmpty(data)
  const res = await sendEmail({
    supabase, userId, organizationId, type: significant ? 'digest' : 'digest_empty',
    to: email, subject: rendered.subject, html: rendered.html,
    dedupeKey: `digest:${userId}:${isoWeekKey()}`,
  })
  return res.sent ? { sent: true } : { sent: false, reason: (res as any).reason }
}

Deno.serve(async (request) => {
  if (request.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
  try {
    const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')
    const body = await request.json().catch(() => ({} as any))

    // ── CRON : itère les membres (opt-out par défaut) ─────────────────────────
    const cronSecret = request.headers.get('x-cron-secret')
    if (cronSecret) {
      const expected = await appSecret(supabase, 'monitor_cron')
      if (!expected || cronSecret !== expected) return json({ error: 'Cron secret invalide' }, 401)
      const { data: allMembers } = await supabase.from('memberships').select('user_id,organization_id')
      // onlyUserId : restreint l'envoi à un membre (validation ciblée, sans spammer).
      const members = body?.onlyUserId ? (allMembers ?? []).filter((m: any) => m.user_id === body.onlyUserId) : (allMembers ?? [])
      let sent = 0, skipped = 0
      const errors: string[] = []
      for (const m of (members ?? [])) {
        try {
          const { data: prefRow } = await supabase.from('email_preferences').select('unsubscribed_all,digest_enabled').eq('user_id', m.user_id).maybeSingle()
          if (prefRow?.unsubscribed_all || prefRow?.digest_enabled === false) { skipped++; continue }
          const { data: userData } = await supabase.auth.admin.getUserById(m.user_id)
          const email = userData?.user?.email
          if (!email) { skipped++; continue }
          const result = await sendForUser(supabase, m.user_id, m.organization_id, email)
          if (result.sent) sent++; else skipped++
        } catch (error) {
          errors.push(error instanceof Error ? error.message : String(error))
        }
      }
      return json({ ok: true, mode: 'cron', week: isoWeekKey(), sent, skipped, errors: errors.slice(0, 5) })
    }

    // ── JWT utilisateur ───────────────────────────────────────────────────────
    const authorization = request.headers.get('Authorization')
    if (!authorization) return json({ error: 'Authentification requise' }, 401)
    const { data: { user }, error: userError } = await supabase.auth.getUser(authorization.replace('Bearer ', ''))
    if (userError || !user) return json({ error: 'Session invalide' }, 401)
    const { test, organizationId, to } = body
    const recipient = (typeof to === 'string' && to.includes('@')) ? to : user.email
    if (!recipient) return json({ error: 'Aucune adresse destinataire' }, 400)

    if (test) {
      const { subject, html } = renderDigest(SAMPLE_DIGEST)
      const result = await sendEmail({ supabase, userId: user.id, organizationId: organizationId ?? null, type: 'digest', to: recipient, subject: `[Test] ${subject}`, html, dedupeKey: `digest-test:${user.id}:${Date.now()}` })
      return json({ ok: true, mode: 'test', recipient, ...result })
    }

    if (!organizationId) return json({ error: 'organizationId requis' }, 400)
    const { data: membership } = await supabase.from('memberships').select('id').eq('organization_id', organizationId).eq('user_id', user.id).maybeSingle()
    if (!membership) return json({ error: 'Accès refusé' }, 403)
    const { data, significant } = await assembleDigest(supabase, organizationId, DASHBOARD_URL)
    const rendered = significant ? renderDigest(data) : renderDigestEmpty(data)
    // Test réel : clé unique pour ne pas être bloqué par la dédup hebdo.
    const result = await sendEmail({ supabase, userId: user.id, organizationId, type: significant ? 'digest' : 'digest_empty', to: recipient, subject: `[Réel] ${rendered.subject}`, html: rendered.html, dedupeKey: `digest-real:${user.id}:${Date.now()}` })
    return json({ ok: true, mode: 'real', significant, recipient, ...result })
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : 'Envoi impossible' }, 500)
  }
})

// Wrapper d'envoi e-mail (Resend) partagé par tous les senders (digest, antisèche,
// alerte, nurturing). Centralise la doctrine d'envoi ACT-88 :
//  - opt-out global + désactivation par type (email_preferences) ;
//  - idempotence via dedupe_key (email_log) : un même e-mail n'est jamais envoyé 2×
//    (digest hebdo = 1 clé/semaine, antisèche = 1 clé/réunion) ;
//  - plafond d'alertes : max N/semaine/utilisateur (défaut 3).
// Aucune intelligence ici : les senders fournissent le HTML déjà rendu.

export type EmailType =
  | 'digest' | 'digest_empty'
  | 'antiseche'
  | 'alerte'
  | 'onb_1' | 'onb_2' | 'onb_3' | 'onb_4' | 'onb_5'

export const EMAIL_FROM = Deno.env.get('EMAIL_FROM') ?? 'Tohu <bonjour@tohu.co>'
export const EMAIL_REPLY_TO = Deno.env.get('EMAIL_REPLY_TO') ?? 'bonjour@tohu.co'
const PREFERENCES_URL = Deno.env.get('EMAIL_PREFERENCES_URL') ?? 'https://tohu.co/preferences'

// Colonne d'activation par famille d'e-mail (null = toujours autorisé).
const TYPE_TOGGLE: Record<EmailType, string | null> = {
  digest: 'digest_enabled', digest_empty: 'digest_enabled',
  antiseche: 'antiseche_enabled',
  alerte: 'alerte_enabled',
  onb_1: 'onboarding_enabled', onb_2: 'onboarding_enabled', onb_3: 'onboarding_enabled',
  onb_4: 'onboarding_enabled', onb_5: 'onboarding_enabled',
}
// Famille de diffusion (pilotage super-admin : global / type de compte / user).
const DISPATCH_FAMILY: Record<EmailType, string> = {
  digest: 'digest', digest_empty: 'digest', antiseche: 'antiseche', alerte: 'alerte',
  onb_1: 'nurturing', onb_2: 'nurturing', onb_3: 'nurturing', onb_4: 'nurturing', onb_5: 'nurturing',
}

/** Lundi 00:00 UTC de la semaine courante — borne du plafond hebdo d'alertes. */
function startOfIsoWeek(now = new Date()): Date {
  const date = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()))
  const day = date.getUTCDay() || 7 // dimanche = 7
  date.setUTCDate(date.getUTCDate() - (day - 1))
  return date
}

export type SendEmailInput = {
  supabase: any
  userId: string
  organizationId?: string | null
  type: EmailType
  to: string
  subject: string
  html: string
  // Clé d'idempotence. Ex. `digest:{userId}:{isoWeek}`, `antiseche:{meetingId}`,
  // `alerte:{signalId}`, `onb_2:{userId}`. Deux appels avec la même clé = 1 envoi.
  dedupeKey: string
  replyTo?: string
}

export type SendEmailResult =
  | { sent: true; id: string | null }
  | { sent: false; skipped: true; reason: string }

export async function sendEmail(input: SendEmailInput): Promise<SendEmailResult> {
  const { supabase, userId, organizationId = null, type, to, subject, html, dedupeKey } = input

  // 1) Idempotence : déjà envoyé sous cette clé ?
  const { data: already } = await supabase.from('email_log')
    .select('status').eq('dedupe_key', dedupeKey).maybeSingle()
  if (already?.status === 'sent') return { sent: false, skipped: true, reason: 'already_sent' }

  // 2) Préférences : opt-out global + désactivation par type.
  const { data: pref } = await supabase.from('email_preferences')
    .select('unsubscribed_all, digest_enabled, antiseche_enabled, alerte_enabled, onboarding_enabled, alerte_max_per_week')
    .eq('user_id', userId).maybeSingle()
  if (pref?.unsubscribed_all) return { sent: false, skipped: true, reason: 'unsubscribed_all' }
  const toggle = TYPE_TOGGLE[type]
  if (toggle && pref && pref[toggle] === false) return { sent: false, skipped: true, reason: 'type_disabled' }

  // Règles de diffusion pilotées par le super-admin (global / type de compte / user).
  const { data: dispatchAllowed } = await supabase.rpc('email_dispatch_allowed', { p_user_id: userId, p_email_type: DISPATCH_FAMILY[type] })
  if (dispatchAllowed === false) return { sent: false, skipped: true, reason: 'dispatch_disabled' }

  // 3) Plafond d'alertes : max N/semaine/utilisateur (ACT-88).
  if (type === 'alerte') {
    const cap = pref?.alerte_max_per_week ?? 3
    const { count } = await supabase.from('email_log')
      .select('id', { count: 'exact', head: true })
      .eq('user_id', userId).eq('email_type', 'alerte').eq('status', 'sent')
      .gte('created_at', startOfIsoWeek().toISOString())
    if ((count ?? 0) >= cap) return { sent: false, skipped: true, reason: 'weekly_alert_cap' }
  }

  // 4) Envoi Resend.
  const apiKey = Deno.env.get('RESEND_API_KEY')
  if (!apiKey) throw new Error('RESEND_API_KEY manquant')
  const response = await fetch('https://api.resend.com/emails', {
    method: 'POST',
    headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      from: EMAIL_FROM,
      to: [to],
      subject,
      html,
      reply_to: input.replyTo ?? EMAIL_REPLY_TO,
      headers: { 'List-Unsubscribe': `<${PREFERENCES_URL}>`, 'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click' },
      tags: [{ name: 'type', value: type }],
    }),
  })
  const payload = await response.json().catch(() => ({}))
  const ok = response.ok

  // 5) Journalisation (upsert sur dedupe_key → l'échec peut être rejoué).
  await supabase.from('email_log').upsert({
    user_id: userId, organization_id: organizationId, email_type: type, dedupe_key: dedupeKey,
    to_email: to, subject, resend_id: (payload as any)?.id ?? null,
    status: ok ? 'sent' : 'failed', error: ok ? null : JSON.stringify(payload).slice(0, 500),
  }, { onConflict: 'dedupe_key' })

  if (!ok) throw new Error(`Resend ${response.status}: ${JSON.stringify(payload).slice(0, 200)}`)
  return { sent: true, id: (payload as any)?.id ?? null }
}

/** Clé de semaine ISO (ex. 2026-W32) pour la dédup du digest hebdo. */
export function isoWeekKey(now = new Date()): string {
  const date = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()))
  const day = date.getUTCDay() || 7
  date.setUTCDate(date.getUTCDate() + 4 - day)
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1))
  const week = Math.ceil(((date.getTime() - yearStart.getTime()) / 86400000 + 1) / 7)
  return `${date.getUTCFullYear()}-W${String(week).padStart(2, '0')}`
}

// Rendu du digest hebdomadaire sur le layout partagé (blanc · 680 · épuré).
// Piloté par données typées ; `SAMPLE_DIGEST` sert au mode test.
import { EPI, MONO, C, esc, sectionLabel, rule, row, emailShell } from './layout.ts'

export type DigestMeeting = { day: string; time: string; who: string; sub: string; badge: string; badgeKind: 'ready' | 'first' | 'out' }
export type DigestAccount = { name: string; note: string; score: number; delta: number }
export type DigestHighlight = { kind: 'ok' | 'warn'; text: string; when: string }
export type DigestWatch = { tag: string; tagColor: 'red' | 'green' | 'blue'; text: string; source: string }
export type DigestData = {
  subject: string
  preheader: string
  periodLabel: string
  headline: string
  dashboardUrl: string
  weekAhead: DigestMeeting[]
  weekAheadNote: string
  nps: { value: number; delta: number; weeks: number; accounts: number }
  warming: DigestAccount[]
  declining: DigestAccount[]
  engagements: {
    slipped: Array<{ account: string; label: string; since: string }>; slippedDelta: number
    inProgress: string[]; inProgressNote: string
    validated: string[]; validatedDelta: number
    openTotal: number
  }
  highlights: DigestHighlight[]
  watch: DigestWatch[]
  watchNote: string
  cadenceNote: string
  computedNote: string
}

const BADGE: Record<DigestMeeting['badgeKind'], string> = {
  ready: `color:${C.green};background:#EDF8F2;`,
  first: `color:${C.violet};background:${C.lav};`,
  out: `color:${C.faint};background:#F3F1F8;`,
}
const WATCH_COLOR: Record<DigestWatch['tagColor'], string> = {
  red: `color:${C.red};background:#FDEFF1;`, green: `color:${C.green};background:#EDF8F2;`, blue: `color:${C.teal};background:#EAF6F8;`,
}

function bar(height: number, color: string, gap = 1): string {
  return `<td valign="bottom" style="padding:0 ${gap}px 0 0;"><div style="height:${height}px;line-height:${height}px;font-size:0;background-color:${color};border-radius:2px;">&nbsp;</div></td>`
}
function meetingRow(m: DigestMeeting): string {
  return `<tr><td style="padding-bottom:8px;"><table role="presentation" width="100%" style="background:${C.lav};border-radius:10px;"><tr>
    <td width="66" valign="middle" style="padding:12px 0 12px 14px;font-family:${MONO};font-size:10px;font-weight:700;letter-spacing:.8px;color:${C.muted};">${esc(m.day)} ${esc(m.time)}</td>
    <td valign="middle" style="padding:12px 8px;font-family:${EPI};font-size:14px;font-weight:700;color:${C.ink};">${esc(m.who)}<div style="font-size:12px;font-weight:400;color:${C.muted};padding-top:2px;">${esc(m.sub)}</div></td>
    <td align="right" valign="middle" style="padding:12px 14px 12px 4px;white-space:nowrap;"><span style="display:inline-block;font-family:${MONO};font-size:9.5px;font-weight:700;letter-spacing:.9px;text-transform:uppercase;${BADGE[m.badgeKind]}padding:4px 8px;border-radius:6px;">${esc(m.badge)}</span></td>
  </tr></table></td></tr>`
}
function accountRow(a: DigestAccount, positive: boolean): string {
  const color = positive ? C.green : C.red
  const arrow = positive ? '&#9650;+' : '&#9660;&minus;'
  const heights = positive ? [4, 6, 5, 8, 7, 10, 9, 13, 12, 15, 14, 20] : [20, 19, 17, 18, 16, 15, 13, 12, 10, 8, 6, 4]
  return `<tr><td style="padding-bottom:8px;"><table role="presentation" width="100%" style="border:1px solid ${C.line};border-radius:10px;"><tr>
    <td valign="middle" style="padding:12px 8px 12px 14px;font-family:${EPI};font-size:14px;font-weight:700;color:${C.ink};">${esc(a.name)}<div style="font-size:12px;font-weight:400;color:${C.muted};padding-top:2px;">${esc(a.note)}</div></td>
    <td width="72" valign="middle" class="hide-s" style="padding:12px 6px;"><table role="presentation" width="64" style="height:20px;"><tr>${heights.map((h) => bar(h, color)).join('')}</tr></table></td>
    <td width="80" align="right" valign="middle" style="padding:12px 14px 12px 4px;font-family:${MONO};font-size:16px;font-weight:700;color:${color};white-space:nowrap;">${a.score} <span style="font-size:11px;">${arrow}${Math.abs(a.delta)}</span></td>
  </tr></table></td></tr>`
}
function engColumn(bg: string, mono: string, label: string, count: number, body: string, footer: string, footerColor: string): string {
  return `<td class="stk" width="33%" valign="top" style="background:${bg};border-radius:11px;padding:14px;"><div style="font-family:${MONO};font-size:9.5px;font-weight:700;letter-spacing:1px;color:${mono};">${label} &middot; ${count}</div><div style="font-family:${EPI};font-size:12.5px;line-height:18px;color:${C.ink};padding-top:8px;">${body}</div>${footer ? `<div style="font-family:${EPI};font-size:11px;color:${footerColor};padding-top:7px;">${footer}</div>` : ''}</td>`
}
// Plafonne l'affichage d'une liste (le compteur reste le total réel).
function capItems(items: string[], max = 5): string {
  const shown = items.slice(0, max).map(esc).join('<br/>')
  const extra = items.length - max
  return extra > 0 ? `${shown}<br/><span style="color:${C.muted};">+${extra} autre${extra > 1 ? 's' : ''}</span>` : (shown || '<span style="color:' + C.muted + ';">—</span>')
}

export function renderDigest(data: DigestData): { subject: string; html: string } {
  const hero = `<div style="font-family:${EPI};font-size:13px;color:${C.soft};padding-bottom:7px;">${esc(data.periodLabel)}</div><div class="h1" style="font-family:${EPI};font-size:30px;line-height:37px;font-weight:800;letter-spacing:-.7px;color:${C.ink};">${data.headline}</div>`

  const week = sectionLabel('Ta semaine qui vient')
    + `<table role="presentation" width="100%">${data.weekAhead.map(meetingRow).join('')}</table>`
    + `<div style="font-family:${EPI};font-size:12px;color:${C.muted};padding-top:3px;">${esc(data.weekAheadNote)}</div>`

  const nps = rule() + `<table role="presentation" width="100%"><tr><td valign="top" style="font-family:${MONO};font-size:10px;font-weight:700;letter-spacing:1.4px;color:${C.muted};">NPS PORTEFEUILLE</td><td align="right" valign="top" style="font-family:${MONO};font-size:26px;font-weight:700;color:${C.ink};line-height:24px;">${data.nps.value} <span style="font-size:13px;color:${data.nps.delta >= 0 ? C.green : C.red};">${data.nps.delta >= 0 ? '&#9650;+' : '&#9660;&minus;'}${Math.abs(data.nps.delta)}</span></td></tr></table><div style="font-family:${EPI};font-size:12px;color:${C.muted};padding-top:10px;">${data.nps.weeks} semaines &middot; ${data.nps.accounts} comptes suivis</div>`

  const accounts = rule() + sectionLabel('Les comptes suivis, cette semaine')
    + `<table role="presentation" width="100%"><tr><td style="font-family:${MONO};font-size:9.5px;font-weight:700;letter-spacing:1px;color:${C.green};padding:0 0 8px 0;">&#9650; SE R&Eacute;CHAUFFENT</td></tr>${data.warming.map((a) => accountRow(a, true)).join('')}`
    + (data.declining.length ? `<tr><td style="font-family:${MONO};font-size:9.5px;font-weight:700;letter-spacing:1px;color:${C.red};padding:12px 0 8px 0;">&#9660; D&Eacute;CROCHE</td></tr>${data.declining.map((a) => accountRow(a, false)).join('')}` : '')
    + `</table>`

  const eng = data.engagements
  const engagements = rule() + sectionLabel(`Vos engagements &middot; ${eng.openTotal} ouverts`)
    + `<table role="presentation" width="100%"><tr>`
    + engColumn('#FDEFF1', C.red, '&#9888; GLISS&Eacute;S', eng.slipped.length, (eng.slipped.slice(0, 5).map((s) => `<strong>${esc(s.account)}</strong> &middot; ${esc(s.label)}<br/><span style="color:${C.red};font-size:11px;">${esc(s.since)}</span>`).join('<br/>') || `<span style="color:${C.muted};">—</span>`) + (eng.slipped.length > 5 ? `<br/><span style="color:${C.muted};">+${eng.slipped.length - 5} autre${eng.slipped.length - 5 > 1 ? 's' : ''}</span>` : ''), '', C.red)
    + `<td width="8" class="hide-s">&nbsp;</td>`
    + engColumn('#FDF6EC', C.amber, '&#8635; EN COURS', eng.inProgress.length, capItems(eng.inProgress), esc(eng.inProgressNote), C.amber)
    + `<td width="8" class="hide-s">&nbsp;</td>`
    + engColumn('#EDF8F2', C.green, '&#10003; VALID&Eacute;S', eng.validated.length, capItems(eng.validated), '', C.green)
    + `</tr></table>`

  const highlights = sectionLabel('Les temps forts de la semaine')
    + `<table role="presentation" width="100%">${data.highlights.map((h) => `<tr><td valign="top" width="18" style="padding:0 0 9px 0;font-family:${EPI};font-size:12px;color:${h.kind === 'ok' ? C.green : C.red};">${h.kind === 'ok' ? '&#10003;' : '&#9888;'}</td><td valign="top" style="padding:0 0 9px 0;font-family:${EPI};font-size:13.5px;line-height:20px;color:${C.ink};">${h.text} <span style="color:${C.faint};font-size:11.5px;white-space:nowrap;">${esc(h.when)}</span></td></tr>`).join('')}</table>`

  const watch = data.watch.length
    ? sectionLabel('Ce qui bouge dehors &middot; veille')
      + `<table role="presentation" width="100%">${data.watch.map((w) => `<tr><td style="padding-bottom:12px;"><span style="display:inline-block;font-family:${MONO};font-size:9.5px;font-weight:700;letter-spacing:.9px;text-transform:uppercase;${WATCH_COLOR[w.tagColor]}padding:4px 8px;border-radius:6px;">${esc(w.tag)}</span><div style="font-family:${EPI};font-size:13.5px;line-height:20px;color:${C.ink};padding-top:6px;">${w.text} <span style="color:${C.faint};font-size:11.5px;">${esc(w.source)}</span></div></td></tr>`).join('')}</table>`
      + `<div style="font-family:${EPI};font-size:11.5px;line-height:17px;color:${C.muted};">${esc(data.watchNote)}</div>`
    : ''

  const inner = row(hero, { top: 34, bottom: 6 })
    + row(week, { top: 26 })
    + row(nps, { top: 26 })
    + row(accounts, { top: 26 })
    + row(engagements, { top: 26 })
    + row(highlights, { top: 26 })
    + row(watch, { top: 24, bottom: 6 })

  return {
    subject: data.subject,
    html: emailShell({
      subject: data.subject, preheader: data.preheader, headerRight: 'Le point · lundi 8 h',
      cta: { label: 'Ouvrir mon tableau de bord', url: data.dashboardUrl },
      footerNote: data.computedNote,
    }, inner),
  }
}

export function renderDigestEmpty(data: DigestData): { subject: string; html: string } {
  const week = sectionLabel('Ta semaine qui vient')
    + `<table role="presentation" width="100%">${data.weekAhead.map(meetingRow).join('')}</table>`
    + `<div style="font-family:${EPI};font-size:13.5px;line-height:21px;color:${C.ink};padding-top:16px;">Aucun mouvement ne justifie ton attention cette semaine. On te le dit plut&ocirc;t que d&rsquo;inventer.</div>`
  const hero = `<div style="font-family:${EPI};font-size:13px;color:${C.soft};padding-bottom:7px;">${esc(data.periodLabel)}</div><div class="h1" style="font-family:${EPI};font-size:30px;line-height:37px;font-weight:800;letter-spacing:-.7px;color:${C.ink};">${data.headline}</div>`
  const inner = row(hero, { top: 34, bottom: 6 }) + row(week, { top: 26, bottom: 6 })
  return {
    subject: data.subject,
    html: emailShell({
      subject: data.subject, preheader: data.preheader, headerRight: 'Le point · lundi 8 h',
      cta: { label: 'Ouvrir mon tableau de bord', url: data.dashboardUrl },
      footerNote: data.computedNote,
    }, inner),
  }
}

