  const requestAnalysis = async (retry: boolean): Promise<Analysis> => {
    const response = await fetch('https://openrouter.ai/api/v1/chat/completions', {
      signal,
      method: 'POST',
      headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json', 'HTTP-Referer': Deno.env.get('SITE_URL') ?? 'https://tohu.app', 'X-Title': 'Tohu Email Behavior Analysis' },
      body: JSON.stringify({
        // Modèle dédié à l'analyse comportementale (découplé du chat Ask Tohu).
        // Surchargable via OPENROUTER_ANALYSIS_MODEL sans toucher aux autres fonctions.
        model,
        temperature: retry ? 0 : 0.1,
        response_format: COGNITIVE_PROFILE_RESPONSE_FORMAT,
        // Empêche OpenRouter de choisir un fournisseur qui ignorerait le
        // JSON Schema et retomberait silencieusement sur l'ancien format.
        provider: { require_parameters: true },
        max_tokens: retry ? 7000 : 6000,
        messages: [{
          role: 'user',
          content: retry
            ? `${prompt}\n\nIMPORTANT : la tentative précédente a produit un JSON invalide, tronqué ou dans un ancien schéma. Repars exclusivement du contrat ci-dessus : cognitive_profile_data.schema_version doit valoir 3 et les six primary_axes doivent tous être présents. Réponds de façon compacte, sans Markdown ni commentaire avant ou après l'objet JSON, et ferme impérativement toutes les structures JSON.`
            : prompt,
        }],
      }),
    })
    if (!response.ok) throw new Error(`OpenRouter ${response.status}`)
    const data = await response.json()
    if (usageLog) await logAiUsage(usageLog.client, { organizationId: usageLog.organizationId, userId: usageLog.userId, fn: 'behavior-analysis:analyze', model, usage: data?.usage })
    const content = openRouterContent(data)
    try {
      const result = extractJson(content)
      assertCurrentCognitiveSchema(asRecord(result.cognitive_profile_data))
      return result
    } catch (error) {
      // Ne jamais journaliser `content` : il peut contenir des paraphrases
      // issues des emails. Les métadonnées suffisent au diagnostic.
      console.warn('Réponse comportementale invalide', {
        retry,
        finishReason: data?.choices?.[0]?.finish_reason ?? null,
        contentLength: content.length,
        validationError: errorMessage(error),
      })
      throw error
    }
  }

  try {
    return await requestAnalysis(false)
  } catch (error) {
    if (!isRetriableAnalysisError(error)) throw error
    return await requestAnalysis(true)
  }
}

// ── Attribution des lignes de transcript à un locuteur ────────────────────────
// Réutilisé par sync-email-analysis (loadMeetingCorpus) et par l'ingestion
// manuelle de transcript.

export function normalizedSpeaker(value: string | null | undefined): string {
  return String(value ?? '')
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()
}

/** Une transcription n'est utilisée que si le préfixe de locuteur correspond
 * exactement à une identité connue du contact. En cas d'ambiguïté, elle reste
 * visible dans l'historique mais n'alimente pas l'inférence comportementale. */
export function attributedTranscriptExcerpt(transcript: string, identities: string[]): string | null {
  const speakers = new Set(identities
    .flatMap((identity) => {
      const email = cleanEmail(identity)
      return [identity, email.includes('@') ? email.split('@')[0] : '']
    })
    .map(normalizedSpeaker)
    .filter((identity) => identity.length >= 4))
  if (!speakers.size) return null

  const attributed = String(transcript ?? '').split(/\r?\n/).flatMap((line) => {
    const match = line.trim().match(/^(.+?)(?:\s+\(\d{1,2}:\d{2}(?::\d{2})?\))?\s*:\s*(.+)$/)
    if (!match || !speakers.has(normalizedSpeaker(match[1]))) return []
    const content = sanitizeBody(match[2])
    return content ? [content] : []
  })
  if (!attributed.length) return null
  return `[Transcription de réunion]\n${attributed.join('\n')}`.slice(0, 2400)
}

// ── Écriture du profil cognitif d'un contact ──────────────────────────────

export type PersistContactProfileParams = {
  organizationId: string
  contactId: string
  result: Analysis
  messageCount: number
  meetingCount: number
  interactionCount: number
  updatedFrom: string[]
  signalSource: string
  /** Défaut : `sync:${now}`. Ex. transcript : `transcript:${meetingId}`. */
  sourceRef?: string
  /** Défaut : maintenant. Ex. transcript : date de la réunion. */
  observedAt?: string
}

/** Upsert du profil cognitif v3 d'un contact + insertion de ses signaux
 *  comportementaux dérivés. Source unique de la logique d'écriture, partagée
 *  entre l'analyse email et l'ingestion de transcript. Lève en cas d'échec
 *  pour que l'appelant journalise (les triggers calculent deduplication_key). */
export async function persistContactProfile(
  supabase: SupabaseClient,
  params: PersistContactProfileParams,
): Promise<{ profileId: string; signalCount: number }> {
  const { organizationId, contactId, result, messageCount, meetingCount, interactionCount, updatedFrom, signalSource } = params
  const cognitiveProfileData = asRecord(result.cognitive_profile_data)
  assertCurrentCognitiveSchema(cognitiveProfileData)
  const structuredSignals = structuredBehavioralSignals(cognitiveProfileData)
  const now = new Date().toISOString()
  const observedAt = params.observedAt ?? now
  const sourceRef = params.sourceRef ?? `sync:${now}`
  // Confiance/Satisfaction (score PERSONNE, 5 axes) : "insufficient" ne doit
  // jamais écraser une valeur déjà mesurée par un run précédent qui aurait
  // eu moins de matière — on ne régresse une mesure réelle vers null que si
  // ce run-ci l'a explicitement invalidée en trouvant un statut différent
  // n'est pas possible ici ; on garde donc simplement : mesuré si "observed"
  // ou "emerging" avec un score non nul, sinon null (zéro hallucination).
  const trust = result.trust?.status && result.trust.status !== 'insufficient' && result.trust.score != null ? result.trust : null
  const satisfaction = result.satisfaction?.status && result.satisfaction.status !== 'insufficient' && result.satisfaction.score != null ? result.satisfaction : null
  const accountRelation = result.account_relation?.status && result.account_relation.status !== 'insufficient'
    && result.account_relation.category && (ACCOUNT_RELATION_CATEGORIES as readonly string[]).includes(result.account_relation.category)
    ? result.account_relation : null
  const { data: cognitiveProfile, error: profileError } = await supabase.from('cognitive_profiles').upsert({
    organization_id: organizationId,
    contact_id: contactId,
    profile_version: 1,
    global_confidence: pct(result.global_confidence),
    summary: result.executive_summary ?? null,
    executive_summary: result.executive_summary ?? null,
    cognitive_mode: result.cognitive_mode ?? null,
    cognitive_mode_confidence: pct(result.cognitive_mode_confidence),
    behavioral_analysis_data: structuredSignals,
    communication_style_data: asRecord(cognitiveProfileData.secondary_axes),
    cognitive_profile_data: cognitiveProfileData,
    source_message_count: messageCount,
    source_meeting_count: meetingCount,
    source_interaction_count: interactionCount,
    maturity_level: maturityFor(interactionCount),
    analysis_version: 3,
    last_analyzed_at: now,
    updated_from: updatedFrom,
    updated_at: now,
    ...(trust ? { trust_score: pct(trust.score), trust_reasoning: trust.observation ?? null, trust_analyzed_at: now } : {}),
    ...(satisfaction ? { satisfaction_score: pct(satisfaction.score), satisfaction_reasoning: satisfaction.observation ?? null, satisfaction_analyzed_at: now } : {}),
    ...(accountRelation ? { account_relation_hint: accountRelation.category, account_relation_hint_confidence: pct(accountRelation.confidence), account_relation_hint_reasoning: accountRelation.observation ?? null, account_relation_hint_analyzed_at: now } : {}),
  }, { onConflict: 'organization_id,contact_id,profile_version' }).select('id').single()
  if (profileError || !cognitiveProfile) throw profileError ?? new Error('Profil cognitif non enregistré')
  const signals = structuredSignals.map((item) => ({ organization_id: organizationId, contact_id: contactId, profile_id: cognitiveProfile.id, signal_type: item.trait, text: item.observation, inference: item.trait, inference_level: 'observable', confidence: pct(item.confidence), source_type: signalSource, source_ref: sourceRef, observed_at: observedAt }))
  if (signals.length) {
    const { error: signalsError } = await supabase.from('behavioral_signals').insert(signals)
    if (signalsError) throw signalsError
  }
  return { profileId: cognitiveProfile.id as string, signalCount: signals.length }
}

// Journalisation de l'usage IA (OpenRouter) → table `ai_usage_events`.
// OpenRouter renvoie `usage` (tokens réels) dans chaque réponse : on stocke ces
// tokens + un coût ESTIMÉ via la grille ci-dessous. La grille est approximative
// (la source de vérité des dépenses reste le tableau de bord OpenRouter) et se
// met à jour ici sans toucher au reste du code.

// Prix approximatifs en USD par 1 000 000 de tokens (entrée / sortie).
// À ajuster selon la facturation OpenRouter réelle.
const PRICING: Record<string, { in: number; out: number }> = {
  'google/gemini-3.1-flash-lite': { in: 0.10, out: 0.40 },
  'anthropic/claude-haiku-4.5': { in: 1.00, out: 5.00 },
  'openai/gpt-4.1-mini': { in: 0.40, out: 1.60 },
}
const DEFAULT_PRICE = { in: 0.50, out: 1.50 }

export type TokenUsage = { prompt_tokens?: number; completion_tokens?: number; total_tokens?: number } | null | undefined

export function estimateCostUsd(model: string, promptTokens: number, completionTokens: number): number {
  const price = PRICING[model] ?? DEFAULT_PRICE
  return (promptTokens / 1_000_000) * price.in + (completionTokens / 1_000_000) * price.out
}

type AnySupabase = { from: (table: string) => { insert: (rows: Record<string, unknown>) => PromiseLike<{ error: unknown }> } }

/** Best-effort : ne jette jamais (une erreur de log ne doit pas casser l'analyse). */
export async function logAiUsage(client: AnySupabase, params: {
  organizationId?: string | null
  userId?: string | null
  fn: string
  model: string
  usage: TokenUsage
}): Promise<void> {
  try {
    const prompt = Math.max(0, Math.round(Number(params.usage?.prompt_tokens ?? 0)))
    const completion = Math.max(0, Math.round(Number(params.usage?.completion_tokens ?? 0)))
    const total = Math.max(0, Math.round(Number(params.usage?.total_tokens ?? prompt + completion)))
    await client.from('ai_usage_events').insert({
      organization_id: params.organizationId ?? null,
      user_id: params.userId ?? null,
      fn: params.fn,
      model: params.model,
      prompt_tokens: prompt,
      completion_tokens: completion,
      total_tokens: total,
      estimated_cost_usd: Number(estimateCostUsd(params.model, prompt, completion).toFixed(6)),
    })
  } catch {
    // silencieux : la journalisation ne doit jamais interrompre le flux principal.
  }
}

// Antisèche (ACT-88, à chaque réunion). CRON toutes les 5 min : réunions dans
// les 2 prochaines heures, en privilégiant un envoi à T−2 h. La fenêtre reste
// ouverte jusqu'à T−5 min afin qu'une réunion ajoutée tardivement ou un passage
// de cron manqué reçoive quand même sa préparation. Pour chaque réunion avec
// des contacts identifiés : engagements ouverts + profil
// comportemental « qui sera en face » + entreprise) envoyée au propriétaire,
// dédup `antiseche:{meetingId}` (une seule fois par réunion).
// Test : { contactId } → antisèche synthétique « dans 2 h » envoyée à l'appelant.
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { sendEmail } from '../_shared/email.ts'
import { renderAntiseche, type AntEngagement, type AntPerson, type AntisecheData } from '../_shared/email-templates/antiseche.ts'

const DAY = 86_400_000
const HOUR = 3_600_000
const MINUTE = 60_000
const DISPLAY_TIME_ZONE = Deno.env.get('MEETING_PREP_TIME_ZONE') ?? 'Europe/Paris'
const MONTHS = ['janv.', 'févr.', 'mars', 'avr.', 'mai', 'juin', 'juil.', 'août', 'sept.', 'oct.', 'nov.', 'déc.']
const corsHeaders = { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-cron-secret', 'Access-Control-Allow-Methods': 'POST, OPTIONS' }
const json = (b: unknown, s = 200) => new Response(JSON.stringify(b), { status: s, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
const esc = (v: unknown) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
const frDate = (t: number) => { const d = new Date(t); return `${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]}` }
function cleanLabel(content: string): string {
  let s = String(content ?? '').replace(/^\s*nous\s*:\s*/i, '').replace(/\s*[—-]\s*échéance.*$/i, '').trim()
  if (s.length > 60) s = s.slice(0, 58).trimEnd() + '…'
  return s
}
async function appSecret(supabase: any, name: string): Promise<string | null> {
  const { data } = await supabase.from('app_secrets').select('value').eq('name', name).maybeSingle()
  return (data as { value?: string } | null)?.value ?? null
}

function meetingWhen(startsAt: string, platform: string | null): string {
  const date = new Date(startsAt)
  const parts = new Intl.DateTimeFormat('fr-FR', {
    timeZone: DISPLAY_TIME_ZONE,
    weekday: 'long',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).formatToParts(date)
  const value = (type: Intl.DateTimeFormatPartTypes) => parts.find((part) => part.type === type)?.value ?? ''
  const weekday = value('weekday')
  const hour = value('hour')
  const minute = value('minute')
  const time = minute === '00' ? `${hour} h` : `${hour} h ${minute}`
  const channel = platform === 'teams' ? 'Teams' : platform === 'google_meet' ? 'Google Meet' : 'réunion'
  return `${weekday} ${time} · dans ~2 h · ${channel}`
}

function deriveProfile(name: string, role: string | null, cp: any): AntPerson {
  const data = cp?.cognitive_profile_data ?? {}
  const inter = cp?.source_interaction_count ?? 0
  const conf = cp?.global_confidence ?? null
  const ip = data.interpersonal ?? {}, ax = data.primary_axes ?? {}
  const warmth = ip.warmth?.score ?? 50, warmthLow = warmth < 45, warmthHigh = warmth > 60
  const fast = (ax.rythme?.raw_score ?? 50) >= 60, direct = (ax.registre?.raw_score ?? 50) >= 60
  const style = `<strong>${esc(ip.assertiveness?.label ?? 'Équilibré')}</strong> · ${fast ? 'rythme rapide' : 'rythme posé'}, ${direct ? 'registre direct et factuel' : 'registre nuancé'}, ${warmthLow ? 'faible chaleur relationnelle' : warmthHigh ? 'chaleureux' : 'chaleur neutre'}`
  const faire = warmthLow ? 'Aller droit au but, structurer en étapes concrètes, t’appuyer sur les faits' : 'Prendre le temps du lien avant d’entrer dans le fond'
  const eviter = warmthLow ? 'Le registre relationnel ou émotionnel — il attend de l’efficacité' : 'Aller trop vite au transactionnel — soigne d’abord la relation'
  return {
    name, role: role ?? 'À qualifier', modeLabel: cp?.cognitive_mode ?? 'Profil', style, faire, eviter,
    stats: `Profil sur ${inter} interaction(s)${conf ? ` · confiance ${conf}%` : ''}`,
  }
}
function engFor(commitments: any[]): AntEngagement[] {
  const now = Date.now(), twoW = now - 14 * DAY
  return (commitments ?? []).slice(0, 3).map((e) => {
    const created = new Date(e.observed_at ?? e.created_at).getTime()
    const overdue = created < twoW
    return { icon: (overdue ? 'slipped' : 'inprogress') as 'slipped' | 'inprogress', title: cleanLabel(e.content), sub: `promis le ${frDate(created)}`, badge: overdue ? `glissé · ${Math.round((now - created) / DAY)} j` : 'en cours' }
  })
}

async function contactBundle(supabase: any, orgId: string, contactId: string): Promise<{ person: AntPerson; engagements: AntEngagement[]; companyId: string | null }> {
  const [{ data: c }, { data: cp }, { data: commitments }] = await Promise.all([
    supabase.from('contacts').select('full_name,role_title,company_id').eq('organization_id', orgId).eq('id', contactId).maybeSingle(),
    supabase.from('cognitive_profiles').select('cognitive_mode,executive_summary,global_confidence,source_interaction_count,cognitive_profile_data').eq('organization_id', orgId).eq('contact_id', contactId).eq('profile_version', 1).maybeSingle(),
    supabase.from('person_memory_entries').select('content,observed_at,created_at').eq('organization_id', orgId).eq('contact_id', contactId).eq('entry_type', 'commitment').is('resolved_at', null).order('created_at', { ascending: true }).limit(5),
  ])
  return { person: deriveProfile(c?.full_name ?? 'Contact', c?.role_title ?? null, cp), engagements: engFor(commitments ?? []), companyId: c?.company_id ?? null }
}

async function buildAntiseche(supabase: any, orgId: string, contactIds: string[], meta: { when: string; title: string; headerRight: string }, fallbackNames: string[] = []): Promise<AntisecheData> {
  const bundles = []
  for (const id of contactIds.slice(0, 2)) bundles.push(await contactBundle(supabase, orgId, id))
  if (!bundles.length) {
    const names = fallbackNames.length ? fallbackNames : ['Participants à confirmer']
    for (const name of names.slice(0, 2)) bundles.push({ person: deriveProfile(name, null, null), engagements: [], companyId: null })
  }
  const engagements = bundles.flatMap((b) => b.engagements).slice(0, 3)
  const companyId = bundles.map((b) => b.companyId).find(Boolean) ?? null
  let companyName = 'Entreprise', watch = 'Aucune actualité captée sur ce compte depuis votre dernier échange.'
  if (companyId) {
    const [{ data: co }, { data: sig }] = await Promise.all([
      supabase.from('companies').select('name').eq('id', companyId).maybeSingle(),
      supabase.from('company_signals').select('title,summary,source,observed_at').eq('organization_id', orgId).eq('company_id', companyId).order('observed_at', { ascending: false }).limit(1),
    ])
    companyName = co?.name ?? companyName
    if (sig?.[0]) watch = `<strong>${esc(sig[0].title ?? sig[0].summary ?? '')}</strong> <span style="color:#9A93AC;font-size:12px;">${esc(sig[0].source ?? '')}</span>`
    else watch += ' <span style="color:#9A93AC;font-size:12px;">On te le dit plutôt que d’inventer.</span>'
  }
  const first = (bundles[0]?.person.name ?? '').split(' ')[0]
  const openingList = engagements.length ? engagements.map((e) => e.title.toLowerCase()).join(', ') : 'les points ouverts'
  return {
    subject: `${meta.when.replace(/·.*/, '').trim()} · ${bundles.map((b) => b.person.name).join(' + ')} — ${meta.title}`,
    preheader: engagements.length ? `${engagements.length} engagement(s) sur la table.` : 'Prépa réunion.',
    headerRight: meta.headerRight, when: meta.when, title: meta.title,
    who: `${bundles.map((b) => b.person.name).join(', ')}, en face.`,
    relationTag: undefined,
    engagements, engagementsNote: engagements.length ? 'Traités dans l’ordre, tu sors avec des réponses.' : undefined,
    people: bundles.map((b) => b.person),
    company: { name: companyName, sub: 'Secteur & effectif — à confirmer', watch },
    opening: { text: `«&nbsp;${esc(first || 'Bonjour')}, pour être efficace : on cadre ${esc(openingList)}.&nbsp;»`, note: 'Calé sur son profil et les engagements encore ouverts.' },
    computedNote: 'Calculé par Tohu · sources connectées',
  }
}

Deno.serve(async (request) => {
  if (request.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
  try {
    const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')
    const body = await request.json().catch(() => ({} as any))
    const cronSecret = request.headers.get('x-cron-secret')

    // ── CRON : réunions dans les 2 prochaines heures ────────────────────────
    if (cronSecret) {
      const expected = await appSecret(supabase, 'monitor_cron')
      if (!expected || cronSecret !== expected) return json({ error: 'Cron secret invalide' }, 401)
      // Hook de validation ciblée (déclenché en SQL) : une antisèche « dans 2 h » sur un contact.
      if (body?.testContactId && body?.testOrg && body?.testEmail) {
        const data = await buildAntiseche(supabase, body.testOrg, [body.testContactId], { when: 'Aujourd’hui dans 2 h · 30 min · visio', title: 'Réunion à venir', headerRight: 'Antisèche · dans 2 h' })
        const rendered = renderAntiseche(data)
        const res = await sendEmail({ supabase, userId: body.testUserId, organizationId: body.testOrg, type: 'antiseche', to: body.testEmail, subject: `[Test réel] ${rendered.subject}`, html: rendered.html, dedupeKey: `antiseche-test:${Date.now()}` })
        return json({ ok: true, mode: 'cron-test', ...res })
      }
      // Le cron tourne toutes les 5 min. On garde une fenêtre large pour rattraper
      // une réunion créée tardivement ; `antiseche:{meetingId}` empêche tout doublon.
      const from = new Date(Date.now() + 5 * MINUTE).toISOString()
      const to = new Date(Date.now() + 2 * HOUR).toISOString()
      // status='confirmed' : jamais de briefing pour une réunion annulée.
      // meeting_scope='individual' : une réunion collective (standup, webinar) ne
      // déclenche jamais de briefing relationnel individuel, même si un de ses
      // participants est déjà une fiche suivie.
      const { data: meetings, error: meetingsError } = await supabase.from('meetings')
        .select('id,title,starts_at,platform,owner_user_id,organization_id')
        .gte('starts_at', from).lte('starts_at', to)
        .eq('status', 'confirmed').eq('meeting_scope', 'individual')
        .order('starts_at', { ascending: true }).limit(200)
      if (meetingsError) throw meetingsError
      let sent = 0, skipped = 0
      const errors: string[] = []
      for (const m of (meetings ?? [])) {
        try {
          if (!m.owner_user_id) { skipped++; continue }
          // contacts!inner + is_tracked=true : seule une relation confirmée par
          // l'utilisateur (pas un candidat tout juste détecté par la synchro
          // calendrier) déclenche un briefing — exclut aussi naturellement les
          // participants sans contact_id (teammate Tohu ou inconnu non rattaché).
          const { data: parts, error: partsError } = await supabase.from('meeting_participants')
            .select('contact_id,display_name,email,contacts!inner(is_tracked)').eq('organization_id', m.organization_id).eq('meeting_id', m.id)
            .eq('is_current_user', false).eq('contacts.is_tracked', true).limit(4)
          if (partsError) throw partsError
          const contactIds = [...new Set((parts ?? []).filter((p: any) => p.contact_id).map((p: any) => String(p.contact_id)))]
          const fallbackNames = [...new Set((parts ?? []).map((p: any) => String(p.display_name ?? p.email?.split('@')[0] ?? '').trim()).filter(Boolean))]
          const data = await buildAntiseche(supabase, m.organization_id, contactIds, { when: meetingWhen(m.starts_at, m.platform), title: m.title ?? 'Réunion', headerRight: 'Antisèche · dans ~2 h' }, fallbackNames)
          const { data: u } = await supabase.auth.admin.getUserById(m.owner_user_id)
          const email = u?.user?.email
          if (!email) { skipped++; continue }
          const rendered = renderAntiseche(data)
          const res = await sendEmail({ supabase, userId: m.owner_user_id, organizationId: m.organization_id, type: 'antiseche', to: email, subject: rendered.subject, html: rendered.html, dedupeKey: `antiseche:${m.id}` })
          if (res.sent) sent++; else skipped++
        } catch (error) {
          skipped++
          errors.push(`${m.id}: ${error instanceof Error ? error.message : String(error)}`)
        }
      }
      return json({ ok: true, mode: 'cron', sent, skipped, errors: errors.slice(0, 10) })
    }

    // ── Test : { contactId } → antisèche « dans 2 h » à l'appelant ─────────────────
    const authorization = request.headers.get('Authorization')
    if (!authorization) return json({ error: 'Authentification requise' }, 401)
    const { data: { user }, error: userError } = await supabase.auth.getUser(authorization.replace('Bearer ', ''))
    if (userError || !user) return json({ error: 'Session invalide' }, 401)
    const { organizationId, contactId, to } = body
    if (!organizationId || !contactId) return json({ error: 'organizationId et contactId requis' }, 400)
    const { data: membership } = await supabase.from('memberships').select('id').eq('organization_id', organizationId).eq('user_id', user.id).maybeSingle()
    if (!membership) return json({ error: 'Accès refusé' }, 403)
    const data = await buildAntiseche(supabase, organizationId, [contactId], { when: 'Aujourd’hui dans 2 h · 30 min · visio', title: 'Réunion à venir', headerRight: 'Antisèche · dans 2 h' })
    const rendered = renderAntiseche(data)
    const recipient = (typeof to === 'string' && to.includes('@')) ? to : user.email
    const res = await sendEmail({ supabase, userId: user.id, organizationId, type: 'antiseche', to: recipient!, subject: `[Test] ${rendered.subject}`, html: rendered.html, dedupeKey: `antiseche-test:${user.id}:${Date.now()}` })
    return json({ ok: true, mode: 'test', ...res })
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : 'Envoi impossible' }, 500)
  }
})

// Wrapper d'envoi e-mail (Resend) partagé par tous les senders (digest, antisèche,
// alerte, nurturing). Centralise la doctrine d'envoi ACT-88 :
//  - opt-out global + désactivation par type (email_preferences) ;
//  - idempotence via dedupe_key (email_log) : un même e-mail n'est jamais envoyé 2×
//    (digest hebdo = 1 clé/semaine, antisèche = 1 clé/réunion) ;
//  - plafond d'alertes : max N/semaine/utilisateur (défaut 3).
// Aucune intelligence ici : les senders fournissent le HTML déjà rendu.

export type EmailType =
  | 'digest' | 'digest_empty'
  | 'antiseche'
  | 'alerte'
  | 'onb_1' | 'onb_2' | 'onb_3' | 'onb_4' | 'onb_5'

export const EMAIL_FROM = Deno.env.get('EMAIL_FROM') ?? 'Tohu <bonjour@tohu.co>'
export const EMAIL_REPLY_TO = Deno.env.get('EMAIL_REPLY_TO') ?? 'bonjour@tohu.co'
const PREFERENCES_URL = Deno.env.get('EMAIL_PREFERENCES_URL') ?? 'https://tohu.co/preferences'

// Colonne d'activation par famille d'e-mail (null = toujours autorisé).
const TYPE_TOGGLE: Record<EmailType, string | null> = {
  digest: 'digest_enabled', digest_empty: 'digest_enabled',
  antiseche: 'antiseche_enabled',
  alerte: 'alerte_enabled',
  onb_1: 'onboarding_enabled', onb_2: 'onboarding_enabled', onb_3: 'onboarding_enabled',
  onb_4: 'onboarding_enabled', onb_5: 'onboarding_enabled',
}
// Famille de diffusion (pilotage super-admin : global / type de compte / user).
const DISPATCH_FAMILY: Record<EmailType, string> = {
  digest: 'digest', digest_empty: 'digest', antiseche: 'antiseche', alerte: 'alerte',
  onb_1: 'nurturing', onb_2: 'nurturing', onb_3: 'nurturing', onb_4: 'nurturing', onb_5: 'nurturing',
}

/** Lundi 00:00 UTC de la semaine courante — borne du plafond hebdo d'alertes. */
function startOfIsoWeek(now = new Date()): Date {
  const date = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()))
  const day = date.getUTCDay() || 7 // dimanche = 7
  date.setUTCDate(date.getUTCDate() - (day - 1))
  return date
}

export type SendEmailInput = {
  supabase: any
  userId: string
  organizationId?: string | null
  type: EmailType
  to: string
  subject: string
  html: string
  // Clé d'idempotence. Ex. `digest:{userId}:{isoWeek}`, `antiseche:{meetingId}`,
  // `alerte:{signalId}`, `onb_2:{userId}`. Deux appels avec la même clé = 1 envoi.
  dedupeKey: string
  replyTo?: string
}

export type SendEmailResult =
  | { sent: true; id: string | null }
  | { sent: false; skipped: true; reason: string }

export async function sendEmail(input: SendEmailInput): Promise<SendEmailResult> {
  const { supabase, userId, organizationId = null, type, to, subject, html, dedupeKey } = input

  // 1) Idempotence : déjà envoyé sous cette clé ?
  const { data: already } = await supabase.from('email_log')
    .select('status').eq('dedupe_key', dedupeKey).maybeSingle()
  if (already?.status === 'sent') return { sent: false, skipped: true, reason: 'already_sent' }

  // 2) Préférences : opt-out global + désactivation par type.
  const { data: pref } = await supabase.from('email_preferences')
    .select('unsubscribed_all, digest_enabled, antiseche_enabled, alerte_enabled, onboarding_enabled, alerte_max_per_week')
    .eq('user_id', userId).maybeSingle()
  if (pref?.unsubscribed_all) return { sent: false, skipped: true, reason: 'unsubscribed_all' }
  const toggle = TYPE_TOGGLE[type]
  if (toggle && pref && pref[toggle] === false) return { sent: false, skipped: true, reason: 'type_disabled' }

  // Règles de diffusion pilotées par le super-admin (global / type de compte / user).
  const { data: dispatchAllowed } = await supabase.rpc('email_dispatch_allowed', { p_user_id: userId, p_email_type: DISPATCH_FAMILY[type] })
  if (dispatchAllowed === false) return { sent: false, skipped: true, reason: 'dispatch_disabled' }

  // 3) Plafond d'alertes : max N/semaine/utilisateur (ACT-88).
  if (type === 'alerte') {
    const cap = pref?.alerte_max_per_week ?? 3
    const { count } = await supabase.from('email_log')
      .select('id', { count: 'exact', head: true })
      .eq('user_id', userId).eq('email_type', 'alerte').eq('status', 'sent')
      .gte('created_at', startOfIsoWeek().toISOString())
    if ((count ?? 0) >= cap) return { sent: false, skipped: true, reason: 'weekly_alert_cap' }
  }

  // 4) Envoi Resend.
  const apiKey = Deno.env.get('RESEND_API_KEY')
  if (!apiKey) throw new Error('RESEND_API_KEY manquant')
  const response = await fetch('https://api.resend.com/emails', {
    method: 'POST',
    headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      from: EMAIL_FROM,
      to: [to],
      subject,
      html,
      reply_to: input.replyTo ?? EMAIL_REPLY_TO,
      headers: { 'List-Unsubscribe': `<${PREFERENCES_URL}>`, 'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click' },
      tags: [{ name: 'type', value: type }],
    }),
  })
  const payload = await response.json().catch(() => ({}))
  const ok = response.ok

  // 5) Journalisation (upsert sur dedupe_key → l'échec peut être rejoué).
  await supabase.from('email_log').upsert({
    user_id: userId, organization_id: organizationId, email_type: type, dedupe_key: dedupeKey,
    to_email: to, subject, resend_id: (payload as any)?.id ?? null,
    status: ok ? 'sent' : 'failed', error: ok ? null : JSON.stringify(payload).slice(0, 500),
  }, { onConflict: 'dedupe_key' })

  if (!ok) throw new Error(`Resend ${response.status}: ${JSON.stringify(payload).slice(0, 200)}`)
  return { sent: true, id: (payload as any)?.id ?? null }
}

/** Clé de semaine ISO (ex. 2026-W32) pour la dédup du digest hebdo. */
export function isoWeekKey(now = new Date()): string {
  const date = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()))
  const day = date.getUTCDay() || 7
  date.setUTCDate(date.getUTCDate() + 4 - day)
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1))
  const week = Math.ceil(((date.getTime() - yearStart.getTime()) / 86400000 + 1) / 7)
  return `${date.getUTCFullYear()}-W${String(week).padStart(2, '0')}`
}

// Rendu de l'antisèche (prépa réunion envoyée environ 2 h avant) sur le layout partagé.
import { EPI, MONO, C, esc, sectionLabel, rule, row, emailShell } from './layout.ts'

export type AntEngagement = { icon: 'slipped' | 'inprogress' | 'validated'; title: string; sub: string; badge: string }
export type AntPerson = { name: string; role: string; modeLabel: string; style: string; faire: string; eviter: string; stats: string; context?: string }
export type AntisecheData = {
  subject: string; preheader: string; headerRight: string
  when: string; title: string; who: string
  relationTag?: { text: string; color: 'red' | 'green' | 'violet' }
  engagements: AntEngagement[]; engagementsNote?: string
  people: AntPerson[]
  company: { name: string; sub: string; watch: string }
  opening: { text: string; note: string }
  computedNote: string
}

const ICON: Record<AntEngagement['icon'], { border: string; glyph: string; color: string; badge: string }> = {
  slipped: { border: C.red, glyph: '&#9888;', color: C.red, badge: `color:${C.red};background:#FDEFF1;` },
  inprogress: { border: C.amber, glyph: '&#8635;', color: C.amber, badge: `color:${C.amber};background:#FDF6EC;` },
  validated: { border: C.green, glyph: '&#10003;', color: C.green, badge: `color:${C.green};background:#EDF8F2;` },
}
const TAG: Record<'red' | 'green' | 'violet', string> = {
  red: `color:${C.red};background:#FDEFF1;`, green: `color:${C.green};background:#EDF8F2;`, violet: `color:${C.violet};background:${C.lav};`,
}

function engRow(e: AntEngagement): string {
  const s = ICON[e.icon]
  return `<tr><td style="padding-bottom:9px;"><table role="presentation" width="100%" style="border:1px solid ${C.line};border-left:3px solid ${s.border};border-radius:9px;"><tr><td width="26" valign="top" style="padding:14px 0 14px 15px;font-family:${EPI};font-size:14px;color:${s.color};">${s.glyph}</td><td valign="top" style="padding:14px 12px 14px 4px;font-family:${EPI};font-size:14.5px;line-height:20px;font-weight:600;color:${C.ink};">${esc(e.title)}<div style="font-size:12px;font-weight:400;color:${C.muted};padding-top:3px;">${esc(e.sub)}</div></td><td align="right" valign="top" style="padding:14px 15px 14px 0;white-space:nowrap;"><span style="display:inline-block;font-family:${MONO};font-size:9.5px;font-weight:700;letter-spacing:.9px;text-transform:uppercase;${s.badge}padding:4px 8px;border-radius:6px;">${esc(e.badge)}</span></td></tr></table></td></tr>`
}
function styleRow(lab: string, labColor: string, text: string): string {
  return `<tr><td width="96" valign="top" style="font-family:${MONO};font-size:9.5px;font-weight:700;letter-spacing:.9px;color:${labColor};padding:4px 0 11px 0;">${lab}</td><td valign="top" style="font-family:${EPI};font-size:14px;line-height:21px;color:${C.ink};padding:0 0 11px 0;">${text}</td></tr>`
}
function personCard(p: AntPerson): string {
  return `<table role="presentation" width="100%" style="background:${C.lav};border-radius:12px;"><tr><td style="padding:18px 20px;"><table role="presentation" width="100%"><tr><td align="left" valign="top" style="font-family:${EPI};font-size:17px;font-weight:800;color:${C.ink};letter-spacing:-.2px;">${esc(p.name)}<div style="font-size:13px;font-weight:400;color:${C.soft};padding-top:3px;">${esc(p.role)}</div></td><td align="right" valign="top" style="font-family:${MONO};font-size:12.5px;font-weight:700;color:${C.violet};white-space:nowrap;">${esc(p.modeLabel)}</td></tr></table>
    <div style="height:1px;background:${C.lavLine};margin:15px 0;font-size:0;line-height:1px;">&nbsp;</div>
    <table role="presentation" width="100%">
      ${styleRow('STYLE', C.faint, esc(p.style))}
      ${styleRow('&#10003; FAIRE', C.green, esc(p.faire))}
      ${styleRow('&#10007; &Eacute;VITER', C.red, esc(p.eviter))}
    </table>
    <div style="font-family:${EPI};font-size:12px;color:${C.muted};padding-top:12px;">${esc(p.stats)}</div></td></tr></table>`
    + (p.context ? `<div style="font-family:${EPI};font-size:13.5px;line-height:21px;color:${C.ink};border:1px dashed #D8D1E8;border-radius:12px;padding:16px 20px;margin-top:11px;">${p.context}</div>` : '')
}

export function renderAntiseche(data: AntisecheData): { subject: string; html: string } {
  const hero = `<div style="font-family:${EPI};font-size:13px;color:${C.soft};padding-bottom:7px;">${esc(data.when)}</div><div class="h1" style="font-family:${EPI};font-size:30px;line-height:37px;font-weight:800;letter-spacing:-.7px;color:${C.ink};padding-bottom:9px;">${esc(data.title)}</div><div style="font-family:${EPI};font-size:14.5px;line-height:22px;color:${C.soft};">${esc(data.who)}${data.relationTag ? ` <span style="display:inline-block;font-family:${MONO};font-size:9.5px;font-weight:700;letter-spacing:.9px;text-transform:uppercase;${TAG[data.relationTag.color]}padding:4px 8px;border-radius:6px;">${esc(data.relationTag.text)}</span>` : ''}</div>`

  const engagements = sectionLabel('Les engagements sur la table')
    + `<table role="presentation" width="100%">${data.engagements.map(engRow).join('')}</table>`
    + (data.engagementsNote ? `<div style="font-family:${EPI};font-size:12px;color:${C.muted};padding-top:3px;">${esc(data.engagementsNote)}</div>` : '')

  const people = rule() + sectionLabel('Qui sera en face') + data.people.map((p, i) => (i ? `<div style="height:10px;">&nbsp;</div>` : '') + personCard(p)).join('')

  const company = rule() + sectionLabel('L’entreprise')
    + `<div style="font-family:${EPI};font-size:17px;font-weight:800;color:${C.ink};letter-spacing:-.2px;">${esc(data.company.name)}<div style="font-size:13px;font-weight:400;color:${C.faint};padding-top:3px;">${esc(data.company.sub)}</div></div>`
    + `<table role="presentation" width="100%" style="border:1px solid ${C.line};border-radius:11px;margin-top:15px;"><tr><td style="padding:15px 18px;"><div style="font-family:${MONO};font-size:9.5px;font-weight:700;letter-spacing:1.1px;color:${C.muted};padding-bottom:8px;">VEILLE EXTERNE</div><div style="font-family:${EPI};font-size:14px;line-height:22px;color:${C.ink};">${data.company.watch}</div></td></tr></table>`

  const opening = `<table role="presentation" width="100%" style="background:${C.lav};border-radius:11px;"><tr><td style="padding:17px 20px;"><div style="font-family:${MONO};font-size:9.5px;font-weight:700;letter-spacing:1.1px;color:${C.muted};padding-bottom:8px;">PAR OÙ OUVRIR</div><div style="font-family:${EPI};font-size:14.5px;line-height:23px;color:${C.ink};font-style:italic;">${data.opening.text}</div><div style="font-family:${EPI};font-size:12px;color:${C.muted};padding-top:9px;">${esc(data.opening.note)}</div></td></tr></table>`

  const inner = row(hero, { top: 34, bottom: 6 })
    + row(engagements, { top: 28 })
    + row(people, { top: 28 })
    + row(company, { top: 28 })
    + row(opening, { top: 28, bottom: 26 })

  return {
    subject: data.subject,
    html: emailShell({ subject: data.subject, preheader: data.preheader, headerRight: data.headerRight, footerNote: data.computedNote }, inner),
  }
}

// Layout e-mail partagé — habillage figé : fond blanc, largeur 680, épuré (pas de
// cadre flottant), masthead dégradé pleine largeur, DA Tohu (Epilogue / JetBrains
// Mono, violet→rose). Tous les templates (digest, antisèche, alerte, nurturing) le
// réutilisent pour rester cohérents.
export const EPI = "'Epilogue',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif"
export const MONO = "'JetBrains Mono',ui-monospace,'SF Mono',Menlo,Consolas,'Courier New',monospace"
export const GRAD = 'background-color:#6E50C8;background-image:linear-gradient(135deg,#6E50C8 0%,#E14FA0 100%)'
export const PX = 'padding-left:34px;padding-right:34px;'

export const C = {
  ink: '#1A1040', soft: '#5B5470', muted: '#8B839F', faint: '#9A93AC',
  green: '#2EA86A', red: '#D94F63', amber: '#C97A20', teal: '#2896A8', violet: '#6E50C8',
  line: '#E7E3F2', lav: '#F7F5FD', lavLine: '#E3DCF5',
}

export function esc(value: string): string {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
}

/** Intitulé de section : ● TEXTE en mono, gris. */
export function sectionLabel(text: string): string {
  return `<div style="font-family:${MONO};font-size:10px;font-weight:700;letter-spacing:1.6px;text-transform:uppercase;color:${C.muted};padding-bottom:13px;">&#9679; ${text}</div>`
}

export function rule(): string {
  return `<div style="height:1px;background:${C.line};margin-bottom:20px;font-size:0;line-height:1px;">&nbsp;</div>`
}

/** Ligne de contenu pleine largeur (padding latéral constant, fond blanc). */
export function row(inner: string, opts: { top?: number; bottom?: number } = {}): string {
  const top = opts.top ?? 28
  const bottom = opts.bottom ?? 0
  return `<tr><td class="px" style="background:#FFFFFF;${PX}padding-top:${top}px;padding-bottom:${bottom}px;">${inner}</td></tr>`
}

/** Bouton principal (dégradé). */
export function ctaButton(label: string, url: string): string {
  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr><td align="center" style="${GRAD};border-radius:12px;"><a href="${esc(url)}" style="display:block;padding:15px 34px;font-family:${EPI};font-size:15px;font-weight:700;color:#FFFFFF;letter-spacing:-.1px;">${label} &rarr;</a></td></tr></table>`
}

