<body style="margin:0;padding:0;background:#FFFFFF;">
<div style="display:none;max-height:0;overflow:hidden;font-size:1px;color:#FFFFFF;">${esc(options.preheader)}</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#FFFFFF;"><tr><td align="center" style="padding:0;">
<table role="presentation" class="wrap" width="680" cellpadding="0" cellspacing="0" border="0" style="width:680px;max-width:680px;">
<tr><td style="${GRAD};padding:18px 34px;"><table role="presentation" width="100%"><tr><td align="left" style="font-family:${EPI};font-size:18px;font-weight:800;color:#FFFFFF;letter-spacing:-.3px;">tohu<span style="color:#FFD9EE;">.</span></td><td align="right" style="font-family:${MONO};font-size:10px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:#FFFFFF;opacity:.92;">${esc(options.headerRight)}</td></tr></table></td></tr>
${inner}
${footerCta}
${footerNote}
<tr><td class="px" style="background:#FFFFFF;${PX}padding-top:6px;padding-bottom:8px;"><div style="height:1px;background:${C.line};font-size:0;line-height:1px;">&nbsp;</div></td></tr>
<tr><td class="px" align="center" style="background:#FFFFFF;${PX}padding-top:6px;padding-bottom:34px;font-family:${EPI};font-size:11.5px;line-height:18px;color:${C.faint};">Tohu &middot; Optee SAS &middot; donn&eacute;es h&eacute;berg&eacute;es en UE &middot; lecture seule<br/><a href="https://tohu.co/preferences" style="color:${C.violet};">R&eacute;gler la fr&eacute;quence</a> &middot; <a href="https://tohu.co/preferences" style="color:${C.violet};">Se d&eacute;sabonner</a></td></tr>
</table></td></tr></table></body></html>`
}

// Alertes (ACT-88, max 3/sem — plafond appliqué par le wrapper). CRON : repère les
// signaux entreprise forts et récents sur comptes suivis et envoie une alerte aux
// membres (dédup `alerte:{signalId}:{user}`). Test : { testAlerteEmail } → exemple.
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { sendEmail } from '../_shared/email.ts'
import { renderAlerte, type AlerteData } from '../_shared/email-templates/alerte.ts'

const corsHeaders = { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-cron-secret', 'Access-Control-Allow-Methods': 'POST, OPTIONS' }
const json = (b: unknown, s = 200) => new Response(JSON.stringify(b), { status: s, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
const esc = (v: unknown) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
async function appSecret(supabase: any, name: string): Promise<string | null> {
  const { data } = await supabase.from('app_secrets').select('value').eq('name', name).maybeSingle()
  return (data as { value?: string } | null)?.value ?? null
}
// company_signals.confidence est stocké 0-1 (colonne numeric(3,2), voir
// monitor-company-news) — un seuil par défaut de 70 comparait une fraction (0.6)
// à une échelle 0-100 et bloquait donc TOUTE alerte, silencieusement, pour
// toujours. monitor-company-news écrit aujourd'hui une confiance fixe de 0.6
// (pas de scoring différencié par signal) : le seuil doit rester à ce niveau ou
// en dessous pour laisser passer un signal réel.
const CONFIDENCE_MIN = Number(Deno.env.get('ALERT_CONFIDENCE_MIN') ?? 0.6)

const FAMILY: Record<string, { tag: string; color: 'red' | 'green' | 'blue'; impact: string }> = {
  mobility: { tag: 'Mobilité', color: 'red', impact: 'Ton point d’entrée bouge. Sécurise le lien avant son départ, ou identifie dès maintenant son remplaçant.' },
  funding: { tag: 'Croissance', color: 'green', impact: 'Budget frais du côté du compte. C’est le moment de remettre sur la table l’extension que tu gardais pour plus tard.' },
  growth: { tag: 'Croissance', color: 'green', impact: 'Le compte accélère. Repositionne-toi comme partenaire de cette croissance.' },
  market: { tag: 'Marché', color: 'blue', impact: 'Le contexte concurrentiel du compte change. Ajuste ton discours de valeur en conséquence.' },
  risk: { tag: 'Risque', color: 'red', impact: 'Signal de risque sur le compte. Anticipe avant que ça touche votre relation.' },
}
function familyFor(f: string) { return FAMILY[String(f ?? '').toLowerCase()] ?? { tag: 'Signal', color: 'blue' as const, impact: 'À surveiller de près sur ce compte.' } }

const SAMPLE_ALERTE: AlerteData = {
  subject: 'Erwan Lefèvre quitte Adivisa Techno',
  preheader: '2 sources concordantes. Il est ton seul point d’entrée sur le compte — et il arrive DG ailleurs.',
  tag: { text: 'Mobilité', color: 'red' },
  title: 'Erwan Lefèvre quitte Adivisa Techno',
  who: 'Adivisa Techno · ton seul point d’entrée sur le compte',
  proof: ['Nouveau poste <strong>Directeur Général</strong> annoncé chez Sarona Group, effet septembre.', 'Profil LinkedIn mis à jour il y a 3 jours, confirmé par la presse RCS.'],
  source: 'LinkedIn + presse RCS · 2 sources',
  impact: 'Il est ton <strong>unique point d’entrée</strong> sur Adivisa. Prends contact avant son départ pour être introduit à son successeur — sinon la relation repart de zéro.',
  cta: { label: 'Ouvrir la fiche', url: 'https://tohu.co/app/home' },
  computedNote: 'Détecté par la veille Tohu · 2 sources',
}

Deno.serve(async (request) => {
  if (request.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
  try {
    const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')
    const body = await request.json().catch(() => ({} as any))
    const cronSecret = request.headers.get('x-cron-secret')
    if (!cronSecret) return json({ error: 'Réservé au cron' }, 401)
    const expected = await appSecret(supabase, 'monitor_cron')
    if (!expected || cronSecret !== expected) return json({ error: 'Cron secret invalide' }, 401)

    // Hook test : envoie l'exemple d'alerte.
    if (body?.testAlerteEmail && body?.testUserId) {
      const rendered = renderAlerte(SAMPLE_ALERTE)
      const res = await sendEmail({ supabase, userId: body.testUserId, organizationId: body.testOrg ?? null, type: 'alerte', to: body.testAlerteEmail, subject: `[Test] ${rendered.subject}`, html: rendered.html, dedupeKey: `alerte-test:${Date.now()}` })
      return json({ ok: true, mode: 'test', ...res })
    }

    // Signaux forts récents (3 j) sur comptes suivis, non rejetés.
    const since = new Date(Date.now() - 3 * 86_400_000).toISOString()
    const { data: signals } = await supabase.from('company_signals')
      .select('id,organization_id,company_id,family,title,summary,source,source_url,confidence,observed_at,companies(name,is_tracked)')
      .gte('observed_at', since).gte('confidence', CONFIDENCE_MIN).neq('status', 'dismissed')
      .order('observed_at', { ascending: false }).limit(50)

    let sent = 0, skipped = 0
    for (const s of (signals ?? [])) {
      if (!s.companies?.is_tracked) { skipped++; continue }
      const fam = familyFor(s.family)
      const data: AlerteData = {
        subject: String(s.title ?? s.summary ?? 'Signal sur un compte suivi'),
        preheader: String(s.summary ?? s.title ?? ''),
        tag: { text: fam.tag, color: fam.color },
        title: String(s.title ?? s.summary ?? 'Nouveau signal'),
        who: `${esc(s.companies?.name ?? 'Compte suivi')}`,
        proof: [esc(s.summary ?? s.title ?? '')].filter(Boolean),
        source: String(s.source ?? 'veille Tohu'),
        impact: fam.impact,
        cta: { label: 'Ouvrir la fiche', url: 'https://tohu.co/app/home' },
        computedNote: `Détecté le ${new Date(s.observed_at).toISOString().slice(0, 10)} · veille Tohu`,
      }
      const rendered = renderAlerte(data)
      const { data: members } = await supabase.from('memberships').select('user_id').eq('organization_id', s.organization_id)
      for (const m of (members ?? [])) {
        try {
          const { data: pref } = await supabase.from('email_preferences').select('unsubscribed_all,alerte_enabled').eq('user_id', m.user_id).maybeSingle()
          if (pref?.unsubscribed_all || pref?.alerte_enabled === false) { skipped++; continue }
          const { data: u } = await supabase.auth.admin.getUserById(m.user_id)
          const email = u?.user?.email
          if (!email) { skipped++; continue }
          const res = await sendEmail({ supabase, userId: m.user_id, organizationId: s.organization_id, type: 'alerte', to: email, subject: rendered.subject, html: rendered.html, dedupeKey: `alerte:${s.id}:${m.user_id}` })
          if (res.sent) sent++; else skipped++
        } catch { skipped++ }
      }
    }
    return json({ ok: true, mode: 'cron', sent, skipped })
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : 'Envoi impossible' }, 500)
  }
})

// Wrapper d'envoi e-mail (Resend) partagé par tous les senders (digest, antisèche,
// alerte, nurturing). Centralise la doctrine d'envoi ACT-88 :
//  - opt-out global + désactivation par type (email_preferences) ;
//  - idempotence via dedupe_key (email_log) : un même e-mail n'est jamais envoyé 2×
//    (digest hebdo = 1 clé/semaine, antisèche = 1 clé/réunion) ;
//  - plafond d'alertes : max N/semaine/utilisateur (défaut 3).
// Aucune intelligence ici : les senders fournissent le HTML déjà rendu.

export type EmailType =
  | 'digest' | 'digest_empty'
  | 'antiseche'
  | 'alerte'
  | 'onb_1' | 'onb_2' | 'onb_3' | 'onb_4' | 'onb_5'

export const EMAIL_FROM = Deno.env.get('EMAIL_FROM') ?? 'Tohu <bonjour@tohu.co>'
export const EMAIL_REPLY_TO = Deno.env.get('EMAIL_REPLY_TO') ?? 'bonjour@tohu.co'
const PREFERENCES_URL = Deno.env.get('EMAIL_PREFERENCES_URL') ?? 'https://tohu.co/preferences'

// Colonne d'activation par famille d'e-mail (null = toujours autorisé).
const TYPE_TOGGLE: Record<EmailType, string | null> = {
  digest: 'digest_enabled', digest_empty: 'digest_enabled',
  antiseche: 'antiseche_enabled',
  alerte: 'alerte_enabled',
  onb_1: 'onboarding_enabled', onb_2: 'onboarding_enabled', onb_3: 'onboarding_enabled',
  onb_4: 'onboarding_enabled', onb_5: 'onboarding_enabled',
}
// Famille de diffusion (pilotage super-admin : global / type de compte / user).
const DISPATCH_FAMILY: Record<EmailType, string> = {
  digest: 'digest', digest_empty: 'digest', antiseche: 'antiseche', alerte: 'alerte',
  onb_1: 'nurturing', onb_2: 'nurturing', onb_3: 'nurturing', onb_4: 'nurturing', onb_5: 'nurturing',
}

/** Lundi 00:00 UTC de la semaine courante — borne du plafond hebdo d'alertes. */
function startOfIsoWeek(now = new Date()): Date {
  const date = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()))
  const day = date.getUTCDay() || 7 // dimanche = 7
  date.setUTCDate(date.getUTCDate() - (day - 1))
  return date
}

export type SendEmailInput = {
  supabase: any
  userId: string
  organizationId?: string | null
  type: EmailType
  to: string
  subject: string
  html: string
  // Clé d'idempotence. Ex. `digest:{userId}:{isoWeek}`, `antiseche:{meetingId}`,
  // `alerte:{signalId}`, `onb_2:{userId}`. Deux appels avec la même clé = 1 envoi.
  dedupeKey: string
  replyTo?: string
}

export type SendEmailResult =
  | { sent: true; id: string | null }
  | { sent: false; skipped: true; reason: string }

export async function sendEmail(input: SendEmailInput): Promise<SendEmailResult> {
  const { supabase, userId, organizationId = null, type, to, subject, html, dedupeKey } = input

  // 1) Idempotence : déjà envoyé sous cette clé ?
  const { data: already } = await supabase.from('email_log')
    .select('status').eq('dedupe_key', dedupeKey).maybeSingle()
  if (already?.status === 'sent') return { sent: false, skipped: true, reason: 'already_sent' }

  // 2) Préférences : opt-out global + désactivation par type.
  const { data: pref } = await supabase.from('email_preferences')
    .select('unsubscribed_all, digest_enabled, antiseche_enabled, alerte_enabled, onboarding_enabled, alerte_max_per_week')
    .eq('user_id', userId).maybeSingle()
  if (pref?.unsubscribed_all) return { sent: false, skipped: true, reason: 'unsubscribed_all' }
  const toggle = TYPE_TOGGLE[type]
  if (toggle && pref && pref[toggle] === false) return { sent: false, skipped: true, reason: 'type_disabled' }

  // Règles de diffusion pilotées par le super-admin (global / type de compte / user).
  const { data: dispatchAllowed } = await supabase.rpc('email_dispatch_allowed', { p_user_id: userId, p_email_type: DISPATCH_FAMILY[type] })
  if (dispatchAllowed === false) return { sent: false, skipped: true, reason: 'dispatch_disabled' }

  // 3) Plafond d'alertes : max N/semaine/utilisateur (ACT-88).
  if (type === 'alerte') {
    const cap = pref?.alerte_max_per_week ?? 3
    const { count } = await supabase.from('email_log')
      .select('id', { count: 'exact', head: true })
      .eq('user_id', userId).eq('email_type', 'alerte').eq('status', 'sent')
      .gte('created_at', startOfIsoWeek().toISOString())
    if ((count ?? 0) >= cap) return { sent: false, skipped: true, reason: 'weekly_alert_cap' }
  }

  // 4) Envoi Resend.
  const apiKey = Deno.env.get('RESEND_API_KEY')
  if (!apiKey) throw new Error('RESEND_API_KEY manquant')
  const response = await fetch('https://api.resend.com/emails', {
    method: 'POST',
    headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      from: EMAIL_FROM,
      to: [to],
      subject,
      html,
      reply_to: input.replyTo ?? EMAIL_REPLY_TO,
      headers: { 'List-Unsubscribe': `<${PREFERENCES_URL}>`, 'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click' },
      tags: [{ name: 'type', value: type }],
    }),
  })
  const payload = await response.json().catch(() => ({}))
  const ok = response.ok

  // 5) Journalisation (upsert sur dedupe_key → l'échec peut être rejoué).
  await supabase.from('email_log').upsert({
    user_id: userId, organization_id: organizationId, email_type: type, dedupe_key: dedupeKey,
    to_email: to, subject, resend_id: (payload as any)?.id ?? null,
    status: ok ? 'sent' : 'failed', error: ok ? null : JSON.stringify(payload).slice(0, 500),
  }, { onConflict: 'dedupe_key' })

  if (!ok) throw new Error(`Resend ${response.status}: ${JSON.stringify(payload).slice(0, 200)}`)
  return { sent: true, id: (payload as any)?.id ?? null }
}

/** Clé de semaine ISO (ex. 2026-W32) pour la dédup du digest hebdo. */
export function isoWeekKey(now = new Date()): string {
  const date = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()))
  const day = date.getUTCDay() || 7
  date.setUTCDate(date.getUTCDate() + 4 - day)
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1))
  const week = Math.ceil(((date.getTime() - yearStart.getTime()) / 86400000 + 1) / 7)
  return `${date.getUTCFullYear()}-W${String(week).padStart(2, '0')}`
}

// Rendu de l'alerte (signal fort en temps réel) sur le layout partagé.
import { EPI, MONO, C, esc, sectionLabel, rule, row, emailShell } from './layout.ts'

export type AlerteData = {
  subject: string; preheader: string
  tag: { text: string; color: 'red' | 'green' | 'blue' }
  title: string           // l'événement (titre du signal)
  who: string             // "Adivisa Techno · Erwan Lefèvre"
  proof: string[]         // "La preuve" : éléments/sources
  source: string          // "LinkedIn + presse · 2 sources"
  impact: string          // "Ce que ça change chez toi"
  cta?: { label: string; url: string }
  computedNote: string
}

const TAG: Record<'red' | 'green' | 'blue', string> = {
  red: `color:${C.red};background:#FDEFF1;`, green: `color:${C.green};background:#EDF8F2;`, blue: `color:${C.teal};background:#EAF6F8;`,
}

export function renderAlerte(data: AlerteData): { subject: string; html: string } {
  const hero = `<div style="padding-bottom:10px;"><span style="display:inline-block;font-family:${MONO};font-size:9.5px;font-weight:700;letter-spacing:.9px;text-transform:uppercase;${TAG[data.tag.color]}padding:4px 9px;border-radius:6px;">${esc(data.tag.text)}</span></div><div class="h1" style="font-family:${EPI};font-size:29px;line-height:36px;font-weight:800;letter-spacing:-.7px;color:${C.ink};padding-bottom:8px;">${esc(data.title)}</div><div style="font-family:${EPI};font-size:14.5px;line-height:22px;color:${C.soft};">${esc(data.who)}</div>`

  const proof = rule() + sectionLabel('La preuve')
    + `<table role="presentation" width="100%" style="border:1px solid ${C.line};border-radius:11px;"><tr><td style="padding:15px 18px;"><table role="presentation" width="100%">${data.proof.map((p) => `<tr><td valign="top" width="18" style="padding:0 0 8px 0;color:${C.teal};font-family:${EPI};font-size:13px;">&#9679;</td><td valign="top" style="padding:0 0 8px 0;font-family:${EPI};font-size:14px;line-height:21px;color:${C.ink};">${p}</td></tr>`).join('')}</table><div style="font-family:${EPI};font-size:11.5px;color:${C.faint};padding-top:6px;">${esc(data.source)}</div></td></tr></table>`

  const impact = rule() + sectionLabel('Ce que ça change chez toi')
    + `<table role="presentation" width="100%" style="background:${C.lav};border-radius:11px;"><tr><td style="padding:16px 18px;font-family:${EPI};font-size:14.5px;line-height:23px;color:${C.ink};">${data.impact}</td></tr></table>`

  const inner = row(hero, { top: 34, bottom: 6 }) + row(proof, { top: 24 }) + row(impact, { top: 24, bottom: 26 })

  return {
    subject: data.subject,
    html: emailShell({ subject: data.subject, preheader: data.preheader, headerRight: 'Alerte · veille', cta: data.cta, footerNote: data.computedNote }, inner),
  }
}

// Layout e-mail partagé — habillage figé : fond blanc, largeur 680, épuré (pas de
// cadre flottant), masthead dégradé pleine largeur, DA Tohu (Epilogue / JetBrains
// Mono, violet→rose). Tous les templates (digest, antisèche, alerte, nurturing) le
// réutilisent pour rester cohérents.
export const EPI = "'Epilogue',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif"
export const MONO = "'JetBrains Mono',ui-monospace,'SF Mono',Menlo,Consolas,'Courier New',monospace"
export const GRAD = 'background-color:#6E50C8;background-image:linear-gradient(135deg,#6E50C8 0%,#E14FA0 100%)'
export const PX = 'padding-left:34px;padding-right:34px;'

export const C = {
  ink: '#1A1040', soft: '#5B5470', muted: '#8B839F', faint: '#9A93AC',
  green: '#2EA86A', red: '#D94F63', amber: '#C97A20', teal: '#2896A8', violet: '#6E50C8',
  line: '#E7E3F2', lav: '#F7F5FD', lavLine: '#E3DCF5',
}

export function esc(value: string): string {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
}

/** Intitulé de section : ● TEXTE en mono, gris. */
export function sectionLabel(text: string): string {
  return `<div style="font-family:${MONO};font-size:10px;font-weight:700;letter-spacing:1.6px;text-transform:uppercase;color:${C.muted};padding-bottom:13px;">&#9679; ${text}</div>`
}

export function rule(): string {
  return `<div style="height:1px;background:${C.line};margin-bottom:20px;font-size:0;line-height:1px;">&nbsp;</div>`
}

/** Ligne de contenu pleine largeur (padding latéral constant, fond blanc). */
export function row(inner: string, opts: { top?: number; bottom?: number } = {}): string {
  const top = opts.top ?? 28
  const bottom = opts.bottom ?? 0
  return `<tr><td class="px" style="background:#FFFFFF;${PX}padding-top:${top}px;padding-bottom:${bottom}px;">${inner}</td></tr>`
}

/** Bouton principal (dégradé). */
export function ctaButton(label: string, url: string): string {
  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr><td align="center" style="${GRAD};border-radius:12px;"><a href="${esc(url)}" style="display:block;padding:15px 34px;font-family:${EPI};font-size:15px;font-weight:700;color:#FFFFFF;letter-spacing:-.1px;">${label} &rarr;</a></td></tr></table>`
}

export type ShellOptions = {
  subject: string
  preheader: string
  headerRight: string          // ex. "Le point · lundi 8 h" / "Antisèche · dans 2 h"
  cta?: { label: string; url: string }
  footerNote?: string          // ligne "Calculé … · sources : …"
}

/** Enveloppe complète : head + masthead + contenu (inner) + pied de page. */
