export function cleanEmail(value: string | null | undefined): string {
  return String(value ?? '').trim().toLowerCase()
}

export function stripHtml(value: string): string {
  return value.replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>|<\/div>/gi, '\n').replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/\s+\n/g, '\n').replace(/\n{3,}/g, '\n\n').replace(/[ \t]{2,}/g, ' ').trim()
}

export function sanitizeBody(value: string): string {
  return stripHtml(value).split('\n').filter((line) => {
    const text = line.trim()
    return text && !text.startsWith('>') && !/^(De|From|À|To|Envoyé|Sent|Objet|Subject)\s*:/i.test(text)
  }).join('\n').slice(0, 1800)
}

export function pct(value: unknown): number {
  const parsed = Number(value ?? 0)
  if (!Number.isFinite(parsed)) return 0
  return Math.round(Math.max(0, Math.min(100, parsed <= 1 ? parsed * 100 : parsed)))
}

export function extractJson(value: string): Analysis {
  const normalized = value.trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')

  try { return JSON.parse(normalized) } catch {
    for (let start = normalized.indexOf('{'); start >= 0; start = normalized.indexOf('{', start + 1)) {
      let depth = 0
      let inString = false
      let escaped = false
      for (let index = start; index < normalized.length; index++) {
        const char = normalized[index]
        if (inString) {
          if (escaped) escaped = false
          else if (char === '\\') escaped = true
          else if (char === '"') inString = false
          continue
        }
        if (char === '"') inString = true
        else if (char === '{') depth++
        else if (char === '}' && --depth === 0) {
          try { return JSON.parse(normalized.slice(start, index + 1)) } catch { break }
        }
      }
    }
    throw new Error('Analyse IA non parsable')
  }
}

export function openRouterContent(data: any): string {
  const content = data?.choices?.[0]?.message?.content
  if (typeof content === 'string') return content
  if (Array.isArray(content)) {
    return content.map((part) => typeof part === 'string' ? part : String(part?.text ?? '')).join('')
  }
  return ''
}

export function errorMessage(error: unknown): string {
  if (error instanceof Error) return error.message
  if (error && typeof error === 'object') {
    const value = error as Record<string, unknown>
    return String(value.message ?? value.error_description ?? value.details ?? JSON.stringify(value))
  }
  return String(error ?? 'analyse impossible')
}

export function asRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {}
}

export function maturityFor(interactionCount: number): 'none' | 'emerging' | 'usable' | 'consolidated' | 'refined' {
  if (interactionCount < 3) return 'none'
  if (interactionCount < 10) return 'emerging'
  if (interactionCount < 25) return 'usable'
  if (interactionCount < 50) return 'consolidated'
  return 'refined'
}

export const PRIMARY_AXIS_IDS = [
  'rythme',
  'argumentation',
  'engagement',
  'registre',
  'tonalite',
  'espace_parole',
] as const

export function structuredBehavioralSignals(profile: Record<string, unknown>): Array<{ trait: string; observation: string; confidence: number }> {
  const axes = asRecord(profile.primary_axes)
  return PRIMARY_AXIS_IDS.flatMap((trait) => {
    const axis = asRecord(axes[trait])
    const observation = typeof axis.observation === 'string' ? axis.observation.trim() : ''
    if (!observation || axis.status === 'insufficient') return []
    return [{ trait, observation, confidence: pct(axis.confidence) }]
  })
}

export function assertCurrentCognitiveSchema(profile: Record<string, unknown>): void {
  if (Number(profile.schema_version) !== 3) throw new Error('Le moteur a retourné un profil comportemental dans un ancien format.')
  const axes = asRecord(profile.primary_axes)
  const missing = PRIMARY_AXIS_IDS.filter((axisId) => !axes[axisId] || typeof axes[axisId] !== 'object')
  if (missing.length) throw new Error(`Profil comportemental incomplet : axes manquants (${missing.join(', ')}).`)
}

export function isRetriableAnalysisError(error: unknown): boolean {
  const message = errorMessage(error)
  return message === 'Analyse IA non parsable'
    || message === 'Le moteur a retourné un profil comportemental dans un ancien format.'
    || message.startsWith('Profil comportemental incomplet :')
}

export type UsageLogContext = { client: Parameters<typeof logAiUsage>[0]; organizationId?: string | null; userId?: string | null }

export async function analyze(
  name: string,
  role: 'responsable' | 'contact',
  excerpts: string[],
  previousProfile: Record<string, unknown> = {},
  interactionCount = excerpts.length,
  usageLog?: UsageLogContext,
  signal?: AbortSignal,
): Promise<Analysis> {
  const apiKey = Deno.env.get('OPENROUTER_API_KEY')
  if (!apiKey) throw new Error('OPENROUTER_API_KEY non configurée')
  const model = Deno.env.get('OPENROUTER_ANALYSIS_MODEL') ?? 'google/gemini-3.1-flash-lite'
  const corpus = excerpts.slice(-30).join('\n---\n').slice(0, 16000)
  const compatiblePreviousProfile = Number(previousProfile.schema_version) === 3 ? previousProfile : {}
  const previous = Object.keys(compatiblePreviousProfile).length ? JSON.stringify(compatiblePreviousProfile).slice(0, 8000) : '{}'
  const roleLabel = role === 'responsable' ? 'responsable de compte connecté' : 'personne suivie'
  const prompt = `Tu construis le profil comportemental évolutif de ${name}, ${roleLabel}.\nTu disposes de ${interactionCount} interactions attribuées à cette personne. Analyse uniquement ce qu'elle a réellement rédigé dans les emails ou messages Slack, ou prononcé dans les passages de réunion explicitement attribués. Le profil précédent sert de mémoire statistique : conserve une tendance si les nouvelles preuves la confirment, nuance-la si elles la contredisent, et ne la remplace jamais sans preuves convergentes.\n\nRègles impératives :\n- aucune pathologie, donnée sensible ou personnalité essentialisée ;\n- aucune citation mot pour mot ni texte d'exemple dans "observation" — seule "evidence" peut paraphraser un verbatim daté ;\n- chaque observation doit être une paraphrase propre à cette personne ;\n- les identifiants et axes du schéma sont fixes et doivent tous être présents ;\n- status vaut "observed" si plusieurs preuves convergent, "emerging" si la tendance reste fragile, "insufficient" sans preuve ;\n- pour "insufficient", tous les champs numériques et textuels de l'axe valent null et "evidence" est vide ;\n- pour interpersonal/posture : score et confidence entre 0 et 100, evolution vaut "rising"/"stable"/"declining"/"mixed"/null ; assertiveness conciliant(0)->assertif(100), warmth distant(0)->chaleureux(100) ;\n- pour chaque axe primaire : "raw_score" position 0-100 du pôle gauche au pôle droit — rythme Posé(0)->Rapide(100), argumentation Récit(0)->Chiffré(100), engagement Implicite(0)->Explicite(100), registre Formel(0)->Direct(100), tonalité Sobre(0)->Chaleureux(100), espace_parole Écoute(0)->Occupe(100) ; "margin_pts" incertitude en points ; "trend_pts" delta signé vs profil précédent (null si aucun), "trend_label" cohérent (stable si |trend_pts|<=3) ; "evidence" 2 à 3 items courts ;\n- pour chaque axe secondaire : "score" 0-100 (orientation Tâche(0)->Relation(100), certainty Prudent(0)->Affirmatif(100), novelty Éprouvé(0)->Exploratoire(100), initiative Suit(0)->Mène(100)) ;\n- evidence_count compte les preuves distinctes ; source_types parmi "email", "meeting_transcript", "slack".\n- "trust" (Confiance) mesure la FIABILITÉ relationnelle, jamais le volume : engagements tenus/non tenus, réponses effectives, respect des échéances. "status":"insufficient" sans preuve concrète.\n- "satisfaction" mesure la QUALITÉ perçue : retours positifs / frustrations. "status":"insufficient" sans signal explicite.\n- "account_relation" identifie la NATURE commerciale de la relation à partir d'indices concrets. "category" parmi Prospect/Client/Fournisseur / Prestataire/Partenaire/Investisseur, ou null pour un "responsable de compte connecté" (auto-profil interne). "status":"insufficient" tant que category est null.\n- "approach_guidance" : 2 à 4 scénarios concrets et contextuels, do/dont exactement 3 chacun, ancrés sur les preuves. Liste vide si insuffisant.\n\nRéponds uniquement avec ce JSON strict :\n{\n  "executive_summary": "synthèse personnalisée ou null",\n  "cognitive_mode": "posture dominante ou null",\n  "cognitive_mode_confidence": 0,\n  "global_confidence": 0,\n  "trust": {"status":"insufficient","score":null,"observation":null,"confidence":null,"evidence":[],"evidence_count":0,"source_types":[]},\n  "satisfaction": {"status":"insufficient","score":null,"observation":null,"confidence":null,"evidence":[],"evidence_count":0,"source_types":[]},\n  "account_relation": {"status":"insufficient","category":null,"observation":null,"confidence":null,"evidence":[],"evidence_count":0,"source_types":[]},\n  "cognitive_profile_data": {\n    "schema_version": 3,\n    "interpersonal": {\n      "assertiveness": {"status":"insufficient","score":null,"label":null,"observation":null,"confidence":null,"evidence_count":0,"source_types":[],"evolution":null},\n      "warmth": {"status":"insufficient","score":null,"label":null,"observation":null,"confidence":null,"evidence_count":0,"source_types":[],"evolution":null}\n    },\n    "primary_axes": {\n      "rythme": {"status":"insufficient","raw_score":null,"margin_pts":null,"trend_pts":null,"trend_label":null,"observation":null,"confidence":null,"evidence":[],"evidence_count":0,"source_types":[]},\n      "argumentation": {"status":"insufficient","raw_score":null,"margin_pts":null,"trend_pts":null,"trend_label":null,"observation":null,"confidence":null,"evidence":[],"evidence_count":0,"source_types":[]},\n      "engagement": {"status":"insufficient","raw_score":null,"margin_pts":null,"trend_pts":null,"trend_label":null,"observation":null,"confidence":null,"evidence":[],"evidence_count":0,"source_types":[]},\n      "registre": {"status":"insufficient","raw_score":null,"margin_pts":null,"trend_pts":null,"trend_label":null,"observation":null,"confidence":null,"evidence":[],"evidence_count":0,"source_types":[]},\n      "tonalite": {"status":"insufficient","raw_score":null,"margin_pts":null,"trend_pts":null,"trend_label":null,"observation":null,"confidence":null,"evidence":[],"evidence_count":0,"source_types":[]},\n      "espace_parole": {"status":"insufficient","raw_score":null,"margin_pts":null,"trend_pts":null,"trend_label":null,"observation":null,"confidence":null,"evidence":[],"evidence_count":0,"source_types":[]}\n    },\n    "secondary_axes": {\n      "orientation": {"status":"insufficient","score":null,"observation":null,"confidence":null,"evidence_count":0,"source_types":[]},\n      "certainty": {"status":"insufficient","score":null,"observation":null,"confidence":null,"evidence_count":0,"source_types":[]},\n      "novelty": {"status":"insufficient","score":null,"observation":null,"confidence":null,"evidence_count":0,"source_types":[]},\n      "initiative": {"status":"insufficient","score":null,"observation":null,"confidence":null,"evidence_count":0,"source_types":[]}\n    },\n    "posture": {"status":"insufficient","score":null,"label":null,"observation":null,"confidence":null,"evidence_count":0,"source_types":[],"evolution":null},\n    "approach_guidance": [{"context":"Avant un rendez-vous","summary":"phrase ancrée ou null","do":["a","b","c"],"dont":["a","b","c"]}]\n  }\n}\n\nProfil précédent : ${previous}\nNouveaux extraits :\n${corpus}`
  const requestAnalysis = async (retry: boolean): Promise<Analysis> => {
    const response = await fetch('https://openrouter.ai/api/v1/chat/completions', {
      signal,
      method: 'POST',
      headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json', 'HTTP-Referer': Deno.env.get('SITE_URL') ?? 'https://tohu.app', 'X-Title': 'Tohu Email Behavior Analysis' },
      body: JSON.stringify({
        model,
        temperature: retry ? 0 : 0.1,
        response_format: COGNITIVE_PROFILE_RESPONSE_FORMAT,
        provider: { require_parameters: true },
        max_tokens: retry ? 7000 : 6000,
        messages: [{
          role: 'user',
          content: retry
            ? `${prompt}\n\nIMPORTANT : la tentative précédente a produit un JSON invalide, tronqué ou dans un ancien schéma. Repars exclusivement du contrat ci-dessus : schema_version doit valoir 3 et les six primary_axes doivent tous être présents. Réponds de façon compacte, sans Markdown, et ferme toutes les structures JSON.`
            : prompt,
        }],
      }),
    })
    if (!response.ok) throw new Error(`OpenRouter ${response.status}`)
    const data = await response.json()
    if (usageLog) await logAiUsage(usageLog.client, { organizationId: usageLog.organizationId, userId: usageLog.userId, fn: 'behavior-analysis:analyze', model, usage: data?.usage })
    const content = openRouterContent(data)
    try {
      const result = extractJson(content)
      assertCurrentCognitiveSchema(asRecord(result.cognitive_profile_data))
      return result
    } catch (error) {
      console.warn('Réponse comportementale invalide', {
        retry,
        finishReason: data?.choices?.[0]?.finish_reason ?? null,
        contentLength: content.length,
        validationError: errorMessage(error),
      })
      throw error
    }
  }

  try {
    return await requestAnalysis(false)
  } catch (error) {
    if (!isRetriableAnalysisError(error)) throw error
    return await requestAnalysis(true)
  }
}

export function normalizedSpeaker(value: string | null | undefined): string {
  return String(value ?? '')
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()
}

export function attributedTranscriptExcerpt(transcript: string, identities: string[]): string | null {
  const speakers = new Set(identities
    .flatMap((identity) => {
      const email = cleanEmail(identity)
      return [identity, email.includes('@') ? email.split('@')[0] : '']
    })
    .map(normalizedSpeaker)
    .filter((identity) => identity.length >= 4))
  if (!speakers.size) return null

  const attributed = String(transcript ?? '').split(/\r?\n/).flatMap((line) => {
    const match = line.trim().match(/^(.+?)(?:\s+\(\d{1,2}:\d{2}(?::\d{2})?\))?\s*:\s*(.+)$/)
    if (!match || !speakers.has(normalizedSpeaker(match[1]))) return []
    const content = sanitizeBody(match[2])
    return content ? [content] : []
  })
  if (!attributed.length) return null
  return `[Transcription de réunion]\n${attributed.join('\n')}`.slice(0, 2400)
}

export type PersistContactProfileParams = {
  organizationId: string
  contactId: string
  result: Analysis
  messageCount: number
  meetingCount: number
  interactionCount: number
  updatedFrom: string[]
  signalSource: string
  sourceRef?: string
  observedAt?: string
}

export async function persistContactProfile(
  supabase: SupabaseClient,
  params: PersistContactProfileParams,
): Promise<{ profileId: string; signalCount: number }> {
  const { organizationId, contactId, result, messageCount, meetingCount, interactionCount, updatedFrom, signalSource } = params
  const cognitiveProfileData = asRecord(result.cognitive_profile_data)
  assertCurrentCognitiveSchema(cognitiveProfileData)
  const structuredSignals = structuredBehavioralSignals(cognitiveProfileData)
  const now = new Date().toISOString()
  const observedAt = params.observedAt ?? now
  const sourceRef = params.sourceRef ?? `sync:${now}`
  const trust = result.trust?.status && result.trust.status !== 'insufficient' && result.trust.score != null ? result.trust : null
  const satisfaction = result.satisfaction?.status && result.satisfaction.status !== 'insufficient' && result.satisfaction.score != null ? result.satisfaction : null
  const accountRelation = result.account_relation?.status && result.account_relation.status !== 'insufficient'
    && result.account_relation.category && (ACCOUNT_RELATION_CATEGORIES as readonly string[]).includes(result.account_relation.category)
    ? result.account_relation : null
  const { data: cognitiveProfile, error: profileError } = await supabase.from('cognitive_profiles').upsert({
    organization_id: organizationId,
    contact_id: contactId,
    profile_version: 1,
    global_confidence: pct(result.global_confidence),
    summary: result.executive_summary ?? null,
    executive_summary: result.executive_summary ?? null,
    cognitive_mode: result.cognitive_mode ?? null,
    cognitive_mode_confidence: pct(result.cognitive_mode_confidence),
    behavioral_analysis_data: structuredSignals,
    communication_style_data: asRecord(cognitiveProfileData.secondary_axes),
    cognitive_profile_data: cognitiveProfileData,
    source_message_count: messageCount,
    source_meeting_count: meetingCount,
    source_interaction_count: interactionCount,
    maturity_level: maturityFor(interactionCount),
    analysis_version: 3,
    last_analyzed_at: now,
    updated_from: updatedFrom,
    updated_at: now,
    ...(trust ? { trust_score: pct(trust.score), trust_reasoning: trust.observation ?? null, trust_analyzed_at: now } : {}),
    ...(satisfaction ? { satisfaction_score: pct(satisfaction.score), satisfaction_reasoning: satisfaction.observation ?? null, satisfaction_analyzed_at: now } : {}),
    ...(accountRelation ? { account_relation_hint: accountRelation.category, account_relation_hint_confidence: pct(accountRelation.confidence), account_relation_hint_reasoning: accountRelation.observation ?? null, account_relation_hint_analyzed_at: now } : {}),
  }, { onConflict: 'organization_id,contact_id,profile_version' }).select('id').single()
  if (profileError || !cognitiveProfile) throw profileError ?? new Error('Profil cognitif non enregistré')
  const signals = structuredSignals.map((item) => ({ organization_id: organizationId, contact_id: contactId, profile_id: cognitiveProfile.id, signal_type: item.trait, text: item.observation, inference: item.trait, inference_level: 'observable', confidence: pct(item.confidence), source_type: signalSource, source_ref: sourceRef, observed_at: observedAt }))
  if (signals.length) {
    const { error: signalsError } = await supabase.from('behavioral_signals').insert(signals)
    if (signalsError) throw signalsError
  }
  return { profileId: cognitiveProfile.id as string, signalCount: signals.length }
}

const PRICING: Record<string, { in: number; out: number }> = {
  'google/gemini-3.1-flash-lite': { in: 0.10, out: 0.40 },
  'anthropic/claude-haiku-4.5': { in: 1.00, out: 5.00 },
  'openai/gpt-4.1-mini': { in: 0.40, out: 1.60 },
}
const DEFAULT_PRICE = { in: 0.50, out: 1.50 }

export type TokenUsage = { prompt_tokens?: number; completion_tokens?: number; total_tokens?: number } | null | undefined

export function estimateCostUsd(model: string, promptTokens: number, completionTokens: number): number {
  const price = PRICING[model] ?? DEFAULT_PRICE
  return (promptTokens / 1_000_000) * price.in + (completionTokens / 1_000_000) * price.out
}

type AnySupabase = { from: (table: string) => { insert: (rows: Record<string, unknown>) => PromiseLike<{ error: unknown }> } }

export async function logAiUsage(client: AnySupabase, params: {
  organizationId?: string | null
  userId?: string | null
  fn: string
  model: string
  usage: TokenUsage
}): Promise<void> {
  try {
    const prompt = Math.max(0, Math.round(Number(params.usage?.prompt_tokens ?? 0)))
    const completion = Math.max(0, Math.round(Number(params.usage?.completion_tokens ?? 0)))
    const total = Math.max(0, Math.round(Number(params.usage?.total_tokens ?? prompt + completion)))
    await client.from('ai_usage_events').insert({
      organization_id: params.organizationId ?? null,
      user_id: params.userId ?? null,
      fn: params.fn,
      model: params.model,
      prompt_tokens: prompt,
      completion_tokens: completion,
      total_tokens: total,
      estimated_cost_usd: Number(estimateCostUsd(params.model, prompt, completion).toFixed(6)),
    })
  } catch {
    // silencieux
  }
}

// Veille PAR PERSONNE (phase 2). Cron : détecte changement de poste + activité récente
// via l'agent d'enrichissement (réutilise cache + déjà-connu) → behavioral_signals + notifications.
//
// v2 — tiering par valeur (A/B/C) + routage de sources par type de domaine +
// réutilisation du contexte entreprise déjà collecté par monitor-company-news,
// pour ne payer l'agent IA que sur ce qui le mérite et ne jamais rechercher deux
// fois la même chose.
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { runEnrichmentAgentThrottled } from '../_shared/enrichment-agent.ts';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-cron-secret',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};
function jsonResponse(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
}

const STALE_MS = 12 * 60 * 60 * 1000;
const MAX_PER_RUN = 18;
// L'agent d'enrichissement tournait via un workflow n8n (webhook + node "AI Agent"),
// sur une instance à mémoire partagée : plusieurs invocations simultanées (cron + un
// "Actualiser" manuel) dépassaient le cap LOCAL ci-dessous et faisaient crasher
// l'instance entière (incidents du 2026-07-20 et du 2026-07-22). Depuis, l'agent tourne
// en appels directs OpenRouter + Perplexity (supabase/functions/_shared/enrichment-agent.ts),
// protégés par un sémaphore GLOBAL en base (acquire_enrichment_slot) qui borne le vrai
// nombre d'appels IA simultanés tous déclencheurs confondus. Ce cap local reste utile
// pour ne pas ouvrir 18 promesses d'un coup en attente du sémaphore.
const LOCAL_CONCURRENCY = 5;
const COMPANY_FRESH_MS = 60 * 24 * 60 * 60 * 1000; // 60 jours

// ── Classification de domaine (portée de enrich-contact) ─────────────────────
const PERSONAL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'outlook.com', 'outlook.fr',
  'hotmail.com', 'hotmail.fr', 'live.com', 'live.fr', 'msn.com',
  'icloud.com', 'me.com', 'yahoo.com', 'yahoo.fr', 'proton.me', 'protonmail.com',
  'orange.fr', 'wanadoo.fr', 'free.fr', 'sfr.fr', 'laposte.net',
  'gmx.com', 'gmx.fr', 'aol.com', 'mac.com',
  'avocat.com', 'avocat.fr',
]);
const MEGACORP_DOMAINS = new Set(['linkedin.com', 'google.com', 'microsoft.com', 'apple.com', 'amazon.com', 'meta.com', 'facebook.com', 'twitter.com', 'x.com']);
const EDU_PATTERNS = ['lycee', 'ecole', 'univ', 'iut', 'ens', 'sup', 'college', 'academie', 'institut', 'school', 'edu', 'campus', 'formation'];

type DomainType = 'personal' | 'megacorp' | 'edu' | 'startup' | 'company_fr' | 'company_intl';

function classifyDomain(email: string): { domain: string; domainType: DomainType } {
  const domain = (email.split('@')[1] ?? '').toLowerCase().trim();
  if (!domain) return { domain, domainType: 'personal' };
  if (MEGACORP_DOMAINS.has(domain)) return { domain, domainType: 'megacorp' };
  if (PERSONAL_DOMAINS.has(domain)) return { domain, domainType: 'personal' };
  const parts = domain.split('.');
  const tld = parts[parts.length - 1] ?? '';
  const isEdu = tld === 'edu' || parts.some((p) => EDU_PATTERNS.some((kw) => p.includes(kw)));
  if (isEdu) return { domain, domainType: 'edu' };
  if (['io', 'ai', 'app'].includes(tld)) return { domain, domainType: 'startup' };
  if (tld === 'fr') return { domain, domainType: 'company_fr' };
  return { domain, domainType: 'company_intl' };
}

function sourceHintsFor(domainType: DomainType): string | null {
  switch (domainType) {
    case 'company_fr': return 'Entreprise française : privilégie pappers.fr, societe.com, infogreffe.fr pour SIREN/dirigeants/forme juridique, puis LinkedIn et le site officiel.';
    case 'startup': return 'Startup : privilégie crunchbase.com et wellfound.com pour fondateurs/levées, puis le site officiel et LinkedIn.';
    case 'company_intl': return 'Entreprise internationale : site officiel (pages équipe/leadership) et LinkedIn en priorité.';
    case 'edu': return 'Établissement éducatif : site institutionnel et LinkedIn en priorité.';
    case 'personal': return 'Email personnel : recherche par nom + rôle connu uniquement, pas de registre d\'entreprise.';
    default: return null;
  }
}

/** "Fxravet81" pour fxravet81@gmail.com, ou "John Doe" pour john.doe@x.com : le
 *  nom actuel n'est qu'une reformulation de la partie locale de l'email, pas un
 *  vrai nom trouvé quelque part. Sert à savoir si on peut remplacer le nom sans
 *  confirmation quand l'agent en trouve un meilleur avec forte confiance. */
function looksLikePlaceholderName(fullName: string, email: string): boolean {
  const local = (email.split('@')[0] ?? '').toLowerCase().replace(/[^a-z0-9]+/g, '');
  const normalized = fullName.toLowerCase().replace(/[^a-z0-9]+/g, '');
  return normalized.length > 0 && normalized === local;
}

/** L'agent renvoie parfois "to_confirm"/"N/A" dans linkedinUrl au lieu de null
 *  (confusion avec les champs *Confidence du schéma) — observé en prod : 8
 *  contacts d'un même org se sont retrouvés avec linkedin_url="to_confirm",
 *  faisant croire au détecteur de doublons que c'était 8 fois la même personne.
 *  Seule une vraie URL de profil personnel est acceptée. */
function sanitizeLinkedinUrl(value: unknown): string | null {
  if (typeof value !== 'string') return null;
  return /^https?:\/\/([a-z]{2,3}\.)?linkedin\.com\/in\//i.test(value.trim()) ? value.trim() : null;
}

/** Filet de sécurité : le modèle respecte presque toujours la consigne "laisse
 *  fullName tel quel si rien trouvé", mais pas toujours — observé en test : un
 *  pseudo non résolu ("satyan81") reformaté en "satyan MICROSOFT" (le nom de la
 *  société pris pour un nom de famille) pour se conformer à la casse imposée.
 *  On ne fait jamais confiance à un candidat qui n'a pas la forme d'un nom de
 *  personne ou qui contient le nom de la société. */
function looksLikeRealPersonName(candidate: string, companyName: string): boolean {
  const parts = candidate.trim().split(/\s+/);
  if (parts.length < 2) return false;
  if (!parts.every((p) => /^[a-zà-öø-ÿ'-]+$/i.test(p))) return false;
  const companyNorm = companyName.toLowerCase().replace(/[^a-z0-9]+/g, '');
  if (companyNorm && parts.some((p) => p.toLowerCase().replace(/[^a-z0-9]+/g, '') === companyNorm)) return false;
  return true;
}

// ── Tiering par valeur ────────────────────────────────────────────────────────
type Tier = 'A' | 'B' | 'C';

function classifyTier(isTracked: boolean, hasOwner: boolean, interactionCount: number): Tier {
  if (isTracked && (hasOwner || interactionCount >= 3)) return 'A';
  if (interactionCount >= 1) return 'B';
  return 'C';
}

/** Exécute `worker` sur chaque item avec au plus `limit` appels concurrents —
 *  contrairement à Promise.allSettled(items.map(...)), qui les lance tous d'un coup. */
async function runWithConcurrency<T>(items: T[], limit: number, worker: (item: T) => Promise<void>): Promise<void> {
  let index = 0;
  async function next(): Promise<void> {
    const current = index++;
    if (current >= items.length) return;
    await worker(items[current]);
    return next();
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, () => next()));
}

type Contact = {
  id: string; full_name: string | null; email: string | null; organization_id: string;
  enrichment_data: any; owner_user_id: string | null; role_title?: string | null;
  linkedin_url?: string | null; location?: string | null;
  companies: { id?: string; name: string; domain: string | null; is_tracked?: boolean; enrichment_data?: any; enriched_at?: string | null } | null;
};

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders });
  if (req.method !== 'POST') return jsonResponse({ error: 'Method not allowed' }, 405);

  const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '');

  const body = await req.json().catch(() => ({}));
  const cronHeader = req.headers.get('x-cron-secret');
  let isCron = false;
  if (cronHeader) {
    const { data: sec } = await supabase.from('app_secrets').select('value').eq('name', 'monitor_cron').maybeSingle();
    if (sec?.value && sec.value === cronHeader) isCron = true;
  }

  let q = supabase.from('contacts')
    .select('id, full_name, email, organization_id, enrichment_data, owner_user_id, role_title, linkedin_url, location, companies(id, name, domain, is_tracked, enrichment_data, enriched_at)')
    .not('email', 'is', null).is('merged_into_contact_id', null);

  let mode: 'cron' | 'user' | 'super_admin_manual' | 'super_admin_contact' | 'super_admin_company' = 'user';
  let forceTierA = false;
  if (!isCron) {
    const auth = req.headers.get('Authorization');
    if (!auth) return jsonResponse({ error: 'Missing authorization' }, 401);
    const { data: { user }, error: userErr } = await supabase.auth.getUser(auth.replace('Bearer ', ''));
    if (userErr || !user) return jsonResponse({ error: 'Unauthorized' }, 401);

    if (body.contactId || body.companyId) {
      // Bouton « Enrichir maintenant » sur la fiche personne / fiche compte : réservé aux super admins.
      const { data: superAdminRow } = await supabase.from('super_admins').select('user_id').eq('user_id', user.id).maybeSingle();
      if (!superAdminRow) return jsonResponse({ error: 'Réservé aux super admins' }, 403);
      forceTierA = true;
      if (body.contactId) { mode = 'super_admin_contact'; q = q.eq('id', body.contactId); }
      else { mode = 'super_admin_company'; q = q.eq('company_id', body.companyId).eq('is_tracked', true); }
    } else if (body.organizationId) {
      q = q.eq('organization_id', body.organizationId).eq('is_tracked', true);
    } else {
      // Mode enrichissement manuel global (sans organizationId ni contactId/companyId) : réservé aux super admins.
      const { data: superAdminRow } = await supabase.from('super_admins').select('user_id').eq('user_id', user.id).maybeSingle();
      if (!superAdminRow) return jsonResponse({ error: 'organizationId required' }, 400);
      mode = 'super_admin_manual';
      const cutoff = new Date(Date.now() - STALE_MS).toISOString();
      q = q.eq('is_tracked', true).or(`last_monitored_at.is.null,last_monitored_at.lt.${cutoff}`);
    }
  } else {
    mode = 'cron';
    if (body.organizationId) {
      q = q.eq('organization_id', body.organizationId).eq('is_tracked', true);
    } else {
      const cutoff = new Date(Date.now() - STALE_MS).toISOString();
      q = q.eq('is_tracked', true).or(`last_monitored_at.is.null,last_monitored_at.lt.${cutoff}`);
    }
  }

  const { data: contacts } = await q.order('last_monitored_at', { ascending: true, nullsFirst: true }).limit(MAX_PER_RUN);
  if (!contacts?.length) return jsonResponse({ success: true, scanned: 0, signals: 0, notified: 0 });

  // ── Volume d'interactions par contact (pour le tiering) — une seule requête ──
  const contactIds = (contacts as Contact[]).map((c) => c.id);
  const { data: msgCounts } = await supabase.from('communication_messages').select('contact_id').in('contact_id', contactIds).limit(2000);
  const interactionByContact = new Map<string, number>();
  for (const row of (msgCounts ?? []) as Array<{ contact_id: string }>) {
    interactionByContact.set(row.contact_id, (interactionByContact.get(row.contact_id) ?? 0) + 1);
  }

  // ── Signaux entreprise récents (déjà collectés par monitor-company-news) ────
  const companyIds = [...new Set((contacts as Contact[]).map((c) => c.companies?.id).filter(Boolean))] as string[];
  const { data: recentCompanySignals } = companyIds.length
    ? await supabase.from('company_signals').select('company_id, title, observed_at').in('company_id', companyIds).order('observed_at', { ascending: false }).limit(60)
    : { data: [] as any[] };
  const signalsByCompany = new Map<string, string[]>();
  for (const row of (recentCompanySignals ?? []) as Array<{ company_id: string; title: string }>) {
    signalsByCompany.set(row.company_id, [...(signalsByCompany.get(row.company_id) ?? []), row.title]);
  }

  function companyContextFor(c: Contact): { context: string | null; skip: boolean } {
    const company = c.companies;
    if (!company) return { context: null, skip: false };
    const facts: string[] = [];
    const enrichedAt = company.enriched_at ? new Date(company.enriched_at).getTime() : 0;
    const isFreshEnrichment = enrichedAt > 0 && Date.now() - enrichedAt < COMPANY_FRESH_MS;
    if (isFreshEnrichment && company.enrichment_data) {
      const data = company.enrichment_data as Record<string, unknown>;
      if (data.industry) facts.push(`Secteur : ${data.industry}`);
      if (data.summary) facts.push(String(data.summary));
    }
    const recentTitles = signalsByCompany.get(company.id ?? '') ?? [];
    if (recentTitles.length) facts.push(`Actualités récentes déjà connues : ${recentTitles.slice(0, 3).join(' · ')}`);
    if (!facts.length) return { context: null, skip: false };
    return { context: `Entreprise ${company.name} — ${facts.join(' | ')}`, skip: true };
  }

  const orgMembers = new Map<string, string[]>();
  const membersOf = async (orgId: string): Promise<string[]> => {
    if (orgMembers.has(orgId)) return orgMembers.get(orgId)!;
    const { data } = await supabase.from('memberships').select('user_id').eq('organization_id', orgId);
    const ids = (data ?? []).map((m: any) => m.user_id);
    orgMembers.set(orgId, ids);
    return ids;
  };

  let totalSignals = 0;
  let totalNotified = 0;
  let totalEnriched = 0;
  let totalFailed = 0;
  const errors: Array<{ contactId: string; message: string }> = [];
  let tierCounts = { A: 0, B: 0, C: 0 };

  const processContact = async (c: Contact) => {
    const email = (c.email ?? '').toLowerCase().trim();
    const { domain, domainType } = classifyDomain(email);
    const interactionCount = interactionByContact.get(c.id) ?? 0;
    // Déclenchement ciblé depuis une fiche (personne/compte) : on force une vraie recherche,
    // le tiering de coût n'a pas lieu d'être quand un super admin demande explicitement cet enrichissement.
    const tier = forceTierA ? 'A' : (domainType === 'megacorp' ? 'C' : classifyTier(c.companies?.is_tracked === true, Boolean(c.owner_user_id), interactionCount));
    tierCounts[tier]++;

    // Tier C : on ne dépense rien — on avance juste last_monitored_at pour ne
    // pas re-sélectionner ce contact à chaque run.
    if (tier === 'C') {
      await supabase.from('contacts').update({ last_monitored_at: new Date().toISOString() }).eq('id', c.id);
      return;
    }

    const entityKey = email ? `person:${email}` : `person:${(c.full_name ?? '').toLowerCase().trim()}`;
    const { data: cacheRow } = await supabase.from('enrichment_cache').select('data').eq('entity_key', entityKey).maybeSingle();
    const previous = cacheRow?.data ?? c.enrichment_data ?? null;
    const { context: companyContext, skip: skipCompanyResearch } = companyContextFor(c);

    const currentNameIsPlaceholder = looksLikePlaceholderName(c.full_name ?? '', email);
    // Historique de carrière (expériences passées + formation) : recherche PLUS
    // coûteuse qu'un simple "y a-t-il du nouveau", donc jamais répétée à chaque
    // cycle — seulement au tout premier enrichissement réussi (aucune ligne
    // experience/education encore en base) et seulement au palier A (le seul
    // qui a le budget de recherche pour ça). Un historique passé ne change pas :
    // pas besoin de le re-demander toutes les 12-24h comme le poste actuel.
    let fetchFullCareerHistory = false;
    if (tier === 'A') {
      const { count: careerHistoryCount } = await supabase.from('person_career_entries')
        .select('id', { count: 'exact', head: true })
        .eq('organization_id', c.organization_id).eq('contact_id', c.id)
        .in('entry_type', ['experience', 'education']);
      fetchFullCareerHistory = !careerHistoryCount;
    }
    let enr: any = null;
    try {
      enr = await runEnrichmentAgentThrottled(supabase, {
        entityType: 'person', fullName: c.full_name ?? '', email, domain: c.companies?.domain ?? domain,
        company: c.companies?.name ?? '', linkedinUrl: '', knownLinkedinUrl: '',
        tier, domainType, sourceHints: sourceHintsFor(domainType), skipCompanyResearch, companyContext,
        nameLooksLikePlaceholder: currentNameIsPlaceholder,
        fetchFullCareerHistory,
        alreadyKnown: { previousEnrichment: previous, note: 'Détecte surtout les CHANGEMENTS récents (poste, activité) vs le déjà-connu.' },
        usageLog: { client: supabase, organizationId: c.organization_id, userId: c.owner_user_id ?? null, fn: 'monitor-contacts' },
      });
    } catch { /* ignore — enr reste null, traité comme échec ci-dessous */ }

    await supabase.from('contacts').update({ last_monitored_at: new Date().toISOString() }).eq('id', c.id);
    if (!enr) {
      const { error: failedUpdateError } = await supabase.from('contacts').update({
        enrichment_status: 'failed',
        enrichment_error: 'Aucune donnée fiable retournée par le moteur d’enrichissement',
      }).eq('id', c.id);
      totalFailed++;
      if (failedUpdateError) errors.push({ contactId: c.id, message: failedUpdateError.message });
      return;
    }

    // Tout le traitement post-fetch est protégé : une exception inattendue (forme de
    // réponse n8n imprévue, etc.) ne doit jamais laisser le contact bloqué en silence
    // sur 'pending' — elle doit retomber sur 'failed' avec un message exploitable.
    try {
      const candidates: Array<{ signal_type: string; text: string; important: boolean; url?: string | null; date?: string | null }> = [];
      const prevRole = previous?.currentRole, prevCo = previous?.currentCompany;
      if (enr.currentRole && enr.roleConfidence === 'confirmed' && prevRole &&
          (enr.currentRole !== prevRole || (enr.currentCompany && enr.currentCompany !== prevCo))) {
        candidates.push({
          signal_type: 'mobility', important: true,
          text: `Changement de poste : ${prevRole}${prevCo ? ' @ ' + prevCo : ''} → ${enr.currentRole}${enr.currentCompany ? ' @ ' + enr.currentCompany : ''}`,
        });
      }
      const prevTitles = new Set((previous?.recentActivity ?? []).map((a: any) => (a.title || '').toLowerCase()));
      for (const a of (enr.recentActivity ?? []).slice(0, 5)) {
        if (a?.title && !prevTitles.has(String(a.title).toLowerCase())) {
          candidates.push({ signal_type: 'recent_activity', important: false, text: a.date ? `${a.title} (${a.date})` : a.title, url: a.url ?? null, date: a.date ?? null });
        }
      }

      const enrichedAt = new Date().toISOString();
      // Résolution du vrai nom : jamais d'écrasement silencieux d'un nom déjà
      // plausible. Auto-appliqué seulement si le nom actuel était un pseudo ET que
      // l'agent est très confiant (2 sources / LinkedIn nominatif) — sinon suggestion
      // à valider (voir contact_name_suggestions, revue sur la fiche personne).
      const nameChanged = typeof enr.fullName === 'string' && enr.fullName.trim() !== '' && enr.fullName.trim() !== (c.full_name ?? '').trim()
        && looksLikeRealPersonName(enr.fullName, c.companies?.name ?? '');
      const autoApplyName = nameChanged && currentNameIsPlaceholder && enr.fullNameConfidence === 'confirmed';
      // Le contenu enrichi et son statut sont écrits séparément. Ainsi une ancienne
      // contrainte de statut ne peut plus empêcher la mise à jour de toute la fiche.
      const { error: enrichmentUpdateError } = await supabase.from('contacts').update({
        enrichment_data: enr,
        web_bio: enr.summary ?? null,
        role_title: enr.currentRole ?? c.role_title ?? null,
        linkedin_url: sanitizeLinkedinUrl(enr.linkedinUrl) ?? c.linkedin_url ?? null,
        location: enr.location ?? c.location ?? null,
        last_enriched_at: enrichedAt,
        enrichment_error: null,
        ...(autoApplyName ? { full_name: enr.fullName } : {}),
      }).eq('id', c.id);
      if (enrichmentUpdateError) {
        totalFailed++;
        errors.push({ contactId: c.id, message: enrichmentUpdateError.message });
        return;
      }
      totalEnriched++;

      if (nameChanged && !autoApplyName) {
        const { data: existingSuggestion } = await supabase.from('contact_name_suggestions')
          .select('id, suggested_full_name').eq('contact_id', c.id).eq('status', 'pending').maybeSingle();
        if (existingSuggestion?.suggested_full_name !== enr.fullName) {
          if (existingSuggestion) await supabase.from('contact_name_suggestions').delete().eq('id', existingSuggestion.id);
          await supabase.from('contact_name_suggestions').insert({
            organization_id: c.organization_id, contact_id: c.id, suggested_full_name: enr.fullName,
            source: 'enrichment_agent',
            evidence: enr.linkedinUrl ? `Trouvé via recherche web (${enr.linkedinUrl})` : 'Trouvé via recherche web.',
          });
        }
      }
      // La contrainte CHECK contacts_enrichment_status_check n'autorise que pending|running|done|failed.
      const { error: statusUpdateError } = await supabase.from('contacts')
        .update({ enrichment_status: 'done' }).eq('id', c.id);
      if (statusUpdateError) errors.push({ contactId: c.id, message: statusUpdateError.message });
      await supabase.from('enrichment_cache').upsert({
        entity_key: entityKey, entity_type: 'person', data: enr, sources: enr.sources ?? null, refreshed_at: new Date().toISOString(),
      }, { onConflict: 'entity_key' });

      // Alimente le CV vivant sans écraser l'historique : un changement détecté
      // clôt l'expérience précédente et crée une nouvelle étape à confirmer.
      if (enr.currentRole && enr.currentCompany) {
        const { data: currentCareer } = await supabase.from('person_career_entries')
          .select('id,title,organization_name').eq('organization_id', c.organization_id)
          .eq('contact_id', c.id).eq('is_current', true)
          .order('created_at', { ascending: false }).limit(1).maybeSingle();
        const roleChanged = !currentCareer
          || String(currentCareer.title).toLowerCase() !== String(enr.currentRole).toLowerCase()
          || String(currentCareer.organization_name).toLowerCase() !== String(enr.currentCompany).toLowerCase();
        if (currentCareer && roleChanged) {
          await supabase.from('person_career_entries').update({
            is_current: false,
            ended_at: new Date().toISOString().slice(0, 10),
            updated_at: enrichedAt,
          }).eq('id', currentCareer.id);
        }
        if (roleChanged) {
          await supabase.from('person_career_entries').insert({
            organization_id: c.organization_id,
            contact_id: c.id,
            company_id: c.companies?.id ?? null,
            entry_type: currentCareer ? 'detected_change' : 'experience',
            title: String(enr.currentRole).slice(0, 200),
            organization_name: String(enr.currentCompany).slice(0, 200),
            location: enr.location ?? null,
            started_at: enr.roleStartedAt ?? new Date().toISOString().slice(0, 10),
            is_current: true,
            verification_status: enr.roleConfidence === 'confirmed' ? 'probable' : 'to_confirm',
            source_type: 'ai_monitoring',
            source_label: 'Veille Tohu',
            source_url: enr.linkedinUrl ?? null,
            observed_at: enrichedAt,
            last_verified_at: enrichedAt,
            confidence: enr.roleConfidence === 'confirmed' ? 90 : 65,
            inference_level: 'observable',
          });
        } else if (currentCareer) {
          await supabase.from('person_career_entries').update({
            last_verified_at: enrichedAt,
            updated_at: enrichedAt,
          }).eq('id', currentCareer.id);
        }
      }

      // Historique complet (une seule fois — voir fetchFullCareerHistory ci-dessus) :
      // expériences passées et formation, jamais le poste actuel (déjà géré au-dessus).
      if (fetchFullCareerHistory) {
        const historyBase = {
          organization_id: c.organization_id, contact_id: c.id, is_current: false,
          verification_status: 'to_confirm', source_type: 'ai_monitoring', source_label: 'Veille Tohu',
          source_url: enr.linkedinUrl ?? null, observed_at: enrichedAt, last_verified_at: enrichedAt,
          confidence: 60, inference_level: 'observable',
        };
        const pastExperience = Array.isArray(enr.pastExperience) ? enr.pastExperience : [];
        if (pastExperience.length) {
          await supabase.from('person_career_entries').insert(pastExperience.slice(0, 15).map((job: any) => ({
            ...historyBase,
            entry_type: 'experience',
            title: String(job.title ?? '').slice(0, 200),
            organization_name: String(job.company ?? '').slice(0, 200),
            started_at: job.startDate ?? null,
            ended_at: job.endDate ?? null,
          })).filter((row: any) => row.title && row.organization_name));
        }
        const education = Array.isArray(enr.education) ? enr.education : [];
        if (education.length) {
          await supabase.from('person_career_entries').insert(education.slice(0, 10).map((entry: any) => ({
            ...historyBase,
            entry_type: 'education',
            title: String(entry.degree ?? '').slice(0, 200),
            organization_name: String(entry.school ?? '').slice(0, 200),
            started_at: entry.startDate ?? null,
            ended_at: entry.endDate ?? null,
          })).filter((row: any) => row.title && row.organization_name));
        }
      }

      if (!candidates.length) return;

      const { data: existing } = await supabase.from('behavioral_signals')
        .select('text').eq('contact_id', c.id).eq('source_type', 'ai_monitoring');
      const seen = new Set((existing ?? []).map((s: any) => (s.text || '').toLowerCase()));
      const fresh = candidates.filter(s => !seen.has(s.text.toLowerCase()));
      if (!fresh.length) return;

      await supabase.from('behavioral_signals').insert(fresh.map(s => ({
        organization_id: c.organization_id, contact_id: c.id,
        signal_type: s.signal_type, text: s.text, inference_level: 'observable',
        confidence: s.important ? 80 : 65, source_type: 'ai_monitoring', source_ref: s.url ?? null,
        observed_at: new Date().toISOString(),
      })));
      totalSignals += fresh.length;

      const important = fresh.filter(s => s.important);
      if (important.length) {
        const members = await membersOf(c.organization_id);
        const notifs = members.flatMap(uid => important.map(s => ({
          organization_id: c.organization_id, user_id: uid, type: 'contact_signal', priority: 'high',
          title: `${c.full_name ?? 'Contact'} — ${s.text}`.slice(0, 200), body: null,
          entity_type: 'contact', entity_id: c.id, link: `/contacts/${c.id}`,
        })));
        if (notifs.length) { await supabase.from('notifications').insert(notifs); totalNotified += notifs.length; }
      }
    } catch (err) {
      totalFailed++;
      const message = err instanceof Error ? err.message : String(err);
      errors.push({ contactId: c.id, message });
      await supabase.from('contacts').update({ enrichment_status: 'failed', enrichment_error: message.slice(0, 500) }).eq('id', c.id);
    }
  };

  await runWithConcurrency(contacts as Contact[], LOCAL_CONCURRENCY, processContact);

  // Détection de doublons inter-comptes (même personne, emails différents) : un
  // balayage par org coûte ~1s pour un millier de contacts (comparaison de noms
  // par trigramme indexée + égalité LinkedIn) — trop pour le déclencher à chaque
  // clic "Enrichir maintenant", donc réservé au passage cron planifié.
  if (mode === 'cron') {
    const touchedOrgIds = [...new Set((contacts as Contact[]).map((c) => c.organization_id))];
    for (const orgId of touchedOrgIds) {
      await supabase.rpc('detect_contact_merge_candidates', { p_organization_id: orgId }).catch(() => null);
    }
  }

  return jsonResponse({
    success: errors.length === 0,
    scanned: contacts.length,
    enriched: totalEnriched,
    failed: totalFailed,
    signals: totalSignals,
    notified: totalNotified,
    tiers: tierCounts,
    errors: errors.slice(0, 10),
    mode,
  });
});

// Agent de recherche B2B (personne/société) — remplace le workflow n8n
// "Tohu-Bohu — Enrichissement IA (OpenRouter + Perplexity)".
//
// Le node "AI Agent" de n8n n'était qu'une boucle ReAct standard (le LLM décide
// d'appeler l'outil de recherche, reçoit le résultat, décide de continuer ou de
// conclure) tournant sur une instance à mémoire partagée et fragile : un pic sur
// UNE exécution pouvait faire crasher toutes les autres en vol. Cette version
// reproduit fidèlement le même prompt système et le même budget de recherche,
// mais en appels directs (chaque invocation d'Edge Function est isolée — plus de
// mémoire partagée à faire tomber) et avec une sortie structurée forcée via
// tool-calling natif (plus fiable qu'un output parser qui "répare" du JSON après
// coup). La vraie protection de charge est le sémaphore global
// (acquire_enrichment_slot / release_enrichment_slot, cf. migration
// 20260724120000_enrichment_slots.sql) — appelé par le code qui invoque cet agent.

import type { SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { logAiUsage } from './ai-usage.ts';

const OPENROUTER_API = 'https://openrouter.ai/api/v1/chat/completions';
const OPENROUTER_MODEL = 'anthropic/claude-haiku-4.5';
const PERPLEXITY_API = 'https://api.perplexity.ai/chat/completions';
const PERPLEXITY_MODEL = 'sonar';
const MAX_ITERATIONS = 6;
const CALL_TIMEOUT_MS = 30000;
const SLOT_ACQUIRE_TIMEOUT_MS = 60000;
const SLOT_POLL_INTERVAL_MS = 1200;

export type EnrichmentInput = {
  entityType: string;
  fullName: string;
  email: string;
  company: string;
  domain: string;
  linkedinUrl: string;
  knownLinkedinUrl: string;
  tier: string;
  domainType: string;
  sourceHints: string | null;
  companyContext: string | null;
  skipCompanyResearch: boolean;
  alreadyKnown: unknown;
  /** Le nom actuel est un pseudo/local-part d'email (ex. "Fxravet81"), pas un vrai
   *  nom — priorité absolue à la recherche du vrai prénom/nom avant tout le reste. */
  nameLooksLikePlaceholder: boolean;
  /** Récupère aussi l'historique complet (expériences passées + formation), pas
   *  seulement le poste actuel — coûte une recherche supplémentaire, donc réservé
   *  au premier enrichissement d'une personne (voir monitor-contacts : ne se
   *  déclenche que si `person_career_entries` n'a encore aucune ligne
   *  experience/education pour ce contact — jamais répété à chaque cycle, un
   *  historique de carrière passé ne change pas). */
  fetchFullCareerHistory?: boolean;
  /** Contexte de journalisation de l'usage IA (facultatif). */
  usageLog?: AgentUsageLog;
};

export type AgentUsageLog = { client: Parameters<typeof logAiUsage>[0]; organizationId?: string | null; userId?: string | null; fn: string };

export type EnrichmentProfile = {
  entityType?: string;
  fullName?: string;
  fullNameConfidence?: 'confirmed' | 'to_confirm';
  currentRole?: string | null;
  currentCompany?: string | null;
  roleConfidence?: 'confirmed' | 'to_confirm';
  roleStartedAt?: string | null;
  seniority?: string | null;
  linkedinUrl?: string | null;
  location?: string | null;
  summary?: string | null;
  recentActivity?: Array<{ title: string; date?: string | null; source?: string | null; url?: string | null }>;
  company?: {
    name?: string | null; domain?: string | null; industry?: string | null; size?: string | null; hq?: string | null;
    description?: string | null;
    recentNews?: Array<{ title: string; date?: string | null; source?: string | null; url?: string | null }>;
  } | null;
  relatedPeople?: Array<{ name: string; role?: string | null; why?: string | null }>;
  talkingPoints?: string[];
  /** Rempli uniquement si `fetchFullCareerHistory` était demandé. Postes précédents,
   *  du plus récent au plus ancien — jamais le poste actuel (déjà dans currentRole). */
  pastExperience?: Array<{ title: string; company: string; startDate?: string | null; endDate?: string | null }>;
  /** Rempli uniquement si `fetchFullCareerHistory` était demandé. */
  education?: Array<{ degree: string; school: string; startDate?: string | null; endDate?: string | null }>;
  sources?: string[];
  confidence?: number;
};

const SYSTEM_PROMPT = `Tu es un analyste de recherche B2B senior pour un CRM relationnel (Tohu-Bohu). Objectif : un profil enrichi PRÉCIS, PROFOND et ACTIONNABLE sur une personne ou une société, à partir de recherches web réelles — au budget de recherche le plus serré possible.

LANGUE DE SORTIE (IMPÉRATIF) : RÉDIGE TOUS les champs textuels EN FRANÇAIS — summary, description, talkingPoints, recentActivity[].title, company.description, company.recentNews[].title, relatedPeople[].role et relatedPeople[].why, etc. MÊME si les sources web sont en anglais, TRADUIS et reformule en français naturel et professionnel. Ne laisse JAMAIS une phrase en anglais. Conserve uniquement en l'état : noms propres, raisons sociales, intitulés de poste usuels (ex. « CEO »), URLs et noms de sources.

BUDGET DE RECHERCHE (IMPÉRATIF — chaque appel à l'outil "web_search" a un coût réel) :
- Palier A (recherche complète) : 2 à 3 appels MAXIMUM. 1 sur la personne/LinkedIn, 1 optionnel sur son actualité récente, 1 optionnel sur l'entreprise UNIQUEMENT si aucun "CONTEXTE ENTREPRISE DÉJÀ CONNU" n'est fourni ci-dessus.
- Palier B (vérification légère) : 1 SEUL appel maximum, ciblé sur "y a-t-il un changement de poste ou une actualité récente" — pas de recherche exhaustive.
- Si un CONTEXTE ENTREPRISE DÉJÀ CONNU est fourni, N'INTERROGE PAS l'outil sur l'entreprise elle-même — réutilise ce contexte tel quel dans le champ "company".
- Si "HISTORIQUE DE CARRIÈRE COMPLET DEMANDÉ" est signalé ci-dessous, ton 1er appel "web_search" doit explicitement demander le profil LinkedIn COMPLET (expériences passées + formation), pas seulement le poste actuel — cela reste DANS le même budget de 2-3 appels, pas un appel de plus.
- N'effectue JAMAIS plus d'appels que ce budget. Si l'information n'est pas trouvée dans ce budget, renseigne "to_confirm" ou null plutôt que de continuer à chercher.

RÉSOLUTION DU VRAI NOM (impératif quand le message signale "NOM ACTUEL PROBABLEMENT UN PSEUDO") : un nom dérivé d'un email (ex. "Fxravet81", "jdupont42") n'est PAS un vrai nom. Dans ce cas, ta priorité n°1 pour le premier appel "web_search" est de trouver le vrai prénom et nom de famille (LinkedIn en priorité, puis web). Renseigne le résultat dans "fullName" avec "fullNameConfidence" :
- "confirmed" seulement si LinkedIn nominatif clair ou DEUX sources concordent sur le même prénom/nom.
- "to_confirm" si une seule source, plausible mais non recoupée.
- Si rien trouvé, renvoie "fullName" EXACTEMENT identique à la valeur donnée dans "Nom :" ci-dessous (recopie-la telle quelle, ne la restructure PAS) et "fullNameConfidence" à "to_confirm" — n'invente jamais un nom, et ne prends JAMAIS le nom de la société ou du domaine pour un nom de famille.
FORMAT DU CHAMP "fullName" (uniquement quand un vrai prénom ET nom de famille de la PERSONNE ont été trouvés) : prénom en casse titre, NOM DE FAMILLE EN MAJUSCULES, dans cet ordre — ex. "François-Xavier RAVET", "Julie MARTIN".

ROUTAGE DES SOURCES : suis STRICTEMENT les "SOURCES PRIORITAIRES POUR CE DOMAINE" transmises dans le message plutôt que d'improviser — ce routage est déjà déterminé (registre légal pour une entreprise française, Crunchbase pour une startup, etc.).

ANTI-HOMONYMES (important) : le domaine email de la personne PROUVE son appartenance à l'organisation citée. Ignore tout résultat concernant un homonyme sans lien avéré avec cette organisation.

ANTI-RÉPÉTITION (important) : les blocs "DÉJÀ CONNU" listent ce que l'utilisateur a déjà. NE les répète PAS tel quel. Apporte du NOUVEAU, du plus récent, ou comble les manques. Si rien de neuf, ne réinvente rien.

DOCTRINE ZÉRO-HALLUCINATION (impératif) :
- N'invente JAMAIS une donnée (poste, tél, taille, email). Non vérifiable → null, roleConfidence="to_confirm".
- Poste actuel affirmé (roleConfidence="confirmed") seulement si DEUX sources concordent, ou si le contexte entreprise déjà connu le confirme. Sinon "to_confirm".
- Cite les URLs réelles dans "sources". Préfère sources primaires : LinkedIn, site officiel, presse éco, registres.

SORTIE : appelle l'outil "emit_profile" une seule fois, avec TOUS LES TEXTES EN FRANÇAIS. talkingPoints = 2-4 angles concrets et personnalisés (en français) pour engager la relation maintenant. recentActivity = faits datés avec source (titres en français). relatedPeople = personnes pertinentes de l'entreprise, uniquement si palier A et pertinent, avec un 'why' actionnable en français.
Si "HISTORIQUE DE CARRIÈRE COMPLET DEMANDÉ" est signalé : remplis aussi "pastExperience" (postes précédents, du plus récent au plus ancien, JAMAIS le poste actuel déjà dans currentRole) et "education" (diplômes). Même doctrine zéro-hallucination : un poste ou diplôme non trouvé ne doit PAS être inventé — tableau vide plutôt qu'une entrée incertaine.`;

function buildUserPrompt(input: EnrichmentInput): string {
  return `Type d'entité : ${input.entityType}
Nom : ${input.fullName}
Email : ${input.email}
Société : ${input.company}
Domaine : ${input.domain}
LinkedIn connu : ${input.knownLinkedinUrl || input.linkedinUrl}
Palier de recherche : ${input.tier} (${input.tier === 'A' ? 'recherche complète' : 'vérification légère'})
Type de domaine : ${input.domainType}
${input.nameLooksLikePlaceholder ? '\n⚠️ NOM ACTUEL PROBABLEMENT UN PSEUDO (dérivé de l\'email, pas un vrai nom) — voir RÉSOLUTION DU VRAI NOM ci-dessus, priorité n°1.\n' : ''}${input.fetchFullCareerHistory ? '\n⚠️ HISTORIQUE DE CARRIÈRE COMPLET DEMANDÉ — remplis aussi pastExperience et education (voir consignes ci-dessus). Premier enrichissement de cette personne : l\'historique n\'a jamais été recherché.\n' : ''}
=== SOURCES PRIORITAIRES POUR CE DOMAINE ===
${input.sourceHints || 'Aucune source spécifique — recherche générale.'}

=== CONTEXTE ENTREPRISE DÉJÀ CONNU (ne PAS re-rechercher l'entreprise si ce contexte est présent) ===
${input.companyContext || 'Aucun contexte entreprise fourni.'}

=== DÉJÀ CONNU SUR LA PERSONNE (ne PAS répéter — base de référence) ===
${JSON.stringify(input.alreadyKnown)}

Mène une recherche web ciblée, dans le budget d'appels imposé par ton palier, et renvoie le profil structuré. Concentre-toi en priorité sur les informations NOUVELLES, récentes ou manquantes par rapport au déjà-connu.`;
}

