    type: 'function',
    function: {
      name: 'emit_profile',
      description: "Renvoie le profil enrichi final structuré. À appeler une seule fois, quand la recherche (dans le budget imparti) est terminée.",
      parameters: EMIT_PROFILE_PARAMETERS,
    },
  },
];

type ChatMessage = Record<string, unknown>;

async function callOpenRouter(apiKey: string, messages: ChatMessage[], forceEmit: boolean, usageLog?: AgentUsageLog) {
  const res = await fetch(OPENROUTER_API, {
    method: 'POST',
    headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: OPENROUTER_MODEL,
      temperature: 0.2,
      messages,
      tools: TOOLS,
      tool_choice: forceEmit ? { type: 'function', function: { name: 'emit_profile' } } : 'auto',
    }),
    signal: AbortSignal.timeout(CALL_TIMEOUT_MS),
  });
  if (!res.ok) throw new Error(`OpenRouter ${res.status} : ${(await res.text()).slice(0, 300)}`);
  const data = await res.json();
  if (usageLog) await logAiUsage(usageLog.client, { organizationId: usageLog.organizationId, userId: usageLog.userId, fn: usageLog.fn, model: OPENROUTER_MODEL, usage: data?.usage });
  return data;
}

async function webSearch(apiKey: string, query: string): Promise<string> {
  try {
    const res = await fetch(PERPLEXITY_API, {
      method: 'POST',
      headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: PERPLEXITY_MODEL,
        messages: [
          { role: 'system', content: 'Recherche web factuelle. Réponds de façon concise (5-10 lignes), cite les faits datés et les sources. Aucune invention.' },
          { role: 'user', content: query },
        ],
        max_tokens: 700,
        temperature: 0.1,
        search_recency_filter: 'year',
      }),
      signal: AbortSignal.timeout(CALL_TIMEOUT_MS),
    });
    if (!res.ok) return `Recherche indisponible (${res.status}).`;
    const data = await res.json();
    const content: string = data.choices?.[0]?.message?.content ?? '';
    const citations: string[] = Array.isArray(data.citations) ? data.citations : [];
    return citations.length ? `${content}\n\nSources : ${citations.join(', ')}` : content;
  } catch (err) {
    return `Recherche impossible : ${err instanceof Error ? err.message : String(err)}`;
  }
}

/** Convention imposée pour tout nom de personne dans l'app : prénom en casse
 *  titre, NOM DE FAMILLE EN MAJUSCULES (ex. "François-Xavier RAVET") — même
 *  règle que public.format_person_full_name (trigger contacts.full_name) et
 *  src/lib/names.ts côté frontend. Le premier "mot" est traité comme le
 *  prénom, le reste comme le nom de famille. */
export function formatPersonName(raw: string): string {
  const trimmed = raw.trim().replace(/\s+/g, ' ');
  if (!trimmed) return trimmed;
  const titleCase = (word: string) => word.split('-').map((part) => part ? part.charAt(0).toUpperCase() + part.slice(1).toLowerCase() : part).join('-');
  const parts = trimmed.split(' ');
  if (parts.length === 1) return titleCase(parts[0]);
  const [firstName, ...rest] = parts;
  return `${titleCase(firstName)} ${rest.join(' ').toUpperCase()}`;
}

function safeParseArgs(raw: string): Record<string, unknown> | null {
  try {
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch {
    return null;
  }
}

/** Boucle ReAct bornée (même contrat que le node "AI Agent" n8n qu'elle remplace) :
 *  le modèle décide d'appeler web_search (budget imposé par le prompt système) puis
 *  conclut via emit_profile (sortie forcée par tool-calling natif, pas de réparation
 *  de JSON a posteriori). Renvoie null si aucun profil fiable n'a pu être produit dans
 *  le budget d'itérations — le code appelant doit alors marquer l'enrichissement en échec. */
export async function runEnrichmentAgent(input: EnrichmentInput): Promise<EnrichmentProfile | null> {
  const openrouterKey = Deno.env.get('OPENROUTER_API_KEY');
  const perplexityKey = Deno.env.get('PERPLEXITY_API_KEY');
  if (!openrouterKey || !perplexityKey) throw new Error('OPENROUTER_API_KEY ou PERPLEXITY_API_KEY manquant côté serveur.');

  const messages: ChatMessage[] = [
    { role: 'system', content: SYSTEM_PROMPT },
    { role: 'user', content: buildUserPrompt(input) },
  ];

  for (let iteration = 1; iteration <= MAX_ITERATIONS; iteration++) {
    const forceEmit = iteration === MAX_ITERATIONS;
    const data = await callOpenRouter(openrouterKey, messages, forceEmit, input.usageLog);
    const msg = data.choices?.[0]?.message;
    if (!msg) throw new Error('Réponse OpenRouter vide.');
    messages.push(msg);

    const toolCalls = msg.tool_calls as Array<{ id: string; function: { name: string; arguments: string } }> | undefined;
    if (!toolCalls?.length) {
      messages.push({ role: 'user', content: 'Réponds uniquement via l’outil emit_profile.' });
      continue;
    }

    let emitted: EnrichmentProfile | null = null;
    for (const call of toolCalls) {
      if (call.function.name === 'emit_profile') {
        const parsed = safeParseArgs(call.function.arguments);
        if (parsed) {
          emitted = parsed as EnrichmentProfile;
          if (typeof emitted.fullName === 'string' && emitted.fullName) emitted.fullName = formatPersonName(emitted.fullName);
          messages.push({ role: 'tool', tool_call_id: call.id, content: 'OK' });
        } else {
          messages.push({ role: 'tool', tool_call_id: call.id, content: 'JSON invalide, réessaie avec un JSON strictement valide.' });
        }
      } else if (call.function.name === 'web_search') {
        const args = safeParseArgs(call.function.arguments);
        const result = await webSearch(perplexityKey, String(args?.query ?? ''));
        messages.push({ role: 'tool', tool_call_id: call.id, content: result });
      } else {
        messages.push({ role: 'tool', tool_call_id: call.id, content: 'Outil inconnu.' });
      }
    }
    if (emitted) return emitted;
  }
  return null;
}

async function acquireSlot(supabase: SupabaseClient): Promise<number> {
  const start = Date.now();
  while (Date.now() - start < SLOT_ACQUIRE_TIMEOUT_MS) {
    const { data, error } = await supabase.rpc('acquire_enrichment_slot');
    if (error) throw new Error(`Sémaphore d'enrichissement indisponible : ${error.message}`);
    if (typeof data === 'number') return data;
    await new Promise((resolve) => setTimeout(resolve, SLOT_POLL_INTERVAL_MS + Math.random() * 400));
  }
  throw new Error('Charge d’enrichissement trop élevée, réessaie plus tard.');
}

async function releaseSlot(supabase: SupabaseClient, slotId: number): Promise<void> {
  await supabase.rpc('release_enrichment_slot', { p_id: slotId });
}

/** Point d'entrée à utiliser par tout appelant : garantit qu'aucun appel IA ne part
 *  sans être compté dans le sémaphore global. C'est l'absence de cette garantie côté
 *  n8n (cap de concurrence local à chaque invocation, jamais partagé entre elles) qui
 *  a permis à plusieurs invocations simultanées de dépasser le cap et de crasher
 *  l'instance le 2026-07-22. */
export async function runEnrichmentAgentThrottled(supabase: SupabaseClient, input: EnrichmentInput): Promise<EnrichmentProfile | null> {
  const slotId = await acquireSlot(supabase);
  try {
    return await runEnrichmentAgent(input);
  } finally {
    await releaseSlot(supabase, slotId);
  }
}

// Journalisation de l'usage IA (OpenRouter) → table `ai_usage_events`.
// OpenRouter renvoie `usage` (tokens réels) dans chaque réponse : on stocke ces
// tokens + un coût ESTIMÉ via la grille ci-dessous. La grille est approximative
// (la source de vérité des dépenses reste le tableau de bord OpenRouter) et se
// met à jour ici sans toucher au reste du code.

// Prix approximatifs en USD par 1 000 000 de tokens (entrée / sortie).
// À ajuster selon la facturation OpenRouter réelle.
const PRICING: Record<string, { in: number; out: number }> = {
  'google/gemini-3.1-flash-lite': { in: 0.10, out: 0.40 },
  'anthropic/claude-haiku-4.5': { in: 1.00, out: 5.00 },
  'openai/gpt-4.1-mini': { in: 0.40, out: 1.60 },
}
const DEFAULT_PRICE = { in: 0.50, out: 1.50 }

export type TokenUsage = { prompt_tokens?: number; completion_tokens?: number; total_tokens?: number } | null | undefined

export function estimateCostUsd(model: string, promptTokens: number, completionTokens: number): number {
  const price = PRICING[model] ?? DEFAULT_PRICE
  return (promptTokens / 1_000_000) * price.in + (completionTokens / 1_000_000) * price.out
}

type AnySupabase = { from: (table: string) => { insert: (rows: unknown) => Promise<{ error: unknown }> } }

/** Best-effort : ne jette jamais (une erreur de log ne doit pas casser l'analyse). */
export async function logAiUsage(client: AnySupabase, params: {
  organizationId?: string | null
  userId?: string | null
  fn: string
  model: string
  usage: TokenUsage
}): Promise<void> {
  try {
    const prompt = Math.max(0, Math.round(Number(params.usage?.prompt_tokens ?? 0)))
    const completion = Math.max(0, Math.round(Number(params.usage?.completion_tokens ?? 0)))
    const total = Math.max(0, Math.round(Number(params.usage?.total_tokens ?? prompt + completion)))
    await client.from('ai_usage_events').insert({
      organization_id: params.organizationId ?? null,
      user_id: params.userId ?? null,
      fn: params.fn,
      model: params.model,
      prompt_tokens: prompt,
      completion_tokens: completion,
      total_tokens: total,
      estimated_cost_usd: Number(estimateCostUsd(params.model, prompt, completion).toFixed(6)),
    })
  } catch {
    // silencieux : la journalisation ne doit jamais interrompre le flux principal.
  }
}

// OAuth HubSpot — connexion CRM (spec Connecteurs, maquette Tohu).
// POST (authentifié, JWT) : action=start → renvoie l'URL d'autorisation HubSpot.
// GET  (public, appelé par HubSpot en retour d'auth) : ?code=&state= → échange le code, stocke le token, redirige vers l'app.
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
};
function jsonResponse(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
}

const APP_URL = 'https://tohu.co';
const HUBSPOT_AUTH_URL = 'https://app.hubspot.com/oauth/authorize';
const HUBSPOT_TOKEN_URL = 'https://api.hubapi.com/oauth/v1/token';
const SCOPES = 'crm.objects.contacts.read crm.objects.companies.read';

function functionUrl(): string {
  const supabaseUrl = Deno.env.get('SUPABASE_URL') ?? '';
  return `${supabaseUrl}/functions/v1/connect-hubspot`;
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders });
  const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '');
  const clientId = Deno.env.get('HUBSPOT_CLIENT_ID');
  const clientSecret = Deno.env.get('HUBSPOT_CLIENT_SECRET');

  // ── GET = callback HubSpot (?code=&state=) ──────────────────────────
  if (req.method === 'GET') {
    const url = new URL(req.url);
    const code = url.searchParams.get('code');
    const state = url.searchParams.get('state');
    const oauthError = url.searchParams.get('error');

    if (oauthError) {
      return Response.redirect(`${APP_URL}/app/connectors?error=hubspot_${encodeURIComponent(oauthError)}`, 302);
    }
    if (!code || !state) return jsonResponse({ error: 'code et state requis' }, 400);
    if (!clientId || !clientSecret) return jsonResponse({ error: 'HUBSPOT_CLIENT_ID/HUBSPOT_CLIENT_SECRET non configurés' }, 500);

    let orgId: string, userId: string;
    try {
      const decoded = JSON.parse(atob(state));
      orgId = decoded.orgId; userId = decoded.userId;
      if (!orgId || !userId) throw new Error('state invalide');
    } catch {
      return Response.redirect(`${APP_URL}/app/connectors?error=hubspot_invalid_state`, 302);
    }

    try {
      const tokenRes = await fetch(HUBSPOT_TOKEN_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
          grant_type: 'authorization_code',
          client_id: clientId,
          client_secret: clientSecret,
          redirect_uri: functionUrl(),
          code,
        }),
      });
      const tokenData = await tokenRes.json();
      if (!tokenRes.ok) {
        console.error('HubSpot token exchange failed:', JSON.stringify(tokenData));
        return Response.redirect(`${APP_URL}/app/connectors?error=hubspot_token_exchange`, 302);
      }

      // Ligne de base « not_connected » : le statut ne passe à « connected » qu'après
      // le stockage effectif du jeton chiffré (même garde-fou que connect-email-provider).
      const { data: connector, error: connectorError } = await supabase.from('connectors').upsert({
        organization_id: orgId,
        user_id: userId,
        provider: 'hubspot',
        status: 'not_connected',
        scopes: SCOPES.split(' '),
        metadata: { connected_at: new Date().toISOString() },
        last_synced_at: null,
        updated_at: new Date().toISOString(),
      }, { onConflict: 'user_id,provider' }).select('id').single();
      if (connectorError || !connector) {
        console.error('HubSpot connector upsert failed:', connectorError?.message);
        return Response.redirect(`${APP_URL}/app/connectors?error=hubspot_internal`, 302);
      }

      // Identifie le portail HubSpot connecté (hub_id/hub_domain) pour l'afficher dans l'UI.
      let hubId: string | null = null;
      let hubDomain: string | null = null;
      try {
        const infoRes = await fetch(`https://api.hubapi.com/oauth/v1/access-tokens/${tokenData.access_token}`);
        if (infoRes.ok) {
          const info = await infoRes.json();
          hubId = info.hub_id != null ? String(info.hub_id) : null;
          hubDomain = info.hub_domain ?? null;
        }
      } catch (infoError) {
        console.error('HubSpot token-info lookup failed:', infoError instanceof Error ? infoError.message : infoError);
      }

      const { error: oauthError } = await supabase.rpc('store_oauth_tokens_server', {
        p_organization_id: orgId,
        p_connector_id: connector.id,
        p_provider_account_id: hubId ?? 'hubspot',
        p_access_token: tokenData.access_token,
        p_refresh_token: tokenData.refresh_token ?? null,
        p_expires_at: new Date(Date.now() + Math.max(60, Number(tokenData.expires_in ?? 1800)) * 1000).toISOString(),
      });
      if (oauthError) {
        console.error('HubSpot token storage failed:', oauthError.message);
        await supabase.from('connectors').update({ status: 'error', metadata: { last_error: oauthError.message.slice(0, 500) } }).eq('id', connector.id);
        return Response.redirect(`${APP_URL}/app/connectors?error=hubspot_token_storage`, 302);
      }

      await supabase.from('connectors').update({
        status: 'connected',
        metadata: { hub_id: hubId, hub_domain: hubDomain, connected_at: new Date().toISOString() },
        updated_at: new Date().toISOString(),
      }).eq('id', connector.id);

      return Response.redirect(`${APP_URL}/app/connectors?connected=hubspot`, 302);
    } catch (e: any) {
      console.error('HubSpot callback error:', e?.message);
      return Response.redirect(`${APP_URL}/app/connectors?error=hubspot_internal`, 302);
    }
  }

  // ── POST = start (authentifié) → renvoie l'URL d'autorisation ────────────────
  if (req.method === 'POST') {
    const auth = req.headers.get('Authorization');
    if (!auth) return jsonResponse({ error: 'Missing authorization' }, 401);
    if (!clientId) return jsonResponse({ error: 'HUBSPOT_CLIENT_ID non configuré côté serveur — voir CONNECTEURS.md' }, 500);

    const { data: { user }, error: userErr } = await supabase.auth.getUser(auth.replace('Bearer ', ''));
    if (userErr || !user) return jsonResponse({ error: 'Unauthorized' }, 401);

    const { organizationId } = await req.json().catch(() => ({}));
    if (!organizationId) return jsonResponse({ error: 'organizationId requis' }, 400);

    const state = btoa(JSON.stringify({ orgId: organizationId, userId: user.id, ts: Date.now() }));
    const authorizeUrl = `${HUBSPOT_AUTH_URL}?client_id=${encodeURIComponent(clientId)}&redirect_uri=${encodeURIComponent(functionUrl())}&scope=${encodeURIComponent(SCOPES)}&state=${encodeURIComponent(state)}`;

    return jsonResponse({ url: authorizeUrl });
  }

  return jsonResponse({ error: 'Method not allowed' }, 405);
});

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
}

async function providerAccount(provider: string, accessToken: string): Promise<{ id: string; email: string | null }> {
  const url = provider === 'google'
    ? 'https://openidconnect.googleapis.com/v1/userinfo'
    : 'https://graph.microsoft.com/v1.0/me?$select=id,mail,userPrincipalName'
  const response = await fetch(url, { headers: { Authorization: `Bearer ${accessToken}` } })
  if (!response.ok) {
    // Le corps de la réponse (ex. InvalidAuthenticationToken de Graph) est la seule
    // information qui permette de diagnostiquer un refus de jeton — on le remonte.
    const body = (await response.text().catch(() => '')).slice(0, 300)
    throw new Error(`Jeton ${provider} refusé (${response.status})${body ? ` — ${body}` : ''}`)
  }
  const data = await response.json()
  return provider === 'google'
    ? { id: String(data.sub), email: data.email ?? null }
    : { id: String(data.id), email: data.mail ?? data.userPrincipalName ?? null }
}

Deno.serve(async (request) => {
  if (request.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
  try {
    const authorization = request.headers.get('Authorization')
    if (!authorization) return json({ error: 'Authentification requise' }, 401)

    const supabase = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
    )
    const jwt = authorization.replace('Bearer ', '')
    const { data: { user }, error: userError } = await supabase.auth.getUser(jwt)
    if (userError || !user) return json({ error: 'Session invalide' }, 401)

    const body = await request.json().catch(() => ({}))
    const { organizationId, provider, accessToken, refreshToken, expiresIn = 3600, action = 'connect', scopes = [] } = body
    if (!organizationId || !['google', 'microsoft'].includes(provider)) return json({ error: 'Organisation ou fournisseur invalide' }, 400)

    const { data: membership } = await supabase.from('memberships').select('id').eq('organization_id', organizationId).eq('user_id', user.id).maybeSingle()
    if (!membership) return json({ error: 'Accès refusé à cette organisation' }, 403)

    // « connected » n'est posé qu'APRÈS le stockage effectif des jetons : sinon la
    // tuile afficherait « Connecté » alors qu'aucune synchronisation n'est possible.
    const { data: connector, error: connectorError } = await supabase.from('connectors').upsert({
      organization_id: organizationId,
      user_id: user.id,
      provider,
      status: action === 'disconnect' ? 'disconnected' : 'not_connected',
      scopes: Array.isArray(scopes) ? scopes : [],
      metadata: action === 'disconnect' ? {} : { connected_at: new Date().toISOString() },
      updated_at: new Date().toISOString(),
    }, { onConflict: 'user_id,provider' }).select('id').single()
    if (connectorError || !connector) throw connectorError ?? new Error('Connecteur introuvable')

    if (action === 'disconnect') {
      await supabase.from('oauth_accounts').delete().eq('connector_id', connector.id)
      return json({ success: true, status: 'disconnected' })
    }
    if (!accessToken) return json({ error: 'Jeton fournisseur manquant. Reconnecte le compte.' }, 400)

    try {
      const account = await providerAccount(provider, accessToken)
      const { error: oauthError } = await supabase.rpc('store_oauth_tokens_server', {
        p_organization_id: organizationId,
        p_connector_id: connector.id,
        p_provider_account_id: account.id,
        p_access_token: accessToken,
        p_refresh_token: refreshToken ?? null,
        p_expires_at: new Date(Date.now() + Math.max(60, Number(expiresIn)) * 1000).toISOString(),
      })
      if (oauthError) throw oauthError

      await supabase.from('connectors').update({
        status: 'connected',
        metadata: { account_email: account.email, provider_account_id: account.id, connected_at: new Date().toISOString() },
      }).eq('id', connector.id)

      return json({ success: true, connectorId: connector.id, provider, accountEmail: account.email })
    } catch (stepError) {
      const message = stepError instanceof Error ? stepError.message : 'Connexion impossible'
      await supabase.from('connectors').update({
        status: 'error',
        metadata: { last_error: message.slice(0, 500) },
        updated_at: new Date().toISOString(),
      }).eq('id', connector.id)
      return json({ error: message }, 500)
    }
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : 'Connexion impossible' }, 500)
  }
})

// Synchronisation CRM HubSpot → Tohu (entreprises + contacts).
// POST (authentifié, JWT) : { organizationId } → tire les objets HubSpot du portail connecté
// et les fait passer par les mêmes fonctions de résolution d'identité que la synchro email,
// pour bénéficier de la même dédoublication (un contact/une entreprise HubSpot fusionne avec
// un contact/une entreprise déjà connu via email plutôt que de créer un doublon).
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
}

function cleanEmail(value: string | null | undefined): string {
  return String(value ?? '').trim().toLowerCase()
}

type HubspotCompany = { id: string; properties: { name?: string; domain?: string; industry?: string } }
type HubspotContact = {
  id: string
  properties: { email?: string; firstname?: string; lastname?: string; jobtitle?: string }
  associations?: { companies?: { results?: Array<{ id: string }> } }
}

async function refreshAccessToken(refreshToken: string): Promise<{ accessToken: string; refreshToken: string; expiresIn: number }> {
  const clientId = Deno.env.get('HUBSPOT_CLIENT_ID')
  const clientSecret = Deno.env.get('HUBSPOT_CLIENT_SECRET')
  if (!clientId || !clientSecret) throw new Error('Secrets OAuth HubSpot manquants')
  const response = await fetch('https://api.hubapi.com/oauth/v1/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ grant_type: 'refresh_token', client_id: clientId, client_secret: clientSecret, refresh_token: refreshToken }),
  })
  if (!response.ok) throw new Error(`Rafraîchissement HubSpot refusé (${response.status})`)
  const data = await response.json()
  return { accessToken: data.access_token, refreshToken: data.refresh_token ?? refreshToken, expiresIn: Number(data.expires_in ?? 1800) }
}

async function hubspotCompanies(token: string): Promise<HubspotCompany[]> {
  const url = 'https://api.hubapi.com/crm/v3/objects/companies?limit=100&properties=name,domain,industry'
  const response = await fetch(url, { headers: { Authorization: `Bearer ${token}` } })
  if (!response.ok) throw new Error(`HubSpot companies ${response.status}`)
  return ((await response.json()).results ?? []) as HubspotCompany[]
}

async function hubspotContacts(token: string): Promise<HubspotContact[]> {
  const url = 'https://api.hubapi.com/crm/v3/objects/contacts?limit=100&properties=email,firstname,lastname,jobtitle&associations=companies'
  const response = await fetch(url, { headers: { Authorization: `Bearer ${token}` } })
  if (!response.ok) throw new Error(`HubSpot contacts ${response.status}`)
  return ((await response.json()).results ?? []) as HubspotContact[]
}

Deno.serve(async (request) => {
  if (request.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
  const startedAt = new Date().toISOString()
  let syncJobId: string | null = null
  const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')
  try {
    const authorization = request.headers.get('Authorization')
    if (!authorization) return json({ error: 'Authentification requise' }, 401)
    const { data: { user }, error: userError } = await supabase.auth.getUser(authorization.replace('Bearer ', ''))
    if (userError || !user) return json({ error: 'Session invalide' }, 401)

    const { organizationId } = await request.json().catch(() => ({}))
    if (!organizationId) return json({ error: 'organizationId requis' }, 400)
    const { data: membership } = await supabase.from('memberships').select('id').eq('organization_id', organizationId).eq('user_id', user.id).maybeSingle()
    if (!membership) return json({ error: 'Accès refusé' }, 403)

    const { data: connector } = await supabase.from('connectors').select('id,metadata').eq('organization_id', organizationId).eq('user_id', user.id).eq('provider', 'hubspot').maybeSingle()
    if (!connector) return json({ error: 'Connecteur HubSpot introuvable' }, 404)
    const { data: tokenRows, error: tokenError } = await supabase.rpc('get_oauth_tokens_server', { p_connector_id: connector.id })
    const oauth = tokenRows?.[0]
    if (tokenError || !oauth) return json({ error: 'Jetons OAuth absents. Reconnecte HubSpot.' }, 401)

    const { data: job } = await supabase.from('sync_jobs').insert({
      organization_id: organizationId,
      connector_id: connector.id,
      user_id: user.id,
      provider: 'hubspot',
      job_type: 'crm_sync',
      status: 'running',
      current_step: 'Connexion à HubSpot',
      progress: 10,
      started_at: startedAt,
      payload: { provider: 'hubspot' },
    }).select('id').single()
    syncJobId = job?.id ?? null

    let accessToken = oauth.access_token as string | null
    let refreshToken = oauth.refresh_token as string | null
    const expiresSoon = !oauth.expires_at || new Date(oauth.expires_at).getTime() < Date.now() + 90_000
    if ((!accessToken || expiresSoon) && refreshToken) {
      const refreshed = await refreshAccessToken(refreshToken)
      accessToken = refreshed.accessToken
      refreshToken = refreshed.refreshToken
      await supabase.rpc('store_oauth_tokens_server', { p_organization_id: organizationId, p_connector_id: connector.id, p_provider_account_id: oauth.provider_account_id, p_access_token: accessToken, p_refresh_token: refreshToken, p_expires_at: new Date(Date.now() + refreshed.expiresIn * 1000).toISOString() })
    }
    if (!accessToken) throw new Error('Jeton HubSpot indisponible')

    if (syncJobId) await supabase.from('sync_jobs').update({ current_step: 'Lecture des entreprises HubSpot', progress: 30 }).eq('id', syncJobId)
    const companies = await hubspotCompanies(accessToken)
    const companyIdByHubspotId = new Map<string, string>()
    let companiesSynced = 0
    for (const company of companies) {
      const name = (company.properties.name ?? '').trim()
      const domain = (company.properties.domain ?? '').trim().toLowerCase() || null
      if (!name && !domain) continue
      const { data: resolved, error } = await supabase.rpc('resolve_company_identity', {
        p_organization_id: organizationId,
        p_name: name || domain || 'Entreprise HubSpot',
        p_domain: domain,
        p_industry: company.properties.industry ?? null,
        p_create_if_missing: true,
      }).maybeSingle()
      if (error || !resolved?.company_id) continue
      companyIdByHubspotId.set(company.id, resolved.company_id)
      companiesSynced++
    }

    if (syncJobId) await supabase.from('sync_jobs').update({ current_step: 'Lecture des contacts HubSpot', progress: 60 }).eq('id', syncJobId)
    const contacts = await hubspotContacts(accessToken)
    let contactsSynced = 0
    for (const contact of contacts) {
      const email = cleanEmail(contact.properties.email)
      if (!email) continue
      const fullName = [contact.properties.firstname, contact.properties.lastname].filter(Boolean).join(' ').trim() || email.split('@')[0]
      const linkedHubspotCompanyId = contact.associations?.companies?.results?.[0]?.id
      const companyId = linkedHubspotCompanyId ? companyIdByHubspotId.get(linkedHubspotCompanyId) ?? null : null
      const { error } = await supabase.rpc('resolve_contact_identity', {
        p_organization_id: organizationId,
        p_email: email,
        p_full_name: fullName,
        p_company_id: companyId,
        p_owner_user_id: user.id,
        p_role_title: contact.properties.jobtitle ?? null,
        p_source: 'hubspot',
      }).maybeSingle()
      if (error) continue
      contactsSynced++
    }

    if (syncJobId) await supabase.from('sync_jobs').update({ current_step: 'Finalisation', progress: 90 }).eq('id', syncJobId)
    await supabase.from('connectors').update({
      status: 'connected',
      last_synced_at: new Date().toISOString(),
      metadata: { ...(connector.metadata ?? {}), last_sync: { companies: companiesSynced, contacts: contactsSynced } },
      updated_at: new Date().toISOString(),
    }).eq('id', connector.id)
    if (syncJobId) await supabase.from('sync_jobs').update({ status: 'succeeded', current_step: 'Synchronisation terminée', progress: 100, completed_at: new Date().toISOString(), payload: { provider: 'hubspot', companies: companiesSynced, contacts: contactsSynced } }).eq('id', syncJobId)

    return json({ success: true, companies: companiesSynced, contacts: contactsSynced })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Synchronisation HubSpot impossible'
    if (syncJobId) await supabase.from('sync_jobs').update({ status: 'failed', current_step: 'Échec de la synchronisation', error_code: 'HUBSPOT_SYNC_FAILED', error_message: message, completed_at: new Date().toISOString() }).eq('id', syncJobId)
    return json({ error: message }, 500)
  }
})

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  })
}

async function stripeRequest(path: string, secret: string, params?: URLSearchParams, method = 'POST') {
  const response = await fetch(`https://api.stripe.com${path}`, {
    method,
    headers: {
      Authorization: `Bearer ${secret}`,
      ...(params ? { 'Content-Type': 'application/x-www-form-urlencoded' } : {}),
    },
    body: params,
  })
  const data = await response.json().catch(() => ({}))
  if (!response.ok) throw new Error(data?.error?.message ?? `Stripe a répondu ${response.status}.`)
  return data
}

function safeOrigin(value: unknown): string {
  try {
    const url = new URL(String(value ?? ''))
    if (!['http:', 'https:'].includes(url.protocol)) throw new Error('invalid')
    return url.origin
  } catch {
    return Deno.env.get('APP_URL') ?? 'https://tohu.co'
  }
}

Deno.serve(async (request) => {
  if (request.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405)

  try {
    const authorization = request.headers.get('Authorization')
    if (!authorization) return json({ error: 'Authentification requise.' }, 401)

    const supabase = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
    )
    const { data: { user }, error: userError } = await supabase.auth.getUser(authorization.replace('Bearer ', ''))
    if (userError || !user) return json({ error: 'Session invalide.' }, 401)

    const body = await request.json().catch(() => ({}))
    const organizationId = String(body.organizationId ?? '')
    const action = String(body.action ?? 'summary')
    const returnUrl = `${safeOrigin(body.returnUrl)}/app/account`

    const { data: membership } = await supabase
      .from('memberships')
      .select('role')
      .eq('organization_id', organizationId)
      .eq('user_id', user.id)
      .maybeSingle()
    if (!membership) return json({ error: 'Accès refusé à ce workspace.' }, 403)

    const { data: subscription } = await supabase
      .from('subscriptions')
      .select('*')
      .eq('organization_id', organizationId)
      .order('created_at', { ascending: false })
      .limit(1)
      .maybeSingle()

    const stripeSecret = Deno.env.get('STRIPE_SECRET_KEY')
    if (action === 'summary') {
      if (!stripeSecret || !subscription?.stripe_customer_id) {
        return json({
          configured: Boolean(stripeSecret),
          customerLinked: false,
          upcoming: null,
          paymentMethod: null,
          invoices: [],
        })
      }

      const customerId = subscription.stripe_customer_id
      const [customerResult, invoiceResult, previewResult] = await Promise.allSettled([
        stripeRequest(`/v1/customers/${encodeURIComponent(customerId)}`, stripeSecret, undefined, 'GET'),
        stripeRequest(`/v1/invoices?customer=${encodeURIComponent(customerId)}&limit=12`, stripeSecret, undefined, 'GET'),
        stripeRequest('/v1/invoices/create_preview', stripeSecret, new URLSearchParams({ customer: customerId })),
      ])
      const customer = customerResult.status === 'fulfilled' ? customerResult.value : null
      const invoices = invoiceResult.status === 'fulfilled' ? invoiceResult.value.data ?? [] : []
      const preview = previewResult.status === 'fulfilled' ? previewResult.value : null
      let paymentMethod = null
      const paymentMethodId = typeof customer?.invoice_settings?.default_payment_method === 'string'
        ? customer.invoice_settings.default_payment_method
        : null
      if (paymentMethodId) {
        try {
          const method = await stripeRequest(`/v1/payment_methods/${encodeURIComponent(paymentMethodId)}`, stripeSecret, undefined, 'GET')
          paymentMethod = method.card ? {
            brand: method.card.brand,
            last4: method.card.last4,
            expMonth: method.card.exp_month,
            expYear: method.card.exp_year,
          } : { type: method.type }
        } catch {
          paymentMethod = null
        }
      }

      return json({
        configured: true,
        customerLinked: true,
        upcoming: preview ? {
          amountDue: preview.amount_due,
          currency: preview.currency,
          date: preview.next_payment_attempt ?? preview.period_end ?? null,
        } : null,
        paymentMethod,
        invoices: invoices.map((invoice: Record<string, unknown>) => ({
          id: invoice.id,
          number: invoice.number,
          status: invoice.status,
          amountPaid: invoice.amount_paid,
          amountDue: invoice.amount_due,
          currency: invoice.currency,
          created: invoice.created,
          invoicePdf: invoice.invoice_pdf,
          hostedInvoiceUrl: invoice.hosted_invoice_url,
        })),
      })
    }

    if (!['owner', 'admin'].includes(membership.role)) {
      return json({ error: 'Seul un owner ou un admin peut gérer la facturation.' }, 403)
    }
    if (!stripeSecret) return json({ error: 'Stripe n’est pas encore configuré côté serveur.' }, 503)

    if (action === 'portal') {
      if (!subscription?.stripe_customer_id) return json({ error: 'Aucun compte de facturation Stripe n’est encore lié.' }, 409)
      const params = new URLSearchParams({
        customer: subscription.stripe_customer_id,
        return_url: returnUrl,
        locale: 'fr',
      })
      if (body.flow === 'payment_method_update') params.set('flow_data[type]', 'payment_method_update')
      const session = await stripeRequest('/v1/billing_portal/sessions', stripeSecret, params)
      return json({ url: session.url })
    }

    if (action !== 'checkout') return json({ error: 'Action inconnue.' }, 400)

    const planId = String(body.planId ?? '')
    const billingCycle = body.billingCycle === 'yearly' ? 'yearly' : 'monthly'
    const requestedSeats = Math.max(1, Math.floor(Number(body.seatQuantity ?? 1)))
    const { data: plan } = await supabase
      .from('subscription_plans')
      .select('id,name,max_licenses,stripe_price_monthly_id,stripe_price_yearly_id,is_active')
      .eq('id', planId)
      .in('id', ['solo', 'pro', 'business'])
      .eq('is_active', true)
      .maybeSingle()
    if (!plan) return json({ error: 'Ce plan commercial n’est pas disponible.' }, 400)

    const maxLicenses = Number(plan.max_licenses)
    const seats = maxLicenses > 0 ? Math.min(requestedSeats, maxLicenses) : requestedSeats
    const priceId = billingCycle === 'yearly' ? plan.stripe_price_yearly_id : plan.stripe_price_monthly_id
    if (!priceId) return json({ error: `Le tarif Stripe ${plan.name} n’est pas encore configuré.` }, 503)

    if (subscription?.stripe_customer_id && subscription?.stripe_subscription_id) {
      const stripeSubscription = await stripeRequest(
        `/v1/subscriptions/${encodeURIComponent(subscription.stripe_subscription_id)}`,
        stripeSecret,
        undefined,
        'GET',
      )
      const itemId = stripeSubscription?.items?.data?.[0]?.id
      if (!itemId) return json({ error: 'La ligne d’abonnement Stripe est introuvable.' }, 409)
      const params = new URLSearchParams({
        customer: subscription.stripe_customer_id,
        return_url: returnUrl,
        'flow_data[type]': 'subscription_update_confirm',
        'flow_data[subscription_update_confirm][subscription]': subscription.stripe_subscription_id,
        'flow_data[subscription_update_confirm][items][0][id]': itemId,
        'flow_data[subscription_update_confirm][items][0][price]': priceId,
        'flow_data[subscription_update_confirm][items][0][quantity]': String(seats),
        'flow_data[after_completion][type]': 'redirect',
        'flow_data[after_completion][redirect][return_url]': `${returnUrl}?billing=updated`,
      })
      const portal = await stripeRequest('/v1/billing_portal/sessions', stripeSecret, params)
      return json({ url: portal.url })
    }

    const params = new URLSearchParams({
      mode: 'subscription',
      success_url: `${returnUrl}?billing=success`,
      cancel_url: `${returnUrl}?billing=canceled`,
      client_reference_id: organizationId,
      customer_email: user.email ?? '',
      'line_items[0][price]': priceId,
      'line_items[0][quantity]': String(seats),
      'subscription_data[metadata][organization_id]': organizationId,
      'subscription_data[metadata][plan_id]': planId,
      'subscription_data[metadata][billing_cycle]': billingCycle,
      'metadata[organization_id]': organizationId,
      'metadata[plan_id]': planId,
      'metadata[seat_quantity]': String(seats),
      allow_promotion_codes: 'true',
      billing_address_collection: 'auto',
      locale: 'fr',
    })
    const checkout = await stripeRequest('/v1/checkout/sessions', stripeSecret, params)
    return json({ url: checkout.url })
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : 'Erreur de facturation.' }, 500)
  }
})

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { EMAIL_FROM, EMAIL_REPLY_TO } from '../_shared/email.ts'
import { renderTeamInvite } from '../_shared/email-templates/invitation.ts'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
}

Deno.serve(async (request) => {
  if (request.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405)

  try {
    const authorization = request.headers.get('Authorization')
    if (!authorization) return json({ error: 'Authentification requise.' }, 401)
    const supabase = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
    )
    const { data: { user }, error: userError } = await supabase.auth.getUser(authorization.replace('Bearer ', ''))
    if (userError || !user) return json({ error: 'Session invalide.' }, 401)

    const body = await request.json().catch(() => ({}))
    const organizationId = String(body.organizationId ?? '')
    const email = String(body.email ?? '').trim().toLowerCase()
    const role = body.role === 'admin' ? 'admin' : 'member'
    if (!organizationId || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      return json({ error: 'Adresse email invalide.' }, 400)
    }

    const { data: membership } = await supabase.from('memberships')
      .select('role').eq('organization_id', organizationId).eq('user_id', user.id).maybeSingle()
    if (!membership || !['owner', 'admin'].includes(membership.role)) {
      return json({ error: 'Seul un owner ou un admin peut inviter un membre.' }, 403)
    }

    const [{ data: subscription }, { count: memberCount }, { count: pendingInvitationCount }, { data: existingInvitation }] = await Promise.all([
      supabase.from('subscriptions')
        .select('plan_id,seat_quantity,subscription_plans(max_licenses)')
        .eq('organization_id', organizationId).order('created_at', { ascending: false }).limit(1).maybeSingle(),
      supabase.from('memberships').select('id', { count: 'exact', head: true }).eq('organization_id', organizationId),
      // Une invitation 'pending' réserve un siège (sinon on pourrait inviter plus
      // de monde que de sièges payés et ne s'en apercevoir qu'à l'acceptation).
      // Annuler l'invitation (status='revoked') libère donc automatiquement ce siège.
      supabase.from('organization_invitations').select('id', { count: 'exact', head: true })
        .eq('organization_id', organizationId).eq('status', 'pending'),
      supabase.from('organization_invitations').select('id,status')
        .eq('organization_id', organizationId).eq('email', email).maybeSingle(),
    ])

    const planLimit = Number((subscription?.subscription_plans as { max_licenses?: number } | null)?.max_licenses ?? 1)
    // max_licenses = -1 est le sentinel « illimité » (enterprise/super_admin/tester) —
    // aucune vérification de siège ne s'applique dans ce cas.
    if (planLimit >= 0) {
      const paidSeats = Math.max(1, Number(subscription?.seat_quantity ?? 1))
      const effectiveSeats = Math.min(planLimit, paidSeats)
      const usedSeats = (memberCount ?? 0) + (pendingInvitationCount ?? 0)
      if (usedSeats >= effectiveSeats) {
        return json({
          error: 'Tous les sièges actifs sont occupés. Ajoute d’abord un siège à ton abonnement.',
          code: 'seat_required',
        }, 409)
      }
    }
    if (existingInvitation?.status === 'pending') {
      return json({ error: 'Une invitation est déjà en attente pour cette adresse.' }, 409)
    }

    const { data: inviterProfile } = await supabase.from('profiles').select('full_name').eq('id', user.id).maybeSingle()
    const { data: organization } = await supabase.from('organizations').select('name').eq('id', organizationId).maybeSingle()
    const inviterName = String(inviterProfile?.full_name ?? user.email ?? 'Un membre de l’équipe')
    const organizationName = String(organization?.name ?? 'ton équipe')
    // Tohu n'a aucune authentification par mot de passe ou lien magique — seul
    // le SSO (Google/Microsoft/LinkedIn) existe (voir login.html). Un lien
    // auth.admin.generateLink({type:'invite'}) authentifierait donc la personne
    // silencieusement via un mécanisme que l'app ne sait ensuite jamais réutiliser
    // (pas de mot de passe à définir). Le lien pointe donc simplement vers la page
    // de connexion Tohu, où elle se connecte normalement via SSO ; l'invitation
    // (organization_invitations, upsertée plus bas) est de toute façon rattachée
    // par email dès la connexion, quel que soit le mécanisme d'auth utilisé
    // (accept_my_organization_invitations, appelé à chaque démarrage de l'app).
    const inviteUrl = `${Deno.env.get('APP_URL') ?? 'https://tohu.co'}/connexion?invited_by=${encodeURIComponent(inviterName)}&org=${encodeURIComponent(organizationName)}`

    const rendered = renderTeamInvite({
      inviterName,
      organizationName,
      role,
      inviteUrl,
    })
    const resendApiKey = Deno.env.get('RESEND_API_KEY')
    if (!resendApiKey) throw new Error('RESEND_API_KEY manquant')
    const emailResponse = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: { Authorization: `Bearer ${resendApiKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        from: EMAIL_FROM, to: [email], subject: rendered.subject, html: rendered.html, reply_to: EMAIL_REPLY_TO,
        tags: [{ name: 'type', value: 'team_invite' }],
      }),
    })
    if (!emailResponse.ok) {
      const payload = await emailResponse.json().catch(() => ({}))
      throw new Error(`Resend ${emailResponse.status}: ${JSON.stringify(payload).slice(0, 200)}`)
    }

    const { error: upsertError } = await supabase.from('organization_invitations').upsert({
      organization_id: organizationId,
      email,
      role,
      invited_by: user.id,
      status: 'pending',
      expires_at: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
      accepted_at: null,
      updated_at: new Date().toISOString(),
    }, { onConflict: 'organization_id,email' })
    if (upsertError) throw upsertError

    await supabase.from('audit_logs').insert({
      organization_id: organizationId,
      actor_user_id: user.id,
      action: 'team_member_invited',
      target_table: 'organization_invitations',
      metadata: { email, role },
    })
    return json({ success: true })
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : 'Invitation impossible.' }, 500)
  }
})

// Wrapper d'envoi e-mail (Resend) partagé par tous les senders (digest, antisèche,
// alerte, nurturing). Centralise la doctrine d'envoi ACT-88 :
//  - opt-out global + désactivation par type (email_preferences) ;
//  - idempotence via dedupe_key (email_log) : un même e-mail n'est jamais envoyé 2×
//    (digest hebdo = 1 clé/semaine, antisèche = 1 clé/réunion) ;
//  - plafond d'alertes : max N/semaine/utilisateur (défaut 3).
// Aucune intelligence ici : les senders fournissent le HTML déjà rendu.

export type EmailType =
  | 'digest' | 'digest_empty'
  | 'antiseche'
  | 'alerte'
  | 'onb_1' | 'onb_2' | 'onb_3' | 'onb_4' | 'onb_5'

export const EMAIL_FROM = Deno.env.get('EMAIL_FROM') ?? 'Tohu <bonjour@tohu.co>'
export const EMAIL_REPLY_TO = Deno.env.get('EMAIL_REPLY_TO') ?? 'bonjour@tohu.co'
const PREFERENCES_URL = Deno.env.get('EMAIL_PREFERENCES_URL') ?? 'https://tohu.co/preferences'

// Colonne d'activation par famille d'e-mail (null = toujours autorisé).
const TYPE_TOGGLE: Record<EmailType, string | null> = {
  digest: 'digest_enabled', digest_empty: 'digest_enabled',
  antiseche: 'antiseche_enabled',
  alerte: 'alerte_enabled',
  onb_1: 'onboarding_enabled', onb_2: 'onboarding_enabled', onb_3: 'onboarding_enabled',
  onb_4: 'onboarding_enabled', onb_5: 'onboarding_enabled',
}
// Famille de diffusion (pilotage super-admin : global / type de compte / user).
const DISPATCH_FAMILY: Record<EmailType, string> = {
  digest: 'digest', digest_empty: 'digest', antiseche: 'antiseche', alerte: 'alerte',
  onb_1: 'nurturing', onb_2: 'nurturing', onb_3: 'nurturing', onb_4: 'nurturing', onb_5: 'nurturing',
}

/** Lundi 00:00 UTC de la semaine courante — borne du plafond hebdo d'alertes. */
function startOfIsoWeek(now = new Date()): Date {
  const date = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()))
  const day = date.getUTCDay() || 7 // dimanche = 7
  date.setUTCDate(date.getUTCDate() - (day - 1))
  return date
}

export type SendEmailInput = {
  supabase: any
  userId: string
  organizationId?: string | null
  type: EmailType
  to: string
  subject: string
  html: string
  // Clé d'idempotence. Ex. `digest:{userId}:{isoWeek}`, `antiseche:{meetingId}`,
  // `alerte:{signalId}`, `onb_2:{userId}`. Deux appels avec la même clé = 1 envoi.
  dedupeKey: string
  replyTo?: string
}

export type SendEmailResult =
  | { sent: true; id: string | null }
  | { sent: false; skipped: true; reason: string }

export async function sendEmail(input: SendEmailInput): Promise<SendEmailResult> {
  const { supabase, userId, organizationId = null, type, to, subject, html, dedupeKey } = input

  // 1) Idempotence : déjà envoyé sous cette clé ?
  const { data: already } = await supabase.from('email_log')
    .select('status').eq('dedupe_key', dedupeKey).maybeSingle()
  if (already?.status === 'sent') return { sent: false, skipped: true, reason: 'already_sent' }

  // 2) Préférences : opt-out global + désactivation par type.
  const { data: pref } = await supabase.from('email_preferences')
    .select('unsubscribed_all, digest_enabled, antiseche_enabled, alerte_enabled, onboarding_enabled, alerte_max_per_week')
    .eq('user_id', userId).maybeSingle()
  if (pref?.unsubscribed_all) return { sent: false, skipped: true, reason: 'unsubscribed_all' }
  const toggle = TYPE_TOGGLE[type]
  if (toggle && pref && pref[toggle] === false) return { sent: false, skipped: true, reason: 'type_disabled' }

  // Règles de diffusion pilotées par le super-admin (global / type de compte / user).
  const { data: dispatchAllowed } = await supabase.rpc('email_dispatch_allowed', { p_user_id: userId, p_email_type: DISPATCH_FAMILY[type] })
  if (dispatchAllowed === false) return { sent: false, skipped: true, reason: 'dispatch_disabled' }

  // 3) Plafond d'alertes : max N/semaine/utilisateur (ACT-88).
  if (type === 'alerte') {
    const cap = pref?.alerte_max_per_week ?? 3
    const { count } = await supabase.from('email_log')
      .select('id', { count: 'exact', head: true })
      .eq('user_id', userId).eq('email_type', 'alerte').eq('status', 'sent')
      .gte('created_at', startOfIsoWeek().toISOString())
    if ((count ?? 0) >= cap) return { sent: false, skipped: true, reason: 'weekly_alert_cap' }
  }

  // 4) Envoi Resend.
  const apiKey = Deno.env.get('RESEND_API_KEY')
  if (!apiKey) throw new Error('RESEND_API_KEY manquant')
  const response = await fetch('https://api.resend.com/emails', {
    method: 'POST',
    headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      from: EMAIL_FROM,
      to: [to],
      subject,
      html,
      reply_to: input.replyTo ?? EMAIL_REPLY_TO,
      headers: { 'List-Unsubscribe': `<${PREFERENCES_URL}>`, 'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click' },
      tags: [{ name: 'type', value: type }],
    }),
  })
  const payload = await response.json().catch(() => ({}))
  const ok = response.ok

  // 5) Journalisation (upsert sur dedupe_key → l'échec peut être rejoué).
  await supabase.from('email_log').upsert({
    user_id: userId, organization_id: organizationId, email_type: type, dedupe_key: dedupeKey,
    to_email: to, subject, resend_id: (payload as any)?.id ?? null,
    status: ok ? 'sent' : 'failed', error: ok ? null : JSON.stringify(payload).slice(0, 500),
  }, { onConflict: 'dedupe_key' })

  if (!ok) throw new Error(`Resend ${response.status}: ${JSON.stringify(payload).slice(0, 200)}`)
  return { sent: true, id: (payload as any)?.id ?? null }
}

/** Clé de semaine ISO (ex. 2026-W32) pour la dédup du digest hebdo. */
export function isoWeekKey(now = new Date()): string {
  const date = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()))
  const day = date.getUTCDay() || 7
  date.setUTCDate(date.getUTCDate() + 4 - day)
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1))
  const week = Math.ceil(((date.getTime() - yearStart.getTime()) / 86400000 + 1) / 7)
  return `${date.getUTCFullYear()}-W${String(week).padStart(2, '0')}`
}

