import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } })
}

function hex(bytes: ArrayBuffer): string {
  return [...new Uint8Array(bytes)].map((byte) => byte.toString(16).padStart(2, '0')).join('')
}

function safeEqual(left: string, right: string): boolean {
  if (left.length !== right.length) return false
  let difference = 0
  for (let index = 0; index < left.length; index += 1) {
    difference |= left.charCodeAt(index) ^ right.charCodeAt(index)
  }
  return difference === 0
}

async function verifySignature(payload: string, signature: string, secret: string): Promise<boolean> {
  const parts = signature.split(',').map((part) => part.split('='))
  const timestamp = parts.find(([key]) => key === 't')?.[1]
  const signatures = parts.filter(([key]) => key === 'v1').map(([, value]) => value)
  if (!timestamp || signatures.length === 0) return false
  if (Math.abs(Date.now() / 1000 - Number(timestamp)) > 300) return false
  const key = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign'],
  )
  const digest = hex(await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(`${timestamp}.${payload}`)))
  return signatures.some((candidate) => safeEqual(candidate, digest))
}

type StripeObject = Record<string, any>

Deno.serve(async (request) => {
  if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
  try {
    const webhookSecret = Deno.env.get('STRIPE_WEBHOOK_SECRET')
    const signature = request.headers.get('Stripe-Signature')
    if (!webhookSecret || !signature) return json({ error: 'Webhook Stripe non configuré.' }, 503)
    const payload = await request.text()
    if (!await verifySignature(payload, signature, webhookSecret)) return json({ error: 'Signature invalide.' }, 400)

    const event = JSON.parse(payload)
    const supabase = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
    )
    const { error: eventError } = await supabase.from('stripe_webhook_events').insert({
      event_id: event.id,
      event_type: event.type,
    })
    if (eventError?.code === '23505') return json({ received: true, duplicate: true })
    if (eventError) throw eventError

    const object = event.data?.object as StripeObject
    let stripeSubscriptionId: string | null = null
    if (event.type.startsWith('customer.subscription.')) stripeSubscriptionId = object.id
    if (event.type === 'checkout.session.completed') {
      stripeSubscriptionId = typeof object.subscription === 'string' ? object.subscription : null
    }
    if (event.type.startsWith('invoice.')) {
      stripeSubscriptionId = typeof object.subscription === 'string'
        ? object.subscription
        : object.parent?.subscription_details?.subscription ?? null
    }
    if (!stripeSubscriptionId) return json({ received: true, ignored: true })

    const stripeSecret = Deno.env.get('STRIPE_SECRET_KEY')
    if (!stripeSecret) throw new Error('STRIPE_SECRET_KEY manquante.')
    const response = await fetch(`https://api.stripe.com/v1/subscriptions/${encodeURIComponent(stripeSubscriptionId)}`, {
      headers: { Authorization: `Bearer ${stripeSecret}` },
    })
    const stripeSubscription = await response.json()
    if (!response.ok) throw new Error(stripeSubscription?.error?.message ?? 'Abonnement Stripe introuvable.')

    const customerId = typeof stripeSubscription.customer === 'string'
      ? stripeSubscription.customer
      : stripeSubscription.customer?.id
    const firstItem = stripeSubscription.items?.data?.[0]
    const priceId = firstItem?.price?.id ?? null
    const organizationId = stripeSubscription.metadata?.organization_id
      ?? object.metadata?.organization_id
      ?? object.client_reference_id
    if (!organizationId) throw new Error('organization_id absent des métadonnées Stripe.')

    const { data: mappedPlan } = priceId
      ? await supabase.from('subscription_plans')
        .select('id,price_monthly,price_yearly,stripe_price_monthly_id,stripe_price_yearly_id')
        .or(`stripe_price_monthly_id.eq.${priceId},stripe_price_yearly_id.eq.${priceId}`)
        .maybeSingle()
      : { data: null }
    const planId = mappedPlan?.id ?? stripeSubscription.metadata?.plan_id
    if (!planId) throw new Error('Plan Tohu impossible à déterminer depuis le tarif Stripe.')

    const isYearly = mappedPlan?.stripe_price_yearly_id === priceId
      || firstItem?.price?.recurring?.interval === 'year'
    const statusMap: Record<string, string> = {
      active: 'active',
      trialing: 'trialing',
      past_due: 'past_due',
      unpaid: 'past_due',
      canceled: 'canceled',
      paused: 'paused',
      incomplete: 'paused',
      incomplete_expired: 'canceled',
    }
    const values = {
      plan_id: planId,
      status: statusMap[stripeSubscription.status] ?? 'paused',
      billing_cycle: isYearly ? 'yearly' : 'monthly',
      amount_per_period: Number(firstItem?.price?.unit_amount ?? 0) * Number(firstItem?.quantity ?? 1),
      seat_quantity: Math.max(1, Number(firstItem?.quantity ?? 1)),
      current_period_start: firstItem?.current_period_start
        ? new Date(firstItem.current_period_start * 1000).toISOString()
        : new Date().toISOString(),
      current_period_end: firstItem?.current_period_end
        ? new Date(firstItem.current_period_end * 1000).toISOString()
        : new Date().toISOString(),
      cancel_at_period_end: Boolean(stripeSubscription.cancel_at_period_end),
      canceled_at: stripeSubscription.canceled_at
        ? new Date(stripeSubscription.canceled_at * 1000).toISOString()
        : null,
      stripe_subscription_id: stripeSubscription.id,
      stripe_customer_id: customerId,
      stripe_price_id: priceId,
      updated_at: new Date().toISOString(),
    }

    const { data: existing } = await supabase.from('subscriptions')
      .select('id').eq('organization_id', organizationId)
      .order('created_at', { ascending: false }).limit(1).maybeSingle()
    const result = existing
      ? await supabase.from('subscriptions').update(values).eq('id', existing.id)
      : await supabase.from('subscriptions').insert({ organization_id: organizationId, ...values })
    if (result.error) throw result.error

    await supabase.from('audit_logs').insert({
      organization_id: organizationId,
      action: 'stripe_subscription_synchronized',
      target_table: 'subscriptions',
      target_id: existing?.id ?? null,
      metadata: { event_id: event.id, event_type: event.type, plan_id: planId, seat_quantity: values.seat_quantity },
    })
    return json({ received: true })
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : 'Webhook impossible.' }, 500)
  }
})

// Synchronise les réunions Google Meet : liste les conferenceRecords (API Meet v2,
// distincte de Calendar), récupère leurs transcripts, et les recoupe avec les
// événements Calendar (mêmes scopes que sync-email-analysis) pour obtenir les emails
// des participants — l'API Meet n'expose que des noms d'affichage, jamais d'email.
//
// Un conferenceRecord n'existe qu'une fois l'appel démarré : sync-google-calendar
// (fenêtre passé+futur, tous types d'événements) crée en général déjà la ligne
// `meetings` correspondante avant que ce conferenceRecord n'apparaisse. On converge
// donc sur le même external_event_id (`google:{eventId}`) quand un événement Calendar
// est apparié, pour enrichir cette ligne (plateforme, transcript) plutôt que d'en
// créer une seconde — upsertCalendarMeeting porte aussi le garde-fou individuel/
// collectif (jamais de fiche candidate pour un participant d'une réunion collective).
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { cleanEmail, upsertCalendarMeeting, type NormalizedCalendarEvent } from '../_shared/calendar-sync.ts'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
}

function positiveIntegerEnv(name: string, fallback: number): number {
  const parsed = Number(Deno.env.get(name))
  return Number.isFinite(parsed) && parsed > 0 ? Math.floor(parsed) : fallback
}

const LOOKBACK_DAYS = positiveIntegerEnv('MEET_SYNC_LOOKBACK_DAYS', 14)
const MAX_CONFERENCES = positiveIntegerEnv('MEET_SYNC_MAX_CONFERENCES', 30)
// Tolérance de rapprochement conferenceRecord ↔ événement Calendar : l'API Meet ne
// référence pas directement l'événement, on recoupe par proximité temporelle du début.
const MATCH_TOLERANCE_MS = 10 * 60 * 1000
// Même seuil que sync-google-calendar/sync-microsoft-calendar (env partagée) : la
// convergence sur la même ligne `meetings` exige le même calcul individuel/collectif.
const SMALL_MEETING_MAX_ATTENDEES = positiveIntegerEnv('CALENDAR_SYNC_SMALL_MEETING_MAX_ATTENDEES', 5)

async function refreshAccessToken(refreshToken: string): Promise<{ accessToken: string; refreshToken: string; expiresIn: number }> {
  const clientId = Deno.env.get('GOOGLE_CLIENT_ID')
  const clientSecret = Deno.env.get('GOOGLE_CLIENT_SECRET')
  if (!clientId || !clientSecret) throw new Error('Secrets OAuth google manquants')
  const response = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ client_id: clientId, client_secret: clientSecret, refresh_token: refreshToken, grant_type: 'refresh_token' }),
  })
  if (!response.ok) throw new Error(`Rafraîchissement google refusé (${response.status})`)
  const data = await response.json()
  return { accessToken: data.access_token, refreshToken: data.refresh_token ?? refreshToken, expiresIn: Number(data.expires_in ?? 3600) }
}

type CalendarAttendee = { email: string; displayName: string | null; organizer: boolean }
type CalendarMeeting = { id: string; title: string; startMs: number; endMs: number | null; attendees: CalendarAttendee[] }

async function meetLinkedCalendarEvents(token: string, sinceIso: string): Promise<CalendarMeeting[]> {
  const results: CalendarMeeting[] = []
  let pageToken: string | null = null
  do {
    const params = new URLSearchParams({
      timeMin: sinceIso, singleEvents: 'true', orderBy: 'startTime', maxResults: '250',
      fields: 'nextPageToken,items(id,summary,start,end,attendees,conferenceData)',
    })
    if (pageToken) params.set('pageToken', pageToken)
    const response = await fetch(`https://www.googleapis.com/calendar/v3/calendars/primary/events?${params}`, { headers: { Authorization: `Bearer ${token}` } })
    if (!response.ok) throw new Error(`Google Calendar ${response.status}`)
    const page = await response.json()
    for (const item of (page.items ?? []) as any[]) {
      const isMeet = item.conferenceData?.conferenceSolution?.key?.type === 'hangoutsMeet'
      const startMs = item.start?.dateTime ? new Date(item.start.dateTime).getTime() : null
      if (!isMeet || !startMs || !item.id) continue
      results.push({
        id: item.id,
        title: item.summary ?? 'Réunion Google Meet',
        startMs,
        endMs: item.end?.dateTime ? new Date(item.end.dateTime).getTime() : null,
        attendees: ((item.attendees ?? []) as any[]).map((attendee) => ({
          email: cleanEmail(attendee.email), displayName: attendee.displayName ?? null, organizer: Boolean(attendee.organizer),
        })).filter((attendee) => attendee.email),
      })
    }
    pageToken = page.nextPageToken ?? null
  } while (pageToken)
  return results
}

async function listConferenceRecords(token: string, sinceIso: string): Promise<any[]> {
  const records: any[] = []
  let pageToken: string | null = null
  do {
    const params = new URLSearchParams({ filter: `start_time>="${sinceIso}"`, pageSize: '50' })
    if (pageToken) params.set('pageToken', pageToken)
    const response = await fetch(`https://meet.googleapis.com/v2/conferenceRecords?${params}`, { headers: { Authorization: `Bearer ${token}` } })
    if (!response.ok) {
      // Compte Google personnel ou Meet non activé pour le Workspace : pas une erreur
      // fatale, juste aucune conférence à synchroniser.
      if (response.status === 403 || response.status === 404) return []
      throw new Error(`Google Meet API ${response.status}`)
    }
    const page = await response.json()
    records.push(...(page.conferenceRecords ?? []))
    pageToken = page.nextPageToken ?? null
  } while (pageToken && records.length < MAX_CONFERENCES)
  return records.slice(0, MAX_CONFERENCES)
}

async function listAll(token: string, url: string, arrayKey: string): Promise<any[]> {
  const items: any[] = []
  let pageToken: string | null = null
  do {
    const separator = url.includes('?') ? '&' : '?'
    const pageUrl = pageToken ? `${url}${separator}pageToken=${encodeURIComponent(pageToken)}` : url
    const response = await fetch(pageUrl, { headers: { Authorization: `Bearer ${token}` } })
    if (!response.ok) return items
    const page = await response.json()
    items.push(...(page[arrayKey] ?? []))
    pageToken = page.nextPageToken ?? null
  } while (pageToken)
  return items
}

function participantLabel(participant: any): string {
  return participant?.signedinUser?.displayName ?? participant?.anonymousUser?.displayName ?? participant?.phoneUser?.displayName ?? 'Participant'
}

Deno.serve(async (request) => {
  if (request.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
  const startedAt = new Date().toISOString()
  let syncJobId: string | null = null
  try {
    const authorization = request.headers.get('Authorization')
    if (!authorization) return json({ error: 'Authentification requise' }, 401)
    const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')
    const { data: { user }, error: userError } = await supabase.auth.getUser(authorization.replace('Bearer ', ''))
    if (userError || !user) return json({ error: 'Session invalide' }, 401)
    const { organizationId } = await request.json().catch(() => ({}))
    if (!organizationId) return json({ error: 'Paramètres invalides' }, 400)
    const { data: membership } = await supabase.from('memberships').select('id').eq('organization_id', organizationId).eq('user_id', user.id).maybeSingle()
    if (!membership) return json({ error: 'Accès refusé' }, 403)
    const { data: connector } = await supabase.from('connectors').select('id,metadata').eq('organization_id', organizationId).eq('user_id', user.id).eq('provider', 'google').maybeSingle()
    if (!connector) return json({ error: 'Connecteur Google introuvable. Connecte Google Workspace d’abord.' }, 404)
    const { data: tokenRows, error: tokenError } = await supabase.rpc('get_oauth_tokens_server', { p_connector_id: connector.id })
    const oauth = tokenRows?.[0]
    if (tokenError || !oauth) return json({ error: 'Jetons OAuth absents. Reconnecte Google Workspace.' }, 401)

    const { data: job } = await supabase.from('sync_jobs').insert({
      organization_id: organizationId, connector_id: connector.id, user_id: user.id, provider: 'google',
      job_type: 'google_meet_sync', status: 'running', current_step: 'Connexion au fournisseur', progress: 10, started_at: startedAt, payload: {},
    }).select('id').single()
    syncJobId = job?.id ?? null

    let accessToken = oauth.access_token as string | null
    let refreshToken = oauth.refresh_token as string | null
    const expiresSoon = !oauth.expires_at || new Date(oauth.expires_at).getTime() < Date.now() + 90_000
    if ((!accessToken || expiresSoon) && refreshToken) {
      const refreshed = await refreshAccessToken(refreshToken)
      accessToken = refreshed.accessToken
      refreshToken = refreshed.refreshToken
      await supabase.rpc('store_oauth_tokens_server', { p_organization_id: organizationId, p_connector_id: connector.id, p_provider_account_id: oauth.provider_account_id, p_access_token: accessToken, p_refresh_token: refreshToken, p_expires_at: new Date(Date.now() + refreshed.expiresIn * 1000).toISOString() })
    }
    if (!accessToken) throw new Error('Jeton OAuth indisponible')

    const ownEmail = cleanEmail((connector.metadata as any)?.account_email ?? user.email)
    const sinceIso = new Date(Date.now() - LOOKBACK_DAYS * 86_400_000).toISOString()

    const [calendarMeetings, conferenceRecords] = await Promise.all([
      meetLinkedCalendarEvents(accessToken, sinceIso),
      listConferenceRecords(accessToken, sinceIso),
    ])
    if (syncJobId) await supabase.from('sync_jobs').update({ current_step: 'Lecture des conférences Google Meet', progress: 35 }).eq('id', syncJobId)

    let meetingsSynced = 0
    let transcriptsSynced = 0
    let participantsMatched = 0
    const errors: string[] = []

    for (const record of conferenceRecords) {
      try {
        const recordStart = record.startTime ? new Date(record.startTime).getTime() : null
        if (!recordStart) continue
        // Rapprochement avec l'événement Calendar le plus proche dans le temps : l'API
        // Meet ne référence pas l'ID d'événement, seulement l'espace de réunion.
        const matchedEvent = calendarMeetings
          .filter((meeting) => Math.abs(meeting.startMs - recordStart) <= MATCH_TOLERANCE_MS)
          .sort((a, b) => Math.abs(a.startMs - recordStart) - Math.abs(b.startMs - recordStart))[0] ?? null

        const externalAttendees = (matchedEvent?.attendees ?? []).filter((attendee) => attendee.email !== ownEmail)
        const event: NormalizedCalendarEvent = {
          externalEventId: matchedEvent?.id ? `google:${matchedEvent.id}` : record.name,
          title: matchedEvent?.title ?? 'Réunion Google Meet',
          startsAt: record.startTime,
          endsAt: record.endTime ?? null,
          status: 'confirmed',
          meetingUrl: null,
          calendarHtmlLink: null,
          platform: 'google_meet',
          attendees: [
            ...externalAttendees.map((attendee) => ({ ...attendee, self: false })),
            { email: ownEmail, displayName: null, organizer: false, self: true },
          ],
          raw: record,
        }
        // Si un événement Calendar est apparié, sync-google-calendar a probablement déjà
        // créé/enrichi cette ligne (scope, statut, liens) — on ne les écrase pas ici,
        // ce conferenceRecord n'apporte que la plateforme "google_meet" et les transcripts.
        const { meetingId, participantsUpserted } = await upsertCalendarMeeting({
          supabase, organizationId, ownerUserId: user.id, event, source: 'google_meet',
          smallMeetingMaxAttendees: SMALL_MEETING_MAX_ATTENDEES,
          preserveCalendarFields: Boolean(matchedEvent?.id),
        })
        meetingsSynced++
        participantsMatched += participantsUpserted
        const meetingRow = { id: meetingId }

        const transcripts = await listAll(accessToken, `https://meet.googleapis.com/v2/${record.name}/transcripts`, 'transcripts')
        if (!transcripts.length) continue
        const participants = await listAll(accessToken, `https://meet.googleapis.com/v2/${record.name}/participants`, 'participants')
        const speakerByName = new Map(participants.map((participant) => [participant.name as string, participantLabel(participant)]))

        const allEntries: any[] = []
        for (const transcript of transcripts) {
          const entries = await listAll(accessToken, `https://meet.googleapis.com/v2/${transcript.name}/entries`, 'transcriptEntries')
          allEntries.push(...entries)
        }
        if (!allEntries.length) continue
        allEntries.sort((a, b) => new Date(a.startTime ?? 0).getTime() - new Date(b.startTime ?? 0).getTime())
        const transcriptText = allEntries.map((entry) => {
          const speaker = speakerByName.get(entry.participant) ?? 'Participant'
          const time = entry.startTime ? new Date(entry.startTime).toISOString().slice(11, 16) : ''
          return `${speaker}${time ? ` (${time})` : ''} : ${entry.text ?? ''}`
        }).join('\n')
        const speakerMap = Object.fromEntries([...speakerByName.entries()])

        const { error: transcriptError } = await supabase.from('meeting_transcripts').upsert({
          organization_id: organizationId, meeting_id: meetingRow.id, provider: 'google_meet',
          transcript_text: transcriptText, speaker_map: speakerMap,
          // Meet affiche un bandeau à tous les participants dès que la transcription
          // démarre : le consentement est déjà géré au niveau de la plateforme.
          consent_status: 'granted',
        }, { onConflict: 'meeting_id,provider' })
        if (transcriptError) throw transcriptError
        transcriptsSynced++
      } catch (recordError) {
        errors.push(recordError instanceof Error ? recordError.message : String(recordError))
      }
    }

    if (syncJobId) await supabase.from('sync_jobs').update({ current_step: 'Synchronisation terminée', progress: 100, status: 'succeeded', completed_at: new Date().toISOString(), payload: { meetings: meetingsSynced, transcripts: transcriptsSynced, errors: errors.slice(0, 5) } }).eq('id', syncJobId)
    return json({ success: true, meetings: meetingsSynced, transcripts: transcriptsSynced, participantsMatched, errors: errors.slice(0, 5) })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Synchronisation impossible'
    if (syncJobId) {
      const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')
      await supabase.from('sync_jobs').update({ status: 'failed', current_step: 'Échec de la synchronisation', error_code: 'GOOGLE_MEET_SYNC_FAILED', error_message: message, completed_at: new Date().toISOString() }).eq('id', syncJobId)
    }
    return json({ error: message }, 500)
  }
})

// Logique métier partagée entre tous les connecteurs calendrier (Google, Microsoft,
// et un futur 3e provider) : upsert idempotent d'un événement dans meetings/
// meeting_participants, calcul individuel/collectif, matching de participants.
// Un nouveau provider construit juste un NormalizedCalendarEvent[] et appelle
// upsertCalendarMeeting — aucune règle métier à réécrire.
import type { SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2'

export const PUBLIC_EMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'outlook.com', 'outlook.fr',
  'hotmail.com', 'hotmail.fr', 'live.com', 'live.fr', 'msn.com',
  'icloud.com', 'me.com', 'yahoo.com', 'yahoo.fr', 'proton.me', 'protonmail.com',
  'orange.fr', 'wanadoo.fr', 'free.fr', 'sfr.fr', 'laposte.net',
  'gmx.com', 'gmx.fr', 'aol.com', 'mac.com',
  'avocat.com', 'avocat.fr',
])

export function cleanEmail(value: string | null | undefined): string {
  return String(value ?? '').trim().toLowerCase()
}

export function corporateDomain(email: string): string | null {
  const domain = cleanEmail(email).split('@')[1] ?? ''
  return domain && !PUBLIC_EMAIL_DOMAINS.has(domain) ? domain : null
}

export function companyNameFromDomain(domain: string): string {
  const base = domain.split('.')[0] ?? domain
  return base.split(/[-_]+/).filter(Boolean).map((part) => part.charAt(0).toUpperCase() + part.slice(1)).join(' ') || domain
}

export type NormalizedAttendee = { email: string; displayName: string | null; organizer: boolean; self: boolean }

export type NormalizedCalendarEvent = {
  /** Préfixé par provider ('google:{id}' | 'microsoft:{id}') pour ne jamais collisionner entre sources. */
  externalEventId: string
  title: string
  startsAt: string
  endsAt: string | null
  status: 'confirmed' | 'cancelled'
  /** Lien de visioconférence à "rejoindre", si présent. */
  meetingUrl: string | null
  /** Lien "ouvrir dans l'agenda" du provider. */
  calendarHtmlLink: string | null
  platform: 'google_meet' | 'teams' | 'calendar_only'
  attendees: NormalizedAttendee[]
  raw: unknown
}

/** Individuelle = 1:1 ou petit meeting (≤ seuil de participants hors soi-même).
 *  Collective = standup, weekly, webinar — jamais de "prochain rendez-vous"
 *  individuel ni de briefing pour ses participants, même déjà fichés. */
export function meetingScopeOf(event: Pick<NormalizedCalendarEvent, 'attendees'>, maxAttendees: number): 'individual' | 'collective' {
  const others = event.attendees.filter((attendee) => !attendee.self)
  return others.length <= maxAttendees ? 'individual' : 'collective'
}

export type UpsertCalendarMeetingInput = {
  supabase: SupabaseClient
  organizationId: string
  ownerUserId: string
  event: NormalizedCalendarEvent
  source: string
  smallMeetingMaxAttendees: number
  /** true : ne réécrit pas meeting_scope/status/meeting_url/calendar_html_link/raw_payload —
   *  utilisé quand un autre passage calendrier a déjà posé ces champs sur la même ligne
   *  (convergence sync-google-meet ↔ sync-google-calendar sur le même external_event_id). */
  preserveCalendarFields?: boolean
}

export type UpsertCalendarMeetingResult = { meetingId: string; participantsUpserted: number }

export async function upsertCalendarMeeting(input: UpsertCalendarMeetingInput): Promise<UpsertCalendarMeetingResult> {
  const { supabase, organizationId, ownerUserId, event, source, smallMeetingMaxAttendees } = input
  const scope = meetingScopeOf(event, smallMeetingMaxAttendees)
  const others = event.attendees.filter((attendee) => !attendee.self)

  let companyId: string | null = null
  const primary = others[0] ?? null
  if (primary) {
    const domain = corporateDomain(primary.email)
    if (domain) {
      const { data: company } = await supabase.rpc('resolve_company_identity', {
        p_organization_id: organizationId, p_name: companyNameFromDomain(domain), p_domain: domain, p_industry: null, p_create_if_missing: true,
      }).maybeSingle()
      companyId = (company as { company_id?: string } | null)?.company_id ?? null
    }
  }

  const payload: Record<string, unknown> = {
    organization_id: organizationId,
    owner_user_id: ownerUserId,
    company_id: companyId,
    external_event_id: event.externalEventId,
    title: event.title,
    starts_at: event.startsAt,
    ends_at: event.endsAt,
    platform: event.platform,
  }
  if (!input.preserveCalendarFields) {
    Object.assign(payload, {
      status: event.status,
      meeting_scope: scope,
      meeting_url: event.meetingUrl,
      calendar_html_link: event.calendarHtmlLink,
      raw_payload: event.raw,
    })
  }

  const { data: meetingRow, error: meetingError } = await supabase.from('meetings')
    .upsert(payload, { onConflict: 'organization_id,external_event_id' })
    .select('id').single()
  if (meetingError || !meetingRow) throw meetingError ?? new Error('Réunion non enregistrée')

  let participantsUpserted = 0
  for (const attendee of others) {
    const { data: resolved } = await supabase.rpc('resolve_contact_identity', {
      p_organization_id: organizationId,
      p_email: attendee.email,
      p_full_name: attendee.displayName ?? attendee.email,
      p_company_id: companyId,
      p_owner_user_id: ownerUserId,
      p_role_title: null,
      p_source: source,
      p_create_if_missing: scope === 'individual',
    }).maybeSingle()
    // contact_id reste null pour un membre Tohu (resolve_contact_identity renvoie
    // alors 0 ligne) ou pour un inconnu en réunion collective : c'est voulu, pas
    // une erreur — rien de spécial à faire ici, la garantie vient de la RPC.
    const { error: participantError } = await supabase.from('meeting_participants').upsert({
      organization_id: organizationId,
      meeting_id: meetingRow.id,
      contact_id: (resolved as { contact_id?: string } | null)?.contact_id ?? null,
      email: attendee.email,
      display_name: attendee.displayName,
      role_in_meeting: attendee.organizer ? 'organizer' : 'attendee',
      is_current_user: false,
    }, { onConflict: 'meeting_id,email' })
    if (!participantError) participantsUpserted++
  }

  return { meetingId: meetingRow.id as string, participantsUpserted }
}

// Consentement admin Microsoft Teams — connexion CRM multi-client (une seule app
// Azure AD multi-tenant appartenant à Tohu-Bohu, chaque client autorise dans SON
// propre tenant). Contrairement à connect-hubspot, aucun jeton utilisateur n'est
// émis ici : seul le tenant_id du client est utile, les appels API se font ensuite
// en client_credentials avec le secret partagé Tohu-Bohu (voir sync-teams-meetings).
//
// POST (authentifié, JWT) : organizationId → renvoie l'URL de consentement admin Microsoft.
// GET  (public, appelé par Microsoft en retour de consentement) : ?tenant=&state=&admin_consent=
//      → enregistre le tenant_id, redirige vers l'app.
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
};
function jsonResponse(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
}

const APP_URL = 'https://tohu.co';
// Permissions Application demandées à l'admin — le scope v2.0/adminconsent attend
// des URLs Graph complètes, pas juste les noms courts.
const SCOPE = 'https://graph.microsoft.com/OnlineMeetings.Read.All https://graph.microsoft.com/OnlineMeetingTranscript.Read.All';

function functionUrl(): string {
  const supabaseUrl = Deno.env.get('SUPABASE_URL') ?? '';
  return `${supabaseUrl}/functions/v1/connect-teams`;
}

/** Pas d'accès pour poser des variables d'environnement Supabase depuis l'agent qui a
 *  développé ceci : les secrets Teams sont donc dans app_secrets (RLS activé, aucune
 *  policy authenticated/anon → accessible uniquement via service_role), même mécanisme
 *  déjà en place pour le secret cron (`monitor_cron`). */
async function appSecret(supabase: ReturnType<typeof createClient>, name: string): Promise<string | null> {
  const { data } = await supabase.from('app_secrets').select('value').eq('name', name).maybeSingle();
  return (data as { value?: string } | null)?.value ?? null;
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders });
  const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '');
  const clientId = await appSecret(supabase, 'teams_sync_client_id');

  // ── GET = retour du consentement admin Microsoft (?tenant=&state=&admin_consent=) ──
  if (req.method === 'GET') {
    const url = new URL(req.url);
    const tenant = url.searchParams.get('tenant');
    const state = url.searchParams.get('state');
    const adminConsent = url.searchParams.get('admin_consent');
    const oauthError = url.searchParams.get('error');

    if (oauthError) {
      return Response.redirect(`${APP_URL}/app/connectors?error=teams_${encodeURIComponent(oauthError)}`, 302);
    }
    if (!state) return jsonResponse({ error: 'state requis' }, 400);

    let orgId: string, userId: string;
    try {
      const decoded = JSON.parse(atob(state));
      orgId = decoded.orgId; userId = decoded.userId;
      if (!orgId || !userId) throw new Error('state invalide');
    } catch {
      return Response.redirect(`${APP_URL}/app/connectors?error=teams_invalid_state`, 302);
    }

    if (adminConsent !== 'True' || !tenant) {
      return Response.redirect(`${APP_URL}/app/connectors?error=teams_consent_declined`, 302);
    }

    try {
      // Pas de jeton à stocker (aucun n'est émis par ce flow) : seul le tenant_id
      // du client est utile, il sert de clé pour les appels client_credentials.
      const { error: connectorError } = await supabase.from('connectors').upsert({
        organization_id: orgId,
        user_id: userId,
        provider: 'teams',
        status: 'connected',
        scopes: SCOPE.split(' '),
        metadata: { tenant_id: tenant, connected_at: new Date().toISOString() },
        last_synced_at: null,
        updated_at: new Date().toISOString(),
      }, { onConflict: 'user_id,provider' });
      if (connectorError) {
        console.error('Teams connector upsert failed:', connectorError.message);
        return Response.redirect(`${APP_URL}/app/connectors?error=teams_internal`, 302);
      }
      return Response.redirect(`${APP_URL}/app/connectors?connected=teams`, 302);
    } catch (e: any) {
      console.error('Teams callback error:', e?.message);
      return Response.redirect(`${APP_URL}/app/connectors?error=teams_internal`, 302);
    }
  }

  // ── POST = start (authentifié) → renvoie l'URL de consentement admin ────────────
  if (req.method === 'POST') {
    const auth = req.headers.get('Authorization');
    if (!auth) return jsonResponse({ error: 'Missing authorization' }, 401);
    if (!clientId) return jsonResponse({ error: 'TEAMS_SYNC_CLIENT_ID non configuré côté serveur' }, 500);

    const { data: { user }, error: userErr } = await supabase.auth.getUser(auth.replace('Bearer ', ''));
    if (userErr || !user) return jsonResponse({ error: 'Unauthorized' }, 401);

    const { organizationId } = await req.json().catch(() => ({}));
    if (!organizationId) return jsonResponse({ error: 'organizationId requis' }, 400);

    const state = btoa(JSON.stringify({ orgId: organizationId, userId: user.id, ts: Date.now() }));
    // "organizations" : point d'entrée générique pour tout tenant professionnel/scolaire —
    // "common" est refusé par Microsoft pour le consentement admin (un compte perso ne peut pas consentir).
    const authorizeUrl = `https://login.microsoftonline.com/organizations/v2.0/adminconsent?client_id=${encodeURIComponent(clientId)}&scope=${encodeURIComponent(SCOPE)}&redirect_uri=${encodeURIComponent(functionUrl())}&state=${encodeURIComponent(state)}`;

    return jsonResponse({ url: authorizeUrl });
  }

  return jsonResponse({ error: 'Method not allowed' }, 405);
});

// Synchronise les réunions Microsoft Teams pour une organisation cliente déjà
// connectée via connect-teams (consentement admin, tenant_id stocké dans
// connectors.metadata). Contrairement à Google Meet, l'accès aux transcripts est
// une permission Application (client_credentials, jeton "app-only" Tohu-Bohu),
// pas un jeton par utilisateur — mais on réutilise le calendrier Outlook déjà
// connecté (token délégué existant) pour savoir QUELLES réunions chercher, car
// l'API Graph ne permet pas de lister les réunions d'un utilisateur en app-only.
//
// ⚠️ Non testé en conditions réelles : aucun tenant M365 avec licence Teams n'est
// disponible à ce stade (voir le plan). Le format VTT des transcripts et la syntaxe
// exacte de certains filtres OData sont reconstitués depuis la documentation Graph,
// à confirmer dès qu'un premier client se connecte.
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
}

function positiveIntegerEnv(name: string, fallback: number): number {
  const parsed = Number(Deno.env.get(name))
  return Number.isFinite(parsed) && parsed > 0 ? Math.floor(parsed) : fallback
}

const LOOKBACK_DAYS = positiveIntegerEnv('TEAMS_SYNC_LOOKBACK_DAYS', 14)
const MAX_MEETINGS_PER_USER = positiveIntegerEnv('TEAMS_SYNC_MAX_MEETINGS_PER_USER', 20)

const PUBLIC_EMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'outlook.com', 'outlook.fr',
  'hotmail.com', 'hotmail.fr', 'live.com', 'live.fr', 'msn.com',
  'icloud.com', 'me.com', 'yahoo.com', 'yahoo.fr', 'proton.me', 'protonmail.com',
  'orange.fr', 'wanadoo.fr', 'free.fr', 'sfr.fr', 'laposte.net',
  'gmx.com', 'gmx.fr', 'aol.com', 'mac.com',
  'avocat.com', 'avocat.fr',
])

function cleanEmail(value: string | null | undefined): string {
  return String(value ?? '').trim().toLowerCase()
}

function corporateDomain(email: string): string | null {
  const domain = cleanEmail(email).split('@')[1] ?? ''
  return domain && !PUBLIC_EMAIL_DOMAINS.has(domain) ? domain : null
}

function companyNameFromDomain(domain: string): string {
  const base = domain.split('.')[0] ?? domain
  return base.split(/[-_]+/).filter(Boolean).map((part) => part.charAt(0).toUpperCase() + part.slice(1)).join(' ') || domain
}

/** Voir app_secrets, section "pourquoi pas des variables d'environnement" dans connect-teams. */
async function appSecret(supabase: ReturnType<typeof createClient>, name: string): Promise<string | null> {
  const { data } = await supabase.from('app_secrets').select('value').eq('name', name).maybeSingle()
  return (data as { value?: string } | null)?.value ?? null
}

// ⚠️ Ce token délégué a été émis pour l'app de login existante (« Tohu Bohu »,
// MICROSOFT_CLIENT_ID/SECRET déjà utilisés par sync-email-analysis) — surtout pas
// les credentials de la nouvelle app Teams (TEAMS_SYNC_*), qui n'ont aucun lien
// avec ce token et feraient échouer le rafraîchissement.
async function refreshDelegatedToken(refreshToken: string): Promise<{ accessToken: string; refreshToken: string; expiresIn: number }> {
  const clientId = Deno.env.get('MICROSOFT_CLIENT_ID')
  const clientSecret = Deno.env.get('MICROSOFT_CLIENT_SECRET')
  if (!clientId || !clientSecret) throw new Error('Secrets OAuth microsoft (login) manquants')
  const response = await fetch('https://login.microsoftonline.com/common/oauth2/v2.0/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      client_id: clientId, client_secret: clientSecret, refresh_token: refreshToken, grant_type: 'refresh_token',
      scope: 'openid profile email offline_access User.Read Mail.Read Calendars.Read',
    }),
  })
  if (!response.ok) throw new Error(`Rafraîchissement microsoft refusé (${response.status})`)
  const data = await response.json()
  return { accessToken: data.access_token, refreshToken: data.refresh_token ?? refreshToken, expiresIn: Number(data.expires_in ?? 3600) }
}

/** Jeton "app-only" (client_credentials) scopé au tenant du client — c'est celui-ci,
 *  pas un jeton utilisateur, qui autorise la lecture des transcripts (permission
 *  Application consentie par l'admin du client via connect-teams). */
async function appOnlyToken(tenantId: string, clientId: string, clientSecret: string): Promise<string> {
  const response = await fetch(`https://login.microsoftonline.com/${tenantId}/oauth2/v2.0/token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      client_id: clientId, client_secret: clientSecret, grant_type: 'client_credentials', scope: 'https://graph.microsoft.com/.default',
    }),
  })
  if (!response.ok) throw new Error(`Jeton app-only Microsoft refusé (${response.status}) — vérifier le consentement admin du tenant client`)
  const data = await response.json()
  return data.access_token
}

type TeamsCalendarEvent = { subject: string; startMs: number; endMs: number | null; joinUrl: string; attendees: Array<{ email: string; displayName: string | null }> }

async function teamsLinkedCalendarEvents(delegatedToken: string, sinceIso: string): Promise<TeamsCalendarEvent[]> {
  const select = 'subject,start,end,isOnlineMeeting,onlineMeetingProvider,onlineMeeting,attendees'
  const filter = `isOnlineMeeting eq true and onlineMeetingProvider eq 'teamsForBusiness' and start/dateTime ge '${sinceIso}'`
  let nextUrl: string | null = `https://graph.microsoft.com/v1.0/me/events?$select=${select}&$filter=${encodeURIComponent(filter)}&$top=50`
  const results: TeamsCalendarEvent[] = []
  while (nextUrl) {
    const response = await fetch(nextUrl, { headers: { Authorization: `Bearer ${delegatedToken}` } })
    if (!response.ok) throw new Error(`Microsoft Graph (calendrier) ${response.status}`)
    const page = await response.json()
    for (const item of (page.value ?? []) as any[]) {
      const joinUrl = item.onlineMeeting?.joinUrl
      const startMs = item.start?.dateTime ? new Date(`${item.start.dateTime}Z`).getTime() : null
      if (!joinUrl || !startMs) continue
      results.push({
        subject: item.subject ?? 'Réunion Teams',
        startMs, endMs: item.end?.dateTime ? new Date(`${item.end.dateTime}Z`).getTime() : null,
        joinUrl,
        attendees: ((item.attendees ?? []) as any[]).map((attendee) => ({
          email: cleanEmail(attendee.emailAddress?.address), displayName: attendee.emailAddress?.name ?? null,
        })).filter((attendee) => attendee.email),
      })
    }
    nextUrl = page['@odata.nextLink'] ?? null
  }
  return results.slice(0, MAX_MEETINGS_PER_USER)
}

/** Résout l'ID de réunion Teams à partir de son lien de participation — l'API Graph
 *  ne relie pas directement un événement Calendar à une ressource onlineMeeting. */
async function resolveOnlineMeetingId(appToken: string, userEmail: string, joinUrl: string): Promise<string | null> {
  const filter = `JoinWebUrl eq '${joinUrl.replace(/'/g, "''")}'`
  const response = await fetch(`https://graph.microsoft.com/v1.0/users/${encodeURIComponent(userEmail)}/onlineMeetings?$filter=${encodeURIComponent(filter)}`, {
    headers: { Authorization: `Bearer ${appToken}` },
  })
  if (!response.ok) return null
  const data = await response.json()
  return data.value?.[0]?.id ?? null
}

async function listTranscripts(appToken: string, userEmail: string, meetingId: string): Promise<Array<{ id: string }>> {
  const response = await fetch(`https://graph.microsoft.com/v1.0/users/${encodeURIComponent(userEmail)}/onlineMeetings/${meetingId}/transcripts`, {
    headers: { Authorization: `Bearer ${appToken}` },
  })
  if (!response.ok) return []
  const data = await response.json()
  return data.value ?? []
}

async function fetchTranscriptVtt(appToken: string, userEmail: string, meetingId: string, transcriptId: string): Promise<string | null> {
  const response = await fetch(`https://graph.microsoft.com/v1.0/users/${encodeURIComponent(userEmail)}/onlineMeetings/${meetingId}/transcripts/${transcriptId}/content?$format=text/vtt`, {
    headers: { Authorization: `Bearer ${appToken}` },
  })
  if (!response.ok) return null
  return await response.text()
}

/** Parseur WebVTT minimal : Teams encode le locuteur en tag <v Nom>texte</v> à
 *  l'intérieur de chaque cue. Format à valider contre un vrai transcript Teams. */
function parseVtt(vtt: string): Array<{ speaker: string; text: string; startMs: number }> {
  const timeToMs = (value: string): number => {
    const match = value.match(/(\d+):(\d{2}):(\d{2})\.(\d{3})/)
    if (!match) return 0
    const [, h, m, s, ms] = match
    return (Number(h) * 3600 + Number(m) * 60 + Number(s)) * 1000 + Number(ms)
  }
  const blocks = vtt.replace(/\r\n/g, '\n').split(/\n\n+/)
  const entries: Array<{ speaker: string; text: string; startMs: number }> = []
  for (const block of blocks) {
    const lines = block.split('\n').filter(Boolean)
    const timingLine = lines.find((line) => line.includes('-->'))
    if (!timingLine) continue
    const startMs = timeToMs(timingLine.split('-->')[0]?.trim() ?? '')
    const textLines = lines.slice(lines.indexOf(timingLine) + 1).join(' ')
    const speakerMatch = textLines.match(/<v\s+([^>]+)>/)
    const speaker = speakerMatch?.[1]?.trim() ?? 'Participant'
    const text = textLines.replace(/<v\s+[^>]+>/g, '').replace(/<\/v>/g, '').trim()
    if (text) entries.push({ speaker, text, startMs })
  }
  return entries
}

Deno.serve(async (request) => {
  if (request.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
  const startedAt = new Date().toISOString()
  let syncJobId: string | null = null
  try {
    const authorization = request.headers.get('Authorization')
    if (!authorization) return json({ error: 'Authentification requise' }, 401)
    const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')
    const { data: { user }, error: userError } = await supabase.auth.getUser(authorization.replace('Bearer ', ''))
    if (userError || !user) return json({ error: 'Session invalide' }, 401)
    const { organizationId } = await request.json().catch(() => ({}))
    if (!organizationId) return json({ error: 'Paramètres invalides' }, 400)
    const { data: membership } = await supabase.from('memberships').select('id').eq('organization_id', organizationId).eq('user_id', user.id).maybeSingle()
    if (!membership) return json({ error: 'Accès refusé' }, 403)

    const { data: teamsConnector } = await supabase.from('connectors').select('id,metadata').eq('organization_id', organizationId).eq('provider', 'teams').eq('status', 'connected').maybeSingle()
    const tenantId = (teamsConnector?.metadata as any)?.tenant_id as string | undefined
    if (!teamsConnector || !tenantId) return json({ error: 'Teams non connecté pour cette organisation. Un admin Microsoft 365 doit d’abord cliquer « Connecter Teams ».' }, 404)

    const clientId = await appSecret(supabase, 'teams_sync_client_id')
    const clientSecret = await appSecret(supabase, 'teams_sync_client_secret')
    if (!clientId || !clientSecret) return json({ error: 'Secrets Teams non configurés (teams_sync_client_id / teams_sync_client_secret dans app_secrets)' }, 500)

    const { data: job } = await supabase.from('sync_jobs').insert({
      organization_id: organizationId, connector_id: teamsConnector.id, user_id: user.id, provider: 'teams',
      job_type: 'teams_meeting_sync', status: 'running', current_step: 'Obtention du jeton applicatif', progress: 10, started_at: startedAt, payload: {},
    }).select('id').single()
    syncJobId = job?.id ?? null

    const appToken = await appOnlyToken(tenantId, clientId, clientSecret)

    // Les réunions à chercher sont celles des utilisateurs déjà connectés à Outlook
    // dans cette org (mêmes personnes qui ont déjà autorisé Calendars.Read en délégué) —
    // c'est la seule façon de savoir QUELLES réunions un jeton app-only doit chercher.
    const { data: microsoftConnectors } = await supabase.from('connectors').select('id,metadata').eq('organization_id', organizationId).eq('provider', 'microsoft').eq('status', 'connected')
    if (syncJobId) await supabase.from('sync_jobs').update({ current_step: 'Lecture des calendriers Outlook connectés', progress: 30 }).eq('id', syncJobId)

    const sinceIso = new Date(Date.now() - LOOKBACK_DAYS * 86_400_000).toISOString()
    let meetingsSynced = 0
    let transcriptsSynced = 0
    let participantsMatched = 0
    const errors: string[] = []

    for (const msConnector of microsoftConnectors ?? []) {
      try {
        const userEmail = (msConnector.metadata as any)?.account_email as string | undefined
        if (!userEmail) continue
        const { data: tokenRows } = await supabase.rpc('get_oauth_tokens_server', { p_connector_id: msConnector.id })
        const oauth = tokenRows?.[0]
        if (!oauth?.refresh_token) continue
        // Le token délégué sert uniquement à découvrir les réunions via le calendrier
        // de l'utilisateur — il ne donne jamais accès aux transcripts (ça, c'est le rôle
        // du jeton app-only ci-dessus, consenti par l'admin du tenant client).
        let delegatedToken = oauth.access_token as string | null
        const expiresSoon = !oauth.expires_at || new Date(oauth.expires_at).getTime() < Date.now() + 90_000
        if (!delegatedToken || expiresSoon) {
          const refreshed = await refreshDelegatedToken(oauth.refresh_token)
          delegatedToken = refreshed.accessToken
          await supabase.rpc('store_oauth_tokens_server', { p_organization_id: organizationId, p_connector_id: msConnector.id, p_provider_account_id: oauth.provider_account_id, p_access_token: refreshed.accessToken, p_refresh_token: refreshed.refreshToken, p_expires_at: new Date(Date.now() + refreshed.expiresIn * 1000).toISOString() })
        }
        const events = await teamsLinkedCalendarEvents(delegatedToken, sinceIso)

        for (const event of events) {
          try {
            const externalAttendees = event.attendees.filter((attendee) => attendee.email !== userEmail)
            let companyId: string | null = null
            const primaryAttendee = externalAttendees[0] ?? null
            if (primaryAttendee) {
              const domain = corporateDomain(primaryAttendee.email)
              if (domain) {
                const { data: company } = await supabase.rpc('resolve_company_identity', {
                  p_organization_id: organizationId, p_name: companyNameFromDomain(domain), p_domain: domain, p_industry: null, p_create_if_missing: true,
                }).maybeSingle()
                companyId = company?.company_id ?? null
              }
            }

            const externalEventId = `teams:${event.joinUrl}`
            const { data: meetingRow, error: meetingError } = await supabase.from('meetings').upsert({
              organization_id: organizationId, owner_user_id: user.id, company_id: companyId,
              external_event_id: externalEventId, title: event.subject,
              starts_at: new Date(event.startMs).toISOString(), ends_at: event.endMs ? new Date(event.endMs).toISOString() : null,
              platform: 'teams', raw_payload: { joinUrl: event.joinUrl },
            }, { onConflict: 'organization_id,external_event_id' }).select('id').single()
            if (meetingError || !meetingRow) throw meetingError ?? new Error('Réunion non enregistrée')
            meetingsSynced++

            for (const attendee of externalAttendees) {
              const { data: resolved } = await supabase.rpc('resolve_contact_identity', {
                p_organization_id: organizationId, p_email: attendee.email, p_full_name: attendee.displayName ?? attendee.email,
                p_company_id: companyId, p_owner_user_id: user.id, p_role_title: null, p_source: 'teams',
              }).maybeSingle()
              const { error: participantError } = await supabase.from('meeting_participants').upsert({
                organization_id: organizationId, meeting_id: meetingRow.id, contact_id: resolved?.contact_id ?? null,
                email: attendee.email, display_name: attendee.displayName, name: attendee.displayName,
                role_in_meeting: 'attendee', is_current_user: false,
              }, { onConflict: 'meeting_id,email' })
              if (!participantError) participantsMatched++
            }

            const onlineMeetingId = await resolveOnlineMeetingId(appToken, userEmail, event.joinUrl)
            if (!onlineMeetingId) continue
            const transcripts = await listTranscripts(appToken, userEmail, onlineMeetingId)
            if (!transcripts.length) continue

            const allEntries: Array<{ speaker: string; text: string; startMs: number }> = []
            for (const transcript of transcripts) {
              const vtt = await fetchTranscriptVtt(appToken, userEmail, onlineMeetingId, transcript.id)
              if (vtt) allEntries.push(...parseVtt(vtt))
            }
            if (!allEntries.length) continue
            allEntries.sort((a, b) => a.startMs - b.startMs)
            const speakerMap: Record<string, string> = {}
            for (const entry of allEntries) speakerMap[entry.speaker] = entry.speaker
            const transcriptText = allEntries.map((entry) => {
              const totalSeconds = Math.floor(entry.startMs / 1000)
              const time = `${String(Math.floor(totalSeconds / 60)).padStart(2, '0')}:${String(totalSeconds % 60).padStart(2, '0')}`
              return `${entry.speaker} (${time}) : ${entry.text}`
            }).join('\n')

            const { error: transcriptError } = await supabase.from('meeting_transcripts').upsert({
              organization_id: organizationId, meeting_id: meetingRow.id, provider: 'teams',
              transcript_text: transcriptText, speaker_map: speakerMap,
              // Comme Meet, Teams affiche un bandeau de consentement à tous les
              // participants dès que la transcription démarre.
              consent_status: 'granted',
            }, { onConflict: 'meeting_id,provider' })
            if (transcriptError) throw transcriptError
            transcriptsSynced++
          } catch (eventError) {
            errors.push(eventError instanceof Error ? eventError.message : String(eventError))
          }
        }
      } catch (userError) {
        errors.push(userError instanceof Error ? userError.message : String(userError))
      }
    }

    if (syncJobId) await supabase.from('sync_jobs').update({ current_step: 'Synchronisation terminée', progress: 100, status: 'succeeded', completed_at: new Date().toISOString(), payload: { meetings: meetingsSynced, transcripts: transcriptsSynced, errors: errors.slice(0, 5) } }).eq('id', syncJobId)
    return json({ success: true, meetings: meetingsSynced, transcripts: transcriptsSynced, participantsMatched, errors: errors.slice(0, 5) })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Synchronisation impossible'
    if (syncJobId) {
      const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')
      await supabase.from('sync_jobs').update({ status: 'failed', current_step: 'Échec de la synchronisation', error_code: 'TEAMS_SYNC_FAILED', error_message: message, completed_at: new Date().toISOString() }).eq('id', syncJobId)
    }
    return json({ error: message }, 500)
  }
})

// Endpoint de vérification manuelle pour supabase/functions/_shared/enrichment-agent.ts
// (remplacement de l'agent n8n). Protégé par le même secret que les crons internes.
// Ne touche aucune donnée réelle (contacts/companies) — sujet de test fourni par l'appelant.
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { runEnrichmentAgentThrottled } from '../_shared/enrichment-agent.ts';

Deno.serve(async (req) => {
  if (req.method !== 'POST') return new Response('Method not allowed', { status: 405 });
  const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '');

  const cronHeader = req.headers.get('x-cron-secret');
  const { data: sec } = await supabase.from('app_secrets').select('value').eq('name', 'monitor_cron').maybeSingle();
  if (!cronHeader || !sec?.value || sec.value !== cronHeader) {
    return new Response(JSON.stringify({ error: 'unauthorized' }), { status: 403, headers: { 'Content-Type': 'application/json' } });
  }

  const body = await req.json().catch(() => ({}));
  const startedAt = Date.now();
  try {
    const result = await runEnrichmentAgentThrottled(supabase, {
      entityType: 'person',
      fullName: body.fullName ?? 'Satya Nadella',
      email: body.email ?? '',
      company: body.company ?? 'Microsoft',
      domain: body.domain ?? 'microsoft.com',
      linkedinUrl: '', knownLinkedinUrl: '',
      tier: body.tier ?? 'B',
      domainType: body.domainType ?? 'megacorp',
      sourceHints: null, companyContext: null, skipCompanyResearch: false,
      nameLooksLikePlaceholder: body.nameLooksLikePlaceholder ?? false,
      alreadyKnown: {},
    });
    return new Response(JSON.stringify({ ok: true, ms: Date.now() - startedAt, result }, null, 2), { headers: { 'Content-Type': 'application/json' } });
  } catch (err) {
    return new Response(JSON.stringify({ ok: false, ms: Date.now() - startedAt, error: err instanceof Error ? err.message : String(err) }, null, 2), { status: 500, headers: { 'Content-Type': 'application/json' } });
  }
});

// Agent de recherche B2B (personne/société) — remplace le workflow n8n
// "Tohu-Bohu — Enrichissement IA (OpenRouter + Perplexity)".
//
// Le node "AI Agent" de n8n n'était qu'une boucle ReAct standard (le LLM décide
// d'appeler l'outil de recherche, reçoit le résultat, décide de continuer ou de
// conclure) tournant sur une instance à mémoire partagée et fragile : un pic sur
// UNE exécution pouvait faire crasher toutes les autres en vol. Cette version
// reproduit fidèlement le même prompt système et le même budget de recherche,
// mais en appels directs (chaque invocation d'Edge Function est isolée — plus de
// mémoire partagée à faire tomber) et avec une sortie structurée forcée via
// tool-calling natif (plus fiable qu'un output parser qui "répare" du JSON après
// coup). La vraie protection de charge est le sémaphore global
// (acquire_enrichment_slot / release_enrichment_slot, cf. migration
// 20260724120000_enrichment_slots.sql) — appelé par le code qui invoque cet agent.

import type { SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2';

const OPENROUTER_API = 'https://openrouter.ai/api/v1/chat/completions';
const OPENROUTER_MODEL = 'anthropic/claude-haiku-4.5';
const PERPLEXITY_API = 'https://api.perplexity.ai/chat/completions';
const PERPLEXITY_MODEL = 'sonar';
const MAX_ITERATIONS = 6;
const CALL_TIMEOUT_MS = 30000;
const SLOT_ACQUIRE_TIMEOUT_MS = 60000;
const SLOT_POLL_INTERVAL_MS = 1200;

export type EnrichmentInput = {
  entityType: string;
  fullName: string;
  email: string;
  company: string;
  domain: string;
  linkedinUrl: string;
  knownLinkedinUrl: string;
  tier: string;
  domainType: string;
  sourceHints: string | null;
  companyContext: string | null;
  skipCompanyResearch: boolean;
  alreadyKnown: unknown;
  /** Le nom actuel est un pseudo/local-part d'email (ex. "Fxravet81"), pas un vrai
   *  nom — priorité absolue à la recherche du vrai prénom/nom avant tout le reste. */
  nameLooksLikePlaceholder: boolean;
};

export type EnrichmentProfile = {
  entityType?: string;
  fullName?: string;
  fullNameConfidence?: 'confirmed' | 'to_confirm';
  currentRole?: string | null;
  currentCompany?: string | null;
  roleConfidence?: 'confirmed' | 'to_confirm';
  roleStartedAt?: string | null;
  seniority?: string | null;
  linkedinUrl?: string | null;
  location?: string | null;
  summary?: string | null;
  recentActivity?: Array<{ title: string; date?: string | null; source?: string | null; url?: string | null }>;
  company?: {
    name?: string | null; domain?: string | null; industry?: string | null; size?: string | null; hq?: string | null;
    description?: string | null;
    recentNews?: Array<{ title: string; date?: string | null; source?: string | null; url?: string | null }>;
  } | null;
  relatedPeople?: Array<{ name: string; role?: string | null; why?: string | null }>;
  talkingPoints?: string[];
  sources?: string[];
  confidence?: number;
};

const SYSTEM_PROMPT = `Tu es un analyste de recherche B2B senior pour un CRM relationnel (Tohu-Bohu). Objectif : un profil enrichi PRÉCIS, PROFOND et ACTIONNABLE sur une personne ou une société, à partir de recherches web réelles — au budget de recherche le plus serré possible.

LANGUE DE SORTIE (IMPÉRATIF) : RÉDIGE TOUS les champs textuels EN FRANÇAIS — summary, description, talkingPoints, recentActivity[].title, company.description, company.recentNews[].title, relatedPeople[].role et relatedPeople[].why, etc. MÊME si les sources web sont en anglais, TRADUIS et reformule en français naturel et professionnel. Ne laisse JAMAIS une phrase en anglais. Conserve uniquement en l'état : noms propres, raisons sociales, intitulés de poste usuels (ex. « CEO »), URLs et noms de sources.

BUDGET DE RECHERCHE (IMPÉRATIF — chaque appel à l'outil "web_search" a un coût réel) :
- Palier A (recherche complète) : 2 à 3 appels MAXIMUM. 1 sur la personne/LinkedIn, 1 optionnel sur son actualité récente, 1 optionnel sur l'entreprise UNIQUEMENT si aucun "CONTEXTE ENTREPRISE DÉJÀ CONNU" n'est fourni ci-dessus.
- Palier B (vérification légère) : 1 SEUL appel maximum, ciblé sur "y a-t-il un changement de poste ou une actualité récente" — pas de recherche exhaustive.
- Si un CONTEXTE ENTREPRISE DÉJÀ CONNU est fourni, N'INTERROGE PAS l'outil sur l'entreprise elle-même — réutilise ce contexte tel quel dans le champ "company".
- N'effectue JAMAIS plus d'appels que ce budget. Si l'information n'est pas trouvée dans ce budget, renseigne "to_confirm" ou null plutôt que de continuer à chercher.

RÉSOLUTION DU VRAI NOM (impératif quand le message signale "NOM ACTUEL PROBABLEMENT UN PSEUDO") : un nom dérivé d'un email (ex. "Fxravet81", "jdupont42") n'est PAS un vrai nom. Dans ce cas, ta priorité n°1 pour le premier appel "web_search" est de trouver le vrai prénom et nom de famille (LinkedIn en priorité, puis web). Renseigne le résultat dans "fullName" avec "fullNameConfidence" :
- "confirmed" seulement si LinkedIn nominatif clair ou DEUX sources concordent sur le même prénom/nom.
- "to_confirm" si une seule source, plausible mais non recoupée.
- Si rien trouvé, renvoie "fullName" EXACTEMENT identique à la valeur donnée dans "Nom :" ci-dessous (recopie-la telle quelle, ne la restructure PAS) et "fullNameConfidence" à "to_confirm" — n'invente jamais un nom, et ne prends JAMAIS le nom de la société ou du domaine pour un nom de famille.
FORMAT DU CHAMP "fullName" (uniquement quand un vrai prénom ET nom de famille de la PERSONNE ont été trouvés) : prénom en minuscules, NOM DE FAMILLE EN MAJUSCULES, dans cet ordre — ex. "françois-xavier RAVET", "julie MARTIN".

ROUTAGE DES SOURCES : suis STRICTEMENT les "SOURCES PRIORITAIRES POUR CE DOMAINE" transmises dans le message plutôt que d'improviser — ce routage est déjà déterminé (registre légal pour une entreprise française, Crunchbase pour une startup, etc.).

ANTI-HOMONYMES (important) : le domaine email de la personne PROUVE son appartenance à l'organisation citée. Ignore tout résultat concernant un homonyme sans lien avéré avec cette organisation.

ANTI-RÉPÉTITION (important) : les blocs "DÉJÀ CONNU" listent ce que l'utilisateur a déjà. NE les répète PAS tel quel. Apporte du NOUVEAU, du plus récent, ou comble les manques. Si rien de neuf, ne réinvente rien.

DOCTRINE ZÉRO-HALLUCINATION (impératif) :
- N'invente JAMAIS une donnée (poste, tél, taille, email). Non vérifiable → null, roleConfidence="to_confirm".
- Poste actuel affirmé (roleConfidence="confirmed") seulement si DEUX sources concordent, ou si le contexte entreprise déjà connu le confirme. Sinon "to_confirm".
- Cite les URLs réelles dans "sources". Préfère sources primaires : LinkedIn, site officiel, presse éco, registres.

SORTIE : appelle l'outil "emit_profile" une seule fois, avec TOUS LES TEXTES EN FRANÇAIS. talkingPoints = 2-4 angles concrets et personnalisés (en français) pour engager la relation maintenant. recentActivity = faits datés avec source (titres en français). relatedPeople = personnes pertinentes de l'entreprise, uniquement si palier A et pertinent, avec un 'why' actionnable en français.`;

