}

const EFFECTIF_LABELS: Record<string, string> = {
  NN: 'Non renseigné', '00': '0 salarié', '01': '1 à 2 salariés', '02': '3 à 5 salariés',
  '03': '6 à 9 salariés', '11': '10 à 19 salariés', '12': '20 à 49 salariés', '21': '50 à 99 salariés',
