  '41': '500 à 999 salariés', '42': '1 000 à 1 999 salariés', '51': '2 000 à 4 999 salariés',
  '52': '5 000 à 9 999 salariés', '53': '10 000 salariés et plus',
}

// Rôle INPI (RNE) → libellé lisible. L'INPI ne publie pas ce référentiel ; calibré
// sur des réponses réelles. Code inconnu → nom affiché sans titre.
const ROLE_LABELS: Record<string, string> = {
  '4': 'Directeur général unique', '5': 'Président', '23': 'Associé gérant', '29': 'Gérant', '30': 'Gérant',
  '40': 'Président du directoire', '41': 'Membre du directoire', '42': 'Président du conseil de surveillance',
  '51': 'Président', '52': 'Président du directoire', '53': 'Directeur général', '60': 'Président-directeur général',
  '61': 'Directeur général délégué', '62': 'Directeur général délégué', '65': 'Administrateur', '66': 'Vice-président',
  '70': 'Représentant permanent',
}
const EXECUTIVE_ROLE_CODES = new Set(['4', '5', '23', '29', '30', '40', '51', '52', '53', '60', '61', '62', '65'])
const MAX_DIRIGEANTS = 6

function fetchWithTimeout(url: string, init?: RequestInit) {
  return fetch(url, { ...init, signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS) })
}

type Dirigeant = { name: string; role: string | null }

async function fetchInseeUnit(siren: string, apiKey: string): Promise<{ legalFormLabel: string | null; nafCode: string | null; employeeRange: string | null } | null> {
  const response = await fetchWithTimeout(`${INSEE_BASE_URL}/siren/${encodeURIComponent(siren)}`, {
    headers: { 'X-INSEE-Api-Key-Integration': apiKey, Accept: 'application/json' },
  })
  if (!response.ok) return null
  const payload = await response.json().catch(() => null) as Record<string, unknown> | null
  const unit = (payload?.uniteLegale ?? null) as Record<string, unknown> | null
  if (!unit) return null
  const periods = Array.isArray(unit.periodesUniteLegale) ? unit.periodesUniteLegale as Array<Record<string, unknown>> : []
  const current = periods.find((period) => period.dateFin === null) ?? periods[0] ?? {}
  const categorieCode = typeof unit.categorieJuridiqueUniteLegale === 'string' ? unit.categorieJuridiqueUniteLegale : null
  const nafCode = typeof current.activitePrincipaleUniteLegale === 'string' ? current.activitePrincipaleUniteLegale : null
  const effectifCode = typeof unit.trancheEffectifsUniteLegale === 'string' ? unit.trancheEffectifsUniteLegale : null
  return {
    legalFormLabel: categorieCode ? (CATEGORIE_JURIDIQUE_LABELS[categorieCode] ?? categorieCode) : null,
    nafCode,
    employeeRange: effectifCode ? (EFFECTIF_LABELS[effectifCode] ?? effectifCode) : null,
  }
}

async function inpiLogin(username: string, password: string): Promise<string | null> {
  const response = await fetchWithTimeout(`${INPI_BASE_URL}/api/sso/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
    body: JSON.stringify({ username, password }),
  })
  if (!response.ok) return null
  const payload = await response.json().catch(() => null) as Record<string, unknown> | null
  return typeof payload?.token === 'string' ? payload.token : null
}

function readString(value: unknown): string | null {
  return typeof value === 'string' && value.trim().length > 0 ? value.trim() : null
}
function asRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : null
}
function asArray(value: unknown): unknown[] {
  return Array.isArray(value) ? value : []
}

function mapIndividu(description: Record<string, unknown>, roleCode: string | null): Dirigeant | null {
  const nom = readString(description.nomUsage) ?? readString(description.nom)
  const prenomsRaw = description.prenoms
  const prenoms = Array.isArray(prenomsRaw) ? readString(prenomsRaw.map((entry) => readString(entry) ?? '').join(' ')) : readString(prenomsRaw)
  const name = [nom, prenoms].filter(Boolean).join(' ').trim()
  if (!name) return null
  const code = roleCode ?? readString(description.role)
  return { name, role: code ? (ROLE_LABELS[code] ?? null) : null }
}

function extractDirigeants(company: unknown): Dirigeant[] {
  const root = asRecord(company)
  if (!root) return []
  const formality = asRecord(root.formality) ?? asRecord(asArray(root.formalities)[0]) ?? root
  const content = asRecord(formality.content) ?? asRecord(root.content)
  if (!content) return []
  const personneMorale = asRecord(content.personneMorale)
  const personnePhysique = asRecord(content.personnePhysique)

  const pouvoirs: unknown[] = []
  if (personneMorale) {
    const composition = asRecord(personneMorale.composition)
    pouvoirs.push(...asArray(composition?.pouvoirs))
    pouvoirs.push(...asArray(personneMorale.pouvoirs))
  }

  const dirigeants: Dirigeant[] = []
  for (const pouvoirRaw of pouvoirs) {
    const record = asRecord(pouvoirRaw)
    if (!record || record.actif === false) continue
    const pouvoirRole = readString(record.roleEntreprise)
    const individu = asRecord(record.individu)
    if (individu) {
      const description = asRecord(individu.descriptionPersonne)
      const mapped = description ? mapIndividu(description, pouvoirRole) : null
      if (mapped) dirigeants.push(mapped)
    }
    const entreprise = asRecord(record.entreprise)
    if (entreprise) {
      const denomination = readString(entreprise.denomination) ?? readString(entreprise.nom)
      if (denomination) {
        const code = readString(entreprise.roleEntreprise) ?? pouvoirRole
        dirigeants.push({ name: denomination, role: code ? (ROLE_LABELS[code] ?? null) : null })
      }
    }
  }

  if (dirigeants.length === 0 && personnePhysique) {
    const identite = asRecord(personnePhysique.identite)
    const description = asRecord(asRecord(identite?.entrepreneur)?.descriptionPersonne)
      ?? asRecord(asRecord(identite?.entreprise)?.descriptionPersonne)
    if (description) {
      const mapped = mapIndividu(description, null)
      if (mapped) dirigeants.push(mapped)
    }
  }

  const seen = new Set<string>()
  const unique = dirigeants.filter((item) => {
    const key = item.name.toLowerCase()
    if (seen.has(key)) return false
    seen.add(key)
    return true
  })
  const isExecutive = (item: Dirigeant) => Object.entries(ROLE_LABELS).some(([code, label]) => label === item.role && EXECUTIVE_ROLE_CODES.has(code))
  return [...unique.filter(isExecutive), ...unique.filter((item) => !isExecutive(item))].slice(0, MAX_DIRIGEANTS)
}

async function fetchInpiDirigeants(siren: string, username: string, password: string): Promise<Dirigeant[]> {
  const token = await inpiLogin(username, password)
  if (!token) return []
  const response = await fetchWithTimeout(`${INPI_BASE_URL}/api/companies/${encodeURIComponent(siren)}`, {
    headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' },
  })
  if (!response.ok) return []
  const payload = await response.json().catch(() => null)
  const company = Array.isArray(payload) ? payload[0] : payload
  return extractDirigeants(company)
}

function formatDirigeants(dirigeants: Dirigeant[]): string | null {
  if (dirigeants.length === 0) return null
  return dirigeants.map((item) => (item.role ? `${item.name} — ${item.role}` : item.name)).join(' ; ')
}

Deno.serve(async (request) => {
  if (request.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405)

  const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')
  const authorization = request.headers.get('Authorization')
  if (!authorization) return json({ error: 'Authentification requise' }, 401)
  const { data: { user }, error: userError } = await supabase.auth.getUser(authorization.replace('Bearer ', ''))
  if (userError || !user) return json({ error: 'Session invalide' }, 401)

  const body = await request.json().catch(() => ({} as Record<string, unknown>))
  const organizationId = typeof body.organizationId === 'string' ? body.organizationId : null
  const companyId = typeof body.companyId === 'string' ? body.companyId : null
  const siren = typeof body.siren === 'string' ? body.siren.replace(/\s+/g, '') : null
  if (!organizationId || !companyId) return json({ error: 'Paramètres invalides' }, 400)
  if (!siren || !/^\d{9}$/.test(siren)) return json({ error: 'SIREN invalide — 9 chiffres attendus.' }, 400)

  const { data: membership } = await supabase.from('memberships').select('id').eq('organization_id', organizationId).eq('user_id', user.id).maybeSingle()
  if (!membership) return json({ error: 'Accès refusé' }, 403)

  const inseeKey = Deno.env.get('INSEE_API_KEY')
  const inpiUsername = Deno.env.get('INPI_USERNAME')
  const inpiPassword = Deno.env.get('INPI_PASSWORD')
  if (!inseeKey) return json({ error: 'INSEE_API_KEY non configurée côté serveur.' }, 500)

  const sourceUrl = `https://annuaire-entreprises.data.gouv.fr/entreprise/${siren}`
  const observedAt = new Date().toISOString()
  const facts: Array<{ fact_key: string; value: string; source_label: string }> = [
    { fact_key: 'registration_number', value: siren, source_label: 'INSEE Sirene' },
  ]

  let unitError: string | null = null
  try {
    const unit = await fetchInseeUnit(siren, inseeKey)
    if (unit) {
      if (unit.legalFormLabel) facts.push({ fact_key: 'legal_form', value: unit.legalFormLabel, source_label: 'INSEE Sirene' })
      if (unit.nafCode) facts.push({ fact_key: 'naf_code', value: unit.nafCode, source_label: 'INSEE Sirene' })
      if (unit.employeeRange) facts.push({ fact_key: 'employee_range', value: unit.employeeRange, source_label: 'INSEE Sirene' })
    } else {
      unitError = 'SIREN introuvable dans le répertoire Sirene.'
    }
  } catch (error) {
    unitError = error instanceof Error ? error.message : 'Appel INSEE Sirene impossible.'
  }

  if (inpiUsername && inpiPassword) {
    try {
      const dirigeants = await fetchInpiDirigeants(siren, inpiUsername, inpiPassword)
      const formatted = formatDirigeants(dirigeants)
      if (formatted) facts.push({ fact_key: 'executives', value: formatted, source_label: 'INPI RNE' })
    } catch {
      // Best-effort : l'identité légale INSEE sort quand même sans dirigeants.
    }
  }

  if (facts.length <= 1 && unitError) return json({ error: unitError }, 502)

  const { error: insertError } = await supabase.from('account_firmographic_facts').insert(
    facts.map((fact) => ({
      organization_id: organizationId,
      company_id: companyId,
      fact_key: fact.fact_key,
      value: fact.value,
      source_type: 'api',
      source_id: siren,
      source_label: fact.source_label,
      source_url: sourceUrl,
      observed_at: observedAt,
      imported_at: observedAt,
      last_verified_at: observedAt,
      confidence: 100,
      inference_level: 'observed',
    })),
  )
  if (insertError) return json({ error: insertError.message }, 500)

  await supabase.from('companies').update({ siren }).eq('id', companyId).eq('organization_id', organizationId)

  return json({ ok: true, factsWritten: facts.length, siren })
})

// Phrase de justification mensuelle du score relationnel — générée À LA DEMANDE
// (quand l'utilisateur ouvre l'onglet Relation), jamais dans la boucle cron de
// score-batch : un seul appel IA par mois et par fiche réellement consultée,
// mis en cache dans relationship_score_narratives (unique organisation/sujet/mois).
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
}

function currentMonthKey(): string {
  const now = new Date()
  return `${now.getUTCFullYear()}-${String(now.getUTCMonth() + 1).padStart(2, '0')}`
}

function extractNarrative(value: string): string {
  try {
    const parsed = JSON.parse(value)
    if (typeof parsed.narrative === 'string' && parsed.narrative.trim()) return parsed.narrative.trim()
  } catch {
    // Réponse non structurée : on retombe sur le texte brut ci-dessous.
  }
  const match = value.match(/\{[\s\S]*\}/)
  if (match) {
    try {
      const parsed = JSON.parse(match[0])
      if (typeof parsed.narrative === 'string' && parsed.narrative.trim()) return parsed.narrative.trim()
    } catch { /* voir le repli texte brut ci-dessous */ }
  }
  return value.trim()
}

async function generatePersonNarrative(
  supabase: ReturnType<typeof createClient>,
  organizationId: string,
  contactId: string,
): Promise<string> {
  const [{ data: contact }, { data: snapshots }] = await Promise.all([
    supabase.from('contacts').select('full_name').eq('id', contactId).maybeSingle(),
    supabase.from('person_relationship_score_snapshots')
      .select('score, phase, phase_delta, intensity_score, reciprocity_score, recency_score, longevity_score, relationship_age_days, total_interactions, email_interactions, meeting_interactions, last_interaction_at, computed_at')
      .eq('organization_id', organizationId).eq('contact_id', contactId)
      .order('computed_at', { ascending: false }).limit(6),
  ])
  const latest = snapshots?.[0]
  if (!latest) throw new Error('Aucun score relationnel calculé pour cette personne pour le moment.')
  const previous = snapshots?.[1] ?? null
  const facts = {
    personne: contact?.full_name ?? 'Cette personne',
    score_actuel: latest.score,
    score_precedent: previous?.score ?? null,
    phase: latest.phase,
    variation_pts: latest.phase_delta,
    intensite: latest.intensity_score,
    reciprocite: latest.reciprocity_score,
    recence: latest.recency_score,
    anciennete_jours: latest.relationship_age_days,
    total_echanges: latest.total_interactions,
    emails: latest.email_interactions,
    reunions: latest.meeting_interactions,
    dernier_contact: latest.last_interaction_at,
    calcule_le: latest.computed_at,
  }
  return callNarrativeModel(facts)
}

async function generateAccountNarrative(
  supabase: ReturnType<typeof createClient>,
  organizationId: string,
  companyId: string,
): Promise<string> {
  const [{ data: company }, { data: snapshots }] = await Promise.all([
    supabase.from('companies').select('name').eq('id', companyId).maybeSingle(),
    supabase.from('account_relationship_score_snapshots')
      .select('score, phase, phase_delta, confidence, contact_coverage, decision_maker_coverage, concentration_risk, total_interactions, last_interaction_at, computed_at')
      .eq('organization_id', organizationId).eq('company_id', companyId)
      .order('computed_at', { ascending: false }).limit(6),
  ])
  const latest = snapshots?.[0]
  if (!latest) throw new Error('Aucun score relationnel calculé pour ce compte pour le moment.')
  const previous = snapshots?.[1] ?? null
  const facts = {
    compte: company?.name ?? 'Ce compte',
    score_actuel: latest.score,
    score_precedent: previous?.score ?? null,
    phase: latest.phase,
    variation_pts: latest.phase_delta,
    couverture_contacts_pct: latest.contact_coverage,
    couverture_decideurs_pct: latest.decision_maker_coverage,
    risque_concentration_pct: latest.concentration_risk,
    total_echanges: latest.total_interactions,
    dernier_contact: latest.last_interaction_at,
    calcule_le: latest.computed_at,
  }
  return callNarrativeModel(facts)
}

async function callNarrativeModel(facts: Record<string, unknown>): Promise<string> {
  const apiKey = Deno.env.get('OPENROUTER_API_KEY')
  if (!apiKey) throw new Error('OPENROUTER_API_KEY non configurée')
  const prompt = `Tu rédiges UNE phrase factuelle (français, 25 mots maximum, sans emphase ni superlatif) qui explique l'évolution du score relationnel ce mois-ci, en te basant EXCLUSIVEMENT sur les données ci-dessous. N'invente aucun fait, aucun chiffre, aucune cause qui n'y figure pas explicitement. Si une donnée manque, ne la mentionne pas.

Données :
${JSON.stringify(facts, null, 2)}

Réponds uniquement avec ce JSON strict : {"narrative": "..."}`
  const response = await fetch('https://openrouter.ai/api/v1/chat/completions', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
      'HTTP-Referer': Deno.env.get('SITE_URL') ?? 'https://tohu.app',
      'X-Title': 'Tohu Relationship Narrative',
    },
    body: JSON.stringify({
      model: Deno.env.get('OPENROUTER_MODEL') ?? 'google/gemini-2.5-flash-lite',
      temperature: 0.2,
      response_format: { type: 'json_object' },
      max_tokens: 200,
      messages: [{ role: 'user', content: prompt }],
    }),
  })
  if (!response.ok) throw new Error(`OpenRouter ${response.status}`)
  const data = await response.json()
  return extractNarrative(String(data.choices?.[0]?.message?.content ?? ''))
}

Deno.serve(async (request) => {
  if (request.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405)

  const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')
  const authorization = request.headers.get('Authorization')
  if (!authorization) return json({ error: 'Authentification requise' }, 401)
  const { data: { user }, error: userError } = await supabase.auth.getUser(authorization.replace('Bearer ', ''))
  if (userError || !user) return json({ error: 'Session invalide' }, 401)

  const body = await request.json().catch(() => ({} as Record<string, unknown>))
  const organizationId = typeof body.organizationId === 'string' ? body.organizationId : null
  const subjectType = body.subjectType === 'account' ? 'account' : body.subjectType === 'person' ? 'person' : null
  const subjectId = typeof body.subjectId === 'string' ? body.subjectId : null
  const monthKey = typeof body.monthKey === 'string' && /^\d{4}-\d{2}$/.test(body.monthKey) ? body.monthKey : currentMonthKey()
  if (!organizationId || !subjectType || !subjectId) return json({ error: 'Paramètres invalides' }, 400)

  const { data: membership } = await supabase.from('memberships').select('id').eq('organization_id', organizationId).eq('user_id', user.id).maybeSingle()
  if (!membership) return json({ error: 'Accès refusé' }, 403)

  const { data: cached } = await supabase.from('relationship_score_narratives')
    .select('narrative, generated_at')
    .eq('organization_id', organizationId).eq('subject_type', subjectType).eq('subject_id', subjectId).eq('month_key', monthKey)
    .maybeSingle()
  if (cached) return json({ narrative: cached.narrative, generatedAt: cached.generated_at, cached: true })

  try {
    const narrative = subjectType === 'person'
      ? await generatePersonNarrative(supabase, organizationId, subjectId)
      : await generateAccountNarrative(supabase, organizationId, subjectId)
    const generatedAt = new Date().toISOString()
    const { error: upsertError } = await supabase.from('relationship_score_narratives').upsert({
      organization_id: organizationId, subject_type: subjectType, subject_id: subjectId, month_key: monthKey,
      narrative, model: Deno.env.get('OPENROUTER_MODEL') ?? 'google/gemini-2.5-flash-lite', generated_at: generatedAt,
    }, { onConflict: 'organization_id,subject_type,subject_id,month_key' })
    if (upsertError) throw upsertError
    return json({ narrative, generatedAt, cached: false })
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : 'Génération impossible' }, 500)
  }
})

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { blockText, notionApi, NotionError, notionPageUrl, NOTION_REAUTH_ERRORS, richText } from '../_shared/notion.ts'
import { analyze, asRecord, attributedTranscriptExcerpt, errorMessage, persistContactProfile } from '../_shared/behavior-analysis.ts'
const headers = { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type', 'Access-Control-Allow-Methods': 'POST, OPTIONS' }
const json = (data: unknown, status = 200) => new Response(JSON.stringify(data), { status, headers: { ...headers, 'Content-Type': 'application/json' } })
const checked = async (query: any) => { const result = await query; if (result.error) throw new Error(result.error.message); return result.data }

async function allBlockText(token: string, rootId: string): Promise<string> {
  const lines: string[] = [], queue = [rootId]
  while (queue.length && lines.join('\n').length < 120000) {
    const id = queue.shift()!, page = await notionApi(token, `/blocks/${id}/children?page_size=100`)
    for (const block of page.results ?? []) {
      const value = blockText(block)
      if (value) lines.push(value)
      if (block.has_children) queue.push(block.id)
    }
    let cursor = page.next_cursor
    while (page.has_more && cursor) {
      const next = await notionApi(token, `/blocks/${id}/children?page_size=100&start_cursor=${encodeURIComponent(cursor)}`)
      for (const block of next.results ?? []) { const value = blockText(block); if (value) lines.push(value); if (block.has_children) queue.push(block.id) }
      cursor = next.next_cursor
      if (!next.has_more) break
    }
  }
  return lines.join('\n').trim()
}

Deno.serve(async req => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers })
  if (req.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
  const db = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!)
  let connector: any, state: any, lease: string | null = null
  try {
    const { data: { user } } = await db.auth.getUser((req.headers.get('Authorization') ?? '').replace('Bearer ', ''))
    if (!user) return json({ error: 'Session invalide' }, 401)
    const { organizationId } = await req.json()
    if (!await checked(db.from('memberships').select('id').eq('organization_id', organizationId).eq('user_id', user.id).maybeSingle())) return json({ error: 'Accès refusé' }, 403)
    connector = await checked(db.from('connectors').select('*').eq('organization_id', organizationId).eq('user_id', user.id).eq('provider', 'notion').single())
    lease = crypto.randomUUID()
    if (!await checked(db.rpc('claim_connector_sync', { p_connector_id: connector.id, p_lease_id: lease }))) { lease = null; return json({ pending: true, retryAfter: 5 }) }
    state = (await checked(db.from('connector_sync_state').select('state').eq('connector_id', connector.id).single())).state ?? {}
    if (state.retryAt > Date.now()) return json({ pending: true, retryAfter: Math.ceil((state.retryAt - Date.now()) / 1000) })
    const oauth = (await checked(db.rpc('get_oauth_tokens_server', { p_connector_id: connector.id })))?.[0]
    if (!oauth?.access_token) throw new NotionError('unauthorized', 401)
    const token = oauth.access_token
    if (!state.phase || state.phase === 'done') {
      const job = await checked(db.from('sync_jobs').insert({ organization_id: organizationId, connector_id: connector.id, user_id: user.id, provider: 'notion', job_type: 'notion_meeting_notes_sync', status: 'running', current_step: 'Lecture des notes de réunion Notion', progress: 5, started_at: new Date().toISOString(), payload: {} }).select('id').single())
      state = { phase: 'query', notes: [], index: 0, count: 0, profilesUpdated: 0, analysisErrors: [], jobId: job.id, watermark: state.watermark ?? null, before: null, newest: state.watermark ?? null }
    }
    if (state.phase === 'query') {
      const filters: any[] = []
      if (state.watermark) filters.push({ property: 'last_edited_time', filter: { operator: 'date_after', value: { type: 'exact', value: state.watermark } } })
      if (state.before) filters.push({ property: 'last_edited_time', filter: { operator: 'date_before', value: { type: 'exact', value: state.before } } })
      const page = await notionApi(token, '/blocks/meeting_notes/query', { method: 'POST', body: JSON.stringify({ limit: 50, sort: [{ property: 'last_edited_time', direction: 'descending' }], ...(filters.length ? { filter: filters.length === 1 ? filters[0] : { operator: 'and', filters } } : {}) }) })
      const fresh = (page.results ?? []).filter((item: any) => !state.notes.some((known: any) => known.id === item.id))
      state.notes.push(...fresh)
      if (!state.newest && fresh[0]?.last_edited_time) state.newest = fresh[0].last_edited_time
      if (page.has_more && fresh.length) state.before = fresh[fresh.length - 1].last_edited_time
      else state.phase = 'process'
    } else if (state.index < state.notes.length) {
      const note = state.notes[state.index], info = note.meeting_notes ?? {}, children = info.children ?? {}
      const sectionIds = [children.summary_block_id, children.notes_block_id, children.transcript_block_id].filter(Boolean)
      const sections: string[] = []
      for (const id of sectionIds) sections.push(await allBlockText(token, id))
      const transcript = sections.filter(Boolean).join('\n\n')
      const title = richText(info.title) || 'Réunion Notion'
      const pageId = note.parent?.page_id ?? note.id
      const sourceUrl = notionPageUrl(pageId)
      const meeting = await checked(db.from('meetings').upsert({ organization_id: organizationId, owner_user_id: user.id, external_event_id: `notion:${note.id}`, title, starts_at: info.calendar_event?.start_time ?? info.recording?.start_time ?? note.created_time, ends_at: info.calendar_event?.end_time ?? info.recording?.end_time ?? null, platform: 'Notion', meeting_type: 'other', raw_payload: { provider: 'notion', block_id: note.id, page_id: pageId, source_url: sourceUrl, status: info.status, workspace_id: connector.metadata.workspace_id, last_edited_time: note.last_edited_time } }, { onConflict: 'organization_id,external_event_id' }).select('id').single())
      await checked(db.from('meeting_transcripts').upsert({ organization_id: organizationId, meeting_id: meeting.id, provider: 'notion', transcript_text: transcript || `[${title}] Notes en cours de génération dans Notion.`, speaker_map: { source_url: sourceUrl, notion_block_id: note.id }, consent_status: 'granted' }, { onConflict: 'meeting_id,provider' }))
      await checked(db.from('meeting_participants').delete().eq('meeting_id', meeting.id))
      const analysable: Array<{ id: string; full_name: string; email: string | null }> = []
      for (const attendeeId of info.calendar_event?.attendees ?? []) {
        const attendee = await notionApi(token, `/users/${attendeeId}`)
        const email = attendee.person?.email?.trim().toLowerCase() ?? null
        let contactId = null
        if (email && attendeeId !== connector.metadata.owner_user_id) {
          const resolved = await checked(db.rpc('resolve_contact_identity', { p_organization_id: organizationId, p_email: email, p_full_name: attendee.name ?? email, p_company_id: null, p_owner_user_id: user.id, p_source: 'notion' }).maybeSingle())
          contactId = resolved?.contact_id ?? null
          if (contactId) {
            const contact = await checked(db.from('contacts').select('id,full_name,email').eq('organization_id', organizationId).eq('id', contactId).single())
            analysable.push(contact)
          }
        }
        await checked(db.from('meeting_participants').insert({ organization_id: organizationId, meeting_id: meeting.id, contact_id: contactId, email, display_name: attendee.name, role_in_meeting: 'participant', is_current_user: attendeeId === connector.metadata.owner_user_id }))
      }
      // Même pipeline que les transcriptions Read AI : analyse uniquement les
      // prises de parole attribuables à un participant rapproché.
      for (const contact of analysable.slice(0, 5)) {
        const excerpt = attributedTranscriptExcerpt(transcript, [contact.full_name, contact.email ?? ''])
        if (!excerpt) continue
        try {
          const [{ count: messageCount }, { count: meetingCount }, { data: previous }] = await Promise.all([
            db.from('communication_messages').select('id', { count: 'exact', head: true }).eq('organization_id', organizationId).eq('contact_id', contact.id).eq('direction', 'inbound'),
            db.from('meeting_participants').select('id', { count: 'exact', head: true }).eq('organization_id', organizationId).eq('contact_id', contact.id),
            db.from('cognitive_profiles').select('cognitive_profile_data,updated_from').eq('organization_id', organizationId).eq('contact_id', contact.id).eq('profile_version', 1).maybeSingle(),
          ])
          const interactions = (messageCount ?? 0) + (meetingCount ?? 0)
          const result = await analyze(contact.full_name, 'contact', [excerpt], asRecord(previous?.cognitive_profile_data), interactions, { client: db, organizationId, userId: user.id })
          await persistContactProfile(db, { organizationId, contactId: contact.id, result, messageCount: messageCount ?? 0, meetingCount: meetingCount ?? 0, interactionCount: interactions, updatedFrom: [...new Set<string>([...(previous?.updated_from ?? []), 'notion', 'meeting_transcript'])], signalSource: 'notion_meeting_notes', sourceRef: sourceUrl, observedAt: info.calendar_event?.start_time ?? note.created_time })
          state.profilesUpdated++
        } catch (error) { state.analysisErrors.push(`${contact.full_name}: ${errorMessage(error)}`) }
      }
      state.index++; state.count++
      if (state.index >= state.notes.length) state.phase = 'done'
    } else state.phase = 'done'
    const complete = state.phase === 'done'
    if (complete && state.newest) state.watermark = state.newest
    state.retryAt = null
    await checked(db.from('connector_sync_state').update({ state }).eq('connector_id', connector.id).eq('lease_id', lease))
    const progress = complete ? 100 : state.phase === 'query' ? 5 : Math.min(95, 10 + Math.floor(state.index / Math.max(1, state.notes.length) * 85))
    await checked(db.from('sync_jobs').update({ status: complete ? 'succeeded' : 'running', current_step: complete ? 'Synchronisation Notion terminée' : 'Import et analyse des notes de réunion Notion', progress, completed_at: complete ? new Date().toISOString() : null, payload: { meetings: state.count, profiles_updated: state.profilesUpdated, analysis_errors: state.analysisErrors.slice(0, 5) } }).eq('id', state.jobId))
    await checked(db.from('connectors').update({ status: 'connected', ...(complete ? { last_synced_at: new Date().toISOString() } : {}), metadata: { ...connector.metadata, last_error: null } }).eq('id', connector.id))
    return json({ success: true, pending: !complete, progress, meetings: state.count, profilesUpdated: state.profilesUpdated })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Synchronisation Notion impossible'
    if (connector && state && error instanceof NotionError && error.retryAfter) { state.retryAt = Date.now() + error.retryAfter * 1000; await db.from('connector_sync_state').update({ state }).eq('connector_id', connector.id); return json({ pending: true, retryAfter: error.retryAfter, progress: 5, meetings: state.count ?? 0, profilesUpdated: state.profilesUpdated ?? 0 }) }
    if (connector) await db.from('connectors').update({ status: error instanceof NotionError && NOTION_REAUTH_ERRORS.includes(error.code) ? 'needs_reauth' : 'error', metadata: { ...connector.metadata, last_error: message } }).eq('id', connector.id)
    if (state?.jobId) await db.from('sync_jobs').update({ status: 'failed', error_message: message, completed_at: new Date().toISOString() }).eq('id', state.jobId)
    return json({ error: message }, 500)
  } finally { if (connector && lease) await db.from('connector_sync_state').update({ lease_until: null, lease_id: null }).eq('connector_id', connector.id).eq('lease_id', lease) }
})

export const NOTION_VERSION = '2026-03-11'

export class NotionError extends Error {
  constructor(public code: string, public status: number, public retryAfter = 0) { super(`Notion : ${code}`) }
}

export async function notionApi(token: string, path: string, init: RequestInit = {}, fetcher: typeof fetch = fetch): Promise<any> {
  const response = await fetcher(`https://api.notion.com/v1${path}`, {
    ...init,
    headers: { Authorization: `Bearer ${token}`, 'Notion-Version': NOTION_VERSION, 'Content-Type': 'application/json', ...(init.headers ?? {}) },
    signal: AbortSignal.timeout(20000),
  })
  if (response.status === 429) throw new NotionError('rate_limited', 429, Math.max(1, Number(response.headers.get('Retry-After')) || 60))
  const data = await response.json().catch(() => ({}))
  if (!response.ok) throw new NotionError(String(data.code ?? `http_${response.status}`), response.status, response.status >= 500 ? 30 : 0)
  return data
}

export function richText(value: any): string {
  return Array.isArray(value) ? value.map(item => String(item?.plain_text ?? item?.text?.content ?? '')).join('').trim() : ''
}

export function blockText(block: any): string {
  const payload = block?.[block?.type]
  return richText(payload?.rich_text ?? payload?.caption)
}

export function notionPageUrl(id: string): string { return `https://www.notion.so/${id.replaceAll('-', '')}` }
export const NOTION_REAUTH_ERRORS = ['unauthorized', 'restricted_resource', 'invalid_request_url']

// Cœur d'analyse comportementale partagé — source unique du "cerveau" Tohu.
//
// Extrait de sync-email-analysis pour être réutilisé sans duplication par
// l'ingestion manuelle de transcripts (ingest-transcript). Contient : le
// contrat de sortie JSON (schema_version 3), l'appel OpenRouter côté serveur
// (`analyze`), les transformations vers `behavioral_signals`, l'attribution
// des lignes de transcript à un locuteur, et l'écriture (upsert) d'un profil
// cognitif de contact (`persistContactProfile`).
//
// Toute évolution du prompt / du schéma se fait ICI et bénéficie aux deux
// chemins (email + transcript) simultanément.
import type { SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { logAiUsage } from './ai-usage.ts'

export type RelationshipAxisResult = {
  status?: string
  score?: number | null
  observation?: string | null
  confidence?: number | null
  evidence?: string[]
}

export type AccountRelationResult = {
  status?: string
  category?: string | null
  observation?: string | null
  confidence?: number | null
  evidence?: string[]
}

export type Analysis = {
  executive_summary?: string
  cognitive_mode?: string
  cognitive_mode_confidence?: number
  global_confidence?: number
  behavioral_analysis_data?: Array<{ trait?: string; observation?: string; confidence?: number }>
  communication_style_data?: Record<string, unknown>
  cognitive_profile_data?: Record<string, unknown>
  // Axes du score relationnel PERSONNE (Confiance/Satisfaction) — distincts du
  // profil de style de communication ci-dessus. Nécessitent une lecture du
  // contenu réel des échanges (pas seulement leurs métadonnées), d'où leur
  // extraction ici plutôt que dans score-batch (pur calcul, sans IA).
  trust?: RelationshipAxisResult
  satisfaction?: RelationshipAxisResult
  // Catégorisation COMPTE (Prospect/Client/Partenaire/Fournisseur/Investisseur) :
  // indice par contact, agrégé au niveau compte par score-batch. Uniquement
  // pertinent pour role="contact" (une seule entreprise externe) — toujours
  // "insufficient" pour role="responsable" (auto-profil interne, multi-comptes).
  account_relation?: AccountRelationResult
}

