  const requestAnalysis = async (retry: boolean): Promise<Analysis> => {
    const response = await fetch('https://openrouter.ai/api/v1/chat/completions', {
      signal,
      method: 'POST',
      headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json', 'HTTP-Referer': Deno.env.get('SITE_URL') ?? 'https://tohu.app', 'X-Title': 'Tohu Email Behavior Analysis' },
      body: JSON.stringify({
        // Modèle dédié à l'analyse comportementale (découplé du chat Ask Tohu).
        // Surchargable via OPENROUTER_ANALYSIS_MODEL sans toucher aux autres fonctions.
        model,
        temperature: retry ? 0 : 0.1,
        response_format: COGNITIVE_PROFILE_RESPONSE_FORMAT,
        // Empêche OpenRouter de choisir un fournisseur qui ignorerait le
        // JSON Schema et retomberait silencieusement sur l'ancien format.
        provider: { require_parameters: true },
        max_tokens: retry ? 7000 : 6000,
        messages: [{
          role: 'user',
          content: retry
            ? `${prompt}\n\nIMPORTANT : la tentative précédente a produit un JSON invalide, tronqué ou dans un ancien schéma. Repars exclusivement du contrat ci-dessus : cognitive_profile_data.schema_version doit valoir 3 et les six primary_axes doivent tous être présents. Réponds de façon compacte, sans Markdown ni commentaire avant ou après l'objet JSON, et ferme impérativement toutes les structures JSON.`
            : prompt,
        }],
      }),
    })
    if (!response.ok) throw new Error(`OpenRouter ${response.status}`)
    const data = await response.json()
    if (usageLog) await logAiUsage(usageLog.client, { organizationId: usageLog.organizationId, userId: usageLog.userId, fn: 'behavior-analysis:analyze', model, usage: data?.usage })
    const content = openRouterContent(data)
    try {
      const result = extractJson(content)
      assertCurrentCognitiveSchema(asRecord(result.cognitive_profile_data))
      return result
    } catch (error) {
      // Ne jamais journaliser `content` : il peut contenir des paraphrases
      // issues des emails. Les métadonnées suffisent au diagnostic.
      console.warn('Réponse comportementale invalide', {
        retry,
        finishReason: data?.choices?.[0]?.finish_reason ?? null,
        contentLength: content.length,
        validationError: errorMessage(error),
      })
      throw error
    }
  }

  try {
    return await requestAnalysis(false)
  } catch (error) {
    if (!isRetriableAnalysisError(error)) throw error
    return await requestAnalysis(true)
  }
}

// ── Attribution des lignes de transcript à un locuteur ────────────────────
// Réutilisé par sync-email-analysis (loadMeetingCorpus) et par l'ingestion
// manuelle de transcript.

export function normalizedSpeaker(value: string | null | undefined): string {
  return String(value ?? '')
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()
}

/** Une transcription n'est utilisée que si le préfixe de locuteur correspond
 * exactement à une identité connue du contact. En cas d'ambiguïté, elle reste
 * visible dans l'historique mais n'alimente pas l'inférence comportementale. */
export function attributedTranscriptExcerpt(transcript: string, identities: string[]): string | null {
  const speakers = new Set(identities
    .flatMap((identity) => {
      const email = cleanEmail(identity)
      return [identity, email.includes('@') ? email.split('@')[0] : '']
    })
    .map(normalizedSpeaker)
    .filter((identity) => identity.length >= 4))
  if (!speakers.size) return null

  const attributed = String(transcript ?? '').split(/\r?\n/).flatMap((line) => {
    const match = line.trim().match(/^(.+?)(?:\s+\(\d{1,2}:\d{2}(?::\d{2})?\))?\s*:\s*(.+)$/)
    if (!match || !speakers.has(normalizedSpeaker(match[1]))) return []
    const content = sanitizeBody(match[2])
    return content ? [content] : []
  })
  if (!attributed.length) return null
  return `[Transcription de réunion]\n${attributed.join('\n')}`.slice(0, 2400)
}

// ── Écriture du profil cognitif d'un contact ──────────────────────────────

export type PersistContactProfileParams = {
  organizationId: string
  contactId: string
  result: Analysis
  messageCount: number
  meetingCount: number
  interactionCount: number
  updatedFrom: string[]
  signalSource: string
  /** Défaut : `sync:${now}`. Ex. transcript : `transcript:${meetingId}`. */
  sourceRef?: string
  /** Défaut : maintenant. Ex. transcript : date de la réunion. */
  observedAt?: string
}

/** Upsert du profil cognitif v3 d'un contact + insertion de ses signaux
 *  comportementaux dérivés. Source unique de la logique d'écriture, partagée
 *  entre l'analyse email et l'ingestion de transcript. Lève en cas d'échec
 *  pour que l'appelant journalise (les triggers calculent deduplication_key). */
export async function persistContactProfile(
  supabase: SupabaseClient,
  params: PersistContactProfileParams,
): Promise<{ profileId: string; signalCount: number }> {
  const { organizationId, contactId, result, messageCount, meetingCount, interactionCount, updatedFrom, signalSource } = params
  const cognitiveProfileData = asRecord(result.cognitive_profile_data)
  assertCurrentCognitiveSchema(cognitiveProfileData)
  const structuredSignals = structuredBehavioralSignals(cognitiveProfileData)
  const now = new Date().toISOString()
  const observedAt = params.observedAt ?? now
  const sourceRef = params.sourceRef ?? `sync:${now}`
  // Confiance/Satisfaction (score PERSONNE, 5 axes) : "insufficient" ne doit
  // jamais écraser une valeur déjà mesurée par un run précédent qui aurait
  // eu moins de matière — on ne régresse une mesure réelle vers null que si
  // ce run-ci l'a explicitement invalidée en trouvant un statut différent
  // n'est pas possible ici ; on garde donc simplement : mesuré si "observed"
  // ou "emerging" avec un score non nul, sinon null (zéro hallucination).
  const trust = result.trust?.status && result.trust.status !== 'insufficient' && result.trust.score != null ? result.trust : null
  const satisfaction = result.satisfaction?.status && result.satisfaction.status !== 'insufficient' && result.satisfaction.score != null ? result.satisfaction : null
  const accountRelation = result.account_relation?.status && result.account_relation.status !== 'insufficient'
    && result.account_relation.category && (ACCOUNT_RELATION_CATEGORIES as readonly string[]).includes(result.account_relation.category)
    ? result.account_relation : null
  const { data: cognitiveProfile, error: profileError } = await supabase.from('cognitive_profiles').upsert({
    organization_id: organizationId,
    contact_id: contactId,
    profile_version: 1,
    global_confidence: pct(result.global_confidence),
    summary: result.executive_summary ?? null,
    executive_summary: result.executive_summary ?? null,
    cognitive_mode: result.cognitive_mode ?? null,
    cognitive_mode_confidence: pct(result.cognitive_mode_confidence),
    behavioral_analysis_data: structuredSignals,
    communication_style_data: asRecord(cognitiveProfileData.secondary_axes),
    cognitive_profile_data: cognitiveProfileData,
    source_message_count: messageCount,
    source_meeting_count: meetingCount,
    source_interaction_count: interactionCount,
    maturity_level: maturityFor(interactionCount),
    analysis_version: 3,
    last_analyzed_at: now,
    updated_from: updatedFrom,
    updated_at: now,
    // evidence : faits datés concrets ayant réellement motivé le score (voir prompt
    // trust/satisfaction plus haut) — distinct de `observation` (synthèse générale).
    // Non écrasé par `[]`/absent : un run qui ne retrouve pas de preuve fraîche ne
    // doit pas effacer une preuve réelle déjà persistée par un run précédent.
    ...(trust ? { trust_score: pct(trust.score), trust_reasoning: trust.observation ?? null, trust_analyzed_at: now, ...(trust.evidence?.length ? { trust_evidence: trust.evidence } : {}) } : {}),
    ...(satisfaction ? { satisfaction_score: pct(satisfaction.score), satisfaction_reasoning: satisfaction.observation ?? null, satisfaction_analyzed_at: now, ...(satisfaction.evidence?.length ? { satisfaction_evidence: satisfaction.evidence } : {}) } : {}),
    ...(accountRelation ? { account_relation_hint: accountRelation.category, account_relation_hint_confidence: pct(accountRelation.confidence), account_relation_hint_reasoning: accountRelation.observation ?? null, account_relation_hint_analyzed_at: now } : {}),
  }, { onConflict: 'organization_id,contact_id,profile_version' }).select('id').single()
  if (profileError || !cognitiveProfile) throw profileError ?? new Error('Profil cognitif non enregistré')
  const signals = structuredSignals.map((item) => ({ organization_id: organizationId, contact_id: contactId, profile_id: cognitiveProfile.id, signal_type: item.trait, text: item.observation, inference: item.trait, inference_level: 'observable', confidence: pct(item.confidence), source_type: signalSource, source_ref: sourceRef, observed_at: observedAt }))
  if (signals.length) {
    const { error: signalsError } = await supabase.from('behavioral_signals').insert(signals)
    if (signalsError) throw signalsError
  }
  return { profileId: cognitiveProfile.id as string, signalCount: signals.length }
}

// Journalisation de l'usage IA (OpenRouter) → table `ai_usage_events`.
// OpenRouter renvoie `usage` (tokens réels) dans chaque réponse : on stocke ces
// tokens + un coût ESTIMÉ via la grille ci-dessous. La grille est approximative
// (la source de vérité des dépenses reste le tableau de bord OpenRouter) et se
// met à jour ici sans toucher au reste du code.

// Prix approximatifs en USD par 1 000 000 de tokens (entrée / sortie).
// À ajuster selon la facturation OpenRouter réelle.
const PRICING: Record<string, { in: number; out: number }> = {
  'google/gemini-3.1-flash-lite': { in: 0.10, out: 0.40 },
  'anthropic/claude-haiku-4.5': { in: 1.00, out: 5.00 },
  'openai/gpt-4.1-mini': { in: 0.40, out: 1.60 },
}
const DEFAULT_PRICE = { in: 0.50, out: 1.50 }

export type TokenUsage = { prompt_tokens?: number; completion_tokens?: number; total_tokens?: number } | null | undefined

export function estimateCostUsd(model: string, promptTokens: number, completionTokens: number): number {
  const price = PRICING[model] ?? DEFAULT_PRICE
  return (promptTokens / 1_000_000) * price.in + (completionTokens / 1_000_000) * price.out
}

type AnySupabase = { from: (table: string) => { insert: (rows: Record<string, unknown>) => PromiseLike<{ error: unknown }> } }

/** Best-effort : ne jette jamais (une erreur de log ne doit pas casser l'analyse). */
export async function logAiUsage(client: AnySupabase, params: {
  organizationId?: string | null
  userId?: string | null
  fn: string
  model: string
  usage: TokenUsage
}): Promise<void> {
  try {
    const prompt = Math.max(0, Math.round(Number(params.usage?.prompt_tokens ?? 0)))
    const completion = Math.max(0, Math.round(Number(params.usage?.completion_tokens ?? 0)))
    const total = Math.max(0, Math.round(Number(params.usage?.total_tokens ?? prompt + completion)))
    await client.from('ai_usage_events').insert({
      organization_id: params.organizationId ?? null,
      user_id: params.userId ?? null,
      fn: params.fn,
      model: params.model,
      prompt_tokens: prompt,
      completion_tokens: completion,
      total_tokens: total,
      estimated_cost_usd: Number(estimateCostUsd(params.model, prompt, completion).toFixed(6)),
    })
  } catch {
    // silencieux : la journalisation ne doit jamais interrompre le flux principal.
  }
}

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
const headers = { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type', 'Access-Control-Allow-Methods': 'GET, POST, OPTIONS' }
const json = (data: unknown, status = 200) => new Response(JSON.stringify(data), { status, headers: { ...headers, 'Content-Type': 'application/json' } })
const checked = async (query: any) => { const result = await query; if (result.error) throw result.error; return result.data }
Deno.serve(async req => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers })
  const db = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!)
  const redirect = `${Deno.env.get('SUPABASE_URL')}/functions/v1/connect-notion`
  const app = Deno.env.get('APP_URL') ?? 'https://tohu.co'
  const clientId = Deno.env.get('NOTION_CLIENT_ID')
  const clientSecret = Deno.env.get('NOTION_CLIENT_SECRET')
  try {
    if (req.method === 'GET') {
      const url = new URL(req.url), nonce = url.searchParams.get('state')
      if (!nonce || !/^[a-f0-9-]{36}$/.test(nonce)) return json({ error: 'État OAuth invalide' }, 400)
      const pending = await checked(db.from('connector_oauth_states').delete().eq('nonce', nonce).eq('provider', 'notion').gt('expires_at', new Date().toISOString()).select().maybeSingle())
      if (!pending) return json({ error: 'Autorisation expirée ou déjà utilisée' }, 400)
      if (url.searchParams.has('error')) return Response.redirect(`${app}/app/connectors?error=notion_access_denied`, 302)
      if (!await checked(db.from('memberships').select('id').eq('organization_id', pending.organization_id).eq('user_id', pending.user_id).maybeSingle())) return json({ error: 'Accès refusé' }, 403)
      if (!clientId || !clientSecret) throw new Error('Secrets Notion non configurés dans les Edge Functions')
      const response = await fetch('https://api.notion.com/v1/oauth/token', { method: 'POST', headers: { Authorization: `Basic ${btoa(`${clientId}:${clientSecret}`)}`, 'Content-Type': 'application/json', 'Notion-Version': '2026-03-11' }, body: JSON.stringify({ grant_type: 'authorization_code', code: url.searchParams.get('code'), redirect_uri: redirect }), signal: AbortSignal.timeout(20000) })
      const token = await response.json()
      if (!response.ok || !token.access_token || !token.workspace_id) throw new Error(String(token.error_description ?? 'Échange OAuth Notion refusé'))
      const connector = await checked(db.from('connectors').upsert({ organization_id: pending.organization_id, user_id: pending.user_id, provider: 'notion', status: 'connected', scopes: ['read_content', 'user_information'], metadata: { workspace_id: token.workspace_id, workspace_name: token.workspace_name, owner_user_id: token.owner?.user?.id, owner_email: token.owner?.user?.person?.email }, last_synced_at: null }, { onConflict: 'user_id,provider' }).select('id').single())
      await checked(db.from('oauth_accounts').delete().eq('connector_id', connector.id))
      await checked(db.rpc('store_oauth_tokens_server', { p_organization_id: pending.organization_id, p_connector_id: connector.id, p_provider_account_id: token.bot_id, p_access_token: token.access_token, p_refresh_token: token.refresh_token ?? null, p_expires_at: null }))
      await checked(db.from('connector_sync_state').upsert({ connector_id: connector.id, state: {} }))
      return Response.redirect(`${app}/app/connectors?connected=notion`, 302)
    }
    if (req.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
    const { data: { user } } = await db.auth.getUser((req.headers.get('Authorization') ?? '').replace('Bearer ', ''))
    if (!user) return json({ error: 'Session invalide' }, 401)
    const { organizationId, action = 'start' } = await req.json()
    if (!await checked(db.from('memberships').select('id').eq('organization_id', organizationId).eq('user_id', user.id).maybeSingle())) return json({ error: 'Accès refusé' }, 403)
    if (action === 'disconnect') {
      const connector = await checked(db.from('connectors').select('id').eq('organization_id', organizationId).eq('user_id', user.id).eq('provider', 'notion').single())
      await checked(db.from('oauth_accounts').delete().eq('connector_id', connector.id))
      await checked(db.from('connector_sync_state').delete().eq('connector_id', connector.id))
      await checked(db.from('connectors').update({ status: 'disconnected', metadata: {}, scopes: [] }).eq('id', connector.id))
      return json({ success: true })
    }
    if (!clientId || !clientSecret) return json({ error: 'NOTION_CLIENT_ID / NOTION_CLIENT_SECRET non configurés dans les secrets Edge Functions' }, 500)
    await checked(db.from('connector_oauth_states').delete().lt('expires_at', new Date().toISOString()))
    const pending = await checked(db.from('connector_oauth_states').insert({ organization_id: organizationId, user_id: user.id, provider: 'notion' }).select('nonce').single())
    return json({ url: `https://api.notion.com/v1/oauth/authorize?${new URLSearchParams({ client_id: clientId, redirect_uri: redirect, response_type: 'code', owner: 'user', state: pending.nonce })}` })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Opération Notion impossible'
    return req.method === 'GET' ? Response.redirect(`${app}/app/connectors?error=${encodeURIComponent(message)}`, 302) : json({ error: message }, 500)
  }
})

// Synchronise le calendrier Google Calendar de façon prospective (passé récent +
// futur), indépendamment de l'API Google Meet (sync-google-meet), qui ne voit que
// des conférences déjà démarrées — jamais un rendez-vous à venir. C'est cette
// fonction qui alimente réellement le bloc "Prochain rendez-vous" des fiches
// Personnes : sans elle, `meetings` ne contient jamais de ligne future.
//
// Double mode (même pattern que monitor-contacts/index.ts) :
//  - x-cron-secret : boucle sur tous les connecteurs Google connectés de toutes
//    les organisations (service role, aucun utilisateur authentifié) ;
//  - Authorization : synchronise uniquement le connecteur Google de l'appelant
//    (bouton "Synchroniser" de ConnectorsPage.tsx).
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { cleanEmail, errorMessage, upsertCalendarMeeting, type NormalizedCalendarEvent } from '../_shared/calendar-sync.ts'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-cron-secret',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
}

function positiveIntegerEnv(name: string, fallback: number): number {
  const parsed = Number(Deno.env.get(name))
  return Number.isFinite(parsed) && parsed > 0 ? Math.floor(parsed) : fallback
}

const LOOKBACK_DAYS = positiveIntegerEnv('CALENDAR_SYNC_LOOKBACK_DAYS', 14)
const LOOKAHEAD_DAYS = positiveIntegerEnv('CALENDAR_SYNC_LOOKAHEAD_DAYS', 60)
const SMALL_MEETING_MAX_ATTENDEES = positiveIntegerEnv('CALENDAR_SYNC_SMALL_MEETING_MAX_ATTENDEES', 5)
const MAX_EVENTS_PER_CONNECTOR = positiveIntegerEnv('CALENDAR_SYNC_MAX_EVENTS_PER_CONNECTOR', 250)
const MAX_CONNECTORS_PER_CRON_RUN = positiveIntegerEnv('CALENDAR_SYNC_MAX_CONNECTORS_PER_RUN', 30)

async function appSecret(supabase: any, name: string): Promise<string | null> {
  const { data } = await supabase.from('app_secrets').select('value').eq('name', name).maybeSingle()
  return (data as { value?: string } | null)?.value ?? null
}

async function refreshAccessToken(refreshToken: string): Promise<{ accessToken: string; refreshToken: string; expiresIn: number }> {
  const clientId = Deno.env.get('GOOGLE_CLIENT_ID')
  const clientSecret = Deno.env.get('GOOGLE_CLIENT_SECRET')
  if (!clientId || !clientSecret) throw new Error('Secrets OAuth google manquants')
  const response = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ client_id: clientId, client_secret: clientSecret, refresh_token: refreshToken, grant_type: 'refresh_token' }),
  })
  if (!response.ok) throw new Error(`Rafraîchissement google refusé (${response.status})`)
  const data = await response.json()
  return { accessToken: data.access_token, refreshToken: data.refresh_token ?? refreshToken, expiresIn: Number(data.expires_in ?? 3600) }
}

export function normalizeGoogleEvent(item: any, ownEmail: string): NormalizedCalendarEvent | null {
  if (!item?.id || !item.start?.dateTime) return null // ignore les événements "journée entière" (pas d'heure exploitable)
  const attendees = ((item.attendees ?? []) as any[]).map((attendee) => ({
    email: cleanEmail(attendee.email),
    displayName: attendee.displayName ?? null,
    organizer: Boolean(attendee.organizer),
    self: Boolean(attendee.self) || cleanEmail(attendee.email) === ownEmail,
  })).filter((attendee) => attendee.email)
  if (!attendees.some((attendee) => attendee.self)) {
    attendees.push({ email: ownEmail, displayName: null, organizer: true, self: true })
  }
  const meetLink = item.conferenceData?.entryPoints?.find((entry: any) => entry.entryPointType === 'video')?.uri ?? item.hangoutLink ?? null
  const platform: NormalizedCalendarEvent['platform'] =
    item.conferenceData?.conferenceSolution?.key?.type === 'hangoutsMeet' ? 'google_meet' : 'calendar_only'
  return {
    externalEventId: `google:${item.id}`,
    title: item.summary ?? 'Réunion',
    startsAt: item.start.dateTime,
    endsAt: item.end?.dateTime ?? null,
    status: item.status === 'cancelled' ? 'cancelled' : 'confirmed',
    meetingUrl: meetLink,
    calendarHtmlLink: item.htmlLink ?? null,
    platform,
    attendees,
    raw: item,
  }
}

async function listCalendarEvents(token: string, sinceIso: string, untilIso: string): Promise<any[]> {
  // showDeleted=true est indispensable : sans lui, un événement annulé disparaît
  // simplement du flux au lieu de renvoyer status=cancelled — on manquerait
  // silencieusement l'annulation au lieu de la propager.
  const items: any[] = []
  let pageToken: string | null = null
  do {
    const params = new URLSearchParams({
      timeMin: sinceIso, timeMax: untilIso, singleEvents: 'true', orderBy: 'startTime', showDeleted: 'true',
      maxResults: '250',
      fields: 'nextPageToken,items(id,status,summary,start,end,attendees,conferenceData,hangoutLink,htmlLink)',
    })
    if (pageToken) params.set('pageToken', pageToken)
    const response = await fetch(`https://www.googleapis.com/calendar/v3/calendars/primary/events?${params}`, { headers: { Authorization: `Bearer ${token}` } })
    if (!response.ok) throw new Error(`Google Calendar ${response.status}`)
    const page = await response.json()
    items.push(...(page.items ?? []))
    pageToken = page.nextPageToken ?? null
  } while (pageToken && items.length < MAX_EVENTS_PER_CONNECTOR)
  return items.slice(0, MAX_EVENTS_PER_CONNECTOR)
}

async function syncOneConnector(
  supabase: any,
  connector: { id: string; metadata: unknown },
  organizationId: string,
  userId: string,
): Promise<{ meetings: number; participants: number; errors: string[] }> {
  const { data: tokenRows, error: tokenError } = await supabase.rpc('get_oauth_tokens_server', { p_connector_id: connector.id })
  const oauth = tokenRows?.[0]
  if (tokenError || !oauth) throw new Error('Jetons OAuth absents. Reconnecte Google Workspace.')

  let accessToken = oauth.access_token as string | null
  let refreshToken = oauth.refresh_token as string | null
  const expiresSoon = !oauth.expires_at || new Date(oauth.expires_at).getTime() < Date.now() + 90_000
  if ((!accessToken || expiresSoon) && refreshToken) {
    const refreshed = await refreshAccessToken(refreshToken)
    accessToken = refreshed.accessToken
    refreshToken = refreshed.refreshToken
    await supabase.rpc('store_oauth_tokens_server', {
      p_organization_id: organizationId, p_connector_id: connector.id, p_provider_account_id: oauth.provider_account_id,
      p_access_token: accessToken, p_refresh_token: refreshToken, p_expires_at: new Date(Date.now() + refreshed.expiresIn * 1000).toISOString(),
    })
  }
  if (!accessToken) throw new Error('Jeton OAuth indisponible')

  const ownEmail = cleanEmail((connector.metadata as any)?.account_email)
  const sinceIso = new Date(Date.now() - LOOKBACK_DAYS * 86_400_000).toISOString()
  const untilIso = new Date(Date.now() + LOOKAHEAD_DAYS * 86_400_000).toISOString()
  const items = await listCalendarEvents(accessToken, sinceIso, untilIso)

  let meetings = 0
  let participants = 0
  const errors: string[] = []
  for (const item of items) {
    try {
      const event = normalizeGoogleEvent(item, ownEmail)
      if (!event) continue
      const result = await upsertCalendarMeeting({
        supabase, organizationId, ownerUserId: userId, event, source: 'google_calendar',
        smallMeetingMaxAttendees: SMALL_MEETING_MAX_ATTENDEES,
      })
      meetings++
      participants += result.participantsUpserted
    } catch (eventError) {
      errors.push(errorMessage(eventError))
    }
  }
  return { meetings, participants, errors }
}

Deno.serve(async (request) => {
  if (request.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
  const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')
  const cronSecret = request.headers.get('x-cron-secret')

  try {
    if (cronSecret) {
      const expected = await appSecret(supabase, 'monitor_cron')
      if (!expected || cronSecret !== expected) return json({ error: 'Cron secret invalide' }, 401)

      const { data: connectors } = await supabase.from('connectors')
        .select('id, organization_id, user_id, metadata')
        .eq('provider', 'google').eq('status', 'connected')
        .order('last_synced_at', { ascending: true, nullsFirst: true })
        .limit(MAX_CONNECTORS_PER_CRON_RUN)

      let meetings = 0, participants = 0, connectorsProcessed = 0
      const errors: string[] = []
      for (const connector of connectors ?? []) {
        try {
          const result = await syncOneConnector(supabase, connector, connector.organization_id, connector.user_id)
          meetings += result.meetings
          participants += result.participants
          connectorsProcessed++
          errors.push(...result.errors.slice(0, 3).map((message) => `${connector.id}: ${message}`))
          await supabase.from('connectors').update({ last_synced_at: new Date().toISOString() }).eq('id', connector.id)
        } catch (connectorError) {
          errors.push(`${connector.id}: ${errorMessage(connectorError)}`)
        }
      }
      return json({ ok: true, mode: 'cron', connectorsProcessed, meetings, participants, errors: errors.slice(0, 10) })
    }

    const authorization = request.headers.get('Authorization')
    if (!authorization) return json({ error: 'Authentification requise' }, 401)
    const { data: { user }, error: userError } = await supabase.auth.getUser(authorization.replace('Bearer ', ''))
    if (userError || !user) return json({ error: 'Session invalide' }, 401)
    const { organizationId } = await request.json().catch(() => ({}))
    if (!organizationId) return json({ error: 'Paramètres invalides' }, 400)
    const { data: membership } = await supabase.from('memberships').select('id').eq('organization_id', organizationId).eq('user_id', user.id).maybeSingle()
    if (!membership) return json({ error: 'Accès refusé' }, 403)
    const { data: connector } = await supabase.from('connectors').select('id,metadata').eq('organization_id', organizationId).eq('user_id', user.id).eq('provider', 'google').maybeSingle()
    if (!connector) return json({ error: 'Connecteur Google introuvable. Connecte Google Workspace d’abord.' }, 404)

    const result = await syncOneConnector(supabase, connector, organizationId, user.id)
    await supabase.from('connectors').update({ last_synced_at: new Date().toISOString() }).eq('id', connector.id)
    return json({ success: true, meetings: result.meetings, participants: result.participants, errors: result.errors.slice(0, 5) })
  } catch (error) {
    return json({ error: errorMessage(error) || 'Synchronisation impossible' }, 500)
  }
})

// Logique métier partagée entre tous les connecteurs calendrier (Google, Microsoft,
// et un futur 3e provider) : upsert idempotent d'un événement dans meetings/
// meeting_participants, calcul individuel/collectif, matching de participants.
// Un nouveau provider construit juste un NormalizedCalendarEvent[] et appelle
// upsertCalendarMeeting — aucune règle métier à réécrire.
import type { SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2'

export const PUBLIC_EMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'outlook.com', 'outlook.fr',
  'hotmail.com', 'hotmail.fr', 'live.com', 'live.fr', 'msn.com',
  'icloud.com', 'me.com', 'yahoo.com', 'yahoo.fr', 'proton.me', 'protonmail.com',
  'orange.fr', 'wanadoo.fr', 'free.fr', 'sfr.fr', 'laposte.net',
  'gmx.com', 'gmx.fr', 'aol.com', 'mac.com',
  'avocat.com', 'avocat.fr',
])

export function cleanEmail(value: string | null | undefined): string {
  return String(value ?? '').trim().toLowerCase()
}

export function corporateDomain(email: string): string | null {
  const domain = cleanEmail(email).split('@')[1] ?? ''
  return domain && !PUBLIC_EMAIL_DOMAINS.has(domain) ? domain : null
}

export function companyNameFromDomain(domain: string): string {
  const base = domain.split('.')[0] ?? domain
  return base.split(/[-_]+/).filter(Boolean).map((part) => part.charAt(0).toUpperCase() + part.slice(1)).join(' ') || domain
}

/** `String(error)` renvoie "[object Object]" pour une PostgrestError ou tout objet
 *  d'erreur qui n'est pas une instance d'Error (cas de la plupart des erreurs
 *  renvoyées par supabase-js) — indispensable pour des logs de cron exploitables. */
export function errorMessage(error: unknown): string {
  if (error instanceof Error) return error.message
  if (error && typeof error === 'object') {
    const obj = error as Record<string, unknown>
    return String(obj.message ?? obj.error ?? obj.details ?? JSON.stringify(obj))
  }
  return String(error)
}

export type NormalizedAttendee = { email: string; displayName: string | null; organizer: boolean; self: boolean }

export type NormalizedCalendarEvent = {
  /** Préfixé par provider ('google:{id}' | 'microsoft:{id}') pour ne jamais collisionner entre sources. */
  externalEventId: string
  title: string
  startsAt: string
  endsAt: string | null
  status: 'confirmed' | 'cancelled'
  /** Lien de visioconférence à "rejoindre", si présent. */
  meetingUrl: string | null
  /** Lien "ouvrir dans l'agenda" du provider. */
  calendarHtmlLink: string | null
  platform: 'google_meet' | 'teams' | 'calendar_only'
  attendees: NormalizedAttendee[]
  raw: unknown
}

/** Individuelle = 1:1 ou petit meeting (≤ seuil de participants hors soi-même).
 *  Collective = standup, weekly, webinar — jamais de "prochain rendez-vous"
 *  individuel ni de briefing pour ses participants, même déjà fichés. */
export function meetingScopeOf(event: Pick<NormalizedCalendarEvent, 'attendees'>, maxAttendees: number): 'individual' | 'collective' {
  const others = event.attendees.filter((attendee) => !attendee.self)
  return others.length <= maxAttendees ? 'individual' : 'collective'
}

export type UpsertCalendarMeetingInput = {
  supabase: SupabaseClient
  organizationId: string
  ownerUserId: string
  event: NormalizedCalendarEvent
  source: string
  smallMeetingMaxAttendees: number
  /** true : ne réécrit pas meeting_scope/status/meeting_url/calendar_html_link/raw_payload —
   *  utilisé quand un autre passage calendrier a déjà posé ces champs sur la même ligne
   *  (convergence sync-google-meet ↔ sync-google-calendar sur le même external_event_id). */
  preserveCalendarFields?: boolean
}

export type UpsertCalendarMeetingResult = { meetingId: string; participantsUpserted: number }

export async function upsertCalendarMeeting(input: UpsertCalendarMeetingInput): Promise<UpsertCalendarMeetingResult> {
  const { supabase, organizationId, ownerUserId, event, source, smallMeetingMaxAttendees } = input
  const scope = meetingScopeOf(event, smallMeetingMaxAttendees)
  const others = event.attendees.filter((attendee) => !attendee.self)

  let companyId: string | null = null
  const primary = others[0] ?? null
  if (primary) {
    const domain = corporateDomain(primary.email)
    if (domain) {
      const { data: company } = await supabase.rpc('resolve_company_identity', {
        p_organization_id: organizationId, p_name: companyNameFromDomain(domain), p_domain: domain, p_industry: null, p_create_if_missing: true,
      }).maybeSingle()
      companyId = (company as { company_id?: string } | null)?.company_id ?? null
    }
  }

  const payload: Record<string, unknown> = {
    organization_id: organizationId,
    owner_user_id: ownerUserId,
    company_id: companyId,
    external_event_id: event.externalEventId,
    title: event.title,
    starts_at: event.startsAt,
    ends_at: event.endsAt,
    platform: event.platform,
  }
  if (!input.preserveCalendarFields) {
    Object.assign(payload, {
      status: event.status,
      meeting_scope: scope,
      meeting_url: event.meetingUrl,
      calendar_html_link: event.calendarHtmlLink,
      raw_payload: event.raw,
    })
  }

  const { data: meetingRow, error: meetingError } = await supabase.from('meetings')
    .upsert(payload, { onConflict: 'organization_id,external_event_id' })
    .select('id').single()
  if (meetingError || !meetingRow) throw meetingError ?? new Error('Réunion non enregistrée')

  let participantsUpserted = 0
  for (const attendee of others) {
    const { data: resolved } = await supabase.rpc('resolve_contact_identity', {
      p_organization_id: organizationId,
      p_email: attendee.email,
      p_full_name: attendee.displayName ?? attendee.email,
      p_company_id: companyId,
      p_owner_user_id: ownerUserId,
      p_role_title: null,
      p_source: source,
      p_create_if_missing: scope === 'individual',
    }).maybeSingle()
    // contact_id reste null pour un membre Tohu (resolve_contact_identity renvoie
    // alors 0 ligne) ou pour un inconnu en réunion collective : c'est voulu, pas
    // une erreur — rien de spécial à faire ici, la garantie vient de la RPC.
    const { error: participantError } = await supabase.from('meeting_participants').upsert({
      organization_id: organizationId,
      meeting_id: meetingRow.id,
      contact_id: (resolved as { contact_id?: string } | null)?.contact_id ?? null,
      email: attendee.email,
      display_name: attendee.displayName,
      role_in_meeting: attendee.organizer ? 'organizer' : 'attendee',
      is_current_user: false,
    }, { onConflict: 'meeting_id,email' })
    if (!participantError) participantsUpserted++
  }

  return { meetingId: meetingRow.id as string, participantsUpserted }
}

// Récupère les photos de profil des contacts via l'API Google People
// (people/me/connections, scope contacts.readonly) et les associe aux fiches Tohu
// PAR EMAIL. On ne remplit que les avatars manquants (jamais d'écrasement d'un
// avatar déjà défini), et on ignore les photos par défaut (silhouette générique).
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}
function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
}

async function refreshAccessToken(refreshToken: string): Promise<{ accessToken: string; refreshToken: string; expiresIn: number }> {
  const clientId = Deno.env.get('GOOGLE_CLIENT_ID')
  const clientSecret = Deno.env.get('GOOGLE_CLIENT_SECRET')
  if (!clientId || !clientSecret) throw new Error('Secrets OAuth google manquants')
  const response = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ client_id: clientId, client_secret: clientSecret, refresh_token: refreshToken, grant_type: 'refresh_token' }),
  })
  if (!response.ok) throw new Error(`Rafraîchissement google refusé (${response.status})`)
  const data = await response.json()
  return { accessToken: data.access_token, refreshToken: data.refresh_token ?? refreshToken, expiresIn: Number(data.expires_in ?? 3600) }
}

async function peopleGet(token: string, url: string): Promise<any | null> {
  const response = await fetch(url, { headers: { Authorization: `Bearer ${token}` } })
  if (!response.ok) {
    // Compte perso, API People non activée ou scope absent : pas fatal.
    if (response.status === 403 || response.status === 404) return null
    throw new Error(`Google People API ${response.status}`)
  }
  return response.json()
}

const AVATAR_BUCKET = 'contact-avatars'
// Plafond d'auto-hébergement par exécution (borne le temps du run). On ne traite
// que les avatars manquants : les runs suivants rapatrient le reste.
const MAX_AVATAR_PERSIST = 400

// Télécharge la photo Google et la stocke dans Supabase Storage (bucket public),
// puis renvoie l'URL publique stable. En cas d'échec (téléchargement, type,
// upload), on retombe sur l'URL source pour garder un avatar plutôt que rien.
async function persistAvatar(
  supabase: ReturnType<typeof createClient>,
  organizationId: string,
  contactId: string,
  sourceUrl: string,
): Promise<string> {
  try {
    const response = await fetch(sourceUrl)
    if (!response.ok) return sourceUrl
    const contentType = response.headers.get('content-type') ?? 'image/jpeg'
    if (!contentType.startsWith('image/')) return sourceUrl
    const bytes = new Uint8Array(await response.arrayBuffer())
    if (!bytes.length || bytes.length > 5_000_000) return sourceUrl
    const ext = contentType.includes('png') ? 'png' : contentType.includes('webp') ? 'webp' : 'jpg'
    const path = `${organizationId}/${contactId}.${ext}`
    const { error } = await supabase.storage.from(AVATAR_BUCKET).upload(path, bytes, { contentType, upsert: true })
    if (error) return sourceUrl
    const { data } = supabase.storage.from(AVATAR_BUCKET).getPublicUrl(path)
    return data?.publicUrl || sourceUrl
  } catch {
    return sourceUrl
  }
}

Deno.serve(async (request) => {
  if (request.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
  const startedAt = new Date().toISOString()
  let syncJobId: string | null = null
  try {
    const authorization = request.headers.get('Authorization')
    if (!authorization) return json({ error: 'Authentification requise' }, 401)
    const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')
    const { data: { user }, error: userError } = await supabase.auth.getUser(authorization.replace('Bearer ', ''))
    if (userError || !user) return json({ error: 'Session invalide' }, 401)
    const { organizationId } = await request.json().catch(() => ({}))
    if (!organizationId) return json({ error: 'Paramètres invalides' }, 400)
    const { data: membership } = await supabase.from('memberships').select('id').eq('organization_id', organizationId).eq('user_id', user.id).maybeSingle()
    if (!membership) return json({ error: 'Accès refusé' }, 403)
    const { data: connector } = await supabase.from('connectors').select('id,metadata').eq('organization_id', organizationId).eq('user_id', user.id).eq('provider', 'google').maybeSingle()
    if (!connector) return json({ error: 'Connecteur Google introuvable.' }, 404)
    const { data: tokenRows, error: tokenError } = await supabase.rpc('get_oauth_tokens_server', { p_connector_id: connector.id })
    const oauth = tokenRows?.[0]
    if (tokenError || !oauth) return json({ error: 'Jetons OAuth absents. Reconnecte Google Workspace.' }, 401)

    const { data: job } = await supabase.from('sync_jobs').insert({
      organization_id: organizationId, connector_id: connector.id, user_id: user.id, provider: 'google',
      job_type: 'google_photos_sync', status: 'running', current_step: 'Lecture des contacts Google', progress: 20, started_at: startedAt, payload: {},
    }).select('id').single()
    syncJobId = job?.id ?? null

    let accessToken = oauth.access_token as string | null
    let refreshToken = oauth.refresh_token as string | null
    const expiresSoon = !oauth.expires_at || new Date(oauth.expires_at).getTime() < Date.now() + 90_000
    if ((!accessToken || expiresSoon) && refreshToken) {
      const refreshed = await refreshAccessToken(refreshToken)
      accessToken = refreshed.accessToken
      refreshToken = refreshed.refreshToken
      await supabase.rpc('store_oauth_tokens_server', { p_organization_id: organizationId, p_connector_id: connector.id, p_provider_account_id: oauth.provider_account_id, p_access_token: accessToken, p_refresh_token: refreshToken, p_expires_at: new Date(Date.now() + refreshed.expiresIn * 1000).toISOString() })
    }
    if (!accessToken) throw new Error('Jeton OAuth indisponible')

    // Contacts sans avatar, indexés par email (on ne remplit que les manquants).
    const { data: contactsData } = await supabase.from('contacts')
      .select('id,email').eq('organization_id', organizationId).is('merged_into_contact_id', null)
      .is('avatar_url', null).not('email', 'is', null)
    const contactByEmail = new Map<string, string>()
    for (const contact of (contactsData ?? []) as any[]) {
      const email = String(contact.email ?? '').trim().toLowerCase()
      if (email) contactByEmail.set(email, contact.id)
    }

    // Photo Google par email (on ignore les photos "default" = silhouette générique).
    const photoByEmail = new Map<string, string>()
    let pageToken: string | null = null
    do {
      const url = `https://people.googleapis.com/v1/people/me/connections?personFields=emailAddresses,photos&pageSize=1000&sortOrder=LAST_MODIFIED_DESCENDING${pageToken ? `&pageToken=${encodeURIComponent(pageToken)}` : ''}`
      const page = await peopleGet(accessToken, url)
      if (!page) break
      for (const person of (page.connections ?? []) as any[]) {
        const photo = (person.photos ?? []).find((item: any) => item?.url && !item?.default)?.url
        if (!photo) continue
        for (const emailEntry of (person.emailAddresses ?? []) as any[]) {
          const email = String(emailEntry?.value ?? '').trim().toLowerCase()
          if (email && !photoByEmail.has(email)) photoByEmail.set(email, photo)
        }
      }
      pageToken = page.nextPageToken ?? null
    } while (pageToken)

    let photosMatched = 0
    let persistAttempts = 0
    for (const [email, contactId] of contactByEmail) {
      const photo = photoByEmail.get(email)
      if (!photo) continue
      // =s256 : force une taille d'avatar nette et homogène.
      const sized = photo.replace(/=s\d+(-c)?$/, '') + '=s256-c'
      // Auto-hébergement (fiabilité + vie privée) tant qu'on est sous le plafond
      // du run ; au-delà, on retombe sur l'URL Google directe.
      let avatarUrl = sized
      if (persistAttempts < MAX_AVATAR_PERSIST) {
        persistAttempts++
        avatarUrl = await persistAvatar(supabase, organizationId, contactId, sized)
      }
      const { error: updateError } = await supabase.from('contacts').update({ avatar_url: avatarUrl }).eq('id', contactId)
      if (!updateError) photosMatched++
    }

    if (syncJobId) await supabase.from('sync_jobs').update({ current_step: 'Synchronisation terminée', progress: 100, status: 'succeeded', completed_at: new Date().toISOString(), payload: { photos: photosMatched } }).eq('id', syncJobId)
    return json({ success: true, photos: photosMatched })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Synchronisation impossible'
    if (syncJobId) {
      const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')
      await supabase.from('sync_jobs').update({ status: 'failed', current_step: 'Échec de la synchronisation', error_code: 'GOOGLE_PHOTOS_SYNC_FAILED', error_message: message, completed_at: new Date().toISOString() }).eq('id', syncJobId)
    }
    return json({ error: message }, 500)
  }
})

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { analyze, persistContactProfile, sanitizeBody } from '../_shared/behavior-analysis.ts'
import { slackApi, SlackError, REAUTH_ERRORS, conversationTypes, isPrivateConversation, authoredMessage, messageKey } from '../_shared/slack.ts'
const headers = { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type', 'Access-Control-Allow-Methods': 'POST, OPTIONS' }
const json = (data: unknown, status = 200) => new Response(JSON.stringify(data), { status, headers: { ...headers, 'Content-Type': 'application/json' } })
const checked = async (query: any) => { const result = await query; if (result.error) throw new Error(result.error.message); return result.data }
const positiveIntegerEnv = (name: string, fallback: number) => {
  const value = Number(Deno.env.get(name) ?? fallback)
  return Number.isInteger(value) && value > 0 ? value : fallback
}
const INITIAL_LOOKBACK_DAYS = positiveIntegerEnv('SLACK_INITIAL_LOOKBACK_DAYS', 90)
const SYNC_MAX_MESSAGES = positiveIntegerEnv('SLACK_SYNC_MAX_MESSAGES', 1000)
const syncProgress = (state: any) => state?.phase === 'done' ? 100
  : state?.phase === 'users' ? 2
  : state?.phase === 'channels' ? 5
  : Math.min(95, 10 + Math.round((Number(state?.index ?? 0) / Math.max(1, Number(state?.channels?.length ?? 0))) * 85))
// One API page per invocation: durable checkpoints survive function deadlines and 429s.
// The UI drives continuations and can be closed/reopened without losing progress.
Deno.serve(async req => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers })
  if (req.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
  const db = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!)
  const started = Date.now()
  let connector: any, state: any, lease: string | null = null
  try {
    const { data: { user } } = await db.auth.getUser((req.headers.get('Authorization') ?? '').replace('Bearer ', ''))
    if (!user) return json({ error: 'Session invalide' }, 401)
    const { organizationId } = await req.json()
    if (!await checked(db.from('memberships').select('id').eq('organization_id', organizationId).eq('user_id', user.id).maybeSingle())) return json({ error: 'Accès refusé' }, 403)
    connector = await checked(db.from('connectors').select('*').eq('organization_id', organizationId).eq('user_id', user.id).eq('provider', 'slack').single())
    if (!['connected', 'error'].includes(connector.status)) return json({ error: 'Reconnecte Slack pour continuer.' }, 401)
    lease = crypto.randomUUID()
    if (!await checked(db.rpc('claim_connector_sync', { p_connector_id: connector.id, p_lease_id: lease }))) { lease = null; return json({ pending: true, retryAfter: 5 }) }
    const saved = await checked(db.from('connector_sync_state').select('state').eq('connector_id', connector.id).single())
    state = saved.state
    // Les checkpoints créés avant l'introduction de la fenêtre de 90 jours
    // parcouraient tout l'historique. Ils sont redémarrés une seule fois.
    if (state.policyVersion !== 2) state = {}
    if (state.retryAt && state.retryAt > Date.now()) return json({ pending: true, retryAfter: Math.ceil((state.retryAt - Date.now()) / 1000) })
    const tokens = await checked(db.rpc('get_oauth_tokens_server', { p_connector_id: connector.id }))
    const oauth = tokens?.[0]
    if (!oauth?.access_token) throw new SlackError('invalid_auth')
    let token = oauth.access_token
    if (oauth.expires_at && new Date(oauth.expires_at).getTime() < Date.now() + 90000) {
      if (!oauth.refresh_token) throw new SlackError('token_expired')
      const clientId = Deno.env.get('SLACK_CLIENT_ID')
      const clientSecret = Deno.env.get('SLACK_CLIENT_SECRET')
      if (!clientId || !clientSecret) throw new SlackError('invalid_refresh_token')
      const response = await fetch('https://slack.com/api/oauth.v2.access', { method: 'POST', body: new URLSearchParams({ client_id: clientId, client_secret: clientSecret, grant_type: 'refresh_token', refresh_token: oauth.refresh_token }), signal: AbortSignal.timeout(20000) })
      if (response.status === 429) throw new SlackError('ratelimited', Number(response.headers.get('Retry-After')) || 60)
      const refreshed = await response.json()
      if (!response.ok || !refreshed.ok) throw new SlackError(refreshed.error ?? 'refresh_failed')
      token = refreshed.access_token
      await checked(db.rpc('store_oauth_tokens_server', { p_organization_id: organizationId, p_connector_id: connector.id, p_provider_account_id: oauth.provider_account_id, p_access_token: token, p_refresh_token: refreshed.refresh_token, p_expires_at: new Date(Date.now() + refreshed.expires_in * 1000).toISOString() }))
    }
    if (!state.phase || state.phase === 'done') {
      const job = await checked(db.from('sync_jobs').insert({ organization_id: organizationId, connector_id: connector.id, user_id: user.id, provider: 'slack', job_type: 'slack_sync', status: 'running', current_step: 'Lecture des utilisateurs Slack', progress: 0, started_at: new Date().toISOString(), payload: {} }).select('id').single())
      const now = Date.now()
      state = { policyVersion: 2, phase: 'users', cursor: '', users: {}, channels: [], index: 0, threads: state.threads ?? {}, threadAuthors: state.threadAuthors ?? {}, watermarks: state.watermarks ?? {}, since: state.until ?? String((now - INITIAL_LOOKBACK_DAYS * 86400000) / 1000), until: String(now / 1000), messages: 0, jobId: job.id }
      await checked(db.from('connector_sync_state').update({ state }).eq('connector_id', connector.id))
    }
    const nextCursor = (page: any) => page.response_metadata?.next_cursor?.trim() ?? ''
    if (state.phase === 'users') {
      const page = await slackApi(token, 'users.list', { limit: '200', cursor: state.cursor })
      for (const member of page.members ?? []) {
        if (!member.is_bot && !member.deleted && member.id !== 'USLACKBOT') state.users[member.id] = { name: member.profile?.real_name ?? member.real_name ?? member.name, email: member.profile?.email ?? null }
      }
      state.cursor = nextCursor(page)
      if (!state.cursor) state.phase = 'channels'
    } else if (state.phase === 'channels') {
      const types = conversationTypes(connector.scopes ?? [])
      if (!types) throw new SlackError('missing_scope')
      const page = await slackApi(token, 'users.conversations', { types, limit: '200', cursor: state.cursor, exclude_archived: 'false' })
      for (const channel of page.channels ?? []) {
        if (!state.channels.some((item: any) => item.id === channel.id)) state.channels.push({ id: channel.id, name: channel.name ?? 'Conversation Slack', private: isPrivateConversation(channel), updated: Number(channel.updated ?? channel.created ?? 0) })
      }
      state.cursor = nextCursor(page)
      if (!state.cursor) {
        // Les canaux publics les plus récemment actifs sont traités en premier.
        // Les conversations privées ne participent pas à l'enrichissement externe.
        state.channels = state.channels.filter((channel: any) => !channel.private).sort((left: any, right: any) => right.updated - left.updated)
        state.phase = 'history'
      }
    } else if (state.index < state.channels.length) {
      const channel = state.channels[state.index]
      const restricted = channel.private || !connector.metadata.share_public
      const team = connector.metadata.team_id
      const prefix = restricted ? `${user.id}:` : ''
      const threadTs = state.replyQueue?.[0]
      const method = state.phase === 'replies' ? 'conversations.replies' : 'conversations.history'
      let page: any
      try {
        page = await slackApi(token, method, { channel: channel.id, limit: '15', oldest: state.watermarks?.[channel.id] ?? state.since, latest: state.until, inclusive: 'false', cursor: state.cursor, ...(threadTs ? { ts: threadTs } : {}) })
      } catch (error) {
        if (error instanceof SlackError && ['channel_not_found', 'not_in_channel', 'missing_scope', 'thread_not_found', 'is_archived'].includes(error.code)) {
          // Surface skipped conversations, without names of private channels in shared jobs.
          state.skipped = (state.skipped ?? 0) + 1
          if (error.code !== 'thread_not_found') state.channelSkipped = true
          else state.threads[channel.id] = (state.threads[channel.id] ?? []).filter((ts: string) => ts !== threadTs)
          page = { messages: [], response_metadata: {} }
        } else throw error
      }
      const remaining = Math.max(0, SYNC_MAX_MESSAGES - state.messages)
      const selectedMessages = (page.messages ?? []).filter(authoredMessage).slice(0, remaining)
      for (const message of selectedMessages) {
        if (Date.now() - started > 40000) {
          // Replay this same page; successfully analyzed messages carry an idempotency marker.
          await checked(db.from('connector_sync_state').update({ state }).eq('connector_id', connector.id).eq('lease_id', lease))
          return json({ pending: true, messages: state.messages })
        }
        if (message.reply_count > 0) {
          const roots: string[] = state.threads[channel.id] ?? []
          if (!roots.includes(message.ts)) roots.push(message.ts)
          state.threads[channel.id] = roots
        }
        state.threadAuthors ??= {}
        if (!message.thread_ts || message.thread_ts === message.ts) state.threadAuthors[`${channel.id}:${message.ts}`] = message.user
        const fromSelf = message.user === connector.metadata.slack_user_id
        const mentions = [...new Set<string>([...String(message.text ?? '').matchAll(/<@([A-Z0-9]+)(?:\|[^>]+)?>/g)].map(match => match[1]))].filter(id => id !== connector.metadata.slack_user_id)
        // Attribute outbound messages only to an explicit recipient or thread author.
        const recipient = mentions.length === 1 ? mentions[0] : mentions.length === 0 ? state.threadAuthors[`${channel.id}:${message.thread_ts}`] : null
        const sender = state.users[fromSelf ? recipient : message.user]
        let contact: any = null
        if (!restricted && sender?.email) {
          // The same identity RPC as HubSpot handles canonical email, aliases and merges.
          const domain = sender.email.trim().toLowerCase().split('@')[1]
          const company = domain ? await checked(db.from('companies').select('id').eq('organization_id', organizationId).eq('normalized_domain', domain).maybeSingle()) : null
          const resolved = await checked(db.rpc('resolve_contact_identity', { p_organization_id: organizationId, p_email: sender.email, p_full_name: sender.name, p_company_id: company?.id ?? null, p_owner_user_id: user.id, p_source: 'slack' }).maybeSingle())
          if (resolved?.contact_id) contact = await checked(db.from('contacts').select('id,full_name,company_id').eq('id', resolved.contact_id).single())
        }
        const externalId = prefix + messageKey(team, channel.id, message.ts)
        const previous = await checked(db.from('communication_messages').select('id,metadata').eq('organization_id', organizationId).eq('provider', 'slack').eq('external_message_id', externalId).maybeSingle())
        const permalink = previous?.metadata?.permalink ?? (await slackApi(token, 'chat.getPermalink', { channel: channel.id, message_ts: message.ts })).permalink
        if (typeof permalink !== 'string' || !/^https:\/\/[^/]+\.slack\.com\//.test(permalink)) throw new Error('Référence Slack indisponible')
        const root = message.thread_ts ?? message.ts
        const thread = await checked(db.from('communication_threads').upsert({ organization_id: organizationId, provider: 'slack', external_thread_id: prefix + messageKey(team, channel.id, root), subject: channel.name, source_owner_user_id: restricted ? user.id : null, updated_at: new Date().toISOString() }, { onConflict: 'organization_id,provider,external_thread_id' }).select('id').single())
        const metadata = { ...previous?.metadata, team_id: team, channel_id: channel.id, ts: message.ts, thread_ts: root, permalink, sender_id: message.user, mentioned_user_ids: mentions, user_id: user.id, connector_id: connector.id, company_id: contact?.company_id ?? null, private: restricted, analyzed_without_body_storage: true }
        await checked(db.from('communication_messages').upsert({ organization_id: organizationId, provider: 'slack', external_message_id: externalId, thread_id: thread.id, contact_id: restricted ? null : contact?.id ?? null, source_owner_user_id: restricted ? user.id : null, direction: fromSelf ? 'outbound' : 'inbound', sent_at: new Date(Number(message.ts) * 1000).toISOString(), subject: channel.name, body_text: null, metadata }, { onConflict: 'organization_id,provider,external_message_id' }).select('id').single())
        // Autorisation utilisateur explicite : seuls les messages entrants des
        // canaux publics peuvent alimenter le pipeline partagé. Les MP et canaux
        // privés restent sans contact, sans corps stocké et sans appel au modèle.
        if (!restricted && contact && !fromSelf && message.text && !previous?.metadata?.slack_analyzed) {
          const profile = await checked(db.from('cognitive_profiles').select('cognitive_profile_data,source_message_count,source_meeting_count,source_interaction_count,updated_from').eq('organization_id', organizationId).eq('contact_id', contact.id).eq('profile_version', 1).maybeSingle())
          const counted = await db.from('communication_messages').select('id', { count: 'exact', head: true }).eq('organization_id', organizationId).eq('contact_id', contact.id).eq('direction', 'inbound')
          if (counted.error) throw new Error(counted.error.message)
          const messageCount = counted.count ?? 0
          const observedAt = new Date(Number(message.ts) * 1000).toISOString()
          const result = await analyze(contact.full_name, 'contact', [`[slack ${observedAt} ${metadata.permalink}] ${sanitizeBody(message.text)}`], profile?.cognitive_profile_data ?? {}, messageCount + (profile?.source_meeting_count ?? 0), { client: db, organizationId, userId: user.id }, AbortSignal.timeout(35000))
          await persistContactProfile(db, { organizationId, contactId: contact.id, result, messageCount, meetingCount: profile?.source_meeting_count ?? 0, interactionCount: messageCount + (profile?.source_meeting_count ?? 0), updatedFrom: [...new Set<string>([...(profile?.updated_from ?? []), 'slack'])], signalSource: 'slack', sourceRef: metadata.permalink, observedAt })
          await checked(db.from('communication_messages').update({ metadata: { ...metadata, slack_analyzed: true } }).eq('organization_id', organizationId).eq('provider', 'slack').eq('external_message_id', externalId))
        }
      }
      state.messages += selectedMessages.length
      if (state.messages >= SYNC_MAX_MESSAGES) {
        state.truncated = true
        state.phase = 'done'
      }
      state.cursor = nextCursor(page)
      if (page.has_more && !state.cursor) throw new Error('Pagination Slack incomplète : aucun curseur reçu')
      if (state.phase !== 'done' && !state.cursor) {
        if (state.phase === 'history') {
          // Revisit ALL known roots: replies to old messages are not in history.
          state.replyQueue = [...(state.threads[channel.id] ?? [])]
          state.phase = 'replies'
        } else state.replyQueue.shift()
        if (!state.replyQueue.length) {
          state.watermarks ??= {}
          if (!state.channelSkipped) state.watermarks[channel.id] = state.until
          state.channelSkipped = false
          state.index++
          state.phase = 'history'
        }
      }
    }
    const complete = state.phase === 'done' || (state.phase === 'history' && state.index >= state.channels.length)
    if (complete) state.phase = 'done'
    state.retryAt = null
    await checked(db.from('connector_sync_state').update({ state }).eq('connector_id', connector.id).eq('lease_id', lease))
    await checked(db.from('sync_jobs').update({ status: complete ? 'succeeded' : 'running', current_step: complete ? 'Synchronisation Slack terminée' : 'Lecture des conversations Slack', progress: complete ? 100 : Math.min(95, Math.floor(state.index / Math.max(1, state.channels.length) * 90)), completed_at: complete ? new Date().toISOString() : null, payload: { messages: state.messages, skipped: state.skipped ?? 0, truncated: state.truncated ?? false, lookback_days: INITIAL_LOOKBACK_DAYS, message_limit: SYNC_MAX_MESSAGES }, error_message: null }).eq('id', state.jobId))
    await checked(db.from('connectors').update({ status: 'connected', ...(complete ? { last_synced_at: new Date().toISOString() } : {}), metadata: { ...connector.metadata, last_error: state.skipped ? `${state.skipped} conversation(s) ou fil(s) inaccessible(s).` : null } }).eq('id', connector.id))
    return json({ success: true, pending: !complete, progress: syncProgress(state), messages: state.messages, skipped: state.skipped ?? 0, truncated: state.truncated ?? false })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Synchronisation Slack impossible'
    if (connector && state && lease) {
      if (error instanceof SlackError && error.retryAfter) {
        state.retryAt = Date.now() + error.retryAfter * 1000
        await checked(db.from('connector_sync_state').update({ state }).eq('connector_id', connector.id).eq('lease_id', lease))
        return json({ pending: true, retryAfter: error.retryAfter, progress: syncProgress(state), messages: state.messages ?? 0 })
      }
      // Failed pages are replayed from their last checkpoint; external IDs deduplicate.
      await db.from('connectors').update({ status: error instanceof SlackError && REAUTH_ERRORS.includes(error.code) ? 'needs_reauth' : 'error', metadata: { ...connector.metadata, last_error: message } }).eq('id', connector.id)
      if (state.jobId) await db.from('sync_jobs').update({ status: 'failed', error_message: message, completed_at: new Date().toISOString() }).eq('id', state.jobId)
    }
    return json({ error: message }, 500)
  } finally {
    if (connector && lease) await db.from('connector_sync_state').update({ lease_until: null, lease_id: null }).eq('connector_id', connector.id).eq('lease_id', lease)
  }
})

// Cœur d'analyse comportementale partagé — source unique du "cerveau" Tohu.
//
// Extrait de sync-email-analysis pour être réutilisé sans duplication par
// l'ingestion manuelle de transcripts (ingest-transcript). Contient : le
// contrat de sortie JSON (schema_version 3), l'appel OpenRouter côté serveur
// (`analyze`), les transformations vers `behavioral_signals`, l'attribution
// des lignes de transcript à un locuteur, et l'écriture (upsert) d'un profil
// cognitif de contact (`persistContactProfile`).
//
// Toute évolution du prompt / du schéma se fait ICI et bénéficie aux deux
// chemins (email + transcript) simultanément.
import type { SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { logAiUsage } from './ai-usage.ts'

export type RelationshipAxisResult = {
  status?: string
  score?: number | null
  observation?: string | null
  confidence?: number | null
  evidence?: string[]
}

export type AccountRelationResult = {
  status?: string
  category?: string | null
  observation?: string | null
  confidence?: number | null
  evidence?: string[]
}

export type Analysis = {
  executive_summary?: string
  cognitive_mode?: string
  cognitive_mode_confidence?: number
  global_confidence?: number
  behavioral_analysis_data?: Array<{ trait?: string; observation?: string; confidence?: number }>
  communication_style_data?: Record<string, unknown>
  cognitive_profile_data?: Record<string, unknown>
  // Axes du score relationnel PERSONNE (Confiance/Satisfaction) — distincts du
  // profil de style de communication ci-dessus. Nécessitent une lecture du
  // contenu réel des échanges (pas seulement leurs métadonnées), d'où leur
  // extraction ici plutôt que dans score-batch (pur calcul, sans IA).
  trust?: RelationshipAxisResult
  satisfaction?: RelationshipAxisResult
  // Catégorisation COMPTE (Prospect/Client/Partenaire/Fournisseur/Investisseur) :
  // indice par contact, agrégé au niveau compte par score-batch. Uniquement
  // pertinent pour role="contact" (une seule entreprise externe) — toujours
  // "insufficient" pour role="responsable" (auto-profil interne, multi-comptes).
  account_relation?: AccountRelationResult
}

