  const requestAnalysis = async (retry: boolean): Promise<Analysis> => {
    const response = await fetch('https://openrouter.ai/api/v1/chat/completions', {
      signal,
      method: 'POST',
      headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json', 'HTTP-Referer': Deno.env.get('SITE_URL') ?? 'https://tohu.app', 'X-Title': 'Tohu Email Behavior Analysis' },
      body: JSON.stringify({
        // Modèle dédié à l'analyse comportementale (découplé du chat Ask Tohu).
        // Surchargable via OPENROUTER_ANALYSIS_MODEL sans toucher aux autres fonctions.
        model,
        temperature: retry ? 0 : 0.1,
        response_format: COGNITIVE_PROFILE_RESPONSE_FORMAT,
        // Empêche OpenRouter de choisir un fournisseur qui ignorerait le
        // JSON Schema et retomberait silencieusement sur l'ancien format.
        provider: { require_parameters: true },
        max_tokens: retry ? 7000 : 6000,
        messages: [{
          role: 'user',
          content: retry
            ? `${prompt}\n\nIMPORTANT : la tentative précédente a produit un JSON invalide, tronqué ou dans un ancien schéma. Repars exclusivement du contrat ci-dessus : cognitive_profile_data.schema_version doit valoir 3 et les six primary_axes doivent tous être présents. Réponds de façon compacte, sans Markdown ni commentaire avant ou après l'objet JSON, et ferme impérativement toutes les structures JSON.`
            : prompt,
        }],
      }),
    })
    if (!response.ok) throw new Error(`OpenRouter ${response.status}`)
    const data = await response.json()
    if (usageLog) await logAiUsage(usageLog.client, { organizationId: usageLog.organizationId, userId: usageLog.userId, fn: 'behavior-analysis:analyze', model, usage: data?.usage })
    const content = openRouterContent(data)
    try {
      const result = extractJson(content)
      assertCurrentCognitiveSchema(asRecord(result.cognitive_profile_data))
      return result
    } catch (error) {
      // Ne jamais journaliser `content` : il peut contenir des paraphrases
      // issues des emails. Les métadonnées suffisent au diagnostic.
      console.warn('Réponse comportementale invalide', {
        retry,
        finishReason: data?.choices?.[0]?.finish_reason ?? null,
        contentLength: content.length,
        validationError: errorMessage(error),
      })
      throw error
    }
  }

  try {
    return await requestAnalysis(false)
  } catch (error) {
    if (!isRetriableAnalysisError(error)) throw error
    return await requestAnalysis(true)
  }
}

// ── Attribution des lignes de transcript à un locuteur ────────────────────
// Réutilisé par sync-email-analysis (loadMeetingCorpus) et par l'ingestion
// manuelle de transcript.

export function normalizedSpeaker(value: string | null | undefined): string {
  return String(value ?? '')
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()
}

/** Une transcription n'est utilisée que si le préfixe de locuteur correspond
 * exactement à une identité connue du contact. En cas d'ambiguïté, elle reste
 * visible dans l'historique mais n'alimente pas l'inférence comportementale. */
export function attributedTranscriptExcerpt(transcript: string, identities: string[]): string | null {
  const speakers = new Set(identities
    .flatMap((identity) => {
      const email = cleanEmail(identity)
      return [identity, email.includes('@') ? email.split('@')[0] : '']
    })
    .map(normalizedSpeaker)
    .filter((identity) => identity.length >= 4))
  if (!speakers.size) return null

  const attributed = String(transcript ?? '').split(/\r?\n/).flatMap((line) => {
    const match = line.trim().match(/^(.+?)(?:\s+\(\d{1,2}:\d{2}(?::\d{2})?\))?\s*:\s*(.+)$/)
    if (!match || !speakers.has(normalizedSpeaker(match[1]))) return []
    const content = sanitizeBody(match[2])
    return content ? [content] : []
  })
  if (!attributed.length) return null
  return `[Transcription de réunion]\n${attributed.join('\n')}`.slice(0, 2400)
}

// ── Écriture du profil cognitif d'un contact ──────────────────────────────

export type PersistContactProfileParams = {
  organizationId: string
  contactId: string
  result: Analysis
  messageCount: number
  meetingCount: number
  interactionCount: number
  updatedFrom: string[]
  signalSource: string
  /** Défaut : `sync:${now}`. Ex. transcript : `transcript:${meetingId}`. */
  sourceRef?: string
  /** Défaut : maintenant. Ex. transcript : date de la réunion. */
  observedAt?: string
}

/** Upsert du profil cognitif v3 d'un contact + insertion de ses signaux
 *  comportementaux dérivés. Source unique de la logique d'écriture, partagée
 *  entre l'analyse email et l'ingestion de transcript. Lève en cas d'échec
 *  pour que l'appelant journalise (les triggers calculent deduplication_key). */
export async function persistContactProfile(
  supabase: SupabaseClient,
  params: PersistContactProfileParams,
): Promise<{ profileId: string; signalCount: number }> {
  const { organizationId, contactId, result, messageCount, meetingCount, interactionCount, updatedFrom, signalSource } = params
  const cognitiveProfileData = asRecord(result.cognitive_profile_data)
  assertCurrentCognitiveSchema(cognitiveProfileData)
  const structuredSignals = structuredBehavioralSignals(cognitiveProfileData)
  const now = new Date().toISOString()
  const observedAt = params.observedAt ?? now
  const sourceRef = params.sourceRef ?? `sync:${now}`
  // Confiance/Satisfaction (score PERSONNE, 5 axes) : "insufficient" ne doit
  // jamais écraser une valeur déjà mesurée par un run précédent qui aurait
  // eu moins de matière — on ne régresse une mesure réelle vers null que si
  // ce run-ci l'a explicitement invalidée en trouvant un statut différent
  // n'est pas possible ici ; on garde donc simplement : mesuré si "observed"
  // ou "emerging" avec un score non nul, sinon null (zéro hallucination).
  const trust = result.trust?.status && result.trust.status !== 'insufficient' && result.trust.score != null ? result.trust : null
  const satisfaction = result.satisfaction?.status && result.satisfaction.status !== 'insufficient' && result.satisfaction.score != null ? result.satisfaction : null
  const accountRelation = result.account_relation?.status && result.account_relation.status !== 'insufficient'
    && result.account_relation.category && (ACCOUNT_RELATION_CATEGORIES as readonly string[]).includes(result.account_relation.category)
    ? result.account_relation : null
  const { data: cognitiveProfile, error: profileError } = await supabase.from('cognitive_profiles').upsert({
    organization_id: organizationId,
    contact_id: contactId,
    profile_version: 1,
    global_confidence: pct(result.global_confidence),
    summary: result.executive_summary ?? null,
    executive_summary: result.executive_summary ?? null,
    cognitive_mode: result.cognitive_mode ?? null,
    cognitive_mode_confidence: pct(result.cognitive_mode_confidence),
    behavioral_analysis_data: structuredSignals,
    communication_style_data: asRecord(cognitiveProfileData.secondary_axes),
    cognitive_profile_data: cognitiveProfileData,
    source_message_count: messageCount,
    source_meeting_count: meetingCount,
    source_interaction_count: interactionCount,
    maturity_level: maturityFor(interactionCount),
    analysis_version: 3,
    last_analyzed_at: now,
    updated_from: updatedFrom,
    updated_at: now,
    // evidence : faits datés concrets ayant réellement motivé le score (voir prompt
    // trust/satisfaction plus haut) — distinct de `observation` (synthèse générale).
    // Non écrasé par `[]`/absent : un run qui ne retrouve pas de preuve fraîche ne
    // doit pas effacer une preuve réelle déjà persistée par un run précédent.
    ...(trust ? { trust_score: pct(trust.score), trust_reasoning: trust.observation ?? null, trust_analyzed_at: now, ...(trust.evidence?.length ? { trust_evidence: trust.evidence } : {}) } : {}),
    ...(satisfaction ? { satisfaction_score: pct(satisfaction.score), satisfaction_reasoning: satisfaction.observation ?? null, satisfaction_analyzed_at: now, ...(satisfaction.evidence?.length ? { satisfaction_evidence: satisfaction.evidence } : {}) } : {}),
    ...(accountRelation ? { account_relation_hint: accountRelation.category, account_relation_hint_confidence: pct(accountRelation.confidence), account_relation_hint_reasoning: accountRelation.observation ?? null, account_relation_hint_analyzed_at: now } : {}),
  }, { onConflict: 'organization_id,contact_id,profile_version' }).select('id').single()
  if (profileError || !cognitiveProfile) throw profileError ?? new Error('Profil cognitif non enregistré')
  const signals = structuredSignals.map((item) => ({ organization_id: organizationId, contact_id: contactId, profile_id: cognitiveProfile.id, signal_type: item.trait, text: item.observation, inference: item.trait, inference_level: 'observable', confidence: pct(item.confidence), source_type: signalSource, source_ref: sourceRef, observed_at: observedAt }))
  if (signals.length) {
    const { error: signalsError } = await supabase.from('behavioral_signals').insert(signals)
    if (signalsError) throw signalsError
  }
  return { profileId: cognitiveProfile.id as string, signalCount: signals.length }
}

// Journalisation de l'usage IA (OpenRouter) → table `ai_usage_events`.
// OpenRouter renvoie `usage` (tokens réels) dans chaque réponse : on stocke ces
// tokens + un coût ESTIMÉ via la grille ci-dessous. La grille est approximative
// (la source de vérité des dépenses reste le tableau de bord OpenRouter) et se
// met à jour ici sans toucher au reste du code.

// Prix approximatifs en USD par 1 000 000 de tokens (entrée / sortie).
// À ajuster selon la facturation OpenRouter réelle.
const PRICING: Record<string, { in: number; out: number }> = {
  'google/gemini-3.1-flash-lite': { in: 0.10, out: 0.40 },
  'anthropic/claude-haiku-4.5': { in: 1.00, out: 5.00 },
  'openai/gpt-4.1-mini': { in: 0.40, out: 1.60 },
}
const DEFAULT_PRICE = { in: 0.50, out: 1.50 }

export type TokenUsage = { prompt_tokens?: number; completion_tokens?: number; total_tokens?: number } | null | undefined

export function estimateCostUsd(model: string, promptTokens: number, completionTokens: number): number {
  const price = PRICING[model] ?? DEFAULT_PRICE
  return (promptTokens / 1_000_000) * price.in + (completionTokens / 1_000_000) * price.out
}

type AnySupabase = { from: (table: string) => { insert: (rows: Record<string, unknown>) => PromiseLike<{ error: unknown }> } }

/** Best-effort : ne jette jamais (une erreur de log ne doit pas casser l'analyse). */
export async function logAiUsage(client: AnySupabase, params: {
  organizationId?: string | null
  userId?: string | null
  fn: string
  model: string
  usage: TokenUsage
}): Promise<void> {
  try {
    const prompt = Math.max(0, Math.round(Number(params.usage?.prompt_tokens ?? 0)))
    const completion = Math.max(0, Math.round(Number(params.usage?.completion_tokens ?? 0)))
    const total = Math.max(0, Math.round(Number(params.usage?.total_tokens ?? prompt + completion)))
    await client.from('ai_usage_events').insert({
      organization_id: params.organizationId ?? null,
      user_id: params.userId ?? null,
      fn: params.fn,
      model: params.model,
      prompt_tokens: prompt,
      completion_tokens: completion,
      total_tokens: total,
      estimated_cost_usd: Number(estimateCostUsd(params.model, prompt, completion).toFixed(6)),
    })
  } catch {
    // silencieux : la journalisation ne doit jamais interrompre le flux principal.
  }
}

export const SLACK_SCOPES = ['users:read', 'users:read.email', 'channels:read', 'channels:history', 'groups:read', 'groups:history', 'im:read', 'im:history', 'mpim:read', 'mpim:history']
export class SlackError extends Error {
  constructor(public code: string, public retryAfter = 0) { super(`Slack : ${code}`) }
}
export async function slackApi(token: string, method: string, params: Record<string, string> = {}, fetcher: typeof fetch = fetch): Promise<any> {
  const response = await fetcher(`https://slack.com/api/${method}`, {
    method: 'POST', headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(params), signal: AbortSignal.timeout(20000),
  })
  if (response.status === 429) throw new SlackError('ratelimited', Math.max(1, Number(response.headers.get('Retry-After')) || 60))
  if (!response.ok) throw new SlackError(`http_${response.status}`, response.status >= 500 ? 30 : 0)
  const data = await response.json()
  if (!data.ok) throw new SlackError(data.error ?? 'invalid_response', data.error === 'ratelimited' ? 60 : 0)
  return data
}
export function conversationTypes(scopes: string[]): string {
  return [['channels', 'public_channel'], ['groups', 'private_channel'], ['im', 'im'], ['mpim', 'mpim']]
    .filter(([scope]) => scopes.includes(`${scope}:read`) && scopes.includes(`${scope}:history`)).map(([, type]) => type).join(',')
}
export function isPrivateConversation(channel: any): boolean {
  // Unknown conversation types are private by default.
  return channel.is_private !== false || channel.is_im === true || channel.is_mpim === true
}
export function messageKey(team: string, channel: string, ts: string): string { return `${team}:${channel}:${ts}` }
export function authoredMessage(message: any): boolean {
  return !!message.user && !message.bot_id && (!message.subtype || message.subtype === 'thread_broadcast') && /^\d+\.\d+$/.test(message.ts ?? '')
}
export const REAUTH_ERRORS = ['invalid_auth', 'token_revoked', 'token_expired', 'account_inactive', 'invalid_refresh_token']

// Identité sécurisée Intercom : le navigateur fournit uniquement son JWT
// Supabase. L'API vérifie la session puis signe elle-même un jeton Intercom
// court, sans jamais exposer INTERCOM_API_SECRET au client.
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import jwt from 'npm:jsonwebtoken@9.0.2'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      ...corsHeaders,
      'Content-Type': 'application/json',
      'Cache-Control': 'no-store, private',
    },
  })
}

Deno.serve(async (request) => {
  if (request.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405)

  try {
    const authorization = request.headers.get('Authorization')
    if (!authorization?.startsWith('Bearer ')) return json({ error: 'Authentification requise' }, 401)

    const supabase = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
    )
    const { data: { user }, error } = await supabase.auth.getUser(authorization.slice('Bearer '.length))
    if (error || !user) return json({ error: 'Session invalide' }, 401)

    const secret = Deno.env.get('INTERCOM_API_SECRET')
    if (!secret) throw new Error('INTERCOM_API_SECRET manquant')

    const metadata = user.user_metadata ?? {}
    const name = String(metadata.full_name ?? metadata.name ?? metadata.user_name ?? '').trim()
    const token = jwt.sign({
      user_id: user.id,
      email: user.email,
      ...(name ? { name } : {}),
    }, secret, {
      algorithm: 'HS256',
      expiresIn: '1h',
    })

    return json({ token, expires_in: 3600 })
  } catch (error) {
    console.error('Création du jeton Intercom impossible', error instanceof Error ? error.message : error)
    return json({ error: 'Identité Intercom indisponible' }, 500)
  }
})

// Enrichit les photos des fiches Personne (contacts) sans avatar, par email.
// Cascade préférée : 1) Gravatar (vraie photo) → 2) logo d'entreprise (icône du
// domaine via DuckDuckGo) → 3) sinon rien (l'UI affiche les initiales). Images
// TÉLÉCHARGÉES et AUTO-HÉBERGÉES dans le bucket public `contact-avatars`.
//
// Deux modes d'appel :
//  - UTILISATEUR (bouton Connecteurs) : JWT + organizationId → l'org du membre ;
//  - CRON (automatique) : en-tête `x-cron-secret` valide → TOUTES les orgs, sans
//    contexte utilisateur. Un cron `tohu-bohu-contact-avatars` l'appelle
//    régulièrement pour que tout nouveau contact récupère sa photo sans action
//    manuelle.
//
// Anti-gaspillage : on horodate chaque tentative (`avatar_checked_at`) et on ne
// re-teste un contact resté sans photo qu'après RECHECK_DAYS — sinon le cron
// re-solliciterait sans fin les mêmes emails qui n'ont ni Gravatar ni logo.
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-cron-secret',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}
function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
}

const AVATAR_BUCKET = 'contact-avatars'
const USER_CAP = 300
const CRON_CAP = 1000
const RUN_DEADLINE_MS = 110_000
const RECHECK_DAYS = 30
const MAX_IMAGE_BYTES = 5_000_000

const FREE_EMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'outlook.com', 'outlook.fr', 'hotmail.com', 'hotmail.fr',
  'live.com', 'live.fr', 'msn.com', 'yahoo.com', 'yahoo.fr', 'icloud.com', 'me.com', 'mac.com',
  'aol.com', 'proton.me', 'protonmail.com', 'gmx.com', 'gmx.fr',
  'orange.fr', 'wanadoo.fr', 'free.fr', 'sfr.fr', 'laposte.net', 'bbox.fr', 'numericable.fr',
])

function corporateDomain(email: string): string | null {
  const domain = email.split('@')[1]?.trim().toLowerCase() ?? ''
  return domain && domain.includes('.') && !FREE_EMAIL_DOMAINS.has(domain) ? domain : null
}

async function sha256Hex(input: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(input))
  return Array.from(new Uint8Array(digest)).map((b) => b.toString(16).padStart(2, '0')).join('')
}

// Télécharge une image et la stocke dans le bucket ; renvoie l'URL publique
// stable, ou null si la source n'a pas d'image exploitable (404, non-image…).
async function fetchAndStore(supabase: ReturnType<typeof createClient>, path: string, url: string): Promise<string | null> {
  try {
    const response = await fetch(url, { redirect: 'follow' })
    if (!response.ok) return null
    const contentType = (response.headers.get('content-type') ?? '').toLowerCase()
    if (!contentType.startsWith('image/')) return null
    const bytes = new Uint8Array(await response.arrayBuffer())
    if (!bytes.length || bytes.length > MAX_IMAGE_BYTES) return null
    const ext = contentType.includes('png') ? 'png'
      : contentType.includes('svg') ? 'svg'
      : contentType.includes('webp') ? 'webp'
      : contentType.includes('gif') ? 'gif'
      : contentType.includes('icon') ? 'ico'
      : 'jpg'
    const fullPath = `${path}.${ext}`
    const { error } = await supabase.storage.from(AVATAR_BUCKET).upload(fullPath, bytes, { contentType, upsert: true })
    if (error) return null
    const { data } = supabase.storage.from(AVATAR_BUCKET).getPublicUrl(fullPath)
    return data?.publicUrl || null
  } catch {
    return null
  }
}

type ContactRow = { id: string; email: string | null; organization_id: string }

async function processContacts(
  supabase: ReturnType<typeof createClient>,
  rows: ContactRow[],
  deadline: number,
): Promise<{ processed: number; gravatar: number; logos: number; none: number }> {
  const logoByKey = new Map<string, string | null>()
  let processed = 0, gravatar = 0, logos = 0, none = 0
  for (const c of rows) {
    if (Date.now() > deadline) break
    processed++
    const now = new Date().toISOString()
    const email = String(c.email ?? '').trim().toLowerCase()
    if (!email.includes('@')) { await supabase.from('contacts').update({ avatar_checked_at: now }).eq('id', c.id); none++; continue }
    const org = c.organization_id

    // 1) Gravatar (vraie photo) — d=404 → 404 s'il n'y a pas d'avatar pour cet email.
    let url = await fetchAndStore(supabase, `${org}/${c.id}`, `https://www.gravatar.com/avatar/${await sha256Hex(email)}?d=404&s=256`)
    let kind: 'gravatar' | 'logo' = 'gravatar'
    if (!url) {
      // 2) Logo/marque d'entreprise via le domaine (mutualisé par org+domaine).
      const dom = corporateDomain(email)
      if (dom) {
        const key = `${org}|${dom}`
        if (!logoByKey.has(key)) logoByKey.set(key, await fetchAndStore(supabase, `${org}/logos/${dom}`, `https://icons.duckduckgo.com/ip3/${dom}.ico`))
        url = logoByKey.get(key) ?? null
        kind = 'logo'
      }
    }
    if (url) {
      await supabase.from('contacts').update({ avatar_url: url, avatar_checked_at: now }).eq('id', c.id)
      if (kind === 'gravatar') gravatar++; else logos++
    } else {
      await supabase.from('contacts').update({ avatar_checked_at: now }).eq('id', c.id)
      none++
    }
  }
  return { processed, gravatar, logos, none }
}

// Filtre commun : sans avatar, jamais testé OU pas re-testé depuis RECHECK_DAYS.
function applyEligibility(query: any) {
  const recheckBefore = new Date(Date.now() - RECHECK_DAYS * 86_400_000).toISOString()
  return query
    .is('merged_into_contact_id', null)
    .is('avatar_url', null)
    .not('email', 'is', null)
    .or(`avatar_checked_at.is.null,avatar_checked_at.lt.${recheckBefore}`)
    .order('is_tracked', { ascending: false })
    .order('avatar_checked_at', { ascending: true, nullsFirst: true })
    .order('created_at', { ascending: false })
}

Deno.serve(async (request) => {
  if (request.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
  const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')
  const deadline = Date.now() + RUN_DEADLINE_MS

  // ── Mode CRON : x-cron-secret valide → toutes les orgs, sans contexte user.
  const cronSecret = request.headers.get('x-cron-secret')
  if (cronSecret) {
    const { data: secretRow } = await supabase.from('app_secrets').select('value').eq('name', 'monitor_cron').maybeSingle()
    if (!secretRow?.value || cronSecret !== secretRow.value) return json({ error: 'Cron secret invalide' }, 401)
    const { data, error } = await applyEligibility(supabase.from('contacts').select('id,email,organization_id')).limit(CRON_CAP)
    if (error) return json({ error: error.message }, 500)
    const result = await processContacts(supabase, (data ?? []) as ContactRow[], deadline)
    return json({ success: true, mode: 'cron', avatars: result.gravatar + result.logos, ...result })
  }

  // ── Mode UTILISATEUR (bouton Connecteurs) : JWT + organizationId.
  const authorization = request.headers.get('Authorization')
  if (!authorization) return json({ error: 'Authentification requise' }, 401)
  const { data: { user }, error: userError } = await supabase.auth.getUser(authorization.replace('Bearer ', ''))
  if (userError || !user) return json({ error: 'Session invalide' }, 401)
  const { organizationId } = await request.json().catch(() => ({}))
  if (!organizationId) return json({ error: 'Paramètres invalides' }, 400)
  const { data: membership } = await supabase.from('memberships').select('id').eq('organization_id', organizationId).eq('user_id', user.id).maybeSingle()
  if (!membership) return json({ error: 'Accès refusé' }, 403)

  let syncJobId: string | null = null
  try {
    const { data: job } = await supabase.from('sync_jobs').insert({
      organization_id: organizationId, user_id: user.id, job_type: 'contact_avatars_enrich',
      status: 'running', current_step: 'Recherche des photos de contacts', progress: 10, started_at: new Date().toISOString(), payload: {},
    }).select('id').single()
    syncJobId = job?.id ?? null

    const { data, error } = await applyEligibility(supabase.from('contacts').select('id,email,organization_id').eq('organization_id', organizationId)).limit(USER_CAP)
    if (error) throw error
    const result = await processContacts(supabase, (data ?? []) as ContactRow[], deadline)

    if (syncJobId) await supabase.from('sync_jobs').update({
      status: 'succeeded', current_step: 'Terminé', progress: 100, completed_at: new Date().toISOString(),
      payload: { avatars: result.gravatar + result.logos, ...result },
    }).eq('id', syncJobId)
    return json({ success: true, mode: 'user', avatars: result.gravatar + result.logos, ...result })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Enrichissement impossible'
    if (syncJobId) await supabase.from('sync_jobs').update({ status: 'failed', current_step: 'Échec', error_code: 'CONTACT_AVATARS_ENRICH_FAILED', error_message: message.slice(0, 500), completed_at: new Date().toISOString() }).eq('id', syncJobId)
    return json({ error: message }, 500)
  }
})

// Synchronise le calendrier Outlook/Microsoft 365 de façon prospective (passé
// récent + futur), à partir du connecteur "microsoft" standard (token délégué
// Calendars.Read déjà accordé à la connexion) — PAS le connecteur "teams" à
// consentement admin (celui-ci reste géré par sync-teams-meetings, pour les
// transcripts, et est inactif pour la quasi-totalité des comptes).
//
// Utilise /me/calendarView plutôt que /me/events : c'est la seule route Graph
// qui explose une série récurrente en occurrences concrètes avec leurs propres
// dates, plutôt que de renvoyer le seul événement maître de la série.
//
// Double mode identique à sync-google-calendar/index.ts (x-cron-secret → boucle
// multi-org service role ; Authorization → un seul connecteur de l'appelant).
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { cleanEmail, errorMessage, upsertCalendarMeeting, type NormalizedCalendarEvent } from '../_shared/calendar-sync.ts'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-cron-secret',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
}

function positiveIntegerEnv(name: string, fallback: number): number {
  const parsed = Number(Deno.env.get(name))
  return Number.isFinite(parsed) && parsed > 0 ? Math.floor(parsed) : fallback
}

const LOOKBACK_DAYS = positiveIntegerEnv('CALENDAR_SYNC_LOOKBACK_DAYS', 14)
const LOOKAHEAD_DAYS = positiveIntegerEnv('CALENDAR_SYNC_LOOKAHEAD_DAYS', 60)
const SMALL_MEETING_MAX_ATTENDEES = positiveIntegerEnv('CALENDAR_SYNC_SMALL_MEETING_MAX_ATTENDEES', 5)
const MAX_EVENTS_PER_CONNECTOR = positiveIntegerEnv('CALENDAR_SYNC_MAX_EVENTS_PER_CONNECTOR', 250)
const MAX_CONNECTORS_PER_CRON_RUN = positiveIntegerEnv('CALENDAR_SYNC_MAX_CONNECTORS_PER_RUN', 30)

async function appSecret(supabase: any, name: string): Promise<string | null> {
  const { data } = await supabase.from('app_secrets').select('value').eq('name', name).maybeSingle()
  return (data as { value?: string } | null)?.value ?? null
}

/** Même app de login existante que sync-teams-meetings/sync-email-analysis
 *  (MICROSOFT_CLIENT_ID/SECRET) — surtout pas les credentials de l'app Teams. */
async function refreshDelegatedToken(refreshToken: string): Promise<{ accessToken: string; refreshToken: string; expiresIn: number }> {
  const clientId = Deno.env.get('MICROSOFT_CLIENT_ID')
  const clientSecret = Deno.env.get('MICROSOFT_CLIENT_SECRET')
  if (!clientId || !clientSecret) throw new Error('Secrets OAuth microsoft (login) manquants')
  const response = await fetch('https://login.microsoftonline.com/common/oauth2/v2.0/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      client_id: clientId, client_secret: clientSecret, refresh_token: refreshToken, grant_type: 'refresh_token',
      scope: 'openid profile email offline_access User.Read Mail.Read Calendars.Read',
    }),
  })
  if (!response.ok) throw new Error(`Rafraîchissement microsoft refusé (${response.status})`)
  const data = await response.json()
  return { accessToken: data.access_token, refreshToken: data.refresh_token ?? refreshToken, expiresIn: Number(data.expires_in ?? 3600) }
}

export function normalizeMicrosoftEvent(item: any, ownEmail: string): NormalizedCalendarEvent | null {
  if (!item?.id || item.isAllDay) return null
  const organizerEmail = cleanEmail(item.organizer?.emailAddress?.address)
  const attendees = ((item.attendees ?? []) as any[]).map((attendee) => {
    const email = cleanEmail(attendee.emailAddress?.address)
    return {
      email,
      displayName: attendee.emailAddress?.name ?? null,
      organizer: email === organizerEmail,
      self: email === ownEmail,
    }
  }).filter((attendee) => attendee.email)
  if (!attendees.some((attendee) => attendee.self)) {
    attendees.push({ email: ownEmail, displayName: null, organizer: organizerEmail === ownEmail, self: true })
  }
  const isTeams = item.isOnlineMeeting && item.onlineMeetingProvider === 'teamsForBusiness'
  return {
    externalEventId: `microsoft:${item.id}`,
    title: item.subject ?? 'Réunion',
    startsAt: item.start?.dateTime ? `${item.start.dateTime}Z` : '',
    endsAt: item.end?.dateTime ? `${item.end.dateTime}Z` : null,
    status: item.isCancelled ? 'cancelled' : 'confirmed',
    meetingUrl: isTeams ? (item.onlineMeeting?.joinUrl ?? null) : null,
    calendarHtmlLink: item.webLink ?? null,
    platform: isTeams ? 'teams' : 'calendar_only',
    attendees,
    raw: item,
  }
}

async function listCalendarView(token: string, sinceIso: string, untilIso: string): Promise<any[]> {
  const select = 'id,subject,start,end,isCancelled,isAllDay,attendees,organizer,onlineMeeting,onlineMeetingProvider,isOnlineMeeting,webLink'
  let url: string | null =
    `https://graph.microsoft.com/v1.0/me/calendarView?startDateTime=${encodeURIComponent(sinceIso)}&endDateTime=${encodeURIComponent(untilIso)}&$select=${select}&$top=100&$orderby=start/dateTime`
  const items: any[] = []
  while (url && items.length < MAX_EVENTS_PER_CONNECTOR) {
    const response = await fetch(url, { headers: { Authorization: `Bearer ${token}`, Prefer: 'outlook.timezone="UTC"' } })
    if (!response.ok) throw new Error(`Microsoft Graph (calendrier) ${response.status}`)
    const page = await response.json()
    items.push(...(page.value ?? []))
    url = page['@odata.nextLink'] ?? null
  }
  return items.slice(0, MAX_EVENTS_PER_CONNECTOR)
}

async function syncOneConnector(
  supabase: any,
  connector: { id: string; metadata: unknown },
  organizationId: string,
  userId: string,
): Promise<{ meetings: number; participants: number; errors: string[] }> {
  const { data: tokenRows, error: tokenError } = await supabase.rpc('get_oauth_tokens_server', { p_connector_id: connector.id })
  const oauth = tokenRows?.[0]
  if (tokenError || !oauth?.refresh_token) throw new Error('Jetons OAuth absents. Reconnecte Microsoft 365.')

  let accessToken = oauth.access_token as string | null
  const expiresSoon = !oauth.expires_at || new Date(oauth.expires_at).getTime() < Date.now() + 90_000
  if (!accessToken || expiresSoon) {
    const refreshed = await refreshDelegatedToken(oauth.refresh_token)
    accessToken = refreshed.accessToken
    await supabase.rpc('store_oauth_tokens_server', {
      p_organization_id: organizationId, p_connector_id: connector.id, p_provider_account_id: oauth.provider_account_id,
      p_access_token: refreshed.accessToken, p_refresh_token: refreshed.refreshToken, p_expires_at: new Date(Date.now() + refreshed.expiresIn * 1000).toISOString(),
    })
  }
  if (!accessToken) throw new Error('Jeton OAuth indisponible')

  const ownEmail = cleanEmail((connector.metadata as any)?.account_email)
  const sinceIso = new Date(Date.now() - LOOKBACK_DAYS * 86_400_000).toISOString()
  const untilIso = new Date(Date.now() + LOOKAHEAD_DAYS * 86_400_000).toISOString()
  const items = await listCalendarView(accessToken, sinceIso, untilIso)

  let meetings = 0
  let participants = 0
  const errors: string[] = []
  for (const item of items) {
    try {
      const event = normalizeMicrosoftEvent(item, ownEmail)
      if (!event || !event.startsAt) continue
      const result = await upsertCalendarMeeting({
        supabase, organizationId, ownerUserId: userId, event, source: 'microsoft_calendar',
        smallMeetingMaxAttendees: SMALL_MEETING_MAX_ATTENDEES,
      })
      meetings++
      participants += result.participantsUpserted
    } catch (eventError) {
      errors.push(errorMessage(eventError))
    }
  }
  return { meetings, participants, errors }
}

Deno.serve(async (request) => {
  if (request.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
  const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')
  const cronSecret = request.headers.get('x-cron-secret')

  try {
    if (cronSecret) {
      const expected = await appSecret(supabase, 'monitor_cron')
      if (!expected || cronSecret !== expected) return json({ error: 'Cron secret invalide' }, 401)

      const { data: connectors } = await supabase.from('connectors')
        .select('id, organization_id, user_id, metadata')
        .eq('provider', 'microsoft').eq('status', 'connected')
        .order('last_synced_at', { ascending: true, nullsFirst: true })
        .limit(MAX_CONNECTORS_PER_CRON_RUN)

      let meetings = 0, participants = 0, connectorsProcessed = 0
      const errors: string[] = []
      for (const connector of connectors ?? []) {
        try {
          const result = await syncOneConnector(supabase, connector, connector.organization_id, connector.user_id)
          meetings += result.meetings
          participants += result.participants
          connectorsProcessed++
          errors.push(...result.errors.slice(0, 3).map((message) => `${connector.id}: ${message}`))
          await supabase.from('connectors').update({ last_synced_at: new Date().toISOString() }).eq('id', connector.id)
        } catch (connectorError) {
          errors.push(`${connector.id}: ${errorMessage(connectorError)}`)
        }
      }
      return json({ ok: true, mode: 'cron', connectorsProcessed, meetings, participants, errors: errors.slice(0, 10) })
    }

    const authorization = request.headers.get('Authorization')
    if (!authorization) return json({ error: 'Authentification requise' }, 401)
    const { data: { user }, error: userError } = await supabase.auth.getUser(authorization.replace('Bearer ', ''))
    if (userError || !user) return json({ error: 'Session invalide' }, 401)
    const { organizationId } = await request.json().catch(() => ({}))
    if (!organizationId) return json({ error: 'Paramètres invalides' }, 400)
    const { data: membership } = await supabase.from('memberships').select('id').eq('organization_id', organizationId).eq('user_id', user.id).maybeSingle()
    if (!membership) return json({ error: 'Accès refusé' }, 403)
    const { data: connector } = await supabase.from('connectors').select('id,metadata').eq('organization_id', organizationId).eq('user_id', user.id).eq('provider', 'microsoft').maybeSingle()
    if (!connector) return json({ error: 'Connecteur Microsoft introuvable. Connecte Microsoft 365 d’abord.' }, 404)

    const result = await syncOneConnector(supabase, connector, organizationId, user.id)
    await supabase.from('connectors').update({ last_synced_at: new Date().toISOString() }).eq('id', connector.id)
    return json({ success: true, meetings: result.meetings, participants: result.participants, errors: result.errors.slice(0, 5) })
  } catch (error) {
    return json({ error: errorMessage(error) || 'Synchronisation impossible' }, 500)
  }
})

// Logique métier partagée entre tous les connecteurs calendrier (Google, Microsoft,
// et un futur 3e provider) : upsert idempotent d'un événement dans meetings/
// meeting_participants, calcul individuel/collectif, matching de participants.
// Un nouveau provider construit juste un NormalizedCalendarEvent[] et appelle
// upsertCalendarMeeting — aucune règle métier à réécrire.
import type { SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2'

export const PUBLIC_EMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'outlook.com', 'outlook.fr',
  'hotmail.com', 'hotmail.fr', 'live.com', 'live.fr', 'msn.com',
  'icloud.com', 'me.com', 'yahoo.com', 'yahoo.fr', 'proton.me', 'protonmail.com',
  'orange.fr', 'wanadoo.fr', 'free.fr', 'sfr.fr', 'laposte.net',
  'gmx.com', 'gmx.fr', 'aol.com', 'mac.com',
  'avocat.com', 'avocat.fr',
])

export function cleanEmail(value: string | null | undefined): string {
  return String(value ?? '').trim().toLowerCase()
}

export function corporateDomain(email: string): string | null {
  const domain = cleanEmail(email).split('@')[1] ?? ''
  return domain && !PUBLIC_EMAIL_DOMAINS.has(domain) ? domain : null
}

export function companyNameFromDomain(domain: string): string {
  const base = domain.split('.')[0] ?? domain
  return base.split(/[-_]+/).filter(Boolean).map((part) => part.charAt(0).toUpperCase() + part.slice(1)).join(' ') || domain
}

/** `String(error)` renvoie "[object Object]" pour une PostgrestError ou tout objet
 *  d'erreur qui n'est pas une instance d'Error (cas de la plupart des erreurs
 *  renvoyées par supabase-js) — indispensable pour des logs de cron exploitables. */
export function errorMessage(error: unknown): string {
  if (error instanceof Error) return error.message
  if (error && typeof error === 'object') {
    const obj = error as Record<string, unknown>
    return String(obj.message ?? obj.error ?? obj.details ?? JSON.stringify(obj))
  }
  return String(error)
}

export type NormalizedAttendee = { email: string; displayName: string | null; organizer: boolean; self: boolean }

export type NormalizedCalendarEvent = {
  /** Préfixé par provider ('google:{id}' | 'microsoft:{id}') pour ne jamais collisionner entre sources. */
  externalEventId: string
  title: string
  startsAt: string
  endsAt: string | null
  status: 'confirmed' | 'cancelled'
  /** Lien de visioconférence à "rejoindre", si présent. */
  meetingUrl: string | null
  /** Lien "ouvrir dans l'agenda" du provider. */
  calendarHtmlLink: string | null
  platform: 'google_meet' | 'teams' | 'calendar_only'
  attendees: NormalizedAttendee[]
  raw: unknown
}

/** Individuelle = 1:1 ou petit meeting (≤ seuil de participants hors soi-même).
 *  Collective = standup, weekly, webinar — jamais de "prochain rendez-vous"
 *  individuel ni de briefing pour ses participants, même déjà fichés. */
export function meetingScopeOf(event: Pick<NormalizedCalendarEvent, 'attendees'>, maxAttendees: number): 'individual' | 'collective' {
  const others = event.attendees.filter((attendee) => !attendee.self)
  return others.length <= maxAttendees ? 'individual' : 'collective'
}

export type UpsertCalendarMeetingInput = {
  supabase: SupabaseClient
  organizationId: string
  ownerUserId: string
  event: NormalizedCalendarEvent
  source: string
  smallMeetingMaxAttendees: number
  /** true : ne réécrit pas meeting_scope/status/meeting_url/calendar_html_link/raw_payload —
   *  utilisé quand un autre passage calendrier a déjà posé ces champs sur la même ligne
   *  (convergence sync-google-meet ↔ sync-google-calendar sur le même external_event_id). */
  preserveCalendarFields?: boolean
}

export type UpsertCalendarMeetingResult = { meetingId: string; participantsUpserted: number }

export async function upsertCalendarMeeting(input: UpsertCalendarMeetingInput): Promise<UpsertCalendarMeetingResult> {
  const { supabase, organizationId, ownerUserId, event, source, smallMeetingMaxAttendees } = input
  const scope = meetingScopeOf(event, smallMeetingMaxAttendees)
  const others = event.attendees.filter((attendee) => !attendee.self)

  let companyId: string | null = null
  const primary = others[0] ?? null
  if (primary) {
    const domain = corporateDomain(primary.email)
    if (domain) {
      const { data: company } = await supabase.rpc('resolve_company_identity', {
        p_organization_id: organizationId, p_name: companyNameFromDomain(domain), p_domain: domain, p_industry: null, p_create_if_missing: true,
      }).maybeSingle()
      companyId = (company as { company_id?: string } | null)?.company_id ?? null
    }
  }

  const payload: Record<string, unknown> = {
    organization_id: organizationId,
    owner_user_id: ownerUserId,
    company_id: companyId,
    external_event_id: event.externalEventId,
    title: event.title,
    starts_at: event.startsAt,
    ends_at: event.endsAt,
    platform: event.platform,
  }
  if (!input.preserveCalendarFields) {
    Object.assign(payload, {
      status: event.status,
      meeting_scope: scope,
      meeting_url: event.meetingUrl,
      calendar_html_link: event.calendarHtmlLink,
      raw_payload: event.raw,
    })
  }

  const { data: meetingRow, error: meetingError } = await supabase.from('meetings')
    .upsert(payload, { onConflict: 'organization_id,external_event_id' })
    .select('id').single()
  if (meetingError || !meetingRow) throw meetingError ?? new Error('Réunion non enregistrée')

  let participantsUpserted = 0
  for (const attendee of others) {
    const { data: resolved } = await supabase.rpc('resolve_contact_identity', {
      p_organization_id: organizationId,
      p_email: attendee.email,
      p_full_name: attendee.displayName ?? attendee.email,
      p_company_id: companyId,
      p_owner_user_id: ownerUserId,
      p_role_title: null,
      p_source: source,
      p_create_if_missing: scope === 'individual',
    }).maybeSingle()
    // contact_id reste null pour un membre Tohu (resolve_contact_identity renvoie
    // alors 0 ligne) ou pour un inconnu en réunion collective : c'est voulu, pas
    // une erreur — rien de spécial à faire ici, la garantie vient de la RPC.
    const { error: participantError } = await supabase.from('meeting_participants').upsert({
      organization_id: organizationId,
      meeting_id: meetingRow.id,
      contact_id: (resolved as { contact_id?: string } | null)?.contact_id ?? null,
      email: attendee.email,
      display_name: attendee.displayName,
      role_in_meeting: attendee.organizer ? 'organizer' : 'attendee',
      is_current_user: false,
    }, { onConflict: 'meeting_id,email' })
    if (!participantError) participantsUpserted++
  }

  return { meetingId: meetingRow.id as string, participantsUpserted }
}

// Synchronise Google Chat : liste les espaces (DM + espaces nommés) et leurs
// messages (API Chat v1). L'API Chat n'expose que des noms d'affichage (jamais
// d'email), donc le rapprochement se fait PAR NOM :
//  - DM 1:1 : l'interlocuteur est créé s'il est inconnu, catégorisé « Collègue » ;
//  - espace nommé : on rattache seulement aux contacts déjà connus (pas de création
//    en masse). Les messages sont enregistrés comme interactions (métadonnées, sans
//    stocker le texte intégral — même doctrine que les emails).
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
}

function positiveIntegerEnv(name: string, fallback: number): number {
  const parsed = Number(Deno.env.get(name))
  return Number.isFinite(parsed) && parsed > 0 ? Math.floor(parsed) : fallback
}

const LOOKBACK_DAYS = positiveIntegerEnv('CHAT_SYNC_LOOKBACK_DAYS', 30)
const MAX_SPACES = positiveIntegerEnv('CHAT_SYNC_MAX_SPACES', 60)
const MAX_MESSAGES_PER_SPACE = positiveIntegerEnv('CHAT_SYNC_MAX_MESSAGES', 200)

function normalizeName(value: string | null | undefined): string {
  return String(value ?? '').trim().replace(/\s+/g, ' ').toLowerCase()
}

async function refreshAccessToken(refreshToken: string): Promise<{ accessToken: string; refreshToken: string; expiresIn: number }> {
  const clientId = Deno.env.get('GOOGLE_CLIENT_ID')
  const clientSecret = Deno.env.get('GOOGLE_CLIENT_SECRET')
  if (!clientId || !clientSecret) throw new Error('Secrets OAuth google manquants')
  const response = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ client_id: clientId, client_secret: clientSecret, refresh_token: refreshToken, grant_type: 'refresh_token' }),
  })
  if (!response.ok) throw new Error(`Rafraîchissement google refusé (${response.status})`)
  const data = await response.json()
  return { accessToken: data.access_token, refreshToken: data.refresh_token ?? refreshToken, expiresIn: Number(data.expires_in ?? 3600) }
}

async function chatGet(token: string, url: string): Promise<any | null> {
  const response = await fetch(url, { headers: { Authorization: `Bearer ${token}` } })
  if (!response.ok) {
    // Compte Google perso ou API Chat non activée pour le Workspace : pas fatal.
    if (response.status === 403 || response.status === 404) return null
    throw new Error(`Google Chat API ${response.status}`)
  }
  return response.json()
}

type ChatSpace = { name: string; spaceType: string; displayName: string | null }

async function listSpaces(token: string): Promise<ChatSpace[]> {
  const spaces: ChatSpace[] = []
  let pageToken: string | null = null
  do {
    const url = `https://chat.googleapis.com/v1/spaces?pageSize=100${pageToken ? `&pageToken=${encodeURIComponent(pageToken)}` : ''}`
    const page = await chatGet(token, url)
    if (!page) break
    for (const space of (page.spaces ?? []) as any[]) {
      spaces.push({ name: space.name, spaceType: space.spaceType ?? space.type ?? 'SPACE', displayName: space.displayName ?? null })
    }
    pageToken = page.nextPageToken ?? null
  } while (pageToken && spaces.length < MAX_SPACES)
  return spaces.slice(0, MAX_SPACES)
}

async function listMessages(token: string, spaceName: string, sinceIso: string): Promise<any[]> {
  const messages: any[] = []
  let pageToken: string | null = null
  const filter = encodeURIComponent(`createTime > "${sinceIso}"`)
  do {
    const url = `https://chat.googleapis.com/v1/${spaceName}/messages?pageSize=100&filter=${filter}&orderBy=${encodeURIComponent('createTime desc')}${pageToken ? `&pageToken=${encodeURIComponent(pageToken)}` : ''}`
    const page = await chatGet(token, url)
    if (!page) break
    messages.push(...(page.messages ?? []))
    pageToken = page.nextPageToken ?? null
  } while (pageToken && messages.length < MAX_MESSAGES_PER_SPACE)
  return messages.slice(0, MAX_MESSAGES_PER_SPACE)
}

Deno.serve(async (request) => {
  if (request.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (request.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
  const startedAt = new Date().toISOString()
  let syncJobId: string | null = null
  try {
    const authorization = request.headers.get('Authorization')
    if (!authorization) return json({ error: 'Authentification requise' }, 401)
    const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')
    const { data: { user }, error: userError } = await supabase.auth.getUser(authorization.replace('Bearer ', ''))
    if (userError || !user) return json({ error: 'Session invalide' }, 401)
    const { organizationId } = await request.json().catch(() => ({}))
    if (!organizationId) return json({ error: 'Paramètres invalides' }, 400)
    const { data: membership } = await supabase.from('memberships').select('id').eq('organization_id', organizationId).eq('user_id', user.id).maybeSingle()
    if (!membership) return json({ error: 'Accès refusé' }, 403)
    const { data: connector } = await supabase.from('connectors').select('id,metadata').eq('organization_id', organizationId).eq('user_id', user.id).eq('provider', 'google').maybeSingle()
    if (!connector) return json({ error: 'Connecteur Google introuvable. Connecte Google Workspace d’abord.' }, 404)
    const { data: tokenRows, error: tokenError } = await supabase.rpc('get_oauth_tokens_server', { p_connector_id: connector.id })
    const oauth = tokenRows?.[0]
    if (tokenError || !oauth) return json({ error: 'Jetons OAuth absents. Reconnecte Google Workspace.' }, 401)

    const { data: job } = await supabase.from('sync_jobs').insert({
      organization_id: organizationId, connector_id: connector.id, user_id: user.id, provider: 'google',
      job_type: 'google_chat_sync', status: 'running', current_step: 'Connexion au fournisseur', progress: 10, started_at: startedAt, payload: {},
    }).select('id').single()
    syncJobId = job?.id ?? null

    let accessToken = oauth.access_token as string | null
    let refreshToken = oauth.refresh_token as string | null
    const expiresSoon = !oauth.expires_at || new Date(oauth.expires_at).getTime() < Date.now() + 90_000
    if ((!accessToken || expiresSoon) && refreshToken) {
      const refreshed = await refreshAccessToken(refreshToken)
      accessToken = refreshed.accessToken
      refreshToken = refreshed.refreshToken
      await supabase.rpc('store_oauth_tokens_server', { p_organization_id: organizationId, p_connector_id: connector.id, p_provider_account_id: oauth.provider_account_id, p_access_token: accessToken, p_refresh_token: refreshToken, p_expires_at: new Date(Date.now() + refreshed.expiresIn * 1000).toISOString() })
    }
    if (!accessToken) throw new Error('Jeton OAuth indisponible')

    // Nom du titulaire du compte pour ne pas se créer soi-même comme contact.
    const { data: profile } = await supabase.from('profiles').select('full_name').eq('id', user.id).maybeSingle()
    const selfName = normalizeName(profile?.full_name ?? user.email)

    // Contacts déjà connus, indexés par nom (pour rattacher sans dupliquer).
    const { data: existingContacts } = await supabase.from('contacts')
      .select('id,full_name').eq('organization_id', organizationId).is('merged_into_contact_id', null)
    const contactByName = new Map<string, string>()
    for (const contact of (existingContacts ?? []) as any[]) {
      const key = normalizeName(contact.full_name)
      if (key && !contactByName.has(key)) contactByName.set(key, contact.id)
    }

    const sinceIso = new Date(Date.now() - LOOKBACK_DAYS * 86_400_000).toISOString()
    const spaces = await listSpaces(accessToken)
    if (syncJobId) await supabase.from('sync_jobs').update({ current_step: 'Lecture des conversations Google Chat', progress: 40 }).eq('id', syncJobId)

    let messagesSynced = 0
    let contactsCreated = 0
    let contactsMatched = 0
    const errors: string[] = []

    const resolveContact = async (displayName: string, allowCreate: boolean): Promise<string | null> => {
      const key = normalizeName(displayName)
      if (!key || key === selfName) return null
      const known = contactByName.get(key)
      if (known) { contactsMatched++; return known }
      if (!allowCreate) return null
      const { data: created, error: createError } = await supabase.from('contacts')
        .insert({ organization_id: organizationId, full_name: displayName.trim(), owner_user_id: user.id, is_tracked: true, email: null })
        .select('id').single()
      if (createError || !created) return null
      contactByName.set(key, created.id)
      // Nouveau contact issu de Chat → catégorisé « Collègue » (réglable à la main).
      await supabase.from('person_settings').upsert({
        organization_id: organizationId, contact_id: created.id, relationship_type: 'Collègue', updated_by: user.id, updated_at: new Date().toISOString(),
      }, { onConflict: 'organization_id,contact_id' })
      contactsCreated++
      return created.id
    }

    for (const space of spaces) {
      try {
        const isDm = space.spaceType === 'DIRECT_MESSAGE'
        const messages = await listMessages(accessToken, space.name, sinceIso)
        if (!messages.length) continue

        const { data: thread } = await supabase.from('communication_threads').upsert({
          organization_id: organizationId, provider: 'google_chat', external_thread_id: space.name,
          subject: space.displayName ?? (isDm ? 'Message direct' : 'Espace Google Chat'), updated_at: new Date().toISOString(),
        }, { onConflict: 'organization_id,provider,external_thread_id' }).select('id').single()
        if (!thread) continue

        for (const message of messages) {
          const sender = message.sender ?? {}
          if (sender.type && sender.type !== 'HUMAN') continue
          const senderName = normalizeName(sender.displayName)
          if (!senderName) continue
          const fromSelf = senderName === selfName
          // DM : on peut créer le contact inconnu ; espace nommé : rattachement seulement.
          const contactId = fromSelf ? null : await resolveContact(sender.displayName, isDm)
          if (!fromSelf && !contactId) continue

          const { error: messageError } = await supabase.from('communication_messages').upsert({
            organization_id: organizationId, thread_id: thread.id, contact_id: contactId, provider: 'google_chat',
            external_message_id: message.name, direction: fromSelf ? 'outbound' : 'inbound',
            sent_at: message.createTime ?? new Date().toISOString(),
            subject: space.displayName ?? (isDm ? 'Message direct' : 'Espace Google Chat'),
            body_text: null,
            metadata: { space_type: space.spaceType, sender: sender.displayName ?? null, analyzed_without_body_storage: true },
          }, { onConflict: 'organization_id,provider,external_message_id' })
          if (!messageError) messagesSynced++
        }
      } catch (spaceError) {
        errors.push(spaceError instanceof Error ? spaceError.message : String(spaceError))
      }
    }

    if (syncJobId) await supabase.from('sync_jobs').update({ current_step: 'Synchronisation terminée', progress: 100, status: 'succeeded', completed_at: new Date().toISOString(), payload: { messages: messagesSynced, contacts_created: contactsCreated, contacts_matched: contactsMatched, errors: errors.slice(0, 5) } }).eq('id', syncJobId)
    return json({ success: true, messages: messagesSynced, contactsCreated, contactsMatched, spaces: spaces.length, errors: errors.slice(0, 5) })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Synchronisation impossible'
    if (syncJobId) {
      const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')
      await supabase.from('sync_jobs').update({ status: 'failed', current_step: 'Échec de la synchronisation', error_code: 'GOOGLE_CHAT_SYNC_FAILED', error_message: message, completed_at: new Date().toISOString() }).eq('id', syncJobId)
    }
    return json({ error: message }, 500)
  }
})

// Ingestion manuelle d'un transcript déposé (glisser-déposer côté UI).
//
// Le client a déjà : (1) uploadé le fichier dans le bucket `tohu-documents`,
// (2) pré-créé une ligne `sync_jobs` (job_type='transcript_analysis'). Cette
// fonction télécharge le fichier, parse les formats .txt/.vtt/.srt en un
// transcript normalisé "Nom (m:ss) : texte", identifie les intervenants et les
// résout vers des contacts EXISTANTS (jamais de contact fantôme), crée
// meetings + meeting_participants + meeting_transcripts (même modèle que le
// webhook Read AI), puis lance l'analyse comportementale partagée
// (_shared/behavior-analysis.ts) pour enrichir le profil de chaque participant
// reconnu — avec traçabilité (source_type='manual_transcript_analysis').
//
// Aucune clé IA côté client : l'appel OpenRouter se fait ici, côté serveur.
import { createClient, type SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2'
import {
  analyze,
  asRecord,
  attributedTranscriptExcerpt,
  errorMessage,
  normalizedSpeaker,
  persistContactProfile,
  type UsageLogContext,
} from '../_shared/behavior-analysis.ts'
import { logAiUsage } from '../_shared/ai-usage.ts'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}
function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
}

// Nombre maximum d'intervenants analysés à chaud (budget d'exécution) — les
// éventuels suivants seront repris par le batch d'analyse existant.
const MAX_ANALYZED_PARTICIPANTS = 8
const MAX_TRANSCRIPT_CHARS = 1_000_000

type ParsedTranscript = { transcriptText: string; speakers: string[]; speakerMap: Record<string, string> }
type ContactRow = { id: string; full_name: string | null; email: string | null }

// ── Extraction engagements + moments depuis le transcript ──────────────────
// Le transcript est stocké (meeting_transcripts) : citer un verbatim est donc
// légitime. Un engagement n'est conservé que si sa phrase source apparaît
// réellement dans le transcript (garde-fou anti-invention).
type TranscriptEngagement = { content: string; confidence: number; due_date: string | null; source_quote: string | null; direction: 'inbound' | 'outbound' }
type TranscriptMoment = { title: string; summary: string | null; occurred_date: string | null; impact: 'friction' | 'reinforce' | 'milestone'; confidence: number }

function normCommitment(value: string): string {
  return value.toLowerCase().replace(/^nous\s*:\s*/, '').replace(/\s+—\s+échéance.*$/, '').replace(/[^\p{L}\p{N}]+/gu, ' ').trim()
}

async function extractTranscriptContext(name: string, transcriptText: string, usageLog?: UsageLogContext): Promise<{ engagements: TranscriptEngagement[]; moments: TranscriptMoment[] }> {
  const empty = { engagements: [] as TranscriptEngagement[], moments: [] as TranscriptMoment[] }
  const apiKey = Deno.env.get('OPENROUTER_API_KEY')
  if (!apiKey || !transcriptText.trim()) return empty
  const corpus = transcriptText.slice(0, 16000)
  const prompt = `À partir de ce transcript de réunion avec ${name}, relève deux choses, uniquement à partir de faits réellement présents (jamais inventé).

1) ENGAGEMENTS — promesses/actions que ${name} ("contact") OU nous ("nous") s'est engagé à faire :
- "text" : reformulation courte et actionnable ;
- "owner" : "contact" ou "nous" ;
- "due_date" : échéance AAAA-MM-JJ si mentionnée, sinon null ;
- "confidence" : 0 à 100 ;
- "source_quote" : la phrase EXACTE du transcript, copiée mot pour mot, qui prouve l'engagement (≤ 240 caractères) ; null si aucune.

2) MOMENTS QUI COMPTENT — jalons observables (avancées ET tensions), 4 à 10 :
- "title" court et factuel ; "summary" une phrase ou null ; "occurred_date" AAAA-MM-JJ ou null ;
- "impact" : "friction" | "reinforce" | "milestone" ; "confidence" 0 à 100.

Réponds uniquement en JSON : {"engagements":[{"text":"...","owner":"contact","due_date":null,"confidence":0,"source_quote":null}],"moments":[{"title":"...","summary":null,"occurred_date":null,"impact":"milestone","confidence":0}]}

Transcript :\n${corpus}`
  const response = await fetch('https://openrouter.ai/api/v1/chat/completions', {
    method: 'POST',
    headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json', 'X-Title': 'Tohu Transcript Context Extraction' },
    body: JSON.stringify({
      model: Deno.env.get('OPENROUTER_ANALYSIS_MODEL') ?? 'google/gemini-3.1-flash-lite',
      temperature: 0,
      response_format: { type: 'json_object' },
      max_tokens: 3000,
      messages: [{ role: 'user', content: prompt }],
    }),
  })
  if (!response.ok) throw new Error(`OpenRouter ${response.status}`)
  const data = await response.json()
  if (usageLog) await logAiUsage(usageLog.client, { organizationId: usageLog.organizationId, userId: usageLog.userId, fn: 'ingest-transcript:extractContext', model: Deno.env.get('OPENROUTER_ANALYSIS_MODEL') ?? 'google/gemini-3.1-flash-lite', usage: data?.usage })
  const raw = asRecord(data).choices
  const content = Array.isArray(raw) ? String(asRecord(asRecord(raw[0]).message).content ?? '{}') : '{}'
  const parsed = asRecord(JSON.parse(content))
  const normText = (v: string) => v.toLowerCase().replace(/\s+/g, ' ').trim()
  const corpusNorm = normText(corpus)
  const engagements = (Array.isArray(parsed.engagements) ? parsed.engagements : [])
    .map((entry) => asRecord(entry))
    .filter((entry) => typeof entry.text === 'string' && String(entry.text).trim().length > 3)
    .slice(0, 20)
    .map((entry) => {
      const owner = entry.owner === 'nous' ? 'nous' : 'contact'
      const text = String(entry.text).trim().slice(0, 300)
      const dueDate = typeof entry.due_date === 'string' && /^\d{4}-\d{2}-\d{2}/.test(entry.due_date) ? String(entry.due_date).slice(0, 10) : null
      const rawQuote = typeof entry.source_quote === 'string' ? entry.source_quote.trim().replace(/^[«"']\s*|\s*[»"']$/g, '').slice(0, 240) : ''
      const quoteVerified = rawQuote.length >= 8 && corpusNorm.includes(normText(rawQuote))
      // Qui doit honorer l'engagement se lit désormais sur `direction` (stockée en
      // source_direction), plus sur un préfixe "Nous : " dans le texte — même
      // convention que sync-email-analysis. L'avatar du répondant côté front
      // (EngagementAvatar) s'appuyait déjà sur ce champ, resté à null jusqu'ici.
      return {
        content: dueDate ? `${text} — échéance ${dueDate}` : text,
        confidence: Number.isFinite(Number(entry.confidence)) ? Math.max(0, Math.min(100, Number(entry.confidence))) : 50,
        due_date: dueDate,
        source_quote: quoteVerified ? rawQuote : null,
        direction: owner === 'nous' ? 'outbound' : 'inbound',
      }
    })
  const moments = (Array.isArray(parsed.moments) ? parsed.moments : [])
    .map((entry) => asRecord(entry))
    .filter((entry) => typeof entry.title === 'string' && String(entry.title).trim().length > 3)
    .slice(0, 12)
    .map((entry) => ({
      title: String(entry.title).trim().slice(0, 200),
      summary: typeof entry.summary === 'string' && String(entry.summary).trim() ? String(entry.summary).trim().slice(0, 400) : null,
      occurred_date: typeof entry.occurred_date === 'string' && /^\d{4}-\d{2}-\d{2}/.test(entry.occurred_date) ? String(entry.occurred_date).slice(0, 10) : null,
      impact: entry.impact === 'friction' ? 'friction' as const : entry.impact === 'reinforce' ? 'reinforce' as const : 'milestone' as const,
      confidence: Number.isFinite(Number(entry.confidence)) ? Math.max(0, Math.min(100, Number(entry.confidence))) : 50,
    }))
  return { engagements, moments }
}

// ── Parsing des formats de transcript ─────────────────────────────────────

function secondsToClock(totalSeconds: number): string {
  const s = Math.max(0, Math.floor(totalSeconds))
  const h = Math.floor(s / 3600)
  const m = Math.floor((s % 3600) / 60)
  const sec = s % 60
  const two = (n: number) => String(n).padStart(2, '0')
  return h > 0 ? `${h}:${two(m)}:${two(sec)}` : `${m}:${two(sec)}`
}

// "00:01:23.400" (VTT) ou "00:01:23,400" (SRT) ou "01:23" → secondes.
function parseTimestamp(raw: string): number | null {
  const cleaned = raw.trim().replace(',', '.')
  const match = cleaned.match(/^(?:(\d{1,2}):)?(\d{1,2}):(\d{2})(?:\.\d{1,3})?$/)
  if (!match) return null
  const h = match[1] ? Number(match[1]) : 0
  const m = Number(match[2])
  const sec = Number(match[3])
  return h * 3600 + m * 60 + sec
}

function cleanSpeakerName(raw: string): string {
  return raw.replace(/["<>]/g, '').replace(/\s+/g, ' ').trim().slice(0, 120)
}

function addLine(lines: string[], speakers: Set<string>, speaker: string, at: number | null, text: string): void {
  const name = cleanSpeakerName(speaker) || 'Participant'
  const body = text.replace(/\s+/g, ' ').trim()
  if (!body) return
  speakers.add(name)
  lines.push(at != null ? `${name} (${secondsToClock(at)}) : ${body}` : `${name} : ${body}`)
}

// Une ligne texte de type "Nom : propos" (avec horodatage optionnel).
const SPEAKER_LINE = /^(.+?)(?:\s+[([]?\d{1,2}:\d{2}(?::\d{2})?[)\]]?)?\s*:\s*(.+)$/

function parseTxt(raw: string): ParsedTranscript {
  const speakers = new Set<string>()
  const lines: string[] = []
  let lastSpeaker: string | null = null
  for (const rawLine of raw.split(/\r?\n/)) {
    const line = rawLine.trim()
    if (!line) continue
    const match = line.match(SPEAKER_LINE)
    // On exige un préfixe locuteur court et plausible (pas une phrase entière
    // ni une URL) pour éviter de confondre un ":" de ponctuation avec un
    // marqueur de locuteur.
    if (match && match[1].length <= 60 && !match[1].includes('http')) {
      lastSpeaker = cleanSpeakerName(match[1])
      addLine(lines, speakers, lastSpeaker, null, match[2])
    } else if (lastSpeaker) {
      // Continuation du dernier locuteur (paragraphe multi-lignes).
      addLine(lines, speakers, lastSpeaker, null, line)
    }
  }
  return { transcriptText: lines.join('\n'), speakers: [...speakers], speakerMap: Object.fromEntries([...speakers].map((s) => [s, s])) }
}

function parseCueBlocks(raw: string, timeSeparator: RegExp): ParsedTranscript {
  const speakers = new Set<string>()
  const lines: string[] = []
  const blocks = raw.replace(/^WEBVTT.*$/im, '').split(/\r?\n\r?\n+/)
  for (const block of blocks) {
    const blockLines = block.split(/\r?\n/).map((l) => l.trim()).filter(Boolean)
    if (!blockLines.length) continue
    let at: number | null = null
    const textLines: string[] = []
    for (const bl of blockLines) {
      const timeMatch = bl.match(timeSeparator)
      if (timeMatch) { at = parseTimestamp(timeMatch[1]); continue }
      if (/^\d+$/.test(bl) && textLines.length === 0) continue // index SRT
      textLines.push(bl)
    }
    if (!textLines.length) continue
    let joined = textLines.join(' ')
    // Locuteur : balise VTT "<v Nom>" ou préfixe "Nom:".
    let speaker = 'Participant'
    const voice = joined.match(/^<v\s+([^>]+)>/i)
    if (voice) {
      speaker = voice[1]
      joined = joined.replace(/^<v\s+[^>]+>/i, '')
    } else {
      const prefixed = joined.match(/^([^:]{1,60}):\s*(.+)$/)
      if (prefixed && !prefixed[1].includes('http')) { speaker = prefixed[1]; joined = prefixed[2] }
    }
    joined = joined.replace(/<\/?[^>]+>/g, ' ') // retire les balises restantes
    addLine(lines, speakers, speaker, at, joined)
  }
  return { transcriptText: lines.join('\n'), speakers: [...speakers], speakerMap: Object.fromEntries([...speakers].map((s) => [s, s])) }
}

function parseTranscript(fileName: string, raw: string): ParsedTranscript {
  const ext = (fileName.split('.').pop() ?? '').toLowerCase()
  const text = raw.slice(0, MAX_TRANSCRIPT_CHARS)
  if (ext === 'vtt') return parseCueBlocks(text, /(\d{1,2}:\d{2}(?::\d{2})?[.,]\d{1,3})\s*-->/)
  if (ext === 'srt') return parseCueBlocks(text, /(\d{1,2}:\d{2}:\d{2}[.,]\d{1,3})\s*-->/)
  return parseTxt(text)
}

// ── Résolution intervenant → contact existant (conservatrice) ─────────────

function matchSpeakerToContact(speaker: string, contacts: ContactRow[]): ContactRow | null {
  const nSpeaker = normalizedSpeaker(speaker)
  if (nSpeaker.length < 3) return null
  const exact = contacts.filter((c) => normalizedSpeaker(c.full_name) === nSpeaker)
  if (exact.length === 1) return exact[0]
  if (exact.length > 1) return null // homonymes → on n'attribue pas
  // Tous les mots du locuteur présents dans un unique nom de contact
  // (ex. "Marie" → "Marie Durand" si elle est la seule "Marie").
  const speakerTokens = nSpeaker.split(' ').filter(Boolean)
  const candidates = contacts.filter((c) => {
    const nameTokens = normalizedSpeaker(c.full_name).split(' ').filter(Boolean)
    return speakerTokens.length > 0 && speakerTokens.every((t) => nameTokens.includes(t))
  })
  return candidates.length === 1 ? candidates[0] : null
}

// ── Handler ───────────────────────────────────────────────────────────────

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (req.method !== 'POST') return json({ error: 'Method not allowed' }, 405)

  const authorization = req.headers.get('Authorization')
  if (!authorization) return json({ error: 'Authentification requise.' }, 401)

  const supabaseUrl = Deno.env.get('SUPABASE_URL') ?? ''
  const userClient = createClient(supabaseUrl, Deno.env.get('SUPABASE_ANON_KEY') ?? '', {
    global: { headers: { Authorization: authorization } },
  })
  const admin: SupabaseClient = createClient(supabaseUrl, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')

  const { data: { user }, error: userError } = await userClient.auth.getUser()
  if (userError || !user) return json({ error: 'Session invalide.' }, 401)

  const { jobId } = await req.json().catch(() => ({})) as { jobId?: string }
  if (!jobId) return json({ error: 'jobId manquant.' }, 400)

  // Le job doit appartenir au caller (RLS via userClient) et être du bon type.
  const { data: job, error: jobError } = await userClient.from('sync_jobs')
    .select('id,organization_id,user_id,job_type,status,payload')
    .eq('id', jobId).maybeSingle()
  if (jobError || !job) return json({ error: 'Job introuvable.' }, 404)
  if (job.job_type !== 'transcript_analysis' || job.user_id !== user.id) return json({ error: 'Job non autorisé.' }, 403)

  const organizationId = job.organization_id as string
  const payload = asRecord(job.payload)
  const storagePath = String(payload.storage_path ?? '')
  const fileName = String(payload.file_name ?? 'transcript.txt')
  const meetingTitle = (typeof payload.title === 'string' && payload.title.trim()) ? payload.title.trim() : `Transcript — ${fileName}`
  const startsAt = typeof payload.meeting_date === 'string' && payload.meeting_date ? payload.meeting_date : new Date().toISOString()
  // Défense en profondeur : le chemin doit vivre dans le dossier de l'org.
  if (!storagePath || !storagePath.startsWith(`${organizationId}/`)) {
    await failJob(admin, jobId, 'Chemin de fichier invalide.', 'invalid_path')
    return json({ error: 'Chemin de fichier invalide.' }, 400)
  }

  const setStep = (step: string, progress: number) =>
    admin.from('sync_jobs').update({ status: 'running', current_step: step, progress }).eq('id', jobId)

  try {
    await admin.from('sync_jobs').update({ status: 'running', started_at: new Date().toISOString(), current_step: 'Lecture du fichier', progress: 5 }).eq('id', jobId)

    // 1) Téléchargement + parsing.
    const { data: fileData, error: downloadError } = await admin.storage.from('tohu-documents').download(storagePath)
    if (downloadError || !fileData) throw new Error(`Fichier introuvable : ${downloadError?.message ?? storagePath}`)
    const raw = await fileData.text()
    await setStep('Analyse du transcript', 20)
    const parsed = parseTranscript(fileName, raw)
    if (!parsed.transcriptText.trim()) throw new Error('Transcript vide ou illisible.')

    // 2) Résolution des intervenants vers des contacts existants.
    await setStep('Identification des intervenants', 35)
    const { data: contactRows, error: contactError } = await admin.from('contacts')
      .select('id,full_name,email')
      .eq('organization_id', organizationId)
      .is('merged_into_contact_id', null)
      .limit(5000)
    if (contactError) throw contactError
    const contacts = (contactRows ?? []) as ContactRow[]
    const resolved = parsed.speakers.map((speaker) => ({ speaker, contact: matchSpeakerToContact(speaker, contacts) }))

    // 3) Réunion + participants + transcript (idempotent sur le job).
    await setStep('Enregistrement de la réunion', 45)
    const { data: meetingRow, error: meetingError } = await admin.from('meetings').upsert({
      organization_id: organizationId,
      owner_user_id: job.user_id,
      external_event_id: `manual:${jobId}`,
      title: meetingTitle,
      starts_at: startsAt,
      platform: 'manual_upload',
      description: null,
      raw_payload: { source: 'manual_upload', file_name: fileName, storage_path: storagePath, speakers: parsed.speakers },
    }, { onConflict: 'organization_id,external_event_id' }).select('id').single()
    if (meetingError || !meetingRow) throw new Error(meetingError?.message ?? 'Réunion non enregistrée.')
    const meetingId = meetingRow.id as string

    await admin.from('meeting_participants').delete().eq('organization_id', organizationId).eq('meeting_id', meetingId)
    const participantRows = resolved.map(({ speaker, contact }) => ({
      organization_id: organizationId,
      meeting_id: meetingId,
      contact_id: contact?.id ?? null,
      email: contact?.email ?? null,
      display_name: speaker,
      name: speaker,
      role_in_meeting: 'attendee',
      is_current_user: false,
    }))
    if (participantRows.length) {
      const { error: participantError } = await admin.from('meeting_participants').insert(participantRows)
      if (participantError) throw participantError
    }

    await admin.from('meeting_transcripts').upsert({
      organization_id: organizationId,
      meeting_id: meetingId,
      provider: 'manual_upload',
      transcript_text: parsed.transcriptText,
      speaker_map: parsed.speakerMap,
      // L'uploadeur atteste du consentement via la case à cocher de l'UI.
      consent_status: payload.consent === false ? 'unknown' : 'granted',
    }, { onConflict: 'meeting_id,provider' })

    // 4) Analyse comportementale par intervenant reconnu (avec extrait attribué).
    const analysable = resolved
      .filter((r): r is { speaker: string; contact: ContactRow } => Boolean(r.contact))
      .map((r) => ({ ...r, excerpt: attributedTranscriptExcerpt(parsed.transcriptText, [r.speaker, r.contact.email ?? '', r.contact.full_name ?? '']) }))
      .filter((r) => Boolean(r.excerpt))
      .slice(0, MAX_ANALYZED_PARTICIPANTS)

    let profilesUpdated = 0
    const analysisErrors: string[] = []
    for (let i = 0; i < analysable.length; i++) {
      const { speaker, contact, excerpt } = analysable[i]
      await setStep(`Analyse comportementale (${i + 1}/${analysable.length})`, 55 + Math.round(((i) / Math.max(1, analysable.length)) * 35))
      try {
        const [{ count: msgCount }, { count: mtgCount }, { data: prev }] = await Promise.all([
          admin.from('communication_messages').select('id', { count: 'exact', head: true }).eq('organization_id', organizationId).eq('contact_id', contact.id).eq('direction', 'inbound'),
          admin.from('meeting_participants').select('id', { count: 'exact', head: true }).eq('organization_id', organizationId).eq('contact_id', contact.id),
          admin.from('cognitive_profiles').select('cognitive_profile_data,updated_from').eq('organization_id', organizationId).eq('contact_id', contact.id).eq('profile_version', 1).maybeSingle(),
        ])
        const messageCount = msgCount ?? 0
        const meetingCount = mtgCount ?? 0
        const interactionCount = messageCount + meetingCount
        const previousProfile = asRecord(prev?.cognitive_profile_data)
        const prevUpdatedFrom = Array.isArray(prev?.updated_from) ? prev!.updated_from.map(String) : []
        const result = await analyze(contact.full_name ?? speaker, 'contact', [excerpt as string], previousProfile, interactionCount, { client: admin, organizationId, userId: job.user_id as string })
        await persistContactProfile(admin, {
          organizationId,
          contactId: contact.id,
          result,
          messageCount,
          meetingCount,
          interactionCount,
          updatedFrom: [...new Set([...prevUpdatedFrom, 'manual_upload', 'meeting_transcript'])],
          signalSource: 'manual_transcript_analysis',
          sourceRef: `transcript:${meetingId}`,
          observedAt: startsAt,
        })
        profilesUpdated++
      } catch (error) {
        analysisErrors.push(`${speaker}: ${errorMessage(error)}`)
      }
    }

    // 5) Engagements pris + moments qui comptent, rattachés au contact ciblé
    // (fiche d'origine si fournie, sinon le premier intervenant reconnu).
    let commitmentsAdded = 0
    const targetContactId = String(payload.contact_id ?? '')
    const targetContact = analysable.find((r) => r.contact.id === targetContactId)?.contact ?? analysable[0]?.contact ?? null
    if (targetContact) {
      await setStep('Extraction des engagements', 92)
      try {
        const ctx = await extractTranscriptContext(targetContact.full_name ?? 'Contact', parsed.transcriptText, { client: admin, organizationId, userId: job.user_id as string })
        if (ctx.engagements.length) {
          const { data: existing } = await admin.from('person_memory_entries')
            .select('content').eq('organization_id', organizationId).eq('contact_id', targetContact.id).eq('entry_type', 'commitment')
          const seen = new Set((existing ?? []).map((r) => normCommitment(String(r.content ?? ''))))
          const fresh = ctx.engagements
            .filter((e) => { const key = normCommitment(e.content); if (seen.has(key)) return false; seen.add(key); return true })
            .map((e) => ({
              organization_id: organizationId,
              contact_id: targetContact.id,
              author_user_id: job.user_id,
              entry_type: 'commitment',
              content: e.content,
              visibility: 'workspace',
              processing_status: 'ready',
              source_type: 'manual_transcript_analysis',
              source_label: 'Tohu · transcript',
              confidence: e.confidence,
              inference_level: 'strong_inference',
              observed_at: startsAt,
              source_excerpt: e.source_quote,
              source_occurred_at: startsAt,
              source_direction: e.direction,
            }))
          if (fresh.length) {
            const { error: memErr } = await admin.from('person_memory_entries').insert(fresh)
            if (memErr) analysisErrors.push(`engagements: ${memErr.message}`); else commitmentsAdded = fresh.length
          }
        }
        if (ctx.moments.length) {
          const { data: existingMoments } = await admin.from('person_key_moments')
            .select('title').eq('organization_id', organizationId).eq('contact_id', targetContact.id)
          const seenM = new Set((existingMoments ?? []).map((r) => normCommitment(String(r.title ?? ''))))
          const freshM = ctx.moments
            .filter((m) => { const key = normCommitment(m.title); if (seenM.has(key)) return false; seenM.add(key); return true })
            .map((m) => ({
              organization_id: organizationId,
              contact_id: targetContact.id,
              occurred_at: m.occurred_date ? new Date(m.occurred_date).toISOString() : startsAt,
              title: m.title,
              summary: m.summary,
              impact: m.impact,
              confidence: m.confidence,
              source_label: 'Tohu · transcript',
            }))
          if (freshM.length) {
            const { error: momErr } = await admin.from('person_key_moments').insert(freshM)
            if (momErr) analysisErrors.push(`moments: ${momErr.message}`)
          }
        }
      } catch (error) {
        analysisErrors.push(`engagements: ${errorMessage(error)}`)
      }
    }

    const matched = resolved.filter((r): r is { speaker: string; contact: ContactRow } => Boolean(r.contact))
    const unmatched = resolved.filter((r) => !r.contact).map((r) => r.speaker)
    const result = {
      meeting_id: meetingId,
      speakers_total: parsed.speakers.length,
      participants_matched: matched.length,
      profiles_updated: profilesUpdated,
      commitments_added: commitmentsAdded,
      matched_participants: matched.map((r) => ({ contact_id: r.contact.id, name: r.contact.full_name ?? r.speaker })),
      speakers_unmatched: unmatched,
      analysis_errors: analysisErrors,
    }
    await admin.from('sync_jobs').update({
      status: 'succeeded',
      current_step: 'Terminé',
      progress: 100,
      completed_at: new Date().toISOString(),
      payload: { ...payload, result },
    }).eq('id', jobId)

    return json({ success: true, ...result })
  } catch (error) {
    const message = errorMessage(error)
    await failJob(admin, jobId, message, 'ingest_failed')
    return json({ error: message }, 500)
  }
})

async function failJob(admin: SupabaseClient, jobId: string, message: string, code: string): Promise<void> {
  await admin.from('sync_jobs').update({
    status: 'failed',
    error_message: message.slice(0, 500),
    error_code: code,
    completed_at: new Date().toISOString(),
  }).eq('id', jobId)
}

// Cœur d'analyse comportementale partagé — source unique du "cerveau" Tohu.
//
// Extrait de sync-email-analysis pour être réutilisé sans duplication par
// l'ingestion manuelle de transcripts (ingest-transcript). Contient : le
// contrat de sortie JSON (schema_version 3), l'appel OpenRouter côté serveur
// (`analyze`), les transformations vers `behavioral_signals`, l'attribution
// des lignes de transcript à un locuteur, et l'écriture (upsert) d'un profil
// cognitif de contact (`persistContactProfile`).
//
// Toute évolution du prompt / du schéma se fait ICI et bénéficie aux deux
// chemins (email + transcript) simultanément.
import type { SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { logAiUsage } from './ai-usage.ts'

export type RelationshipAxisResult = {
  status?: string
  score?: number | null
  observation?: string | null
  confidence?: number | null
  evidence?: string[]
}

export type AccountRelationResult = {
  status?: string
  category?: string | null
  observation?: string | null
  confidence?: number | null
  evidence?: string[]
}

export type Analysis = {
  executive_summary?: string
  cognitive_mode?: string
  cognitive_mode_confidence?: number
  global_confidence?: number
  behavioral_analysis_data?: Array<{ trait?: string; observation?: string; confidence?: number }>
  communication_style_data?: Record<string, unknown>
  cognitive_profile_data?: Record<string, unknown>
  // Axes du score relationnel PERSONNE (Confiance/Satisfaction) — distincts du
  // profil de style de communication ci-dessus. Nécessitent une lecture du
  // contenu réel des échanges (pas seulement leurs métadonnées), d'où leur
  // extraction ici plutôt que dans score-batch (pur calcul, sans IA).
  trust?: RelationshipAxisResult
  satisfaction?: RelationshipAxisResult
  // Catégorisation COMPTE (Prospect/Client/Partenaire/Fournisseur/Investisseur) :
  // indice par contact, agrégé au niveau compte par score-batch. Uniquement
  // pertinent pour role="contact" (une seule entreprise externe) — toujours
  // "insufficient" pour role="responsable" (auto-profil interne, multi-comptes).
  account_relation?: AccountRelationResult
}

const STATUS_SCHEMA = { type: 'string', enum: ['observed', 'emerging', 'insufficient'] }
const NULLABLE_NUMBER_SCHEMA = { type: ['number', 'null'] }
export const NULLABLE_STRING_SCHEMA = { type: ['string', 'null'] }
const SOURCE_TYPES_SCHEMA = {
  type: 'array',
  items: { type: 'string', enum: ['email', 'meeting_transcript', 'slack'] },
}

// Catégories inférables du contenu d'échanges B2B — distinctes des catégories
// purement internes (Collègue/Interne/Réseau) qui ne concernent pas un compte
// externe et ne sont donc jamais suggérées ici.
export const ACCOUNT_RELATION_CATEGORIES = ['Prospect', 'Client', 'Partenaire', 'Fournisseur / Prestataire', 'Investisseur'] as const

export function strictObject(properties: Record<string, unknown>): Record<string, unknown> {
  return { type: 'object', properties, required: Object.keys(properties), additionalProperties: false }
}

const INTERPERSONAL_AXIS_SCHEMA = strictObject({
  status: STATUS_SCHEMA,
  score: NULLABLE_NUMBER_SCHEMA,
  label: NULLABLE_STRING_SCHEMA,
  observation: NULLABLE_STRING_SCHEMA,
  confidence: NULLABLE_NUMBER_SCHEMA,
  evidence_count: { type: 'integer', minimum: 0 },
  source_types: SOURCE_TYPES_SCHEMA,
  evolution: { type: ['string', 'null'], enum: ['rising', 'stable', 'declining', 'mixed', null] },
})

const PRIMARY_AXIS_SCHEMA = strictObject({
  status: STATUS_SCHEMA,
  raw_score: NULLABLE_NUMBER_SCHEMA,
  margin_pts: NULLABLE_NUMBER_SCHEMA,
  trend_pts: NULLABLE_NUMBER_SCHEMA,
  trend_label: { type: ['string', 'null'], enum: ['rising', 'stable', 'declining', null] },
  observation: NULLABLE_STRING_SCHEMA,
  confidence: NULLABLE_NUMBER_SCHEMA,
  evidence: { type: 'array', items: { type: 'string' } },
  evidence_count: { type: 'integer', minimum: 0 },
  source_types: SOURCE_TYPES_SCHEMA,
})

const SECONDARY_AXIS_SCHEMA = strictObject({
  status: STATUS_SCHEMA,
  score: NULLABLE_NUMBER_SCHEMA,
  observation: NULLABLE_STRING_SCHEMA,
  confidence: NULLABLE_NUMBER_SCHEMA,
  evidence_count: { type: 'integer', minimum: 0 },
  source_types: SOURCE_TYPES_SCHEMA,
})

// « Comment aborder cette personne » : scénarios contextuels do/don't déduits des
// preuves (jamais générique). Nourrit les listes À faire / À éviter de la fiche.
const APPROACH_SCENARIO_SCHEMA = strictObject({
  context: { type: 'string' },
  summary: NULLABLE_STRING_SCHEMA,
  do: { type: 'array', items: { type: 'string' } },
  dont: { type: 'array', items: { type: 'string' } },
})

const PRIMARY_AXES_OBJECT_SCHEMA = strictObject({
  rythme: PRIMARY_AXIS_SCHEMA,
  argumentation: PRIMARY_AXIS_SCHEMA,
  engagement: PRIMARY_AXIS_SCHEMA,
  registre: PRIMARY_AXIS_SCHEMA,
  tonalite: PRIMARY_AXIS_SCHEMA,
  espace_parole: PRIMARY_AXIS_SCHEMA,
})

// Axes Confiance/Satisfaction du score relationnel PERSONNE (doc 5-axes) :
// échelle qualité (0=faible, 100=fort), pas une échelle pôle-à-pôle comme les
// axes de style ci-dessus. Nécessitent une preuve datée pour compter.
const RELATIONSHIP_AXIS_SCHEMA = strictObject({
  status: STATUS_SCHEMA,
  score: NULLABLE_NUMBER_SCHEMA,
  observation: NULLABLE_STRING_SCHEMA,
  confidence: NULLABLE_NUMBER_SCHEMA,
  evidence: { type: 'array', items: { type: 'string' } },
  evidence_count: { type: 'integer', minimum: 0 },
  source_types: SOURCE_TYPES_SCHEMA,
})

// Catégorisation COMPTE — même logique de preuve que trust/satisfaction
// (jamais déduite du volume), mais une catégorie plutôt qu'un score continu.
const ACCOUNT_RELATION_SCHEMA = strictObject({
  status: STATUS_SCHEMA,
  category: { type: ['string', 'null'], enum: [...ACCOUNT_RELATION_CATEGORIES, null] },
  observation: NULLABLE_STRING_SCHEMA,
  confidence: NULLABLE_NUMBER_SCHEMA,
  evidence: { type: 'array', items: { type: 'string' } },
  evidence_count: { type: 'integer', minimum: 0 },
  source_types: SOURCE_TYPES_SCHEMA,
})

export const COGNITIVE_PROFILE_RESPONSE_FORMAT = {
  type: 'json_schema',
  json_schema: {
    name: 'tohu_cognitive_profile_v3',
    strict: true,
    schema: strictObject({
      executive_summary: NULLABLE_STRING_SCHEMA,
      cognitive_mode: NULLABLE_STRING_SCHEMA,
      cognitive_mode_confidence: { type: 'number', minimum: 0, maximum: 100 },
      global_confidence: { type: 'number', minimum: 0, maximum: 100 },
      trust: RELATIONSHIP_AXIS_SCHEMA,
      satisfaction: RELATIONSHIP_AXIS_SCHEMA,
      account_relation: ACCOUNT_RELATION_SCHEMA,
      cognitive_profile_data: strictObject({
