Nouveaux extraits :\n${corpus}`
  const requestAnalysis = async (retry: boolean): Promise<Analysis> => {
    const response = await fetch('https://openrouter.ai/api/v1/chat/completions', {
      signal,
      method: 'POST',
      headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json', 'HTTP-Referer': Deno.env.get('SITE_URL') ?? 'https://tohu.app', 'X-Title': 'Tohu Email Behavior Analysis' },
      body: JSON.stringify({
        // Modèle dédié à l'analyse comportementale (découplé du chat Ask Tohu).
        // Surchargable via OPENROUTER_ANALYSIS_MODEL sans toucher aux autres fonctions.
        model,
        temperature: retry ? 0 : 0.1,
        response_format: COGNITIVE_PROFILE_RESPONSE_FORMAT,
        // Empêche OpenRouter de choisir un fournisseur qui ignorerait le
        // JSON Schema et retomberait silencieusement sur l'ancien format.
        provider: { require_parameters: true },
        max_tokens: retry ? 7000 : 6000,
        messages: [{
          role: 'user',
          content: retry
            ? `${prompt}\n\nIMPORTANT : la tentative précédente a produit un JSON invalide, tronqué ou dans un ancien schéma. Repars exclusivement du contrat ci-dessus : cognitive_profile_data.schema_version doit valoir 3 et les six primary_axes doivent tous être présents. Réponds de façon compacte, sans Markdown ni commentaire avant ou après l'objet JSON, et ferme impérativement toutes les structures JSON.`
            : prompt,
        }],
      }),
    })
    if (!response.ok) throw new Error(`OpenRouter ${response.status}`)
    const data = await response.json()
    if (usageLog) await logAiUsage(usageLog.client, { organizationId: usageLog.organizationId, userId: usageLog.userId, fn: 'behavior-analysis:analyze', model, usage: data?.usage })
    const content = openRouterContent(data)
    try {
      const result = extractJson(content)
      assertCurrentCognitiveSchema(asRecord(result.cognitive_profile_data))
      return result
    } catch (error) {
      // Ne jamais journaliser `content` : il peut contenir des paraphrases
      // issues des emails. Les métadonnées suffisent au diagnostic.
      console.warn('Réponse comportementale invalide', {
        retry,
        finishReason: data?.choices?.[0]?.finish_reason ?? null,
        contentLength: content.length,
        validationError: errorMessage(error),
      })
      throw error
    }
  }

  try {
    return await requestAnalysis(false)
  } catch (error) {
    if (!isRetriableAnalysisError(error)) throw error
    return await requestAnalysis(true)
  }
}

// ── Attribution des lignes de transcript à un locuteur ────────────────────
// Réutilisé par sync-email-analysis (loadMeetingCorpus) et par l'ingestion
// manuelle de transcript.

export function normalizedSpeaker(value: string | null | undefined): string {
  return String(value ?? '')
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()
}

/** Une transcription n'est utilisée que si le préfixe de locuteur correspond
 * exactement à une identité connue du contact. En cas d'ambiguïté, elle reste
 * visible dans l'historique mais n'alimente pas l'inférence comportementale. */
export function attributedTranscriptExcerpt(transcript: string, identities: string[]): string | null {
  const speakers = new Set(identities
    .flatMap((identity) => {
      const email = cleanEmail(identity)
      return [identity, email.includes('@') ? email.split('@')[0] : '']
    })
    .map(normalizedSpeaker)
    .filter((identity) => identity.length >= 4))
  if (!speakers.size) return null

  const attributed = String(transcript ?? '').split(/\r?\n/).flatMap((line) => {
    const match = line.trim().match(/^(.+?)(?:\s+\(\d{1,2}:\d{2}(?::\d{2})?\))?\s*:\s*(.+)$/)
    if (!match || !speakers.has(normalizedSpeaker(match[1]))) return []
    const content = sanitizeBody(match[2])
    return content ? [content] : []
  })
  if (!attributed.length) return null
  return `[Transcription de réunion]\n${attributed.join('\n')}`.slice(0, 2400)
}

// ── Écriture du profil cognitif d'un contact ──────────────────────────────

export type PersistContactProfileParams = {
  organizationId: string
  contactId: string
  result: Analysis
  messageCount: number
  meetingCount: number
  interactionCount: number
  updatedFrom: string[]
  signalSource: string
  /** Défaut : `sync:${now}`. Ex. transcript : `transcript:${meetingId}`. */
  sourceRef?: string
  /** Défaut : maintenant. Ex. transcript : date de la réunion. */
  observedAt?: string
}

/** Upsert du profil cognitif v3 d'un contact + insertion de ses signaux
 *  comportementaux dérivés. Source unique de la logique d'écriture, partagée
 *  entre l'analyse email et l'ingestion de transcript. Lève en cas d'échec
 *  pour que l'appelant journalise (les triggers calculent deduplication_key). */
export async function persistContactProfile(
  supabase: SupabaseClient,
  params: PersistContactProfileParams,
): Promise<{ profileId: string; signalCount: number }> {
  const { organizationId, contactId, result, messageCount, meetingCount, interactionCount, updatedFrom, signalSource } = params
  const cognitiveProfileData = asRecord(result.cognitive_profile_data)
  assertCurrentCognitiveSchema(cognitiveProfileData)
  const structuredSignals = structuredBehavioralSignals(cognitiveProfileData)
  const now = new Date().toISOString()
  const observedAt = params.observedAt ?? now
  const sourceRef = params.sourceRef ?? `sync:${now}`
  // Confiance/Satisfaction (score PERSONNE, 5 axes) : "insufficient" ne doit
  // jamais écraser une valeur déjà mesurée par un run précédent qui aurait
  // eu moins de matière — on ne régresse une mesure réelle vers null que si
  // ce run-ci l'a explicitement invalidée en trouvant un statut différent
  // n'est pas possible ici ; on garde donc simplement : mesuré si "observed"
  // ou "emerging" avec un score non nul, sinon null (zéro hallucination).
  const trust = result.trust?.status && result.trust.status !== 'insufficient' && result.trust.score != null ? result.trust : null
  const satisfaction = result.satisfaction?.status && result.satisfaction.status !== 'insufficient' && result.satisfaction.score != null ? result.satisfaction : null
  const accountRelation = result.account_relation?.status && result.account_relation.status !== 'insufficient'
    && result.account_relation.category && (ACCOUNT_RELATION_CATEGORIES as readonly string[]).includes(result.account_relation.category)
    ? result.account_relation : null
  const { data: cognitiveProfile, error: profileError } = await supabase.from('cognitive_profiles').upsert({
    organization_id: organizationId,
    contact_id: contactId,
    profile_version: 1,
    global_confidence: pct(result.global_confidence),
    summary: result.executive_summary ?? null,
    executive_summary: result.executive_summary ?? null,
    cognitive_mode: result.cognitive_mode ?? null,
    cognitive_mode_confidence: pct(result.cognitive_mode_confidence),
    behavioral_analysis_data: structuredSignals,
    communication_style_data: asRecord(cognitiveProfileData.secondary_axes),
    cognitive_profile_data: cognitiveProfileData,
    source_message_count: messageCount,
    source_meeting_count: meetingCount,
    source_interaction_count: interactionCount,
    maturity_level: maturityFor(interactionCount),
    analysis_version: 3,
    last_analyzed_at: now,
    updated_from: updatedFrom,
    updated_at: now,
    // evidence : faits datés concrets ayant réellement motivé le score (voir prompt
    // trust/satisfaction plus haut) — distinct de `observation` (synthèse générale).
    // Non écrasé par `[]`/absent : un run qui ne retrouve pas de preuve fraîche ne
    // doit pas effacer une preuve réelle déjà persistée par un run précédent.
    ...(trust ? { trust_score: pct(trust.score), trust_reasoning: trust.observation ?? null, trust_analyzed_at: now, ...(trust.evidence?.length ? { trust_evidence: trust.evidence } : {}) } : {}),
    ...(satisfaction ? { satisfaction_score: pct(satisfaction.score), satisfaction_reasoning: satisfaction.observation ?? null, satisfaction_analyzed_at: now, ...(satisfaction.evidence?.length ? { satisfaction_evidence: satisfaction.evidence } : {}) } : {}),
    ...(accountRelation ? { account_relation_hint: accountRelation.category, account_relation_hint_confidence: pct(accountRelation.confidence), account_relation_hint_reasoning: accountRelation.observation ?? null, account_relation_hint_analyzed_at: now } : {}),
  }, { onConflict: 'organization_id,contact_id,profile_version' }).select('id').single()
  if (profileError || !cognitiveProfile) throw profileError ?? new Error('Profil cognitif non enregistré')
  const signals = structuredSignals.map((item) => ({ organization_id: organizationId, contact_id: contactId, profile_id: cognitiveProfile.id, signal_type: item.trait, text: item.observation, inference: item.trait, inference_level: 'observable', confidence: pct(item.confidence), source_type: signalSource, source_ref: sourceRef, observed_at: observedAt }))
  if (signals.length) {
    const { error: signalsError } = await supabase.from('behavioral_signals').insert(signals)
    if (signalsError) throw signalsError
  }
  return { profileId: cognitiveProfile.id as string, signalCount: signals.length }
}

// Journalisation de l'usage IA (OpenRouter) → table `ai_usage_events`.
// OpenRouter renvoie `usage` (tokens réels) dans chaque réponse : on stocke ces
// tokens + un coût ESTIMÉ via la grille ci-dessous. La grille est approximative
// (la source de vérité des dépenses reste le tableau de bord OpenRouter) et se
// met à jour ici sans toucher au reste du code.

// Prix approximatifs en USD par 1 000 000 de tokens (entrée / sortie).
// À ajuster selon la facturation OpenRouter réelle.
const PRICING: Record<string, { in: number; out: number }> = {
  'google/gemini-3.1-flash-lite': { in: 0.10, out: 0.40 },
  'anthropic/claude-haiku-4.5': { in: 1.00, out: 5.00 },
  'openai/gpt-4.1-mini': { in: 0.40, out: 1.60 },
}
const DEFAULT_PRICE = { in: 0.50, out: 1.50 }

export type TokenUsage = { prompt_tokens?: number; completion_tokens?: number; total_tokens?: number } | null | undefined

export function estimateCostUsd(model: string, promptTokens: number, completionTokens: number): number {
  const price = PRICING[model] ?? DEFAULT_PRICE
  return (promptTokens / 1_000_000) * price.in + (completionTokens / 1_000_000) * price.out
}

type AnySupabase = { from: (table: string) => { insert: (rows: Record<string, unknown>) => PromiseLike<{ error: unknown }> } }

/** Best-effort : ne jette jamais (une erreur de log ne doit pas casser l'analyse). */
export async function logAiUsage(client: AnySupabase, params: {
  organizationId?: string | null
  userId?: string | null
  fn: string
  model: string
  usage: TokenUsage
}): Promise<void> {
  try {
    const prompt = Math.max(0, Math.round(Number(params.usage?.prompt_tokens ?? 0)))
    const completion = Math.max(0, Math.round(Number(params.usage?.completion_tokens ?? 0)))
    const total = Math.max(0, Math.round(Number(params.usage?.total_tokens ?? prompt + completion)))
    await client.from('ai_usage_events').insert({
      organization_id: params.organizationId ?? null,
      user_id: params.userId ?? null,
      fn: params.fn,
      model: params.model,
      prompt_tokens: prompt,
      completion_tokens: completion,
      total_tokens: total,
      estimated_cost_usd: Number(estimateCostUsd(params.model, prompt, completion).toFixed(6)),
    })
  } catch {
    // silencieux : la journalisation ne doit jamais interrompre le flux principal.
  }
}

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { SLACK_SCOPES, slackApi } from '../_shared/slack.ts'
const headers = { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type', 'Access-Control-Allow-Methods': 'GET, POST, OPTIONS' }
const json = (data: unknown, status = 200) => new Response(JSON.stringify(data), { status, headers: { ...headers, 'Content-Type': 'application/json' } })
const checked = async (query: any) => { const result = await query; if (result.error) throw result.error; return result.data }
Deno.serve(async req => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers })
  const db = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!)
  const redirect = `${Deno.env.get('SUPABASE_URL')}/functions/v1/connect-slack`
  const app = Deno.env.get('APP_URL') ?? 'https://tohu.co'
  const clientId = Deno.env.get('SLACK_CLIENT_ID')
  const clientSecret = Deno.env.get('SLACK_CLIENT_SECRET')
  let callbackConnectorId: string | null = null
  let callbackLease: string | null = null
  try {
    if (req.method === 'GET') {
      const url = new URL(req.url)
      const nonce = url.searchParams.get('state')
      if (!nonce || !/^[a-f0-9-]{36}$/.test(nonce)) return json({ error: 'État OAuth invalide' }, 400)
      const pending = await checked(db.from('connector_oauth_states').delete().eq('nonce', nonce).eq('provider', 'slack').gt('expires_at', new Date().toISOString()).select().maybeSingle())
      if (!pending) return json({ error: 'Autorisation expirée ou déjà utilisée' }, 400)
      if (url.searchParams.has('error')) return Response.redirect(`${app}/app/connectors?error=slack_access_denied`, 302)
      const member = await checked(db.from('memberships').select('id').eq('organization_id', pending.organization_id).eq('user_id', pending.user_id).maybeSingle())
      if (!member) return json({ error: 'Accès refusé' }, 403)
      const code = url.searchParams.get('code')
      if (!code) return json({ error: 'Code OAuth manquant' }, 400)
      if (!clientId || !clientSecret) throw new Error('Secrets Slack non configurés dans les Edge Functions')
      const response = await fetch('https://slack.com/api/oauth.v2.access', { method: 'POST', body: new URLSearchParams({ client_id: clientId, client_secret: clientSecret, redirect_uri: redirect, code }), signal: AbortSignal.timeout(20000) })
      const token = await response.json()
      if (!response.ok || !token.ok || !token.authed_user?.access_token || !token.team?.id) throw new Error('Échange OAuth Slack refusé')
      const existing = await checked(db.from('connectors').select('id').eq('organization_id', pending.organization_id).eq('user_id', pending.user_id).eq('provider', 'slack').maybeSingle())
      if (existing) {
        const lease = crypto.randomUUID()
        if (!await checked(db.rpc('claim_connector_sync', { p_connector_id: existing.id, p_lease_id: lease }))) throw new Error('Synchronisation en cours, réessaie la connexion dans quelques minutes')
        callbackConnectorId = existing.id
        callbackLease = lease
      }
      const connector = await checked(db.from('connectors').upsert({ organization_id: pending.organization_id, user_id: pending.user_id, provider: 'slack', status: 'not_connected', scopes: (token.authed_user.scope ?? '').split(','), metadata: { team_id: token.team.id, team_name: token.team.name, slack_user_id: token.authed_user.id, share_public: true }, last_synced_at: null }, { onConflict: 'user_id,provider' }).select('id').single())
      callbackConnectorId = connector.id
      // Remove the previous refresh token: the shared vault RPC preserves null refresh tokens.
      await checked(db.from('oauth_accounts').delete().eq('connector_id', connector.id))
      await checked(db.rpc('store_oauth_tokens_server', { p_organization_id: pending.organization_id, p_connector_id: connector.id, p_provider_account_id: token.team.id, p_access_token: token.authed_user.access_token, p_refresh_token: token.authed_user.refresh_token ?? null, p_expires_at: token.authed_user.expires_in ? new Date(Date.now() + token.authed_user.expires_in * 1000).toISOString() : null }))
      await checked(db.from('connector_sync_state').upsert({ connector_id: connector.id, state: {}, lease_until: null, lease_id: null }))
      await checked(db.from('connectors').update({ status: 'connected' }).eq('id', connector.id))
      return Response.redirect(`${app}/app/connectors?connected=slack`, 302)
    }
    if (req.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
    const { data: { user } } = await db.auth.getUser((req.headers.get('Authorization') ?? '').replace('Bearer ', ''))
    if (!user) return json({ error: 'Session invalide' }, 401)
    const { organizationId, action = 'start', sharePublic } = await req.json()
    const member = await checked(db.from('memberships').select('id').eq('organization_id', organizationId).eq('user_id', user.id).maybeSingle())
    if (!member) return json({ error: 'Accès refusé' }, 403)
    if (action === 'disconnect' || action === 'configure') {
      const connector = await checked(db.from('connectors').select('*').eq('organization_id', organizationId).eq('user_id', user.id).eq('provider', 'slack').single())
      const lease = crypto.randomUUID()
      if (!await checked(db.rpc('claim_connector_sync', { p_connector_id: connector.id, p_lease_id: lease }))) return json({ error: 'Synchronisation en cours. Réessaie dans quelques instants.' }, 409)
      try {
        if (action === 'configure') {
          if (typeof sharePublic !== 'boolean') return json({ error: 'Configuration invalide' }, 400)
          await checked(db.from('connectors').update({ metadata: { ...connector.metadata, share_public: sharePublic } }).eq('id', connector.id))
          await checked(db.from('connector_sync_state').update({ state: {} }).eq('connector_id', connector.id))
        } else {
          const tokens = await checked(db.rpc('get_oauth_tokens_server', { p_connector_id: connector.id }))
          if (tokens?.[0]?.access_token) {
            try { await slackApi(tokens[0].access_token, 'auth.revoke') } catch { /* Local disconnect still removes all credentials. */ }
          }
          await checked(db.from('oauth_accounts').delete().eq('connector_id', connector.id))
          await checked(db.from('connectors').update({ status: 'disconnected', metadata: {}, scopes: [] }).eq('id', connector.id))
          await checked(db.from('connector_sync_state').update({ state: {} }).eq('connector_id', connector.id))
        }
      } finally { await checked(db.from('connector_sync_state').update({ lease_until: null, lease_id: null }).eq('connector_id', connector.id).eq('lease_id', lease)) }
      return json({ success: true })
    }
    if (action !== 'start') return json({ error: 'Action invalide' }, 400)
    if (!clientId || !clientSecret) return json({ error: 'SLACK_CLIENT_ID / SLACK_CLIENT_SECRET non configurés dans les secrets Edge Functions' }, 500)
    await checked(db.from('connector_oauth_states').delete().lt('expires_at', new Date().toISOString()))
    const pending = await checked(db.from('connector_oauth_states').insert({ organization_id: organizationId, user_id: user.id, provider: 'slack' }).select('nonce').single())
    return json({ url: `https://slack.com/oauth/v2/authorize?${new URLSearchParams({ client_id: clientId, redirect_uri: redirect, user_scope: SLACK_SCOPES.join(','), state: pending.nonce })}` })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Opération Slack impossible'
    if (req.method === 'GET') {
      if (callbackConnectorId) await db.from('connectors').update({ status: 'error' }).eq('id', callbackConnectorId)
      return Response.redirect(`${app}/app/connectors?error=${encodeURIComponent(message)}`, 302)
    }
    return json({ error: message }, 500)
  } finally {
    if (callbackConnectorId && callbackLease) await db.from('connector_sync_state').update({ lease_until: null, lease_id: null }).eq('connector_id', callbackConnectorId).eq('lease_id', callbackLease)
  }
})

export const SLACK_SCOPES = ['users:read', 'users:read.email', 'channels:read', 'channels:history', 'groups:read', 'groups:history', 'im:read', 'im:history', 'mpim:read', 'mpim:history']
export class SlackError extends Error {
  constructor(public code: string, public retryAfter = 0) { super(`Slack : ${code}`) }
}
export async function slackApi(token: string, method: string, params: Record<string, string> = {}, fetcher: typeof fetch = fetch): Promise<any> {
  const response = await fetcher(`https://slack.com/api/${method}`, {
    method: 'POST', headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(params), signal: AbortSignal.timeout(20000),
  })
  if (response.status === 429) throw new SlackError('ratelimited', Math.max(1, Number(response.headers.get('Retry-After')) || 60))
  if (!response.ok) throw new SlackError(`http_${response.status}`, response.status >= 500 ? 30 : 0)
  const data = await response.json()
  if (!data.ok) throw new SlackError(data.error ?? 'invalid_response', data.error === 'ratelimited' ? 60 : 0)
  return data
}
export function conversationTypes(scopes: string[]): string {
  return [['channels', 'public_channel'], ['groups', 'private_channel'], ['im', 'im'], ['mpim', 'mpim']]
    .filter(([scope]) => scopes.includes(`${scope}:read`) && scopes.includes(`${scope}:history`)).map(([, type]) => type).join(',')
}
export function isPrivateConversation(channel: any): boolean {
  // Unknown conversation types are private by default.
  return channel.is_private !== false || channel.is_im === true || channel.is_mpim === true
}
export function messageKey(team: string, channel: string, ts: string): string { return `${team}:${channel}:${ts}` }
export function authoredMessage(message: any): boolean {
  return !!message.user && !message.bot_id && (!message.subtype || message.subtype === 'thread_broadcast') && /^\d+\.\d+$/.test(message.ts ?? '')
}
export const REAUTH_ERRORS = ['invalid_auth', 'token_revoked', 'token_expired', 'account_inactive', 'invalid_refresh_token']

// Récepteur webhook Read AI (public, verify_jwt=false). Read AI POSTe un rapport
// après chaque réunion (Zoom / Teams / Meet) : résumé + transcript + participants
// avec emails. On identifie l'organisation via le secret `?token=`, on résout les
// participants en contacts PAR EMAIL, puis on stocke dans le même pipeline que
// Google Meet (meetings + meeting_participants + meeting_transcripts).
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { extractMeetingContext, extractParticipants, extractTranscriptText, signingKeyBytes } from '../_shared/read-ai-webhook.ts'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}
function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
}

const FREE_EMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'outlook.com', 'hotmail.com', 'hotmail.fr', 'live.com', 'live.fr',
  'yahoo.com', 'yahoo.fr', 'icloud.com', 'me.com', 'aol.com', 'proton.me', 'protonmail.com',
  'orange.fr', 'free.fr', 'wanadoo.fr', 'sfr.fr', 'laposte.net', 'gmx.com', 'msn.com',
])

function emailDomain(email: string | null | undefined): string | null {
  const at = String(email ?? '').trim().toLowerCase().split('@')[1]
  return at && at.includes('.') ? at : null
}
function corporateDomain(email: string | null | undefined): string | null {
  const domain = emailDomain(email)
  return domain && !FREE_EMAIL_DOMAINS.has(domain) ? domain : null
}
function companyNameFromDomain(domain: string): string {
  const core = domain.split('.').slice(0, -1).join(' ') || domain
  return core.charAt(0).toUpperCase() + core.slice(1)
}
function asText(value: unknown): string | null {
  if (typeof value === 'string') return value.trim() || null
  if (value && typeof value === 'object') {
    const obj = value as Record<string, unknown>
    return asText(obj.text ?? obj.summary ?? obj.value ?? null)
  }
  return null
}
// Read AI envoie les dates en Unix millisecondes (parfois secondes ou ISO) : on normalise.
function toIso(value: unknown): string | null {
  if (value == null) return null
  if (typeof value === 'number') {
    const date = new Date(value < 1e12 ? value * 1000 : value)
    return Number.isNaN(date.getTime()) ? null : date.toISOString()
  }
  const raw = String(value).trim()
  if (!raw) return null
  if (/^\d+$/.test(raw)) return toIso(Number(raw))
  const date = new Date(raw)
  return Number.isNaN(date.getTime()) ? null : date.toISOString()
}

// Vérification de signature Read AI (en-tête X-Read-Signature = HMAC-SHA256 du body
// brut). On calcule hex ET base64 pour être robuste à l'encodage exact de Read AI.
async function hmacSignatures(body: string, key: string): Promise<{ hex: string; base64: string }> {
  const bytes = signingKeyBytes(key)
  const keyData = bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) as ArrayBuffer
  const cryptoKey = await crypto.subtle.importKey('raw', keyData, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'])
  const signature = await crypto.subtle.sign('HMAC', cryptoKey, new TextEncoder().encode(body))
  const signatureBytes = new Uint8Array(signature)
  const hex = Array.from(signatureBytes).map((b) => b.toString(16).padStart(2, '0')).join('')
  const base64 = btoa(String.fromCharCode(...signatureBytes))
  return { hex, base64 }
}
function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false
  let result = 0
  for (let i = 0; i < a.length; i++) result |= a.charCodeAt(i) ^ b.charCodeAt(i)
  return result === 0
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (req.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
  try {
    const token = new URL(req.url).searchParams.get('token')
    if (!token) return json({ error: 'token manquant' }, 401)
    const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')

    // Le secret identifie l'organisation destinataire.
    const { data: connector } = await supabase.from('connectors')
      .select('organization_id,user_id,metadata')
      .eq('provider', 'read_ai').eq('status', 'connected')
      .eq('metadata->>webhook_secret', token).maybeSingle()
    if (!connector) return json({ error: 'Secret webhook invalide' }, 401)
    const organizationId = connector.organization_id as string
    const ownerUserId = connector.user_id as string

    // Body brut lu AVANT parsing : nécessaire pour recalculer la signature à l'identique.
    const rawBody = await req.text()

    // Vérification de signature si une Signing Key est configurée (sécurité renforcée).
    const signingKey = (connector.metadata as { signing_key?: string | null } | null)?.signing_key ?? null
    if (signingKey) {
      const provided = (req.headers.get('x-read-signature') ?? '').trim().replace(/^sha256=/i, '')
      if (!provided) return json({ error: 'Signature manquante' }, 401)
      const { hex, base64 } = await hmacSignatures(rawBody, signingKey)
      if (!timingSafeEqual(provided, hex) && !timingSafeEqual(provided, base64)) return json({ error: 'Signature invalide' }, 401)
    }

    let body: unknown = null
    try { body = JSON.parse(rawBody) } catch { body = null }
    if (!body || typeof body !== 'object') return json({ error: 'Payload invalide' }, 400)
    const p = ((body as any).session ?? (body as any).data ?? body) as Record<string, any>

    const sessionId = asText(p.session_id ?? p.id ?? p.session_id) ?? `${Date.now()}`
    const requestId = asText(p.request_id)
    const participants = extractParticipants(p)
    const { text: transcriptText, speakerMap } = extractTranscriptText(p)
    const meetingContext = extractMeetingContext(p)

    // Ping / trigger sans contenu exploitable : on acquitte sans rien stocker.
    if (!participants.length && !transcriptText && !meetingContext) return json({ success: true, ignored: true })

    if (requestId) {
      const { data: duplicate } = await supabase.from('meetings').select('id').eq('organization_id', organizationId)
        .eq('external_event_id', `readai:${sessionId}`).contains('raw_payload', { request_id: requestId }).maybeSingle()
      if (duplicate) return json({ success: true, duplicate: true, meeting: duplicate.id })
    }

    // Entreprise déduite du premier participant à domaine professionnel.
    let companyId: string | null = null
    const primary = participants.find((participant) => corporateDomain(participant.email))
    const primaryDomain = primary ? corporateDomain(primary.email) : null
    if (primaryDomain) {
      const { data: company } = await supabase.rpc('resolve_company_identity', {
        p_organization_id: organizationId, p_name: companyNameFromDomain(primaryDomain), p_domain: primaryDomain, p_industry: null, p_create_if_missing: true,
      }).maybeSingle()
      companyId = (company as { company_id?: string } | null)?.company_id ?? null
    }

    const { data: meetingRow, error: meetingError } = await supabase.from('meetings').upsert({
      organization_id: organizationId, owner_user_id: ownerUserId, company_id: companyId,
      external_event_id: `readai:${sessionId}`,
      title: asText(p.title ?? p.session_title) ?? 'Réunion Read AI',
      starts_at: toIso(p.start_time ?? p.session_start_time),
      ends_at: toIso(p.end_time ?? p.session_end_time),
      platform: 'read_ai',
      // Le contexte structuré facilite l'affichage et l'exploitation ultérieure ;
      // le payload original reste conservé pour garantir la provenance Read.ai.
      description: meetingContext || asText(p.summary),
      raw_payload: body,
    }, { onConflict: 'organization_id,external_event_id' }).select('id').single()
    if (meetingError || !meetingRow) return json({ error: meetingError?.message ?? 'Réunion non enregistrée' }, 500)

    let participantsMatched = 0
    const ownerEmail = String(p.owner?.email ?? '').trim().toLowerCase()
    for (const participant of participants) {
      if (!participant.email) continue
      const isCurrentUser = participant.email === ownerEmail
      let contactId: string | null = null
      if (!isCurrentUser) {
        const { data: resolved } = await supabase.rpc('resolve_contact_identity', {
          p_organization_id: organizationId, p_email: participant.email, p_full_name: participant.name ?? participant.email,
          p_company_id: corporateDomain(participant.email) === primaryDomain ? companyId : null,
          p_owner_user_id: ownerUserId, p_role_title: null, p_source: 'read_ai',
        }).maybeSingle()
        contactId = (resolved as { contact_id?: string } | null)?.contact_id ?? null
      }
      const { error: participantError } = await supabase.from('meeting_participants').upsert({
        organization_id: organizationId, meeting_id: meetingRow.id, contact_id: contactId,
        email: participant.email, display_name: participant.name, name: participant.name,
        role_in_meeting: isCurrentUser ? 'owner' : 'attendee', is_current_user: isCurrentUser,
      }, { onConflict: 'meeting_id,email' })
      if (!participantError) participantsMatched++
    }

    let transcriptStored = false
    if (transcriptText) {
      const { error: transcriptError } = await supabase.from('meeting_transcripts').upsert({
        organization_id: organizationId, meeting_id: meetingRow.id, provider: 'read_ai',
        transcript_text: transcriptText, speaker_map: speakerMap,
        // Read AI notifie les participants de l'enregistrement : consentement au niveau plateforme.
        consent_status: 'granted',
      }, { onConflict: 'meeting_id,provider' })
      transcriptStored = !transcriptError
    }

    await supabase.from('connectors').update({ last_synced_at: new Date().toISOString() })
      .eq('organization_id', organizationId).eq('user_id', ownerUserId).eq('provider', 'read_ai')

    return json({ success: true, meeting: meetingRow.id, participantsMatched, transcriptStored, contextStored: !!meetingContext })
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : 'Traitement impossible' }, 500)
  }
})

export type ReadAiParticipant = { email: string | null; name: string | null }

function asText(value: unknown): string | null {
  if (typeof value === 'string') return value.trim() || null
  if (value && typeof value === 'object') {
    const obj = value as Record<string, unknown>
    return asText(obj.text ?? obj.summary ?? obj.value ?? null)
  }
  return null
}

/** Read.ai exposes its webhook signing key as Base64. */
export function signingKeyBytes(key: string): Uint8Array {
  try {
    return Uint8Array.from(atob(key.trim()), (char) => char.charCodeAt(0))
  } catch {
    // Preserve compatibility with keys saved before Read.ai documented Base64.
    return new TextEncoder().encode(key)
  }
}

export function extractParticipants(payload: Record<string, any>): ReadAiParticipant[] {
  const raw: any[] = []
  if (Array.isArray(payload.participants)) raw.push(...payload.participants)
  if (payload.owner) raw.push(payload.owner)
  if (Array.isArray(payload.attendees)) raw.push(...payload.attendees)

  const seen = new Set<string>()
  const participants: ReadAiParticipant[] = []
  for (const item of raw) {
    const email = String(item?.email ?? '').trim().toLowerCase() || null
    const fallbackName = email ? (email.split('@')[0] ?? email) : null
    const name = asText(item?.name ?? item?.display_name ?? item?.full_name) ?? fallbackName
    const domain = email ? (email.split('@')[1] ?? '') : ''
    if (domain === 'read.ai' || domain.endsWith('.read.ai')) continue
    if (name && /\bvia read ai\b/i.test(name)) continue
    const key = email ?? name ?? ''
    if (!key || seen.has(key)) continue
    seen.add(key)
    participants.push({ email, name })
  }
  return participants
}

export function extractTranscriptText(payload: Record<string, any>): { text: string; speakerMap: Record<string, string> } {
  const speakerMap: Record<string, string> = {}
  const lines: string[] = []
  const push = (speaker: unknown, words: unknown) => {
    const speakerObject = speaker && typeof speaker === 'object' ? speaker as Record<string, unknown> : null
    const name = asText(speakerObject?.name ?? speaker) ?? 'Participant'
    const text = asText(words)
    if (!text) return
    speakerMap[name] = name
    lines.push(`${name} : ${text}`)
  }

  const transcript = payload.transcript
  if (transcript && Array.isArray(transcript.speaker_blocks)) {
    for (const block of transcript.speaker_blocks) push(block?.speaker, block?.words ?? block?.text)
  } else if (transcript && Array.isArray(transcript.turns)) {
    for (const block of transcript.turns) push(block?.speaker, block?.text ?? block?.words)
  } else if (Array.isArray(transcript)) {
    for (const block of transcript) push(block?.speaker, block?.words ?? block?.text)
  } else if (Array.isArray(payload.transcript_segments)) {
    for (const block of payload.transcript_segments) push(block?.speaker, block?.words ?? block?.text)
  }
  return { text: lines.join('\n'), speakerMap }
}

export function extractMeetingContext(payload: Record<string, any>): string {
  const lines: string[] = []
  const add = (label: string, value: unknown) => {
    const text = asText(value)
    if (text) lines.push(`${label} : ${text}`)
  }
  add('Résumé', payload.summary)
  for (const item of payload.action_items ?? []) add('Action', item)
  for (const item of payload.key_questions ?? []) add('Question clé', item)
  for (const item of payload.topics ?? []) add('Sujet', item)
  for (const chapter of payload.chapter_summaries ?? []) {
    const title = asText(chapter?.title)
    add(`Chapitre${title ? ` — ${title}` : ''}`, chapter?.description ?? chapter?.summary)
  }
  return lines.join('\n').slice(0, 24_000)
}

// Connecteur Read AI — Read AI ne s'interroge pas en OAuth : il POUSSE un rapport
// (résumé + transcript + participants avec emails) vers une URL webhook après chaque
// réunion. Ce endpoint (authentifié) génère/retourne un secret propre à l'organisation
// et l'URL webhook à coller dans Read AI (Settings → Integrations → Webhooks).
// Idempotent : renvoie toujours le même secret pour une organisation donnée.
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}
function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
}

function newSecret(): string {
  return (crypto.randomUUID() + crypto.randomUUID()).replace(/-/g, '')
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (req.method !== 'POST') return json({ error: 'Method not allowed' }, 405)
  try {
    const auth = req.headers.get('Authorization')
    if (!auth) return json({ error: 'Authentification requise' }, 401)
    const supabase = createClient(Deno.env.get('SUPABASE_URL') ?? '', Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '')
    const { data: { user }, error: userError } = await supabase.auth.getUser(auth.replace('Bearer ', ''))
    if (userError || !user) return json({ error: 'Session invalide' }, 401)
    const { organizationId, signingKey } = await req.json().catch(() => ({}))
    if (!organizationId) return json({ error: 'organizationId requis' }, 400)
    const { data: membership } = await supabase.from('memberships').select('id').eq('organization_id', organizationId).eq('user_id', user.id).maybeSingle()
    if (!membership) return json({ error: 'Accès refusé' }, 403)

    // Réutilise le secret existant s'il y en a un (idempotent), et préserve les autres
    // champs de metadata (dont la Signing Key déjà enregistrée).
    const { data: existing } = await supabase.from('connectors')
      .select('metadata').eq('organization_id', organizationId).eq('user_id', user.id).eq('provider', 'read_ai').maybeSingle()
    const existingMeta = (existing?.metadata as Record<string, unknown> | null) ?? {}
    const secret = (existingMeta.webhook_secret as string | undefined) ?? newSecret()
    // signingKey fourni ('' = retirer, texte = enregistrer) ; absent = on garde l'existant.
    const nextSigningKey = typeof signingKey === 'string'
      ? (signingKey.trim() || null)
      : ((existingMeta.signing_key as string | null | undefined) ?? null)

    const { error: upsertError } = await supabase.from('connectors').upsert({
      organization_id: organizationId, user_id: user.id, provider: 'read_ai', status: 'connected',
      scopes: [], metadata: { ...existingMeta, webhook_secret: secret, signing_key: nextSigningKey, connected_at: (existingMeta.connected_at as string | undefined) ?? new Date().toISOString() }, updated_at: new Date().toISOString(),
    }, { onConflict: 'user_id,provider' })
    if (upsertError) return json({ error: upsertError.message }, 500)

    const webhookUrl = `${Deno.env.get('SUPABASE_URL') ?? ''}/functions/v1/read-ai-webhook?token=${secret}`
    return json({ webhookUrl, secret, hasSigningKey: !!nextSigningKey })
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : 'Connexion impossible' }, 500)
  }
})
